       +'<td style="color:#cbd5e1;font-weight:700">#'+_dEsc(o.num)+'</td>'
       +'<td><div class="cust"><span class="av2" style="background:'+_dColor(o.nombre)+'">'+_dEsc(_dIni(o.nombre))+'</span>'+_dEsc(o.nombre)+'</div></td>'
