def _flex_rc2(o) -> float:
    """Lo que cobra Envialo Flex por este CP. Un CP del conurbano que todavia no aparecio se
    cobra como 2do cordon ($6.600), que es la banda mas frecuente."""
    cp = _rc2_cp4(o)
    if not cp:
        return FLEX_RC2_2DO
    hit = FLEX_RC2_CP.get(cp)
    if hit:
        return hit
    return FLEX_RC2_CABA if int(cp) <= 1499 else FLEX_RC2_2DO


# Envios UNIFICADOS: varios pedidos del mismo cliente que se despachan en UN SOLO paquete.
# No es una regla general ni se deduce sola: es una decision puntual de Cristian, cargada a mano.
# Paga el envio el pedido de numero MAS BAJO del grupo; los demas suman 0, porque el flete se
# pago una sola vez. Si no estuviera esto, 4 pedidos de un mismo cliente cobraban 4 fletes y
# hundian la ganancia de ese dia sin que nadie hubiera pagado esos envios.
ENVIOS_UNIFICADOS = [
    {"7039", "7040", "7042", "7044"},   # Leonardo Gallo, 03-10-2026: 4 unidades en 1 paquete
]


def _envio_unificado_paga(num) -> bool:
    """False si este pedido viaja dentro del paquete de otro: no debe sumar envio."""
    n = str(num or "").replace("#", "").strip()
    for g in ENVIOS_UNIFICADOS:
        if n in g:
            return n == min(g)
    return True


def _envio_final_and2(zona, valor_declarado, suc=False) -> int:
    """Lo que se paga de verdad por un envio con la tarifa medida el 30-09-2026."""
    tabla = ENVIO_AND2_SUC if suc else ENVIO_AND2_DOM
    t = tabla.get(zona) or tabla["centro"]
    seg = float(valor_declarado or 0) * ENVIO_SEGURO_PCT / 100.0
    return int(round((t + seg) * 1.21 * ENVIO_CUPON))

_ENV_ACC = str.maketrans("áéíóúüàèìòùÁÉÍÓÚÜÑñ", "aeiouuaeiouAEIOUUNn")
def _env_norm(s):
    return str(s or "").translate(_ENV_ACC).lower().strip()

# provincia (nombre normalizado) -> zona. Buenos Aires se resuelve por CP aparte.
_PROV_ZONA = {
    "capital federal": "amba", "ciudad autonoma de buenos aires": "amba", "caba": "amba",
    "ciudad de buenos aires": "amba", "capital": "amba", "c.a.b.a.": "amba",
    "cordoba": "centro", "santa fe": "centro", "entre rios": "centro", "la pampa": "centro",
    "mendoza": "cuyo", "san juan": "cuyo", "san luis": "cuyo", "tucuman": "cuyo",
    "santiago del estero": "cuyo", "catamarca": "cuyo", "la rioja": "cuyo",
    "misiones": "cuyo", "corrientes": "cuyo", "chaco": "cuyo", "formosa": "cuyo",
    "neuquen": "cuyo", "rio negro": "cuyo",
    "salta": "extremo", "jujuy": "extremo", "chubut": "extremo",
    "santa cruz": "extremo", "tierra del fuego": "extremo",
}
# código ISO 3166-2 de 1 letra (TN a veces manda 'C','X'...). 'B' = Buenos Aires → por CP.
_ISO_ZONA = {
    "C": "amba", "X": "centro", "S": "centro", "E": "centro", "L": "centro",
    "M": "cuyo", "J": "cuyo", "D": "cuyo", "T": "cuyo", "G": "cuyo", "K": "cuyo",
    "F": "cuyo", "N": "cuyo", "W": "cuyo", "H": "cuyo", "P": "cuyo", "Q": "cuyo", "R": "cuyo",
    "A": "extremo", "Y": "extremo", "U": "extremo", "Z": "extremo", "V": "extremo",
}

def _prov_cp(o):
    """Provincia + CP del pedido, sirve tanto para la forma Shopify (shipping_address dict con
    'province'/'zip') como para el pedido nativo de Tiendanube (varias ubicaciones posibles)."""
    for src in (o.get("shipping_address"), o.get("billing_address")):
        if isinstance(src, dict):
            prov = src.get("province") or src.get("state") or ""
            cp = src.get("zipcode") or src.get("zip") or src.get("postal_code") or ""
            if prov or cp:
                return prov, cp
    prov = o.get("shipping_province") or o.get("province") or ""
    cp = o.get("shipping_zipcode") or o.get("shipping_zip") or o.get("zip") or ""
    return prov, cp

def _envio_zona(o) -> str:
    prov, cp = _prov_cp(o)
    cp = "".join(ch for ch in str(cp) if ch.isdigit())
    pn = _env_norm(prov)
    code = str(prov).strip().upper()
    # CABA (nombre en cualquier variante)
    if ("capital federal" in pn or "autonoma de buenos aires" in pn or "ciudad de buenos aires" in pn
            or pn in ("caba", "capital", "c.a.b.a.") or code == "C"):
        return "amba"
    # Buenos Aires PROVINCIA → GBA (CP 1xxx) = AMBA ; interior = Centro
    if code == "B" or "buenos aires" in pn or pn in ("bs as", "bsas", "pba"):
        return "amba" if cp[:1] == "1" else "centro"
    # código ISO de 1 letra
    if len(code) == 1 and code in _ISO_ZONA:
        return _ISO_ZONA[code]
    # nombre de provincia por coincidencia (soporta nombres oficiales largos)
    for k, z in _PROV_ZONA.items():
        if k in ("capital federal", "ciudad autonoma de buenos aires", "caba",
                 "ciudad de buenos aires", "capital", "c.a.b.a."):
            continue
        if k in pn:
            return z
    return "amba" if cp[:1] == "1" else "centro"   # último fallback por CP

def _envio_zona2(o) -> str:
    """Zona para la tabla del 30-09-2026. NO reemplaza a _envio_zona: esa sigue devolviendo las
    4 zonas viejas (amba/centro/cuyo/extremo) porque las tablas historicas dependen de ellas.
    Acá se refinan los dos cortes que la medicion mostro que cambiaron:
      - CABA deja de ir con GBA y pasa a pagar como Cordoba/Rosario ("centro").
      - LA PAMPA se separa de "centro" a su propia banda, la mas cara del pais.
    """
    z = _envio_zona(o)
    prov, cp = _prov_cp(o)
    pn = _env_norm(prov)
    code = str(prov).strip().upper()
    # el CP puntual manda sobre la provincia: hay pueblos con recargo propio
    _cp4 = "".join(ch for ch in str(cp) if ch.isdigit())[:4]
    if _cp4 in ENVIO_CP_RECARGO:
        return ENVIO_CP_RECARGO[_cp4]
    if "la pampa" in pn or code == "L":
        return "pampa"
    if z == "amba":
        # CABA paga IGUAL que GBA. Lo medi mal la primera vez (un solo envio, con la provincia
        # escrita "CAPITAL FEDERAL", dio la banda de arriba) y lo corregi con 19 CPs REALES de
        # CABA: los 19 dieron $ 10.495,92, el mismo precio que Florida, Munro, Boulogne y El Talar.
        return "gba"
    return z


def _txt_es_sucursal(txt) -> bool:
    """ÚNICA fuente de verdad para clasificar sucursal por el TEXTO del método de envío.
    Regla conservadora: por DEFECTO domicilio. Sucursal solo con señal explícita como PALABRA
    ENTERA (no substring: 'hop' NO cuenta dentro de 'shop'). Si el texto dice 'domicilio' →
    NUNCA sucursal. Así jamás flipeamos un domicilio a sucursal."""
    import re
    txt = (txt or "").lower()
    if not txt.strip():
        return False
    if re.search(r"\b(a\s+)?domicilio\b|\bhome\s*deliver|\benv[ií]o\s+a\s+casa\b", txt):
        return False
    return bool(re.search(
        r"\bsucursal\b|\bpick\s*-?\s*up\b|\bpickup\b|\bretir[oa]\b|\bagencia\b|"
        r"\bpunto\s+(de\s+)?retiro\b|\bpunto\s+andreani\b|\bhop\b|\bcorreo\s+arg\w*\s+sucursal\b",
        txt))


def _envio_suc(o) -> bool:
    """Costo: usa la MISMA regla que el export. Pickup explícito de TN, o el texto del método."""
    if o.get("shipping_pickup_type") == "pickup":
        return True
    txt = " ".join(((s.get("title") or "") + " " + (s.get("code") or "")) for s in (o.get("shipping_lines") or []))
    txt += " " + (o.get("shipping_option") or "")   # TN manda el método acá ("Envío a domicilio"/"Punto de retiro")
    return _txt_es_sucursal(txt)

def _envio_hora_ar(o) -> str:
    """Fecha y HORA del pedido en hora ARGENTINA, como 'YYYY-MM-DDTHH:MM'.

    Shopify y Tiendanube mandan ISO con offset ('2026-09-24T09:15:33-03:00'), que ya es hora
    local. Pero no se puede dar por hecho y cortar el string a lo bruto: si alguna orden viniera
    en UTC ('...Z'), un pedido de las 8:30 de la mañana se leería como 11:30 y caería del lado
    equivocado del corte de las 10:00, cobrándole al pedido la tarifa que no es."""
    import re as _re_h
    s = str(o.get("created_at") or o.get("completed_at") or "").strip()
    if not s:
        return ""
    m = _re_h.match(r"^(\d{4}-\d\d-\d\d)[T ](\d\d):(\d\d)(?::\d\d)?(?:\.\d+)?\s*(Z|[+-]\d\d:?\d\d)?", s)
    if not m:
        return s[:16]
    try:
        dt = _dt.datetime.strptime("%s %s:%s" % (m.group(1), m.group(2), m.group(3)), "%Y-%m-%d %H:%M")
    except Exception:
        return s[:16]
    off = m.group(4) or ""
    if off:                                    # sin offset se asume que ya viene en hora argentina
        if off.upper() == "Z":
            omin = 0
        else:
            o2 = off.replace(":", "")
            omin = (1 if o2[0] == "+" else -1) * (int(o2[1:3]) * 60 + int(o2[3:5]))
        dt = dt - _dt.timedelta(minutes=omin)  # a UTC
        dt = dt - _dt.timedelta(hours=3)       # UTC -> Argentina (UTC-3)
    return dt.strftime("%Y-%m-%dT%H:%M")


def _envio_costo(o) -> int:
    """Costo de envío del pedido, según provincia/CP y si va a sucursal o domicilio.

    Hay DOS cortes en el tiempo, y ninguno reescribe el histórico:
      1) hasta el 14/09/2026 -> tabla vieja de ANDREANI.
      2) del 15/09 hasta el 24/09 a las 10:00 -> tabla de REDCHAT (la logística que reemplazó a
         Envialo, que cerró: su API devuelve 403 ENVIALO_LOCKED_DOWN).
      3) desde el 24/09/2026 a las 10:00 -> se vuelve a despachar con ANDREANI, así que vuelve a
         regir SU tabla.
    El corte 3 es por HORA y no por día a propósito: los pedidos de esa misma mañana anteriores a
    las 10 salieron con la logística anterior y tienen que quedar costeados con la lista anterior.
    Cubre Shopify y Tiendanube (las dos traen created_at)."""
    suc = _envio_suc(o)
    z = _envio_zona(o)
    fecha = str(o.get("created_at") or o.get("completed_at") or "")[:10]
    _hora = _envio_hora_ar(o)
    if _hora and _hora >= ENVIO_RC2_DESDE:
        # Andreani le saco el cupon: ahora se paga por RedChat, precio cerrado por zona.
        # Ya no se suma seguro ni se aplica el 0,75 del cupon: ese precio es el final.
        return _envio_rc2(o, suc)
    if _hora and _hora >= ENVIO_AND2_DESDE:
        # Tarifa medida el 30-09-2026. El seguro es 1% del VALOR DECLARADO, asi que el costo sube
        # con el ticket y no puede salir de un numero fijo por zona.
        _val = 0.0
        for _k in ("total_price", "current_total_price", "total", "total_amount"):
            try:
                _val = float(o.get(_k) or 0)
            except Exception:
                _val = 0.0
            if _val:
                break
        # sucursal agrupa distinto que domicilio: cada uno con SU mapa de zonas.
        return _envio_final_and2(_envio_zona(o) if suc else _envio_zona2(o), _val, suc)
    if _hora and _hora >= ENVIO_AND_VUELVE:     # volvimos a Andreani
        z3 = ENVIO_ZONAS.get(z) or {"sucursal": ENVIO_SUCURSAL, "domicilio": ENVIO_DOMICILIO}
        return z3["sucursal"] if suc else z3["domicilio"]
    if fecha >= ENVIO_RC_DESDE:
        # En RETIRO la Patagonia paga como Cuyo; sólo Salta/Jujuy quedan en la banda cara.
        # (Verificado: Trelew, Pto Madryn, Comodoro y Río Gallegos a $6.979, no a $7.286.)
        if suc and z == "extremo":
            _p = _env_norm(_prov_cp(o)[0])
            if "salta" not in _p and "jujuy" not in _p:
                z = "cuyo"
        t = ENVIO_ZONAS_RC.get(z) or ENVIO_ZONAS_RC["centro"]
        return t["sucursal"] if suc else t["domicilio"]
    z2 = ENVIO_ZONAS.get(z) or {"sucursal": ENVIO_SUCURSAL, "domicilio": ENVIO_DOMICILIO}
    return z2["sucursal"] if suc else z2["domicilio"]


ENVIALO_BASE = "https://www.envialo.com.ar/api/v1"
ENVIALO_KEYS = DATA_DIR / "envialo_keys.json"   # API key de Envialo por usuario (persistente)
_ENVIALO_CACHE = {}   # email -> (ts, {nº pedido: costo})


def _envialo_keys() -> dict:
    try:
        return _json.loads(ENVIALO_KEYS.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _envialo_save_key(email, key) -> None:
    d = _envialo_keys()
    d[str(email)] = key
    ENVIALO_KEYS.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")


def _envialo_key_de(email):
    import os
    return (_envialo_keys().get(email) or os.getenv("ENVIALO_API_KEY", "")) if email else ""


def _envialo_fetch(key: str) -> dict:
    """{nº de pedido → costo REAL de envío} pegándole a Envialo con esa API key."""
    out = {}
    try:
        for pg in range(40):
            r = requests.get(ENVIALO_BASE + "/orders", headers={"X-API-Key": key},
                             params={"page": pg, "limit": 50}, timeout=30)
            if r.status_code != 200:
                break
            j = r.json()
            for o in j.get("orders", []):
                n = str(o.get("number") or "").strip()
                sc = o.get("shipping_cost")
                if n and sc not in (None, "", 0):
                    try:
                        out[n] = float(sc)
                    except (TypeError, ValueError):
                        pass
            if not j.get("hasMore"):
                break
    except Exception:
        pass
    return out


def _envialo_costos(email=None):
    """{nº de pedido → costo REAL de envío} desde la cuenta Envialo de ESE usuario.
    Vacío si no conectó su API key. Cache 5 min por usuario."""
    import time as _t
    key = _envialo_key_de(email)
    if not key:
        return {}
    c = _ENVIALO_CACHE.get(email)
    if c and (_t.time() - c[0] < 300):
        return c[1]
    out = _envialo_fetch(key)
    _ENVIALO_CACHE[email] = (_t.time(), out)
    return out


@app.get("/envialo/estado")
def envialo_estado():
    email = _user_actual()
    return jsonify({"ok": True, "conectado": bool(email and email in _envialo_keys())})


@app.post("/envialo/conectar")
@limiter.limit("20 per hour")
def envialo_conectar():
    """Guarda la API key de Envialo del usuario. Valida pegándole una vez a la API."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "error": "Tenés que iniciar sesión."}), 401
    data = request.get_json(silent=True) or request.form
    key = (data.get("api_key", "") or "").strip()
    if not key:
        return jsonify({"ok": False, "error": "Pegá tu API key de Envialo."}), 400
    try:
        r = requests.get(ENVIALO_BASE + "/orders", headers={"X-API-Key": key},
                         params={"page": 0, "limit": 1}, timeout=25)
        if r.status_code in (401, 403):
            return jsonify({"ok": False, "error": "La API key no es válida (Envialo la rechazó)."}), 400
        if r.status_code != 200:
            return jsonify({"ok": False, "error": "Envialo no respondió bien. Probá de nuevo."}), 400
    except Exception:
        return jsonify({"ok": False, "error": "No pudimos conectar con Envialo. Probá de nuevo."}), 502
    _envialo_save_key(email, key)
    _ENVIALO_CACHE.pop(email, None)
    return jsonify({"ok": True})


@app.get("/desconectar-envialo")
def desconectar_envialo():
    email = _user_actual()
    if email:
        d = _envialo_keys()
        d.pop(email, None)
        ENVIALO_KEYS.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
        _ENVIALO_CACHE.pop(email, None)
    return redirect("/?integ=1")


def _mp_costos(email, desde, hasta):
    """Costos REALES de MercadoPago del período (de la cuenta MP conectada del usuario).
    costo real por pago = transaction_amount − net_received_amount (incluye comisión +
    financiación de cuotas + IVA, todo lo que MP realmente te sacó).
    Devuelve montos y % separando 1 pago (al instante) de cuotas (3 sin interés). None si no hay MP."""
    import os, time as _t
    tk = _mp_tokens().get(email)
    token = tk.get("access_token") if tk else None
    fr = _mp_freeze_all().get(email)
    if not token and not fr:
        return None
    key = (email, desde, hasta)
    c = _MP_COST_CACHE.get(key)
    if c and (_t.time() - c[0] < 300):
        return c[1]
    # Histórico (<= FREEZE_END) del congelado; nuevo (> FREEZE_END) en vivo desde MP.
    if fr:
        _fe = _mp_freeze_end(email) or FREEZE_END
        _live_ini = _dia_post(_fe) if desde <= _fe else desde
        _run_live = hasta > _fe
        _frozen = _mp_freeze_slice(fr, desde, min(hasta, _fe))
    else:
        _live_ini = desde; _run_live = True; _frozen = []
    ini = _live_ini + "T00:00:00.000-03:00"
    fin = hasta + "T23:59:59.999-03:00"
    vol1 = cost1 = volc = costc = 0.0
    n1 = nc = 0
    offset = 0
    for p in _frozen:
        ta = float(p.get("transaction_amount") or 0)
        det = p.get("transaction_details") or {}
        net = float(det.get("net_received_amount") or 0)
        costo = (ta - net) if net else sum(float(f.get("amount") or 0)
                                           for f in (p.get("fee_details") or []))
        inst = int(p.get("installments") or 1)
        if inst <= 1:
            vol1 += ta; cost1 += costo; n1 += 1
        else:
            volc += ta; costc += costo; nc += 1
    try:
        while _run_live and token:
            r = requests.get("https://api.mercadopago.com/v1/payments/search",
                             headers={"Authorization": "Bearer " + token},
                             params={"sort": "date_approved", "criteria": "desc",
                                     "range": "date_approved", "begin_date": ini, "end_date": fin,
                                     "status": "approved", "offset": offset, "limit": 100}, timeout=30)
            if r.status_code >= 400:
                if not _frozen and offset == 0:
                    return None
                break
            data = r.json()
            res = data.get("results") or []
            for p in res:
                ta = float(p.get("transaction_amount") or 0)
                det = p.get("transaction_details") or {}
                net = float(det.get("net_received_amount") or 0)
                costo = (ta - net) if net else sum(float(f.get("amount") or 0)
                                                   for f in (p.get("fee_details") or []))
                inst = int(p.get("installments") or 1)
                if inst <= 1:
                    vol1 += ta; cost1 += costo; n1 += 1
                else:
                    volc += ta; costc += costo; nc += 1
            offset += 100
            if offset >= (data.get("paging") or {}).get("total", 0) or not res:
                break
    except Exception:
        if not _frozen:
            return None
    vol = vol1 + volc
    costo = cost1 + costc
    out = {"vol": round(vol, 2), "costo": round(costo, 2),
           "pct_total": round(costo / vol * 100, 2) if vol else 0.0,
           "pct_1pago": round(cost1 / vol1 * 100, 2) if vol1 else 0.0,
           "pct_cuotas": round(costc / volc * 100, 2) if volc else 0.0,
           "costo_1pago": round(cost1, 2), "costo_cuotas": round(costc, 2),
           "n_1pago": n1, "n_cuotas": nc}
    _MP_COST_CACHE[key] = (_t.time(), out)
    return out


@app.get("/pf-mp-costos")
def pf_mp_costos():
    """% real que te saca MercadoPago (al instante vs 3 cuotas), para mostrar en Comisiones."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    desde = request.args.get("desde") or _hoy()
    hasta = request.args.get("hasta") or desde
    mp = _mp_costos(email, desde, hasta)
    if mp is None:
        return jsonify({"ok": True, "conectado": False})
    return jsonify({"ok": True, "conectado": True, **mp})


@app.post("/pf-congelar-mp")
def pf_congelar_mp():
    """Congela TODO lo cobrado en MP hasta ?hasta (default FREEZE_END) en DATA_DIR/mp_freeze.json.
    Se corre UNA vez, con la cuenta de MP VIEJA todavía conectada, ANTES de cambiar de cuenta.
    Después, cualquier fecha <= FREEZE_END se sirve de este snapshot."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "error": "sin sesión"})
    token = (_mp_tokens().get(email) or {}).get("access_token")
    if not token:
        return jsonify({"ok": False, "error": "MP no conectado en esta cuenta"})
    hasta = request.args.get("hasta") or FREEZE_END
    fin = hasta + "T23:59:59.999-03:00"
    guardados, offset = [], 0
    try:
        while True:
            r = requests.get("https://api.mercadopago.com/v1/payments/search",
                             headers={"Authorization": "Bearer " + token},
                             params={"sort": "date_approved", "criteria": "asc",
                                     "range": "date_approved",
                                     "begin_date": "2020-01-01T00:00:00.000-03:00",
                                     "end_date": fin, "status": "approved",
                                     "offset": offset, "limit": 100}, timeout=45)
            if r.status_code >= 400:
                return jsonify({"ok": False, "error": "MP HTTP %s" % r.status_code})
            data = r.json()
            res = data.get("results") or []
            for p in res:
                det = p.get("transaction_details") or {}
                guardados.append({
                    "date_approved": p.get("date_approved"),
                    "transaction_amount": p.get("transaction_amount"),
                    "transaction_details": {"net_received_amount": det.get("net_received_amount")},
                    "fee_details": [{"type": f.get("type"), "amount": f.get("amount")}
                                    for f in (p.get("fee_details") or [])],
                    "installments": p.get("installments"),
                    "external_reference": p.get("external_reference"),
                    "payment_method_id": p.get("payment_method_id"),
                    "payment_type_id": p.get("payment_type_id"),
                })
            offset += 100
            if offset >= (data.get("paging") or {}).get("total", 0) or not res:
                break
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)[:140]})
    allf = _mp_freeze_all()
    allf[email] = guardados
    global _MP_FREEZE_CACHE
    _MP_FREEZE_CACHE = allf
    try:
        _MP_FREEZE_FILE.write_text(_json.dumps(allf, ensure_ascii=False), encoding="utf-8")
    except Exception as e:
        return jsonify({"ok": False, "error": "no se pudo guardar: %s" % str(e)[:100]})
    _MP_COST_CACHE.clear()
    try:
        _MP_LISTA_CACHE.clear()
    except Exception:
        pass
    return jsonify({"ok": True, "email": email, "pagos": len(guardados), "hasta": hasta})


@app.post("/pf-cambiar-mp")
def pf_cambiar_mp():
    """Cambio de cuenta de MercadoPago. Congela el histórico de la cuenta ACTUAL hasta el día
    ANTERIOR a ?fecha y guarda la fecha de switch. Desde las 00:00 de ?fecha se costea con el MP
    nuevo. Después el frontend redirige al OAuth (/conectar-mp) para conectar la cuenta nueva."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "error": "sin sesión"})
    fecha = (request.args.get("fecha") or request.form.get("fecha") or "").strip()
    try:
        fd = _dt.date.fromisoformat(fecha)
    except Exception:
        return jsonify({"ok": False, "error": "Elegí una fecha válida."})
    hoy = (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).date()
    if fd < hoy - _dt.timedelta(days=3):
        return jsonify({"ok": False, "error": "La fecha no puede ser más de 3 días para atrás."})
    if fd > hoy + _dt.timedelta(days=90):
        return jsonify({"ok": False, "error": "La fecha es demasiado lejana."})
    hasta = _dia_ant(fecha)   # el congelado cubre hasta el día anterior a la fecha de switch
    # Anti-duplicado: si YA hay un congelado que cubre hasta esa fecha, NO se vuelve a bajar
    # (no duplica y NO re-congela desde otra cuenta si ya cambiaste). Solo actualiza la fecha.
    fr_prev = _mp_freeze_all().get(email)
    ult_prev = max(((p.get("date_approved") or "")[:10] for p in fr_prev), default="") if fr_prev else ""
    if fr_prev and ult_prev and ult_prev >= hasta:
        sw = _mp_switch(); sw[email] = fecha; _mp_save_switch(sw)
        _MP_COST_CACHE.clear()
        try:
            _MP_LISTA_CACHE.clear()
        except Exception:
            pass
        return jsonify({"ok": True, "email": email, "pagos": len(fr_prev), "fecha": fecha,
                        "congelado_hasta": hasta, "reuso": True})
    token = (_mp_tokens().get(email) or {}).get("access_token")
    if not token:
        return jsonify({"ok": False, "error": "No hay un MercadoPago conectado para congelar."})
    fin = hasta + "T23:59:59.999-03:00"
    guardados, offset = [], 0
    try:
        while True:
            r = requests.get("https://api.mercadopago.com/v1/payments/search",
                             headers={"Authorization": "Bearer " + token},
                             params={"sort": "date_approved", "criteria": "asc", "range": "date_approved",
                                     "begin_date": "2020-01-01T00:00:00.000-03:00", "end_date": fin,
                                     "status": "approved", "offset": offset, "limit": 100}, timeout=45)
            if r.status_code >= 400:
                return jsonify({"ok": False, "error": "MP HTTP %s" % r.status_code})
            data = r.json(); res = data.get("results") or []
            for p in res:
                det = p.get("transaction_details") or {}
                guardados.append({
                    "date_approved": p.get("date_approved"),
                    "transaction_amount": p.get("transaction_amount"),
                    "transaction_details": {"net_received_amount": det.get("net_received_amount")},
                    "fee_details": [{"type": f.get("type"), "amount": f.get("amount")} for f in (p.get("fee_details") or [])],
                    "installments": p.get("installments"),
                    "external_reference": p.get("external_reference"),
                    "payment_method_id": p.get("payment_method_id"),
                    "payment_type_id": p.get("payment_type_id"),
                })
            offset += 100
            if offset >= (data.get("paging") or {}).get("total", 0) or not res:
                break
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)[:140]})
    global _MP_FREEZE_CACHE
    allf = _mp_freeze_all(); allf[email] = guardados; _MP_FREEZE_CACHE = allf
    try:
        _MP_FREEZE_FILE.write_text(_json.dumps(allf, ensure_ascii=False), encoding="utf-8")
    except Exception as e:
        return jsonify({"ok": False, "error": "no se pudo guardar: %s" % str(e)[:100]})
    sw = _mp_switch(); sw[email] = fecha; _mp_save_switch(sw)
    _MP_COST_CACHE.clear()
    try:
        _MP_LISTA_CACHE.clear()
    except Exception:
        pass
    return jsonify({"ok": True, "email": email, "pagos": len(guardados), "fecha": fecha, "congelado_hasta": hasta})


