@app.get("/pf-pedidos-cero")
def pf_pedidos_cero():
    """Los pedidos en $0 del periodo con el MOTIVO que dejo atencion en la nota.
    No son ventas (no facturan), pero cuestan el producto, el envio y el fulfillment:
    por eso hay que poder verlos y saber por que se cargaron. Solo lectura."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 400
    tk = _shop_tokens().get(email)
    if not tk or not tk.get("access_token"):
        return jsonify({"ok": False, "msg": "Shopify no conectado"})
    desde = request.args.get("desde") or (_dt.date.today() - _dt.timedelta(days=30)).isoformat()
    hasta = request.args.get("hasta") or _hoy()
    shop, token = tk["shop"], tk["access_token"]
    H = {"X-Shopify-Access-Token": token}
    url = "https://%s/admin/api/2026-07/orders.json" % shop
    params = {"status": "any", "limit": 250,
              "created_at_min": desde + "T00:00:00-03:00",
              "created_at_max": hasta + "T23:59:59-03:00",
              "fields": ("id,order_number,name,total_price,current_total_price,financial_status,"
                         "cancelled_at,created_at,line_items,note,note_attributes,tags,customer,"
                         "shipping_address,shipping_lines,gateway,payment_gateway_names")}
    orders = []
    for _ in range(40):
        try:
            r = requests.get(url, headers=H, params=params, timeout=30)
        except Exception as e:
            return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:90])})
        if r.status_code != 200:
            return jsonify({"ok": False, "msg": "Shopify devolvio %s" % r.status_code})
        orders.extend(r.json().get("orders", []))
        link = r.headers.get("Link", "") or r.headers.get("link", "")
        nxt = None
        for part in link.split(","):
            if 'rel="next"' in part and "<" in part and ">" in part:
                nxt = part[part.find("<") + 1:part.find(">")]
        if not nxt:
            break
        url, params = nxt, None
    costos = (_costos().get(email) or {})
    emap = _envialo_costos(email)
    out = []
    for o in orders:
        if o.get("cancelled_at"):
            continue
        tot = float(o.get("total_price") or o.get("current_total_price") or 0)
        if tot > 0:
            continue
        num = str(o.get("order_number") or o.get("name") or "").replace("#", "").strip()
        cp = un = 0
        prods = []
        for li in (o.get("line_items") or []):
            q = int(li.get("quantity") or 0)
            un += q
            c = costos.get(str(li.get("product_id") or ""))
            if c:
                cp += _costo_qty(c, q)
            prods.append("%s x%d" % ((li.get("title") or "?")[:40], q))
        env = emap.get(num)
        env_fuente = "real"
        if env is None:
            env = _envio_costo(o); env_fuente = "promedio"
        cust = o.get("customer") or {}
        nota = (o.get("note") or "").strip()
        for na in (o.get("note_attributes") or []):
            if na.get("value"):
                nota += ((" · " if nota else "") + "%s: %s" % (na.get("name"), na.get("value")))
        out.append({"pedido": num, "fecha": (o.get("created_at") or "")[:16].replace("T", " "),
                    "cliente": ((cust.get("first_name") or "") + " " + (cust.get("last_name") or "")).strip()
                               or (o.get("shipping_address") or {}).get("name", ""),
                    "estado": o.get("financial_status") or "",
                    "unidades": un, "costo_prod": round(cp, 2),
                    "envio": round(float(env or 0), 2), "envio_fuente": env_fuente,
                    "fulfillment": OPER_ORDEN,
                    "perdida": round(cp + float(env or 0) + OPER_ORDEN, 2),
                    "tags": o.get("tags") or "", "nota": nota[:400],
                    "productos": ", ".join(prods)[:200]})
    out.sort(key=lambda x: x["fecha"], reverse=True)
    return jsonify({"ok": True, "desde": desde, "hasta": hasta, "n": len(out),
                    "perdida_total": round(sum(x["perdida"] for x in out), 2),
                    "unidades_total": sum(x["unidades"] for x in out),
                    "pedidos": out})


@app.get("/pf-debug-meli")
def pf_debug_meli():
    """Desglose REAL de cada venta de MercadoLibre, para auditarla igual que las de la tienda.
    Junta las DOS fuentes que existen:
      - la orden de ML: total, items, sale_fee por item, envio, cupon;
      - el pago en MercadoPago: comision, cuotas y RETENCIONES de IIBB (charges_details).
    El segundo pedazo hoy NO entra en ningun calculo: _meli_resumen solo mira el sale_fee de ML.
    Este endpoint existe para medir cuanto es lo que falta antes de tocar la ganancia."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    desde = request.args.get("desde") or _hoy()
    hasta = request.args.get("hasta") or desde
    n = int(request.args.get("n") or 10)
    tok, uid = _meli_ctx(email)
    if not tok or not uid:
        return jsonify({"ok": True, "meli": False})
    h = {"Authorization": "Bearer " + tok}
    ordenes = []
    try:
        off = 0
        for _ in range(200):          # mismo criterio que _meli_resumen: paginar hasta agotar
            rr = requests.get("%s/orders/search" % MELI_API, headers=h, timeout=25, params={
                "seller": uid, "sort": "date_desc", "limit": 50, "offset": off,
                "order.date_created.from": desde + "T00:00:00.000-03:00",
                "order.date_created.to": hasta + "T23:59:59.000-03:00"})
            if rr.status_code >= 400:
                break
            jj = rr.json() or {}
            ordenes += (jj.get("results") or [])
            off += 50
            if off >= int((jj.get("paging") or {}).get("total") or 0):
                break
    except Exception as e:
        return jsonify({"ok": False, "error": "%s: %s" % (type(e).__name__, str(e)[:120])})
    # pagos de MP del periodo: aca SI me quedo con los de MELI (ref de 16 digitos que arranca 2000)
    pagos = _mp_pagos_lista(email, desde, hasta) or []
    mp_ml = {}
    for p in pagos:
        if _mp_es_de_meli(p.get("ref")):
            mp_ml[str(p.get("ref"))] = p
    costos = (_costos().get(email) or {})
    out = []
    tot_fee_ml = tot_fee_mp = tot_ret = tot_env = tot_cup = 0.0
    for o in ordenes:
        if (o.get("status") or "").lower() != "paid":
            continue
        oid = str(o.get("id") or "")
        tot = float(o.get("total_amount") or 0)
        com = 0.0
        items = []
        cp = 0.0
        for it in (o.get("order_items") or []):
            q = int(it.get("quantity") or 0)
            sf = float(it.get("sale_fee") or 0)
            com += sf * q
            itm = it.get("item") or {}
            sku = str(itm.get("seller_sku") or itm.get("seller_custom_field") or "").strip()
            items.append({"titulo": (itm.get("title") or "")[:44], "cant": q, "sku": sku,
                          "precio": float(it.get("unit_price") or 0), "sale_fee_u": round(sf, 2)})
            c = costos.get("meli:%s" % sku) if sku else None
            if c:
                cp += _costo_qty(c, q)
            else:
                _b = costos.get("meli:POTE")
                if _b:
                    cp += _costo_num(_b) * (_meli_units_from_sku(sku) if sku else 1) * q
        # lo que informan los PAGOS de la orden (ML los trae adentro)
        env_ml = cup = tax_ml = 0.0
        for pg in (o.get("payments") or []):
            env_ml += float(pg.get("shipping_cost") or 0)
            cup += float(pg.get("coupon_amount") or 0)
            tax_ml += float(pg.get("taxes_amount") or 0)
        pm = mp_ml.get(oid)
        tot_fee_ml += com; tot_env += env_ml; tot_cup += cup
        if pm:
            tot_fee_mp += float(pm.get("fee") or 0)
            tot_ret += float(pm.get("ret") or 0)
        out.append({"orden": oid, "total": round(tot, 2), "items": items,
                    "comision_ml": round(com, 2), "pct_comision": round(com / tot * 100, 2) if tot else 0,
                    "costo_prod": round(cp, 2), "envio_ml": round(env_ml, 2),
                    "cupon": round(cup, 2), "impuestos_ml": round(tax_ml, 2),
                    "mp_encontrado": bool(pm),
                    "mp_fee": round(float(pm.get("fee") or 0), 2) if pm else None,
                    "mp_ret": round(float(pm.get("ret") or 0), 2) if pm else None,
                    "mp_cargos": (pm.get("cargos") or {}) if pm else {},
                    "mp_neto": pm.get("net") if pm else None})
    out.sort(key=lambda x: x["orden"], reverse=True)
    return jsonify({"ok": True, "meli": True, "ordenes": out[:n], "cantidad": len(out),
                    "totales": {"comision_ml": round(tot_fee_ml, 2),
                                "mp_fee": round(tot_fee_mp, 2),
                                "mp_retenciones": round(tot_ret, 2),
                                "envio_ml": round(tot_env, 2),
                                "cupones": round(tot_cup, 2),
                                "pagos_mp_encontrados": sum(1 for x in out if x["mp_encontrado"])}})


@app.get("/pf-debug-ordenes")
def pf_debug_ordenes():
    """Detalle de costos REALES por pedido (últimos N) para verificar el cálculo pedido-por-pedido."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    n = int(request.args.get("n") or 3)
    desde = request.args.get("desde") or (_dt.date.today() - _dt.timedelta(days=10)).isoformat()
    hasta = request.args.get("hasta") or _hoy()
    tk = _shop_tokens().get(email)
    if not tk or not tk.get("access_token"):
        return jsonify({"ok": True, "shopify": False})
    try:
        orders = _shopify_orders(tk.get("shop"), tk.get("access_token"), desde, hasta)
    except Exception:
        return jsonify({"ok": False, "error": "shopify"})
    orders = [o for o in orders if not o.get("cancelled_at")]
    # MISMO filtro que el dashboard: efectivo/transferencia pendiente NO es una venta todavia.
    # Sin esto el detalle traia pedidos que el resumen no cuenta y no cerraba contra la pantalla.
    _PAG = ("paid", "partially_paid", "refunded", "partially_refunded")
    orders = [o for o in orders if (o.get("financial_status") or "").lower() in _PAG]
    orders.sort(key=lambda o: int(o.get("order_number") or 0), reverse=True)
    costos = (_costos().get(email) or {})
    emap = _envialo_costos(email)
    pagos = _mp_pagos_lista(email, desde, hasta)
    by_ref, by_amt = {}, {}
    # Los pagos de MERCADOLIBRE quedan FUERA de la bolsa de la tienda: su comision ya se cuenta
    # en meli_comision y, al entrar aca, se pegaba por monto a pedidos de Shopify del mismo
    # importe y se restaba dos veces (medido 29-09-2026: 26 pagos, $596.169 en UN dia).
    for p in (pagos or []):
        if _mp_es_de_meli(p.get("ref")):
            continue
        if p["ref"]:
            by_ref.setdefault(str(p["ref"]), []).append(p)
        by_amt.setdefault(p["amount"], []).append(p)
    out = []
    for o in orders[:n]:
        tot = float(o.get("total_price") or o.get("current_total_price") or 0)
        u = sum(int(li.get("quantity") or 0) for li in (o.get("line_items") or []))
        cp = sum(_costo_qty(costos.get(str(li.get("product_id") or "")), int(li.get("quantity") or 0))
                 for li in (o.get("line_items") or []))
        # QUE ENTRA DE VERDAD EN LA VENTA. "unidades" suma TODAS las lineas, asi que mete la guia
        # digital y el oxido nitrico que va de regalo con el pack grande: por eso aparecian ventas
        # de "8 potes" a $109.990 que en realidad son 3 potes + regalos. Para agrupar hay que
        # contar los potes de NAD aparte.
        _nad = _oxi = _dig = 0
        _det = []
        for li in (o.get("line_items") or []):
            _q = int(li.get("quantity") or 0)
            _t = (li.get("title") or "")
            _tl = _t.lower()
            if "xido" in _tl or "nitrico" in _tl or "nítrico" in _tl:
                _oxi += _q
            elif "gu" in _tl and ("ebook" in _tl or "guia" in _tl or "guía" in _tl or "dias" in _tl or "días" in _tl):
                _dig += _q
            else:
                _nad += _q
            _det.append({"producto": _t[:46], "cant": _q})
        num = str(o.get("order_number") or o.get("name") or "").replace("#", "").strip()
        # envío real o promedio
        env = emap.get(num)
        env_fuente = "envialo" if env is not None else "promedio"
        if env is None:
            env = _envio_costo(o)
        # match MP. Se anota COMO matcheo: por referencia (confiable) o por monto (puede cruzarse
        # con otro pedido del mismo precio, que es lo que pasa con precios fijos).
        pago = None; _como = "sin match"; _ref_usada = ""
        if pagos is not None:
            for ref in (str(o.get("checkout_token") or ""), str(o.get("checkout_id") or ""),
                        str(o.get("id")), str(o.get("order_number")), num):
                if not ref:
                    continue
                lst = by_ref.get(ref)
                if lst:
                    pago = lst.pop(0); _como = "referencia"; _ref_usada = ref; break
            if pago is None:
                pago = _mp_tomar_cercano(by_amt.get(round(tot)), o.get("created_at"))
                if pago is not None:
                    _como = "monto+hora"
        mp_fee = pago["fee"] if pago else 0.0
        mp_neto = pago["net"] if pago else None
        mp_ret = (pago.get("ret") or 0.0) if pago else 0.0      # IIBB/Ganancias ya retenidos
        mp_cargos = (pago.get("cargos") or {}) if pago else {}
        mp_lib = (pago.get("lib") or "") if pago else ""       # cuando se libera la plata
        iibb = tot * IIBB_PCT / 100.0
        tienda = tot * TIENDA_PCT / 100.0
        gan = tot - cp - mp_fee - mp_ret - env - iibb - tienda - OPER_ORDEN
        # IVA DE ESTA VENTA, con los numeros de ESTA venta (nada de promedios del periodo).
        # Debito: el 10,5% contenido en lo que cobraste (alicuota reducida). Credito: el 21%
        # contenido en producto, envio y comision de MercadoPago — esa tasa la pone quien
        # factura. El 0,6% de Shopify y el fulfillment NO dan credito.
        iva_deb = tot * _IVA_F_VTA                       # lo que el COBRA: 10,5%
        iva_cred = (cp + env + mp_fee) * _IVA_F_CMP      # lo que le COBRAN: 21%
        iva_pag = iva_deb - iva_cred
        # BREAK EVEN DE ESTA VENTA: lo maximo que se puede pagar de publicidad por traerla.
        # Pagando exactamente esto, esta venta da CERO. Un pack de 3 deja mas que uno de 1, por
        # eso el numero es POR VENTA y no un promedio del dia.
        be = tot - cp - mp_fee - mp_ret - env - iibb - tienda - OPER_ORDEN - iva_pag
        out.append({"pedido": num, "total": round(tot, 2), "unidades": u,
                    "costo_prod": round(cp, 2), "mp_fee": round(mp_fee, 2),
                    "mp_neto_recibido": (round(mp_neto, 2) if mp_neto is not None else None),
                    "mp_matcheo": ("ok" if pago else "SIN MATCH"),
                    "mp_ret": round(mp_ret, 2), "mp_cargos": mp_cargos, "mp_liberado": mp_lib, "mp_como": _como, "mp_ref_usada": _ref_usada,
                    "tok_checkout": o.get("checkout_token"), "tok_cart": o.get("cart_token"),
                    "tok_order": o.get("token"), "checkout_id": o.get("checkout_id"),
                    "mp_ref_pago": ((pago or {}).get("ref") or ""),
                    "mp_cuotas": ((pago or {}).get("inst") or 0),
                    "mp_medio": ((pago or {}).get("medio") or ""),
                    "envio": round(env, 2), "envio_fuente": env_fuente,
                    "oper": OPER_ORDEN,
                    "iibb": round(iibb, 2), "tienda": round(tienda, 2),
                    "potes_nad": _nad, "oxido": _oxi, "digital": _dig, "detalle": _det,
                    "iva_debito": round(iva_deb, 2), "iva_favor": round(iva_cred, 2),
                    "iva_pagar": round(iva_pag, 2),
                    "break_even": round(be, 2),
                    "ganancia": round(gan, 2)})
    # Resumen POR PACK: dentro de un pack el precio y el producto son iguales, lo unico que
    # cambia es la zona del envio y en cuantas cuotas pago. Por eso se muestran el minimo, el
    # maximo y la mediana REALES, no un promedio que no le corresponde a ninguna venta.
    import statistics as _st
    packs = {}
    for x in out:
        k = int(x.get("potes_nad") or 0)      # por POTES DE NAD, no por lineas del pedido
        packs.setdefault(k, []).append(x)
    resumen = []
    for k in sorted(packs):
        bes = sorted(y["break_even"] for y in packs[k])
        resumen.append({"potes_nad": k, "ventas": len(bes),
                        "con_oxido": sum(1 for y in packs[k] if y.get("oxido")),
                        "con_guia": sum(1 for y in packs[k] if y.get("digital")),
                        "be_min": round(bes[0], 2), "be_max": round(bes[-1], 2),
                        "be_mediana": round(_st.median(bes), 2),
                        "ticket": round(_st.median([y["total"] for y in packs[k]]), 2)})
    return jsonify({"ok": True, "shopify": True, "mp_conectado": pagos is not None,
                    "por_pack": resumen, "ordenes": out})


_IMG_CACHE = {}


def _shop_img(shop, token, product_id):
    """URL de la foto de un producto de Shopify (cacheada). '' si no hay."""
    pid = str(product_id or "").strip()
    if not pid:
        return ""
    if pid in _IMG_CACHE:
        return _IMG_CACHE[pid]
    url = ""
    try:
        r = requests.get("https://%s/admin/api/2026-07/products/%s.json" % (shop, pid),
                         headers={"X-Shopify-Access-Token": token},
                         params={"fields": "id,image,images"}, timeout=15)
        if r.status_code == 200:
            p = (r.json() or {}).get("product") or {}
            url = ((p.get("image") or {}).get("src")
                   or ((p.get("images") or [{}])[0] or {}).get("src") or "")
    except Exception:
        pass
    _IMG_CACHE[pid] = url
    return url


# ==================== STOCK (inventario) ====================
STOCK_FILE = DATA_DIR / "stock.json"           # {email: {pid: {nombre,unidad,stock,costo,sku}}}
STOCK_LEDGER = DATA_DIR / "stock_ledger.json"  # {email: {order_key: {delta:{pid:qty}, estado}}}
STOCK_PEDIDOS = DATA_DIR / "stock_pedidos.json"  # {email: [{id,pid,qty,fecha,estado}]}


def _stk_read(path, default):
    """Lee el JSON; si quedo cortado, cae al .bak en vez de devolver vacio.
    Antes devolvia {} ante cualquier error: si el proceso moria a mitad de una escritura
    (Render reiniciando / 502), el archivo quedaba truncado y el stock se perdia EN SILENCIO."""
    for p in (path, path.with_suffix(path.suffix + ".bak")):
        try:
            t = p.read_text(encoding="utf-8")
            if t.strip():
                return _json.loads(t)
        except Exception:
            continue
    return default


def _stk_write(path, data):
    """Escritura ATOMICA: escribe un .tmp y recien ahi reemplaza (os.replace es atomico).
    Deja la version anterior en .bak. Si el proceso muere a mitad, el archivo bueno sigue
    intacto: nunca queda un JSON truncado."""
    path.parent.mkdir(parents=True, exist_ok=True)
    txt = _json.dumps(data, ensure_ascii=False, indent=1)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(txt, encoding="utf-8")
    try:
        if path.exists():
            _os.replace(str(path), str(path.with_suffix(path.suffix + ".bak")))
    except Exception:
        pass
    _os.replace(str(tmp), str(path))


STOCK_SNAP = DATA_DIR / "stock_snap.json"   # {email: {pid: {"YYYY-MM-DD": stock_al_cierre}}}


def _stock_snap_set(email, prods):
    """Con cuanto stock quedo cada dia. Se registra en CADA lectura, asi el ultimo valor
    anotado de un dia queda como su cierre (a las 00 rota el dia y el de ayer queda fijo)."""
    try:
        hoy = (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).date().isoformat()
        sn = _stk_read(STOCK_SNAP, {})
        e = sn.setdefault(email, {})
        for pid, p in (prods or {}).items():
            d = e.setdefault(str(pid), {})
            d[hoy] = int(p.get("stock") or 0)
            if len(d) > 400:
                for k in sorted(d)[:-400]:
                    d.pop(k, None)
        _stk_write(STOCK_SNAP, sn)
    except Exception:
        pass


def _stock_orders(email, dias=90):
    """Pedidos recientes (TN + Shopify) -> [{key, pid_qty, estado, fecha}].
    estado: paid | pending | refunded | cancelled."""
    desde = (_dt.datetime.utcnow() - _dt.timedelta(days=dias)).date().isoformat()
    out = []
    tk = _tn_tokens().get(email)
    if tk and tk.get("access_token") and tk.get("store_id"):
        store, hdr = tk["store_id"], _tn_headers(tk["access_token"])
        page = 1
        while page <= 14:
            try:
                r = requests.get("%s/%s/orders" % (TN_API, store), headers=hdr,
                                 params={"per_page": 50, "page": page,
                                         "created_at_min": desde + "T00:00:00-03:00",
                                         "fields": "id,payment_status,cancelled_at,created_at,products"},
                                 timeout=30)
                lote = r.json() if r.content else []
            except Exception:
                lote = []
            if not isinstance(lote, list) or not lote:
                break
            for o in lote:
                pq = {}
                for li in (o.get("products") or []):
                    pid = "tn:%s" % li.get("product_id")
                    pq[pid] = pq.get(pid, 0) + int(li.get("quantity") or 0)
                ps = (o.get("payment_status") or "").lower()
                est = ("cancelled" if o.get("cancelled_at")
                       else "refunded" if ps in ("refunded", "voided", "partially_refunded")
                       else "paid" if ps == "paid" else "pending")
                out.append({"key": "tn:%s" % o.get("id"), "pid_qty": pq, "estado": est,
                            "fecha": str(o.get("created_at") or "")[:10]})
            if len(lote) < 50:
                break
            page += 1
    stk = _shop_tokens().get(email)
    if stk and stk.get("access_token") and stk.get("shop"):
        try:
            # PAGINADO (via _shopify_orders, que sigue el header Link). Antes se pedia
            # limit=250 SIN paginar: Shopify devolvia solo las 250 mas nuevas, que con este
            # volumen son ~3 dias, y todo lo anterior quedaba en cero. Ademas el corte caia
            # en un punto distinto cada vez que entraba un pedido, asi que el stock "saltaba"
            # solo sin que nadie lo tocara.
            import time as _tdl
            for o in _shopify_orders(stk["shop"], stk["access_token"], desde, _hoy(),
                                     deadline=_tdl.time() + 45):
                pq = {}
                for li in (o.get("line_items") or []):
                    pid = str(li.get("product_id") or "")
                    if pid:
                        pq[pid] = pq.get(pid, 0) + int(li.get("quantity") or 0)
                fs = (o.get("financial_status") or "").lower()
                est = ("cancelled" if o.get("cancelled_at")
                       else "refunded" if fs in ("refunded", "partially_refunded", "voided")
                       else "paid" if fs in ("paid", "partially_paid") else "pending")
                out.append({"key": "sh:%s" % o.get("id"), "pid_qty": pq, "estado": est,
                            "fecha": str(o.get("created_at") or "")[:10], "canal": "tienda"})
        except Exception:
            pass
    # MercadoLibre: hasta el 13/09 NO descontaba stock (solo se leia TN y Shopify), asi que los
    # potes vendidos por ML nunca se restaban del deposito. Se cuentan en POTES via el SKU.
    try:
        _tok, _uid = _meli_ctx(email)
    except Exception:
        _tok = _uid = None
    if _tok and _uid:
        _pid_ml = None
        try:
            _pr = (_stk_read(STOCK_FILE, {}).get(email) or {})
            if _pr:
                _pid_ml = sorted(_pr.items(), key=lambda kv: -int(kv[1].get("stock") or 0))[0][0]
        except Exception:
            _pid_ml = None
        if _pid_ml:
            _off = 0
            while _off < 400:
                try:
                    _r = requests.get("%s/orders/search" % MELI_API, timeout=30,
                                      headers={"Authorization": "Bearer " + _tok},
                                      params={"seller": _uid, "sort": "date_desc",
                                              "limit": 50, "offset": _off,
                                              "order.date_created.from": desde + "T00:00:00.000-03:00"})
                    _res = ((_r.json() if _r.content else {}) or {}).get("results") or []
                except Exception:
                    break
                for _o in _res:
                    _q = 0
                    for _it in (_o.get("order_items") or []):
                        _im = _it.get("item") or {}
                        _sk = str(_im.get("seller_sku") or _im.get("seller_custom_field") or "")
                        _q += _meli_units_sku(_sk)[0] * int(_it.get("quantity") or 1)
                    if not _q:
                        continue
                    _st = (_o.get("status") or "").lower()
                    _e = ("cancelled" if _st == "cancelled"
                          else "refunded" if _st in ("refunded", "partially_refunded")
                          else "paid" if _st in ("paid", "confirmed", "partially_paid") else "pending")
                    out.append({"key": "ml:%s" % _o.get("id"), "pid_qty": {_pid_ml: _q},
                                "estado": _e, "fecha": str(_o.get("date_created") or "")[:10],
                                "canal": "meli"})
                if len(_res) < 50:
                    break
                _off += 50
    return out


def _stock_sync(email):
    """Aplica ventas pagadas (descuenta) y devoluciones/cancelaciones (repone). Idempotente."""
    st = _stk_read(STOCK_FILE, {}); prods = st.get(email) or {}
    if not prods:
        return prods, []
    led = _stk_read(STOCK_LEDGER, {}); ledE = led.get(email) or {}
    orders = _stock_orders(email, 90)
    changed = False
    for o in orders:
        deltas = {}
        for _pid, _p in prods.items():
            _lp, _sp = _p.get("link_pid"), _p.get("split")
            if _lp and _sp:                                   # producto dividido 30/60 (par/impar)
                _base = o["pid_qty"].get(_lp, 0)
                _q = (_base // 2) if _sp == "60" else (_base % 2)
            else:
                _q = o["pid_qty"].get(_pid, 0)
            if _q > 0:
                deltas[_pid] = _q
        if not deltas:
            continue
        entry = ledE.get(o["key"])
        if o["estado"] == "paid" and not entry:
            for pid, q in deltas.items():
                prods[pid]["stock"] = int(prods[pid].get("stock", 0)) - q
            ledE[o["key"]] = {"delta": deltas, "estado": "paid", "fecha": o["fecha"]}
            changed = True
        elif o["estado"] in ("refunded", "cancelled") and entry and entry.get("estado") == "paid":
            for pid, q in (entry.get("delta") or {}).items():
                if pid in prods:
                    prods[pid]["stock"] = int(prods[pid].get("stock", 0)) + q
            entry["estado"] = "reverted"
            changed = True
    if changed:
        # El LEDGER primero: si el proceso muere entre las dos escrituras, la venta queda
        # marcada como aplicada y NO se vuelve a descontar. Al reves (stock primero) el
        # descuento se repetia en cada corrida y el stock se hundia solo.
        led[email] = ledE; _stk_write(STOCK_LEDGER, led)
        st[email] = prods; _stk_write(STOCK_FILE, st)
    _stock_snap_set(email, prods)
    return prods, orders


def _stock_seed(email, pid, link_pid=None):
    """Al empezar a trackear un producto, marca los pedidos ACTUALES como ya procesados
    (no retro-descuenta el histórico; solo cuentan las ventas NUEVAS). Para productos divididos
    30/60 se seedea por el producto REAL (link_pid)."""
    match = link_pid or pid
    led = _stk_read(STOCK_LEDGER, {}); ledE = led.get(email) or {}
    for o in _stock_orders(email, 120):
        if match in o["pid_qty"] and o["key"] not in ledE:
            ledE[o["key"]] = {"delta": {}, "estado": "seed"}
    led[email] = ledE; _stk_write(STOCK_LEDGER, led)


def _stock_metrics(email, pid, orders, split=None, link_pid=None):
    hoy = (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).date()   # hora ARGENTINA (UTC-3): si no, las ventas de la noche caen en "ayer" y la barra de hoy sale vacía
    dias = {}
    for o in orders:
        if o["estado"] != "paid":
            continue
        if split and link_pid:
            base = o["pid_qty"].get(link_pid, 0)          # cantidad del producto REAL en ese pedido
            q = (base // 2) if split == "60" else (base % 2)   # par/impar: 60ml=÷2, 30ml=resto impar
        else:
            q = o["pid_qty"].get(pid, 0)
        if not q:
            continue
        try:
            f = _dt.date.fromisoformat(o["fecha"])
        except Exception:
            continue
        off = (hoy - f).days
        if 0 <= off < 14:
            dias[off] = dias.get(off, 0) + q
    # mismo calculo, partido por canal (para el historial de abajo)
    dias_t, dias_m = {}, {}
    for o in orders:
        if o["estado"] != "paid":
            continue
        if split and link_pid:
            _b = o["pid_qty"].get(link_pid, 0)
            _q = (_b // 2) if split == "60" else (_b % 2)
        else:
            _q = o["pid_qty"].get(pid, 0)
        if not _q:
            continue
        try:
            _f = _dt.date.fromisoformat(o["fecha"])
        except Exception:
            continue
        _off = (hoy - _f).days
        if 0 <= _off < 14:
            if (o.get("canal") or "tienda") == "meli":
                dias_m[_off] = dias_m.get(_off, 0) + _q
            else:
                dias_t[_off] = dias_t.get(_off, 0) + _q
    ventas14 = [dias.get(13 - i, 0) for i in range(14)]
    v14_tienda = [dias_t.get(13 - i, 0) for i in range(14)]
    v14_meli = [dias_m.get(13 - i, 0) for i in range(14)]
    d14 = sum(ventas14); d7 = sum(ventas14[-7:]); d3 = sum(dias.get(off, 0) for off in range(3))
    # Promedio/día = promedio REAL de los ultimos 7 dias. Antes era max(d3/3, d7/7): agarraba
    # el pico de los ultimos 3 dias y lo proyectaba, asi que el numero saltaba solo de un dia
    # para el otro (con 499 potes en 3 dias marcaba 166/dia en vez de 71). Si no hay 7 dias de
    # datos cae a 14; d3 queda solo como referencia.
    # Ritmo: SOLO los ultimos 3 y 7 dias, promedio de ambos. Los 14 dias ya no entran: diluian
    # el ritmo de ahora con dias viejos mas flojos. Tampoco se toma el MAYOR de los dos (eso
    # agarraba el pico de 3 dias y lo proyectaba: marcaba 166/dia cuando el real era 71).
    if d3 and d7:
        rate = round((d3 / 3.0 + d7 / 7.0) / 2.0)
    elif d3:
        rate = round(d3 / 3.0)
    elif d7:
        rate = round(d7 / 7.0)
    else:
        rate = 0
    return {"ventas14": ventas14, "v14_tienda": v14_tienda, "v14_meli": v14_meli,
            "d3": d3, "d7": d7, "d14": d14, "rate": rate}


@app.get("/pf-stock")
def pf_stock():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "productos": []})
    prods, orders = _stock_sync(email)
    ped = (_stk_read(STOCK_PEDIDOS, {}).get(email) or [])
    out = []
    for pid, p in prods.items():
        m = _stock_metrics(email, pid, orders, split=p.get("split"), link_pid=p.get("link_pid"))
        pend = [x for x in ped if x.get("pid") == pid and x.get("estado") == "proceso"]
        out.append({"id": pid, "nombre": p.get("nombre", ""), "unidad": p.get("unidad", "u"),
                    "stock": int(p.get("stock", 0)), "costo": float(p.get("costo", 0)),
                    "sku": p.get("sku", ""), "ventas14": m["ventas14"],
                    "snap": ((_stk_read(STOCK_SNAP, {}).get(email) or {}).get(str(pid)) or {}),
                    "v14_tienda": m["v14_tienda"], "v14_meli": m["v14_meli"],
                    "d3": m["d3"], "d7": m["d7"],
                    "d14": m["d14"], "rate": m["rate"], "pendientes": pend,
                    "split": p.get("split", ""), "link_pid": p.get("link_pid", "")})
    return jsonify({"ok": True, "productos": out})


