def _skus_map(email) -> dict:
    try:
        return (_json.loads(SKUS_FILE.read_text(encoding="utf-8"))).get(email, {})
    except Exception:
        return {}


def _skus_save(email, m) -> None:
    try:
        d = _json.loads(SKUS_FILE.read_text(encoding="utf-8"))
    except Exception:
        d = {}
    d[email] = m
    SKUS_FILE.parent.mkdir(parents=True, exist_ok=True)
    SKUS_FILE.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")


def _sku_cfg(v) -> dict:
    """Normaliza → {'tipo','base','map'}. tipo: unitario | variable | fijo.
    Compat con lo viejo: xn→unitario, spray→variable, string→fijo."""
    if isinstance(v, dict):
        t = (v.get("tipo") or "unitario")
        t = {"xn": "unitario", "spray": "variable"}.get(t, t)
        if t not in ("unitario", "variable", "fijo"):
            t = "unitario"
        return {"tipo": t, "base": (v.get("base") or ""), "map": (v.get("map") or {})}
    if isinstance(v, str) and v.strip():
        return {"tipo": "fijo", "base": v.strip(), "map": {}}
    return {"tipo": "unitario", "base": "", "map": {}}


def _sku_calc(cfg, u: int) -> str:
    """SKU de la orden según el tipo y la cantidad comprada `u`."""
    c = _sku_cfg(cfg)
    t, b, m = c["tipo"], (c["base"] or "").strip(), (c.get("map") or {})
    if t == "variable":
        s = (str(m.get(str(int(u))) or "")).strip()
        if s:
            return s
        # Cantidad no definida en el mapa (típico q>=5, ej x6) → la COMPONGO par/impar con las
        # unidades base ya configuradas, MISMA lógica y formato que q1-q4.
        # Ej VisionPure: 1='30ML', 2='60ML' → x6 = 3x60ML = '3 60ML' (no 'x6', no 'X3 1 60ML').
        u1 = re.sub(r"^[xX]?\s*\d+\s*", "", str(m.get("1") or "").strip()).strip()  # '1 30ML'->'30ML'
        u2 = re.sub(r"^[xX]?\s*\d+\s*", "", str(m.get("2") or "").strip()).strip()  # '1 60ML'->'60ML'
        if u2 and int(u) >= 2:
            c60, c30 = divmod(int(u), 2)          # 60ml = u//2, 30ml = resto (par/impar)
            partes = []
            if c60:
                partes.append("%d %s" % (c60, u2))     # ej '3 60ML'
            if c30 and u1:
                partes.append("%d %s" % (c30, u1))     # ej '1 30ML'
            if partes:
                return " + ".join(partes)
        return "x%d" % u                           # sin unidades base → último recurso
    if t == "fijo":
        return b
    # unitario: 'xN base' (ej 'x2 Pote').
    # Si la base trae un "+" es un COMBO ("POTE+ CAPS", o "2 POTE + 1 CAPS"): se multiplica
    # CADA componente, nunca el texto entero. Mismo criterio que el armado de la etiqueta:
    # 2 combos = "x2 POTE + x2 CAPS", jamas "x2 POTE+ CAPS".
    if not b:
        return "x%d" % u
    if "+" in b:
        _ps = []
        for _tr in [t.strip() for t in b.split("+")]:
            if not _tr:
                continue
            _q = _tr.split(None, 1)
            if len(_q) == 2 and _q[0].isdigit():
                _ps.append("x%d %s" % (int(_q[0]) * int(u), _q[1].strip()))
            else:
                _ps.append("x%d %s" % (int(u), _tr))
        if _ps:
            return " + ".join(_ps)
    return ("x%d %s" % (u, b)).strip()


@app.post("/pf-sku-set")
def pf_sku_set():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    data = request.get_json(silent=True) or {}
    pid = str(data.get("pid") or "").strip()
    if not pid:
        return jsonify({"ok": False})
    tipo = (data.get("tipo") or "unitario").strip()
    tipo = {"xn": "unitario", "spray": "variable"}.get(tipo, tipo)
    if tipo not in ("unitario", "variable", "fijo"):
        tipo = "unitario"
    base = str(data.get("base") or "").strip()
    smap = {}                                          # variable: {cantidad: sku}
    for k, v in (data.get("map") or {}).items():
        if str(k).isdigit() and str(v or "").strip():
            smap[str(int(k))] = str(v).strip()
    m = _skus_map(email)
    if tipo == "variable":
        if smap:
            m[pid] = {"tipo": "variable", "base": "", "map": smap}
        else:
            m[pid] = {"tipo": "variable", "base": "", "map": {}}
    elif base:
        m[pid] = {"tipo": tipo, "base": base}
    else:
        m.pop(pid, None)                               # sin base y no-variable → limpiar
    _skus_save(email, m)
    return jsonify({"ok": True, "ejemplos": {str(n): _sku_calc(m.get(pid), n) for n in (1, 2, 3)}})


def _es_sucursal_ship(o) -> bool:
    """Shopify: sucursal por el texto del método de envío (misma regla central, nunca flipea)."""
    sl = o.get("shipping_lines") or []
    txt = " ".join(((s.get("title") or "") + " " + (s.get("code") or "")) for s in sl)
    return _txt_es_sucursal(txt)


def _solo_dig(v) -> str:
    return "".join(ch for ch in str(v or "") if ch.isdigit())


def _dni_de(o) -> str:
    """DNI real del pedido de SHOPIFY, buscando en todos los lugares donde suele venir en AR:
    note_attributes (dni/documento/cuil/cuit), y el campo 'company' del envío/facturación/cliente."""
    for na in (o.get("note_attributes") or []):
        n = (na.get("name") or "").lower()
        if any(k in n for k in ("dni", "documento", "cuil", "cuit", "identif")):
            v = _solo_dig(na.get("value"))
            if len(v) >= 7:
                return v
    # también en la nota libre del pedido
    m = _re_and.search(r'(?:dni|documento|cuil|cuit)\D{0,4}(\d{7,11})', str(o.get("note") or ""), _re_and.I)
    if m:
        return m.group(1)
    cust = o.get("customer") or {}
    for src in (_D(o.get("shipping_address")), _D(o.get("billing_address")),
                _D(cust.get("default_address"))):
        comp = _solo_dig(src.get("company"))
        if 7 <= len(comp) <= 11:
            return comp
    return ""


def _D(x):
    """Devuelve x si es dict, si no {}. CLAVE: en Tiendanube billing_address/shipping_address
    a veces vienen como STRING (no dict) → `x or {}` NO protege (un string no vacío es truthy) y
    el .get() explota (AttributeError), tirando abajo TODO el fetch de despachos. _D() lo blinda."""
    return x if isinstance(x, dict) else {}


def _tn_dni(o) -> str:
    """DNI real del pedido de TIENDANUBE (contact_identification es el campo estándar; con respaldos)."""
    cust = _D(o.get("customer"))
    for v in (o.get("contact_identification"), cust.get("identification"),
              _D(o.get("billing_address")).get("identification"),
              _D(o.get("shipping_address")).get("identification")):
        d = _solo_dig(v)
        if len(d) >= 7:
            return d
    # respaldo: buscar 'DNI 12345678' en la nota del cliente/pedido
    for txt in (o.get("note"), o.get("owner_note")):
        m = _re_and.search(r'(?:dni|documento|cuil|cuit)\D{0,4}(\d{7,11})', str(txt or ""), _re_and.I)
        if m:
            return m.group(1)
    return ""


def _despachos_orders(email, desde=None, hasta=None, refresh=False):
    """TODOS los pedidos a despachar del usuario: Shopify + Tiendanube juntos, ya
    mapeados a la MISMA forma (para que pasen por el MISMO resolver Andreani, intacto).
    DEADLINE compartido: el fetch total nunca supera ~30s → jamás lo mata el timeout de
    gunicorn (90s) → nunca 'Error de conexión' aunque una tienda esté lenta/colgada."""
    import time as _t
    # 55 y no 30: pasados los 250 pedidos sin despachar hacen falta VARIAS paginas, y con
    # 30s la ultima no llegaba. Como el paginado va de viejos a nuevos, lo que se perdia
    # eran los pedidos MAS NUEVOS (24-10-2026: faltaban 29 del dia).
    deadline = _t.time() + 55
    out = []
    sh = _despachos_orders_shopify(email, desde, hasta, refresh=refresh, deadline=deadline)
    tn = _tiendanube_orders(email, desde, hasta, refresh=refresh, deadline=deadline)
    if sh is None and tn is None:
        return None                      # ninguna tienda conectada
    if sh:
        out.extend(sh)
    if tn:
        out.extend(tn)
    out.sort(key=lambda x: int(x["num"]) if str(x["num"]).isdigit() else 0, reverse=True)
    return out


def _tn_shipping(o):
    """El envío real de un pedido de Tiendanube (tipo/opción/punto de retiro)."""
    fs = o.get("fulfillments") or []
    if fs and isinstance(fs, list) and isinstance(fs[0], dict):
        return fs[0].get("shipping") or {}
    return {}


def _tn_suc_nombre(sh):
    """String de la sucursal/HOP que eligió el cliente en Tiendanube. Se arma con la
    opción de envío + los datos del punto de retiro, para que el resolver Andreani lo
    matchee IGUAL que el título de Shopify (no cambia la lógica de sucursales)."""
    partes = [(sh.get("option") or {}).get("name") or ""]
    pd = sh.get("pickup_details") or {}
    for k in ("name", "address", "street", "number", "locality", "city", "zipcode"):
        v = pd.get(k)
        if v:
            partes.append(str(v))
    return " ".join(p for p in partes if p).strip()


def _tn_pickup(o):
    """El punto de retiro REAL que eligió el cliente. En TiendaNube viene en el pedido
    (shipping_pickup_details), NO adentro de fulfillments. Devuelve el dict o {}."""
    pd = o.get("shipping_pickup_details")
    if isinstance(pd, dict) and pd:
        return pd
    return {}


def _tn_pickup_nombre(o):
    """Nombre EXACTO de la sucursal/HOP de Andreani que eligió el cliente en TiendaNube.
    Ej: 'Andreani Punto de Retiro — PUNTO ANDREANI HOP MALABIA 781' → 'PUNTO ANDREANI HOP MALABIA 781'.
    Este es el dato posta para NO equivocar la sucursal. Si no está, cae al string genérico."""
    pd = _tn_pickup(o)
    nom = (pd.get("name") or "").strip()
    if nom:
        for sep in ("—", " - ", "–", ":"):
            if sep in nom:
                nom = nom.split(sep, 1)[1].strip()
                break
        return nom
    # sin nombre → armo con la dirección del punto (calle + localidad + CP)
    ad = _D(pd.get("address"))
    partes = [ad.get("address"), ad.get("locality") or ad.get("city"), ad.get("zipcode")]
    s = " ".join(str(p) for p in partes if p).strip()
    return s


def _tn_tel(o):
    """Primer teléfono usable del cliente de Tiendanube."""
    sa = _D(o.get("shipping_address"))
    cust = o.get("customer") or {}
    for p in (sa.get("phone"), o.get("contact_phone"), o.get("billing_phone"), cust.get("phone")):
        p = (p or "").strip()
        if p and not p.lower().startswith("no inform") and _re_and.sub(r"\D", "", p):
            return p
    return ""


def _tiendanube_orders(email, desde=None, hasta=None, refresh=False, deadline=None):
    """Pedidos de Tiendanube PAGADOS y NO despachados (por empaquetar + por enviar),
    mapeados a la MISMA forma que _despachos_orders_shopify. Devuelve None si el usuario
    no tiene Tiendanube conectada. CACHEADO (persistente) → no rebaja 40 páginas cada vez ni se cuelga."""
    tk = _tn_tokens().get(email)
    if not tk or not tk.get("access_token"):
        return None
    store, token = tk.get("store_id"), tk.get("access_token")
    if not store:
        return None
    hdr = _tn_headers(token)
    st = _desp_state(email)
    import time as _t
    ckey = "%s|%s" % (desde or "", hasta or "")
    _tn_desp_load()
    _c = _TN_DESP_CACHE.get(email)
    if (not refresh) and _c and _c.get("key") == ckey and (_t.time() - _c.get("ts", 0) < _DESP_TTL):
        for it in _c["out"]:                       # re-aplico el estado local → "marcar" se refleja SIN re-fetch
            it["estado"] = st.get(str(it["num"])) or "empaquetar"
        return _c["out"]
    out, vistos = [], set()
    filtros = [{"payment_status": "paid", "shipping_status": "unpacked"},     # por empaquetar
               {"payment_status": "paid", "shipping_status": "unfulfilled"}]  # packed → por enviar
    for filt in filtros:
        page = 1
        while page <= 5:                                   # tope 5 págs/filtro (era 20) → no se cuelga
            if deadline and _t.time() > deadline:          # presupuesto de tiempo agotado → corto (no cuelga el server)
                break
            params = {"per_page": 200, "page": page, **filt}
            if desde:
                params["created_at_min"] = desde + "T00:00:00-03:00"
            if hasta:
                params["created_at_max"] = hasta + "T23:59:59-03:00"
            try:
                r = requests.get("%s/%s/orders" % (TN_API, store), headers=hdr,
                                 params=params, timeout=12)                # era 40s → 12s (no cuelga el hilo)
                lote = r.json() if r.content else []
            except Exception:
                lote = []
            if not isinstance(lote, list) or not lote:
                break
            for o in lote:
                num = str(o.get("number") or "")
                if not num or num in vistos:
                    continue
                vistos.add(num)
                if o.get("cancelled_at"):
                    continue
                if (o.get("payment_status") or "") != "paid":
                    continue
                unidades = sum(int(p.get("quantity") or 0) for p in (o.get("products") or []))
                if unidades == 0:                       # ebook-only → no se despacha
                    continue
                sh = _tn_shipping(o)
                # Sucursal si TiendaNube lo marca pickup (campo del pedido/envío) O si el método dice
                # sucursal/"Punto de retiro" (texto, misma regla central). Por defecto domicilio →
                # nunca flipeamos un domicilio a sucursal (si el método dice 'domicilio', gana domicilio).
                # Punto de retiro REAL que eligió el cliente (viene en shipping_pickup_details del pedido).
                pk = _tn_pickup(o)
                suc_nom = _tn_pickup_nombre(o)                 # nombre EXACTO de la sucursal Andreani
                es_suc = ((o.get("shipping_pickup_type") == "pickup") or (sh.get("type") == "pickup")
                          or bool(pk)
                          or _txt_es_sucursal((o.get("shipping_option") or "") + " " + suc_nom))
                sa = _D(o.get("shipping_address"))
                cust = o.get("customer") or {}
                nombre = (sa.get("name") or o.get("contact_name") or cust.get("name") or "—")
                # TiendaNube trae calle y número en campos SEPARADOS → los uso tal cual (no adivino).
                calle = str(sa.get("address") or "").strip()
                numero = str(sa.get("number") or "").strip()
                floor = str(sa.get("floor") or "").strip()
                # Para SUCURSAL, la localidad/CP posta son las del PUNTO (el shipping_address suele venir "No informado").
                pkad = _D(pk.get("address"))
                localidad = ((pkad.get("locality") or pkad.get("city")) if es_suc and pkad else "") or (sa.get("locality") or sa.get("city") or "").strip()
                cp = (str(pkad.get("zipcode") or "") if es_suc and pkad else "") or str(sa.get("zipcode") or "").strip()
                prov = ((pkad.get("province") or "") if es_suc and pkad else "") or (sa.get("province") or "").strip()
                # Coordenadas EXACTAS del punto elegido + id del punto (para resolver la sucursal sin adivinar)
                suc_lat = pkad.get("latitude") or pkad.get("lat") or ""
                suc_lng = pkad.get("longitude") or pkad.get("lng") or pkad.get("lon") or ""
                suc_pid = str(o.get("shipping_option_reference") or "")
                tel = _tn_tel(o)
                dni = _tn_dni(o)
                incompleta = (not es_suc) and (not calle or not cp or not tel)
                estado = st.get(num) or "empaquetar"
                out.append({
                    "tienda": "tn", "num": num, "nombre": (nombre or "").strip(),
                    "tipo": "sucursal" if es_suc else "domicilio",
                    "localidad": localidad, "cp": cp, "provincia": prov, "unidades": unidades,
                    "total": round(float(o.get("total") or 0), 2),
                    "tel": tel, "dni": dni, "fecha": o.get("created_at") or o.get("completed_at") or "",
                    "email": o.get("contact_email") or (cust.get("email") or ""),
                    "suc_nombre": suc_nom or _tn_suc_nombre(sh), "calle": calle, "numero": numero, "extra": floor,
                    "suc_lat": suc_lat, "suc_lng": suc_lng, "suc_pid": suc_pid,
                    "incompleta": incompleta, "estado": estado,
                })
            if len(lote) < 200:
                break
            page += 1
    out.sort(key=lambda x: int(x["num"]) if str(x["num"]).isdigit() else 0, reverse=True)
    _TN_DESP_CACHE[email] = {"key": ckey, "ts": _t.time(), "out": out}
    _tn_desp_save()
    return out


_DESP_CACHE = {}      # {email: {"key": (desde,hasta), "ts": epoch, "orders": [...]}} — cachea lo LENTO (traer de Shopify)
_DESP_TTL = 600       # 10 min. Abrir/recargar Despachos usa el caché (instantáneo); "Sincronizar" lo refresca.
_DESP_CACHE_FILE = DATA_DIR / "desp_cache.json"   # persiste el caché → tras un DEPLOY, Despachos carga al toque (no rebaja todo)
_DESP_LOADED = False


def _desp_cache_load():
    """Carga el caché de despachos desde disco (una vez) → sobrevive reinicios/deploys."""
    global _DESP_LOADED
    if _DESP_LOADED:
        return
    _DESP_LOADED = True
    try:
        d = _json.loads(_DESP_CACHE_FILE.read_text(encoding="utf-8"))
        if isinstance(d, dict):
            for em, v in d.items():
                if em not in _DESP_CACHE:
                    _DESP_CACHE[em] = v
    except Exception:
        pass


def _desp_cache_save():
    try:
        _DESP_CACHE_FILE.write_text(_json.dumps(_DESP_CACHE), encoding="utf-8")
    except Exception:
        pass


# Caché de despachos de TiendaNube (era lo que se colgaba: 40 págs × 40s sin caché). Persistente.
_TN_DESP_CACHE = {}
_TN_DESP_FILE = DATA_DIR / "tn_desp_cache.json"
_TN_DESP_LOADED = False


def _tn_desp_load():
    global _TN_DESP_LOADED
    if _TN_DESP_LOADED:
        return
    _TN_DESP_LOADED = True
    try:
        d = _json.loads(_TN_DESP_FILE.read_text(encoding="utf-8"))
        if isinstance(d, dict):
            for em, v in d.items():
                if em not in _TN_DESP_CACHE:
                    _TN_DESP_CACHE[em] = v
    except Exception:
        pass


def _tn_desp_save():
    try:
        _TN_DESP_FILE.write_text(_json.dumps(_TN_DESP_CACHE), encoding="utf-8")
    except Exception:
        pass
# Candado: máximo N operaciones PESADAS concurrentes (Shopify/TN/PDF). Tope DEBAJO del nº de hilos
# (5 < 12) → aunque las 5 pesadas queden colgadas, SIEMPRE quedan ~7 hilos libres para navegar/abrir.
# Esto es lo que evita que el server quede muerto para todos (HTTP 000) cuando algo externo se cuelga.
_SHOP_SEM = threading.BoundedSemaphore(5)
_CARR_CACHE = {}      # {email: {"dias": n, "ts": epoch, "items": [...]}} — cachea el fetch pesado de carritos
_CARR_TTL = 300       # 5 min. Abrir/recargar Carritos usa el caché; enviar o refresh=1 lo refresca.
_SKU_PED_CACHE = {}   # {email: (ts, mapa)} — cachea los pedidos del "Insertar SKU" (no rebaja 60 días cada vez)
_SKU_PED_TTL = 300    # 5 min
_SKU_PED_FILE = DATA_DIR / "sku_ped_cache.json"   # PERSISTE a disco → un redeploy NO deja el "Insertar SKU" en frío
_SKU_PED_LOADED = False


def _sku_ped_load():
    global _SKU_PED_LOADED
    if _SKU_PED_LOADED:
        return
    _SKU_PED_LOADED = True
    try:
        d = _json.loads(_SKU_PED_FILE.read_text(encoding="utf-8"))
        for k, v in d.items():
            _SKU_PED_CACHE[k] = (v.get("ts", 0), v.get("mapa") or {})
    except Exception:
        pass


def _sku_ped_save():
    try:
        d = {k: {"ts": v[0], "mapa": v[1]} for k, v in _SKU_PED_CACHE.items()}
        _SKU_PED_FILE.parent.mkdir(parents=True, exist_ok=True)
        _SKU_PED_FILE.write_text(_json.dumps(d, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass
_WA_LOG_LOCK = threading.Lock()   # serializa la escritura del log de chats (envíos en PARALELO seguros)


def _heavy(fn):
    """Endpoints que pegan a APIs externas (envíos): a lo sumo 8 a la vez. Si está saturado, responde
    'ocupado' YA (libera el hilo) en vez de encolar → el server nunca se tilda; el front reintenta."""
    from functools import wraps as _wraps

    @_wraps(fn)
    def _w(*a, **k):
        got = _SHOP_SEM.acquire(timeout=4)
        if not got:
            return jsonify({"ok": False, "busy": True, "msg": "servidor ocupado, reintentá en unos segundos"})
        try:
            return fn(*a, **k)
        finally:
            _SHOP_SEM.release()
    return _w


def _despachos_orders_shopify(email, desde=None, hasta=None, refresh=False, deadline=None):
    """Órdenes de Shopify PAGADAS y NO despachadas (para despachar por Andreani).
    Solo entran las PAGADAS (si no está paga, no aparece). Filtra por fecha si se pasa desde/hasta.
    Los pedidos crudos de Shopify se CACHEAN (lo lento); la lista final se rearma siempre (rápido)
    con el estado local actualizado. refresh=True fuerza volver a bajar todo."""
    import time as _t
    tk = _shop_tokens().get(email)
    if not tk or not tk.get("access_token"):
        return None
    shop, token = tk.get("shop"), tk.get("access_token")
    ckey = "todo"        # UNA sola clave: las fechas se filtran abajo, en Python (ver nota)
    _desp_cache_load()                    # trae el caché de disco (tras deploy) → carga instantánea
    _c = _DESP_CACHE.get(email)
    orders = None
    _got = False
    if (not refresh) and _c and _c.get("key") == ckey and (_t.time() - _c.get("ts", 0) < _DESP_TTL):
        orders = _c.get("orders")                            # caché fresco → NO vuelve a pegarle a Shopify
    if orders is None:
        _got = _SHOP_SEM.acquire(timeout=3)
    if orders is None and not _got:
        # Shopify saturado/throttleado (muchas llamadas en curso) → uso el último caché si hay, sin colgar
        # el hilo esperando. Mejor mostrar lo último conocido que dejar la web tildada.
        if _c and _c.get("orders") is not None:
            orders = _c["orders"]
        else:
            return None
    if orders is None:                     # conseguí lugar en el candado → bajo de Shopify
        try:
            # Sin created_at_min/max a proposito: se baja el set completo una sola vez y las
            # pestanias (Hoy / Ayer / 7 dias) se resuelven filtrando en Python, mas abajo.
            _POR_PAG = 250          # con el cursor las paginas vienen llenas: menos vueltas
            params = {"status": "open", "financial_status": "paid",
                      "fulfillment_status": "unshipped", "limit": _POR_PAG,
                      "fields": "id,order_number,name,total_price,current_total_price,"
                                "financial_status,fulfillment_status,cancelled_at,line_items,"
                                "note,created_at,shipping_lines,shipping_address,customer,contact_email,"
                                "note_attributes,fulfillments"}
            orders = []
            # PAGINADO CON EL CURSOR DE SHOPIFY (cabecera Link rel="next").
            # Antes se paginaba con since_id y se cortaba cuando una pagina traia menos
            # items que el limite. Con el filtro fulfillment_status eso es FALSO: Shopify
            # devuelve paginas incompletas aunque queden mas, asi que cortaba en la primera
            # (con limit 250 daba 248, con 100 daba 99) y se perdian justo los pedidos mas
            # nuevos. El cursor no tiene ese problema: se sigue hasta que no hay "next".
            _completo = False
            _url = "https://%s/admin/api/2026-07/orders.json" % shop
            _pars = params
            try:
                for _ in range(40):
                    if deadline and _t.time() > deadline:            # presupuesto agotado → incompleto
                        break
                    r = requests.get(_url, headers={"X-Shopify-Access-Token": token},
                                     params=_pars, timeout=20)
                    if r.status_code >= 400:
                        raise RuntimeError("Shopify HTTP %s" % r.status_code)
                    orders.extend((r.json() or {}).get("orders") or [])
                    _next = ""
                    for _tr in (r.headers.get("Link") or "").split(","):
                        if 'rel="next"' in _tr and "<" in _tr and ">" in _tr:
                            _next = _tr[_tr.find("<") + 1:_tr.find(">")]
                    if not _next:
                        _completo = True                             # no hay mas paginas
                        break
                    _url, _pars = _next, None    # la URL del cursor ya trae todos los filtros
            except Exception:
                _completo = False
                if _c and _c.get("orders") is not None:
                    orders = _c["orders"]                        # si Shopify falla, uso el último caché
                else:
                    return []
        finally:
            _SHOP_SEM.release()
        # Nunca pisar un cache bueno con uno incompleto ni con uno vacio: si no se completo,
        # se muestra lo ultimo conocido pero NO se renueva la hora, asi el proximo pedido
        # reintenta en vez de esperar otros 10 minutos.
        if _completo and (orders or not (_c and _c.get("orders"))):
            _DESP_CACHE[email] = {"key": ckey, "ts": _t.time(), "orders": orders}
            _desp_cache_save()            # persisto a disco → el próximo deploy no arranca frío
    st = _desp_state(email)
    out = []
    for o in orders:
        if o.get("cancelled_at"):
            continue
        if (o.get("financial_status") or "").lower() != "paid":   # doble seguro: solo pagadas
            continue
        if desde or hasta:
            # created_at viene con el huso de la tienda (-03:00), asi que los 10 primeros
            # caracteres YA son la fecha local: el mismo corte que hacia created_at_min/max.
            _fch = str(o.get("created_at") or "")[:10]
            if desde and _fch < desde:
                continue
            if hasta and _fch > hasta:
                continue
        # PEDIDOS QUE NO SE DESPACHAN. La "Guia Digital" es descargable: Shopify la marca
        # requires_shipping=false y el pedido nunca pasa a enviado, asi que con el filtro
        # "pagado + sin despachar" quedaba ACA PARA SIEMPRE. Aparecia en todas las tandas y
        # se colaba en el Excel de Andreani sin direccion (23-10-2026, pedido #8954: la fila
        # daba 3 errores y el envio se hubiera pagado al pepe).
        # Si Shopify no manda el campo se asume que SI se despacha, para no esconder ventas.
        _lis = o.get("line_items") or []
        _lis_env = [li for li in _lis
                    if li.get("requires_shipping") is None or li.get("requires_shipping")]
        if _lis and not _lis_env:
            continue
        tiene_trk = any(f.get("tracking_number") for f in (o.get("fulfillments") or []))
        num = str(o.get("order_number") or o.get("name") or "").replace("#", "").strip()
        sa = _D(o.get("shipping_address"))
        cust = o.get("customer") or {}
        nombre = (sa.get("name") or (((cust.get("first_name") or "") + " " + (cust.get("last_name") or "")).strip())
                  or o.get("contact_email") or "—")
        suc = _es_sucursal_ship(o)
        # Solo las unidades que se despachan: en un pedido mixto la guia no va en la caja.
        unidades = sum(int(li.get("quantity") or 0) for li in _lis_env)
        localidad = sa.get("city") or ""
        cp = sa.get("zip") or ""
        prov = sa.get("province") or ""
        tel = sa.get("phone") or (cust.get("phone") or "")
        # Domicilio incompleto (sucursal no necesita dirección de casa).
        incompleta = (not suc) and (not sa.get("address1") or not cp or not tel)
        # Estado REAL: si ya tiene tracking en Shopify → enviada (aunque el estado local no lo sepa).
        # Si no, usa el estado local (exportada al generar Excel) o por defecto empaquetar.
        estado = "enviada" if tiene_trk else (st.get(num) or "empaquetar")
        out.append({
            "tienda": "shopify", "num": num, "nombre": nombre.strip(), "tipo": "sucursal" if suc else "domicilio",
            "localidad": localidad, "cp": cp, "provincia": prov, "unidades": unidades,
            "total": round(float(o.get("total_price") or o.get("current_total_price") or 0), 2),
            "tel": tel, "dni": _dni_de(o), "fecha": o.get("created_at") or "",
            "email": o.get("contact_email") or (cust.get("email") or ""),
            "suc_nombre": " ".join((s.get("title") or "") for s in (o.get("shipping_lines") or [])).strip(),
            "calle": sa.get("address1") or "", "extra": sa.get("address2") or "",
            "incompleta": incompleta, "estado": estado,
            "logistica": _logi_de(email, num, " ".join(
                (s.get("title") or "") for s in (o.get("shipping_lines") or []))),
            "logi_manual": str(num) in _logi(email),
        })
    out.sort(key=lambda x: int(x["num"]) if str(x["num"]).isdigit() else 0, reverse=True)
    return out


@app.get("/pf-despachos")
def pf_despachos_list():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "rows": []})
    desde = request.args.get("desde") or None
    hasta = request.args.get("hasta") or None
    refresh = request.args.get("refresh") in ("1", "true", "yes")
    try:
        rows = _despachos_orders(email, desde, hasta, refresh=refresh)
    except Exception as e:
        # NUNCA 500 (el front lo lee como "Error de conexión"). Devuelvo vacío + el ERROR REAL (tipo: mensaje)
        # así el front lo muestra y sabemos al toque qué falló (en vez de un genérico).
        import traceback as _tb
        _detalle = "%s: %s" % (type(e).__name__, str(e)[:200])
        _linea = ""
        try:
            _tbl = _tb.extract_tb(e.__traceback__)
            if _tbl:
                _linea = " @ %s:%d" % (_tbl[-1].name, _tbl[-1].lineno)
        except Exception:
            pass
        return jsonify({"ok": True, "shopify": True, "rows": [], "tiendas": [], "_err": True,
                        "err_detalle": _detalle + _linea,
                        "resumen": {"empaquetar": {"n": 0, "monto": 0}, "exportada": {"n": 0, "monto": 0},
                                    "enviada": {"n": 0, "monto": 0}, "todas": {"n": 0, "monto": 0}}})
    if rows is None:
        return jsonify({"ok": True, "shopify": False, "rows": []})

    def _suma(lst):
        return round(sum(r["total"] for r in lst), 2)
    grp = {e: [r for r in rows if r["estado"] == e] for e in ("empaquetar", "exportada", "enviada")}
    tiendas = []                                     # qué tiendas hay conectadas (para el selector: solo si son 2+)
    if (_shop_tokens().get(email) or {}).get("access_token"):
        tiendas.append("shopify")
    _tktn = _tn_tokens().get(email) or {}
    if _tktn.get("access_token") and _tktn.get("store_id"):
        tiendas.append("tn")
    return jsonify({"ok": True, "shopify": True, "rows": rows, "tiendas": tiendas,
                    "resumen": {
                        "empaquetar": {"n": len(grp["empaquetar"]), "monto": _suma(grp["empaquetar"])},
                        "exportada": {"n": len(grp["exportada"]), "monto": _suma(grp["exportada"])},
                        "enviada": {"n": len(grp["enviada"]), "monto": _suma(grp["enviada"])},
                        "todas": {"n": len(rows), "monto": _suma(rows)}}})


# ============================ SEGUIMIENTOS (página /seguimientos) ============================
# Qué pasó con cada envío ya despachado. Dos fuentes que el dueño YA maneja:
#   1) el PDF de etiquetas de Andreani  → pedido ↔ nº de seguimiento (lo guarda _seg_leer_run)
#   2) el Excel "EnviosPagados" del portal → nº de seguimiento ↔ ESTADO real
# Cruzando las dos sale: pedido · cliente · estado · hace cuántos días está así.
ENVIOS_EST = DATA_DIR / "envios_estado.json"     # {email: {track: {estado, desde, fecha, dest, loc}}}
ENVIOS_MAP = DATA_DIR / "envios_mapa.json"       # {email: {track: {"num":..., "nombre":...}}}
ENVIOS_PED = DATA_DIR / "envios_pedidos.json"    # {email: {nº pedido: {"nom":..., "fecha":...}}}       # {email: {track: {"num":..., "nombre":...}}}

# Estados de Andreani → color/orden. El que importa es "pendiente de ingreso":
# significa que el envío está pago pero el correo todavía NO lo recibió.
# OJO con el ORDEN: se evalúa de arriba hacia abajo y gana el primero que matchea.
# "No entregado" TIENE que ir antes que "entregado", si no un envío FALLIDO se cuenta
# como entregado (pasó: 137 entregados cuando eran 136 + 1 no entregado).
_ENV_CLASES = [
    ("no entregado", "back", "No entregado"),
    ("no  entregado","back", "No entregado"),
    ("entregado",    "ok",   "Entregado"),
    ("devolu",       "back", "En devolución"),
    ("rezago",       "back", "En rezago"),
    ("siniestr",     "back", "Con problema"),
    ("sucursal",     "suc",  "En sucursal"),
    ("retiro",       "suc",  "Para retirar"),
    ("disponible",   "suc",  "Para retirar"),
    ("camino",       "move", "En camino"),
    ("distribu",     "move", "En distribución"),
    ("transito",     "move", "En tránsito"),
    ("tránsito",     "move", "En tránsito"),
    ("ingresado",    "move", "Ingresado"),      # ya lo tiene el correo
    ("pendiente",    "wait", "Pendiente de ingreso"),
    ("ingreso",       "wait", "Pendiente de ingreso"),
]
ENV_NUEVO = "Pagado, sin despachar"     # todavía no tiene etiqueta: no existe para el correo


def _env_load(p):
    try:
        return _json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _env_save(p, d):
    try:
        p.write_text(_json.dumps(d, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass


def _env_clase(estado):
    e = (estado or "").lower()
    for k, c, _n in _ENV_CLASES:
        if k in e:
            return c
    return "otro"


def _env_guardar_mapa(email, pedidos):
    """Guarda pedido ↔ seguimiento cuando se lee el PDF de Andreani. Sin esto, el Excel de
    estados no se puede cruzar con los pedidos (el Excel NO trae el nº de pedido)."""
    if not email or not pedidos:
        return
    d = _env_load(ENVIOS_MAP)
    m = d.get(email) or {}
    for p in pedidos:
        t = str(p.get("track") or "").strip()
        n = str(p.get("num") or "").strip()
        if t and n:
            m[t] = {"num": n, "nombre": (p.get("nombre") or "").strip()[:60]}
    d[email] = m
    _env_save(ENVIOS_MAP, d)


@app.post("/pf-envios-mapa")
def pf_envios_mapa():
    """Carga en lote el cruce pedido ↔ seguimiento (el que sale de los PDFs de etiquetas).
    Sirve para sembrar el histórico de una, sin tener que re-subir PDF por PDF."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    d = request.get_json(silent=True) or {}
    pares = d.get("pares") or {}
    if not isinstance(pares, dict) or not pares:
        return jsonify({"ok": False, "msg": "mandá {'pares': {track: {'num':..,'nombre':..}}}"})
    todo = _env_load(ENVIOS_MAP)
    # reset=true REEMPLAZA el mapeo entero (para limpiar envíos que no son de esta tienda).
    m = {} if d.get("reset") else (todo.get(email) or {})
    n = 0
    for trk, v in pares.items():
        t = "".join(ch for ch in str(trk) if ch.isdigit())
        if not t:
            continue
        num = str((v or {}).get("num") or "").strip()
        if not num:
            continue
        m[t] = {"num": num, "nombre": str((v or {}).get("nombre") or "").strip()[:60]}
        n += 1
    todo[email] = m
    _env_save(ENVIOS_MAP, todo)
    return jsonify({"ok": True, "cargados": n, "total": len(m)})


@app.post("/pf-envios-estados")
def pf_envios_estados():
    """Actualiza estados en lote: {"estados": {nro_seguimiento: "Estado"}}.
    Lo usa el refrescador automático, así no hay que subir el Excel a mano."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    d = request.get_json(silent=True) or {}
    est = d.get("estados") or {}
    if not isinstance(est, dict) or not est:
        return jsonify({"ok": False, "msg": "mandá {'estados': {track: 'Estado'}}"})
    hoy = _fin_hoy_ar().isoformat()
    todo = _env_load(ENVIOS_EST)
    prev = todo.get(email) or {}
    n = cambios = 0
    for trk, e in est.items():
        t = "".join(ch for ch in str(trk) if ch.isdigit())
        e = str(e or "").strip()
        if not t or not e:
            continue
        ant = prev.get(t) or {}
        if ant.get("estado") and ant["estado"] != e:
            cambios += 1
        ant.update({"estado": e, "visto": hoy,
                    "desde": ant.get("desde") if ant.get("estado") == e else hoy})
        prev[t] = ant
        n += 1
    todo[email] = prev
    _env_save(ENVIOS_EST, todo)
    return jsonify({"ok": True, "actualizados": n, "cambios": cambios, "total": len(prev)})


@app.get("/pf-envios-activos")
def pf_envios_activos():
    """Los seguimientos que TODAVÍA pueden cambiar (no entregados). El refrescador consulta
    solo estos: un entregado ya no cambia nunca, no tiene sentido volver a preguntarle."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "activos": []}), 401
    est = (_env_load(ENVIOS_EST).get(email) or {})
    mapa = (_env_load(ENVIOS_MAP).get(email) or {})
    act = [t for t in mapa if _env_clase((est.get(t) or {}).get("estado")) != "ok"]
    return jsonify({"ok": True, "activos": act, "total_mapa": len(mapa), "con_estado": len(est)})


@app.post("/pf-envios-subir")
def pf_envios_subir():
    """Recibe el Excel 'EnviosPagados' bajado de pymes.andreani.com (Ver mis envíos → Descargar
    envíos) y actualiza el estado de cada seguimiento."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    f = request.files.get("excel") or (next(iter(request.files.values())) if request.files else None)
    if not f:
        return jsonify({"ok": False, "msg": "Subí el Excel de Andreani."})
    try:
        import openpyxl
        wb = openpyxl.load_workbook(f, read_only=True, data_only=True)
        ws = wb.worksheets[0]
        filas = list(ws.iter_rows(values_only=True))
        wb.close()
    except Exception as e:
        return jsonify({"ok": False, "msg": "No pude leer el archivo (%s). ¿Es el Excel de Andreani?" % type(e).__name__})
    if not filas:
        return jsonify({"ok": False, "msg": "El archivo está vacío."})
    # ubico las columnas por NOMBRE (no por posición: si Andreani las reordena, sigue andando)
    hdr = [str(h or "").strip().lower() for h in filas[0]]

    def col(*claves):
        for i, h in enumerate(hdr):
            if any(k in h for k in claves):
                return i
        return None
    i_trk = col("n° de envío", "nro de envio", "envío", "envio")
    i_est = col("estado")
    if i_trk is None or i_est is None:
        return jsonify({"ok": False, "msg": "No encontré las columnas 'N° de envío' y 'Estado'. Columnas: " + ", ".join(hdr[:8])})
    i_dst, i_fec, i_loc = col("destinatario"), col("fecha"), col("localidad")
    hoy = _fin_hoy_ar().isoformat()
    d = _env_load(ENVIOS_EST)
    prev = d.get(email) or {}
    nuevo, cambios, n = {}, 0, 0
    for r in filas[1:]:
        trk = "".join(ch for ch in str(r[i_trk] or "") if ch.isdigit())
        if not trk:
            continue
        est = str(r[i_est] or "").strip()
        ant = prev.get(trk) or {}
        # "desde" = cuándo lo vimos por primera vez EN ESE estado → de ahí salen los días parado
        desde = ant.get("desde") if ant.get("estado") == est else hoy
        if ant.get("estado") and ant.get("estado") != est:
            cambios += 1
        nuevo[trk] = {"estado": est, "desde": desde or hoy, "visto": hoy,
                      "fecha": str(r[i_fec])[:10] if i_fec is not None and r[i_fec] else ant.get("fecha", ""),
                      "dest": str(r[i_dst] or "").strip()[:60] if i_dst is not None else ant.get("dest", ""),
                      "loc": str(r[i_loc] or "").strip()[:40] if i_loc is not None else ant.get("loc", "")}
        n += 1
    prev.update(nuevo)          # no piso los viejos: el Excel puede venir filtrado por fecha
    d[email] = prev
    _env_save(ENVIOS_EST, d)
    return jsonify({"ok": True, "leidos": n, "cambios": cambios, "total": len(prev)})


@app.get("/pf-envios")
def pf_envios():
    """Una fila POR PEDIDO de Shopify, con el estado de su envío.
    La BASE son las órdenes (Shopify); el estado se le pega encima cruzando
    etiqueta (pedido↔seguimiento) + Andreani. Un pedido sin etiqueta = "Pagado, sin despachar"."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "envios": []}), 401
    est = (_env_load(ENVIOS_EST).get(email) or {})     # seguimiento → estado
    mapa = (_env_load(ENVIOS_MAP).get(email) or {})    # seguimiento → {num, nombre}
    tped = _env_load(ENVIOS_PED)
    peds = tped.get(email) or {}                       # nº pedido → {nom, fecha}
    hoy = _fin_hoy_ar()
    # Traigo EN VIVO los últimos días de Shopify y los acumulo. El caché de Despachos solo se
    # refresca cuando alguien abre esa sección, así que por sí solo deja pedidos afuera.
    try:
        tk = _shop_tokens().get(email) or {}
        if tk.get("access_token") and tk.get("shop"):
            _PAG = ("paid", "partially_paid", "refunded", "partially_refunded")
            nuevos = 0
            for o in (_shopify_orders(tk["shop"], tk["access_token"],
                                      (hoy - _dt.timedelta(days=5)).isoformat(),
                                      hoy.isoformat(), max_pages=5, timeout=20) or []):
                if o.get("cancelled_at") or (o.get("financial_status") or "").lower() not in _PAG:
                    continue
                n = str(o.get("order_number") or "").strip()
                if not n:
                    continue
                c = o.get("customer") or {}
                sa = o.get("shipping_address") or {}
                _nom = (sa.get("name") or "").strip() or \
                       ((c.get("first_name") or "") + " " + (c.get("last_name") or "")).strip() or \
                       (o.get("contact_email") or "")
                _ant = peds.get(n) or {}
                peds[n] = {"nom": _nom or _ant.get("nom", ""),
                           "fecha": (o.get("created_at") or "")[:10] or _ant.get("fecha", "")}
                nuevos += 1
            if nuevos:
                tped[email] = peds
                _env_save(ENVIOS_PED, tped)
    except Exception:
        pass
    # seguimientos de cada pedido
    por_num = {}
    for t, i in mapa.items():
        n = (i or {}).get("num")
        if n:
            por_num.setdefault(n, []).append(t)
    _ord = {"nuevo": 0, "back": 1, "wait": 2, "suc": 3, "move": 4, "otro": 5, "ok": 6}
    out = []
    for num, p in peds.items():
        tracks = por_num.get(num) or []
        # Si el pedido tiene VARIAS etiquetas (reimpresiones), la entrega manda: si alguna dice
        # Entregado, el pedido llegó. Sin esto, una etiqueta vieja que quedó "en camino" tapaba
        # la nueva ya entregada (daba 305 "en camino" cuando eran 42).
        mejor = entregado = None
        for t in tracks:
            v = est.get(t)
            if not v:
                continue
            c = _env_clase(v.get("estado"))
            if c == "ok" and entregado is None:
                entregado = (t, c, v)
            if mejor is None or _ord.get(c, 9) < _ord.get(mejor[1], 9):
                mejor = (t, c, v)
        if entregado:
            mejor = entregado
        if mejor:
            t, c, v = mejor
            base = v.get("desde") or hoy.isoformat()
            estado, track, visto, loc = v.get("estado") or "—", t, v.get("visto") or "", v.get("loc") or ""
        elif tracks:
            c, base, estado, track, visto, loc = "otro", p.get("fecha") or hoy.isoformat(), "Etiqueta hecha", tracks[0], "", ""
        else:
            c, base, estado, track, visto, loc = "nuevo", p.get("fecha") or hoy.isoformat(), ENV_NUEVO, "", hoy.isoformat(), ""
        try:
            dias = (hoy - _dt.date.fromisoformat(base[:10])).days
        except Exception:
            dias = 0
        out.append({"num": num, "cliente": p.get("nom") or "", "track": track, "estado": estado,
                    "clase": c, "loc": loc, "fecha": p.get("fecha") or "", "dias": max(dias, 0),
                    "visto": visto, "bultos": len(tracks)})
    out.sort(key=lambda x: (_ord.get(x["clase"], 9), -x["dias"]))
    cnt = {}
    for e in out:
        cnt[e["clase"]] = cnt.get(e["clase"], 0) + 1
    try:
        tienda = _botify_marca(email) or ""
    except Exception:
        tienda = ""
    return jsonify({"ok": True, "envios": out, "conteo": cnt, "total": len(out),
                    "tienda": tienda, "sin_pedido": 0})


@app.post("/pf-envios-pedidos")
def pf_envios_pedidos():
    """Carga en lote los pedidos históricos: {"pedidos": {num: {"nom":..,"fecha":..}}}."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    d = request.get_json(silent=True) or {}
    ps = d.get("pedidos") or {}
    if not isinstance(ps, dict) or not ps:
        return jsonify({"ok": False, "msg": "mandá {'pedidos': {num: {...}}}"})
    todo = _env_load(ENVIOS_PED)
    m = {} if d.get("reset") else (todo.get(email) or {})
    for n, v in ps.items():
        n = str(n).strip().lstrip("#")
        if n:
            m[n] = {"nom": str((v or {}).get("nom") or "")[:60], "fecha": str((v or {}).get("fecha") or "")[:10]}
    todo[email] = m
    _env_save(ENVIOS_PED, todo)
    return jsonify({"ok": True, "total": len(m)})


@app.get("/seguimientos")
def pagina_seguimientos():
    """Página propia: estado de cada envío despachado."""
    if not _user_actual():
        return redirect("/")
    return Response(_SEGUIMIENTOS_HTML, mimetype="text/html")


