def _seg_enviar_shopify(email, pedidos) -> dict:
    """Carga el tracking en Shopify + avisa al cliente (doble vía fulfillmentCreate /
    fulfillmentTrackingInfoUpdate). Versión SINCRÓNICA para lotes chicos (endpoint viejo): usa los
    mismos helpers que el job (/pf-despachos-seg-lanzar), con reintento ante 429/THROTTLED y la vía 2
    resuelta por GraphQL en lote (antes un GET REST por pedido: un 429 salía como falso fallo)."""
    ctx = _sege_shop_ctx(email)
    if not ctx:
        return {"ok": False, "msg": "Shopify no conectado", "enviados": 0}
    ps = [_sege_pedido_lite(p) for p in (pedidos or []) if isinstance(p, dict)]
    env = salt = fail = 0
    errores = []
    resto = []
    ya = []
    ebook = {"cerrados": 0, "errores": []}
    _eb_lock = threading.Lock()

    def _al_ebook(p, cerr, errs):          # el ebook va APARTE: nunca cambia el resultado del pedido
        with _eb_lock:
            ebook["cerrados"] += cerr
            for m in errs:
                ebook["errores"].append({"num": p.get("num"), "msg": m})
    for p in ps:
        if p.get("tn"):
            salt += 1
            ya.append(p)
        else:
            resto.append(p)
    from concurrent.futures import ThreadPoolExecutor
    for i in range(0, len(resto), 25):
        trozo = resto[i:i + 25]
        info = _sege_shop_lote(ctx, trozo)
        with ThreadPoolExecutor(max_workers=6) as ex:
            res = list(ex.map(lambda q: _sege_shop_uno(ctx, q, info.get(str(q.get("order_id"))), _al_ebook), trozo))
        for p, r in zip(trozo, res):
            if r[0] == "env":
                env += 1
            elif r[0] == "salt":
                salt += 1
            else:
                fail += 1
                errores.append({"num": p["num"], "msg": r[1] or "error"})
    if ya:                                 # tracking ya cargado: sólo falta cerrar el ebook (si hay)
        try:
            _sege_shop_ebooks_de(ctx, ya, _al_ebook)
        except Exception as e:
            ebook["errores"].append({"num": "", "msg": _sege_err(e)})
    if env:
        try:
            _DESP_CACHE.pop(email, None)
            _desp_cache_save()
        except Exception:
            pass
    return {"ok": True, "enviados": env, "saltados": salt, "fallaron": fail, "errores": errores[:8],
            "ebook_cerrados": ebook["cerrados"], "ebook_errores": ebook["errores"][:8]}


def _seg_tienda_auto(email, pedida="") -> str:
    """Qué tienda usar para el seguimiento: LA QUE ESTÉ INTEGRADA (Shopify o Tiendanube).
    Antes caía por defecto en "tn", así que en una cuenta con Shopify buscaba los pedidos en
    Tiendanube y no matcheaba NINGUNO. Si viene pedida y está conectada, se respeta; si no,
    se elige sola la que haya."""
    t = (pedida or "").strip().lower()
    hay_shop = bool((_shop_tokens().get(email) or {}).get("access_token"))
    _tn = _tn_tokens().get(email) or {}
    hay_tn = bool(_tn.get("access_token") and _tn.get("store_id"))
    if t == "shopify" and hay_shop:
        return "shopify"
    if t == "tn" and hay_tn:
        return "tn"
    return "shopify" if hay_shop else ("tn" if hay_tn else (t or "tn"))


@app.post("/pf-despachos-seg-leer")
def pf_despachos_seg_leer():
    """Lee el PDF de Andreani → pedido + seguimiento, matchea con TiendaNube (cliente, unidades,
    teléfono) y calcula el estado POR CANAL: ya cargado en TN / ya enviado por WhatsApp."""
    if not (email := _user_actual()):
        return jsonify({"ok": False}), 401
    f = request.files.get("pdf") or (next(iter(request.files.values())) if request.files else None)
    if not f:
        return jsonify({"ok": False, "msg": "subí el PDF de Andreani"})
    tienda = _seg_tienda_auto(email, request.form.get("tienda"))
    # Auto-detecta la tienda: si pide una que NO está conectada pero la otra SÍ, usa esa.
    # (así una cuenta Shopify no pide "conectá TiendaNube" solo porque el modal arranca en TN)
    sh_ok = bool(_seg_shop_conn(email)[0])
    tn_ok = bool((_seg_tn_store(email) or (None, None))[0])
    if tienda == "tn" and not tn_ok and sh_ok:
        tienda = "shopify"
    elif tienda == "shopify" and not sh_ok and tn_ok:
        tienda = "tn"
    if tienda == "shopify":
        if not sh_ok:
            return jsonify({"ok": False, "msg": "conectá tu Shopify en Integraciones"})
        store = hdr = None
    else:
        store, hdr = _seg_tn_store(email)
        if not store:
            return jsonify({"ok": False, "msg": "conectá tu tienda (Shopify o TiendaNube) en Integraciones"})
    import tempfile
    tmp = tempfile.mktemp(suffix=".pdf")
    f.save(tmp)
    try:
        items = _seg_leer_pdf(tmp)
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude leer el PDF (%s)" % (str(e)[:80])})
    finally:
        try:
            _os.remove(tmp)
        except Exception:
            pass
    if not items:
        return jsonify({"ok": False, "msg": "no reconocí ninguna etiqueta en ese PDF. Sirven las de Andreani, "
                                       "las de Flex de RealProfit y las de Envialo."})
    # JOB EN SEGUNDO PLANO: buscar los pedidos en la tienda (Shopify/TN) puede tardar. NO lo hacemos
    # dentro del request (colgaba el server 5 min y saturaba los hilos si tocabas subir varias veces).
    # El request vuelve YA con un job; el frontend consulta /pf-despachos-seg-progreso hasta que termina.
    import uuid as _uuid, time as _t2
    # GUARDIA: 1 solo job por cuenta a la vez. Si subís el PDF varias veces (o quedó uno colgado <120s),
    # NO arranco otro hilo → evita acumular docenas de hilos parseando Shopify (ahogaban el server).
    _ahora = _t2.time()
    for _jid, _st in list(_SEG_JOBS.items()):
        if _st.get("email") == email and not _st.get("listo") and (_ahora - _st.get("t0", 0) < 120):
            return jsonify({"ok": True, "job": _jid, "total": _st.get("total", len(items))})
    # limpio jobs viejos (>10 min) para que el dict no crezca infinito
    for _jid in [k for k, v in list(_SEG_JOBS.items()) if _ahora - v.get("t0", 0) > 600]:
        _SEG_JOBS.pop(_jid, None)
    job = _uuid.uuid4().hex[:12]
    _SEG_JOBS[job] = {"listo": False, "error": None, "pedidos": None, "resumen": None,
                      "tienda": tienda, "total": len(items), "done": 0, "email": email, "t0": _ahora}
    _job_put(job, _SEG_JOBS[job])            # persisto YA → el OTRO worker de gunicorn también ve el job
    threading.Thread(target=_seg_leer_run, args=(job, items, email, tienda, store, hdr), daemon=True).start()
    return jsonify({"ok": True, "job": job, "total": len(items)})


_SEG_JOBS = {}   # job_id → estado del lector de seguimientos (corre en un hilo aparte, no bloquea el request)

# ── JOBS COMPARTIDOS ENTRE WORKERS ─────────────────────────────────────────────────────────
# gunicorn corre 2 workers; un dict en memoria vive en UN worker → el poll del progreso puede caer
# en el OTRO worker y NO encontrar el job ("el proceso venció"). Fix: persisto el estado a disco.
_JOBS_DIR = DATA_DIR / "jobs"


def _job_put(job, d):
    try:
        _JOBS_DIR.mkdir(parents=True, exist_ok=True)
        import time as _tj
        dd = {k: v for k, v in d.items() if k != "pdf"}     # los bytes del PDF NO van al JSON
        dd["ts"] = _tj.time()                               # latido: ultima señal de vida
        # ATÓMICO (tmp + replace): el otro worker leía el archivo a medio escribir → _job_get None →
        # "el proceso venció" falso. El tmp lleva pid+hilo: dos hilos no se pisan el temporal.
        _dst = _JOBS_DIR / (job + ".json")
        _tmp = _JOBS_DIR / ("%s.json.%d.%d.tmp" % (job, _os.getpid(), threading.get_ident()))
        _tmp.write_text(_json.dumps(dd, ensure_ascii=False, default=str), encoding="utf-8")
        _os.replace(str(_tmp), str(_dst))
    except Exception:
        pass


def _job_get(job):
    try:
        return _json.loads((_JOBS_DIR / (job + ".json")).read_text(encoding="utf-8"))
    except Exception:
        return None


def _seg_leer_run(job, items, email, tienda, store, hdr):
    """Corre en un hilo: matchea el PDF con la tienda y arma la lista. Guarda el resultado en _SEG_JOBS."""
    try:
        nums = [it["pedido"] for it in items]
        mapa = _seg_mapa_orders_shopify(email, nums) if tienda == "shopify" else _seg_mapa_orders(store, hdr, nums)
        wpp_env = _wa_seg_all().get(email, {})
        pedidos = []
        n_tn = n_wpp = n_ambos = n_falta = 0
        for it in items:
            o = mapa.get(it["pedido"]) or {}
            if tienda == "shopify":
                cust = o.get("customer") or {}
                _st = " ".join((s.get("title") or "") for s in (o.get("shipping_lines") or [])).lower()
                nombre = (((cust.get("first_name") or "") + " " + (cust.get("last_name") or "")).strip()
                          or (_D(o.get("shipping_address"))).get("name") or it.get("dest", ""))
                # Sólo las unidades que viajan: la "Guía Digital" (requires_shipping=false) no va en la
                # caja y sumada pasaba 1 pote a "combo de 2" en la plantilla de WhatsApp.
                u = sum(int(float(li.get("quantity") or 0)) for li in (o.get("line_items") or [])
                        if li.get("requires_shipping") is not False)
                tel = _seg_shop_tel(o)
                # Pendiente de seguimiento = el envío FÍSICO sin tracking. El FO del ebook (digital, sin
                # tracking, abierto o cerrado) no cuenta: sólo mira si algún fulfillment tiene número.
                tn_ok = any((f.get("tracking_number") for f in (o.get("fulfillments") or [])))
                es_suc = _txt_es_sucursal(_st)
                oid = o.get("id"); fo_id = None
                match = bool(oid)
            else:
                cust = o.get("customer") or {}
                nombre = cust.get("name") or it.get("dest", "")
                ff = o.get("fulfillments") or []
                fo_id = ff[0].get("id") if ff else None
                es_suc = (((ff[0].get("shipping") or {}).get("type")) == "pickup") if ff else False
                u = _seg_unidades(o) if o else 0
                tel = _seg_tel_real(o) if o else ""
                tn_ok = _seg_estado_tn(o) if o else False
                oid = o.get("id")
                match = bool(oid and fo_id)
            wpp_ok = bool(wpp_env.get(str(it["pedido"])))
            pedidos.append({
                "num": it["pedido"], "nombre": nombre, "track": it["seguimiento"],
                "url": _seg_url_track(it), "carrier": it.get("carrier") or "andreani",
                "wa_id": _seg_e164(tel) if tel else "", "unidades": u,
                "order_id": oid, "fo_id": fo_id, "es_sucursal": es_suc,
                "tn": tn_ok, "wpp": wpp_ok, "match": match, "tienda": tienda,
            })
            _SEG_JOBS[job]["done"] = len(pedidos)
            if len(pedidos) % 5 == 0:
                _job_put(job, _SEG_JOBS[job])       # progreso visible aunque el poll caiga en el otro worker
            if tn_ok and wpp_ok:
                n_ambos += 1
            elif tn_ok:
                n_tn += 1
            elif wpp_ok:
                n_wpp += 1
            else:
                n_falta += 1
        _wc = _wa_conf(email) or {}
        wpp_on = bool(_wc.get("token") and _wc.get("phone_id"))
        try:                       # guardo pedido ↔ seguimiento para la página /seguimientos
            _env_guardar_mapa(email, pedidos)
        except Exception:
            pass
        # Y ADEMAS los saco de "por empaquetar". Si Andreani ya emitio la etiqueta con su
        # numero de seguimiento, ese pedido esta despachado. Antes el PDF solo alimentaba
        # /seguimientos y Despachos nunca se enteraba: los MISMOS pedidos volvian a salir en
        # la tanda siguiente y se despachaban dos veces (23-10-2026: quedaron 125 "por
        # empaquetar" despues de subir el PDF de 147 etiquetas).
        # Se marca "ENVIADA". El circuito es: generar el Excel -> "exportada"; cargar el PDF
        # de seguimientos -> "enviada". Si llego el numero de seguimiento, el paquete salio.
        try:
            _st = _desp_state(email)
            _n_marc = 0
            for _p in pedidos:
                _k = str(_p.get("num") or "").replace("#", "").strip()
                if not _k or not _p.get("track"):
                    continue
                if _st.get(_k) != "enviada":
                    _n_marc += 1
                _st[_k] = "enviada"
            if _n_marc:
                _desp_save(email, _st)
            _SEG_JOBS[job]["marcados"] = _n_marc
        except Exception:
            pass
        _SEG_JOBS[job].update({"listo": True, "pedidos": pedidos, "wpp_on": wpp_on,
                               "resumen": {"total": len(pedidos), "ambos": n_ambos, "solo_tn": n_tn,
                                           "solo_wpp": n_wpp, "ninguno": n_falta}})
        _job_put(job, _SEG_JOBS[job])            # resultado final a disco (lo lee cualquier worker)
    except Exception as e:
        import traceback as _tb
        _tbl = _tb.extract_tb(e.__traceback__)
        _ln = (" @ %s:%d" % (_tbl[-1].name, _tbl[-1].lineno)) if _tbl else ""
        _SEG_JOBS[job].update({"listo": True, "error": "%s: %s%s" % (type(e).__name__, str(e)[:180], _ln)})
        _job_put(job, _SEG_JOBS[job])


@app.get("/pf-despachos-seg-progreso")
def pf_despachos_seg_progreso():
    if not _user_actual():
        return jsonify({"ok": False}), 401
    _jid = (request.args.get("job") or "").strip()
    st = _SEG_JOBS.get(_jid) or _job_get(_jid)      # disco → sirve aunque el poll caiga en otro worker
    if not st:
        return jsonify({"ok": False, "msg": "el proceso venció, subí el PDF de nuevo"})
    if not st.get("listo"):
        return jsonify({"ok": True, "listo": False, "done": st.get("done", 0), "total": st.get("total", 0)})
    if st.get("error"):
        return jsonify({"ok": False, "msg": "error buscando en la tienda (%s)" % st["error"]})
    return jsonify({"ok": True, "listo": True, "pedidos": st["pedidos"], "tienda": st.get("tienda"),
                    "wpp_on": st.get("wpp_on", False), "resumen": st["resumen"]})


