@app.post("/wa-tpl-resena")
def wa_tpl_resena():
    """Crea la plantilla de la campaña de reseñas en Meta y la manda a aprobación.

    RealProfit solo LEIA plantillas; no habia forma de crear una. El WABA y su token estan
    en la config de la cuenta (no en variables de entorno), asi que esto corre con la sesion
    del dueño. Si ya existe, Meta devuelve el error y se muestra tal cual."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    c = _wa_conf(email) or {}
    waba, tok = str(c.get("waba_id") or ""), c.get("token")
    if not waba or not tok:
        return jsonify({"ok": False, "msg": "falta el WABA o el token en Config bot"}), 400
    payload = {
        "name": RESENA_TPL_NOMBRE,
        "language": "es_AR",
        "category": "MARKETING",
        "components": [
            {"type": "BODY", "text": RESENA_TPL_CUERPO,
             "example": {"body_text": [["Favio"]]}},
            {"type": "FOOTER", "text": "Respondé BAJA para no recibir más mensajes"},
            {"type": "BUTTONS", "buttons": [
                {"type": "QUICK_REPLY", "text": "Quiero el 35%"},
                {"type": "QUICK_REPLY", "text": "Ahora no"}]},
        ],
    }
    try:
        r = requests.post("%s/%s/message_templates" % (WA_GRAPH, waba), timeout=30,
                          headers={"Authorization": "Bearer " + tok,
                                   "Content-Type": "application/json"},
                          json=payload)
        j = r.json() if r.content else {}
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:140])}), 500
    if r.status_code >= 400:
        e = j.get("error") or {}
        return jsonify({"ok": False, "http": r.status_code,
                        "msg": e.get("error_user_msg") or e.get("message") or str(j)[:200],
                        "detalle": e.get("error_user_title") or ""}), 400
    return jsonify({"ok": True, "id": j.get("id"), "estado": j.get("status"),
                    "categoria": j.get("category"), "nombre": RESENA_TPL_NOMBRE,
                    "msg": "Creada y enviada a aprobación de Meta."})


@app.get("/wa-tpl-resena")
def wa_tpl_resena_ver():
    """Dice si la plantilla ya existe y en que estado esta (APPROVED / PENDING / REJECTED)."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    c = _wa_conf(email) or {}
    waba, tok = str(c.get("waba_id") or ""), c.get("token")
    if not waba or not tok:
        return jsonify({"ok": False, "msg": "falta el WABA o el token en Config bot"}), 400
    try:
        r = requests.get("%s/%s/message_templates" % (WA_GRAPH, waba), timeout=25,
                         headers={"Authorization": "Bearer " + tok},
                         params={"fields": "name,status,category,language,components", "limit": 100})
        j = r.json() if r.content else {}
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:140])}), 500
    todas = [{"nombre": t.get("name"), "estado": t.get("status"),
              "idioma": t.get("language"), "categoria": t.get("category")}
             for t in (j.get("data") or [])]
    mia = [t for t in todas if t["nombre"] == RESENA_TPL_NOMBRE]
    return jsonify({"ok": True, "existe": bool(mia), "resena": mia,
                    "waba": waba, "todas": todas})


def _wa_tpl_body(conf, name):
    """Trae el TEXTO (cuerpo) de una plantilla de WhatsApp desde Meta, cacheado."""
    waba = (conf or {}).get("waba_id"); tok = (conf or {}).get("token")
    if not waba or not tok:
        return ""
    ck = (str(waba), name)
    if ck in _WA_TPL_CACHE:
        return _WA_TPL_CACHE[ck]
    body = ""
    try:
        r = requests.get("%s/%s/message_templates" % (WA_GRAPH, waba),
                         params={"limit": 100, "access_token": tok}, timeout=15)
        for t in (r.json().get("data", []) if r.status_code == 200 else []):
            if t.get("name") == name:
                for comp in t.get("components", []):
                    if comp.get("type") == "BODY":
                        body = comp.get("text", "")
                break
    except Exception:
        body = ""
    _WA_TPL_CACHE[ck] = body
    return body


def _wa_tpl_render(body, params):
    """Reemplaza {{1}},{{2}}… por los params → el mensaje REAL que vio el cliente."""
    import re as _r
    def _rep(m):
        i = int(m.group(1)) - 1
        return str(params[i]) if 0 <= i < len(params) else m.group(0)
    return _r.sub(r"\{\{(\d+)\}\}", _rep, body or "")


def _seg_enviar_wpp(email, pedidos, force=False) -> dict:
    """Manda el seguimiento por WhatsApp (plantilla por unidades). Versión SINCRÓNICA (endpoint viejo).
    Cada pedido se marca en wa_seg_enviado APENAS Meta lo acepta (antes recién al final de la tanda:
    si el server moría en el medio, al reintentar se le volvía a mandar al cliente). Los mensajes se
    anotan en wa_chats en UNA escritura liviana al final (_wa_anotar_plantillas)."""
    c = _wa_conf(email)
    if not c:
        return {"ok": False, "msg": "WhatsApp no conectado", "enviados": 0}
    wpp_env = {} if force else (_wa_seg_all().get(email) or {})
    ps = [_sege_pedido_lite(p) for p in (pedidos or []) if isinstance(p, dict)]
    env = salt = fail = 0
    errores = []
    tareas = []
    for p in ps:
        if wpp_env.get(p["num"]):
            salt += 1
        else:
            tareas.append(p)

    def _m(p):
        r = _sege_wpp_uno(c, p)
        if r[0] == "env":
            if r[2]:
                r[2]["_f"] = _wa_anot_encolar(email, [r[2]])   # kill -9 a mitad: la anota _wa_drenar()
            try:
                _wa_seg_marcar_varios_seguro(email, [p["num"]])
            except Exception:
                pass
        return r
    from concurrent.futures import ThreadPoolExecutor as _TPE
    with _TPE(max_workers=8) as _ex:
        res = list(_ex.map(_m, tareas))
    anotar = []
    for p, r in zip(tareas, res):
        if r[0] == "env":
            env += 1
            if r[2]:
                anotar.append(r[2])
        else:
            fail += 1
            errores.append({"num": p["num"], "msg": r[1] or "error"})
    if anotar:
        _wa_anotar_plantillas(email, anotar)
    return {"ok": True, "enviados": env, "saltados": salt, "fallaron": fail, "errores": errores[:8]}


def _seg_enviar_tn(email, pedidos) -> dict:
    """Carga el tracking en TiendaNube (PATCH fulfillment-order + notify). Salta los ya cargados.
    En paralelo de a 3 (antes de a uno con timeout 30) y con reintento ante 429."""
    ctx = _sege_tn_ctx(email)
    if not ctx:
        return {"ok": False, "msg": "TiendaNube no conectado", "enviados": 0}
    ps = [_sege_pedido_lite(p) for p in (pedidos or []) if isinstance(p, dict)]
    env = salt = fail = 0
    errores = []
    resto = []
    for p in ps:
        if p.get("tn"):
            salt += 1
        else:
            resto.append(p)
    from concurrent.futures import ThreadPoolExecutor as _TPE
    with _TPE(max_workers=3) as _ex:
        res = list(_ex.map(lambda q: _sege_tn_uno(ctx, q), resto))
    for p, r in zip(resto, res):
        if r[0] == "env":
            env += 1
        else:
            fail += 1
            errores.append({"num": p["num"], "msg": r[1] or "error"})
    return {"ok": True, "enviados": env, "saltados": salt, "fallaron": fail, "errores": errores[:8]}


