# ═══════════════════════════════════════════════════════════════════════════════════════════════
# ENVÍO DE SEGUIMIENTOS COMO JOB (31-10-2026)
#
# Antes: el navegador mandaba tandas de 15 pedidos, una atrás de la otra, cada una dentro de UN
# request sincrónico que terminaba reescribiendo wa_chats.json (12+ MB). Los estados de WhatsApp
# (sent/delivered/read) de cada plantilla llegaban al webhook y CADA UNO releía y reescribía ese
# archivo con un candado entre los 2 workers → CPU 100%, /pf-version sin contestar, watchdog que
# reiniciaba el server entero y tandas de 15 que pasaban de 15 s a 200 s ("15 cada 2 minutos").
#
# Ahora:
#  - el envío es UN job en un hilo, con latido a disco cada 1 s (lo lee cualquier worker);
#  - cada pedido se RECLAMA en un log por job (jobs/<job>.log, append) ANTES de mandarlo y se
#    anota OK/F/U apenas vuelve → si el worker muere, al reanudar NO se re-manda nada que ya
#    salió (y lo que quedó "en vuelo" queda EN DUDA, no se reintenta solo);
#  - el WhatsApp se marca en wa_seg_enviado.json pedido por pedido (no al final de la tanda);
#  - los mensajes de las plantillas se anotan en wa_chats en pocas escrituras (cada ~30 o 15 s);
#  - los estados del webhook van a una cola en memoria que se vuelca cada 10 s en UNA escritura.
# ═══════════════════════════════════════════════════════════════════════════════════════════════
_SEGE_JOBS = {}                 # job → estado (solo en el worker que lo corre; el resto lee disco)
_SEGE_LOCK = threading.Lock()   # protege los dicts de estado mientras los hilos del pool escriben
_SEGE_MUERTO = 60               # s sin latido = job caído
_SEGE_LATIDO_FILE = DATA_DIR / "jobs" / "_envio_latido"    # lo mira el watchdog
_SEGE_CANALES = ("tn", "wpp", "todos")
_SEG_MARK_LOCK = threading.Lock()
_SEGE_PARAR = set()             # jobs que este proceso tiene que soltar (se está apagando)
_SEGE_LANZAR_LOCK = threading.Lock()   # lanzar: chequeo "¿ya hay uno?" + alta, atómicos dentro del proceso


def _sege_err(e) -> str:
    """TipoDeError: mensaje @ función:línea (regla errores-reales-en-ui)."""
    import traceback as _tb
    tbl = _tb.extract_tb(e.__traceback__) if getattr(e, "__traceback__", None) else []
    ln = (" @ %s:%d" % (tbl[-1].name, tbl[-1].lineno)) if tbl else ""
    return "%s: %s%s" % (type(e).__name__, str(e)[:200], ln)


class _sege_flock:
    """Candado de archivo ENTRE procesos (los 2 workers) + no rompe si el SO no tiene flock."""

    def __init__(self, path):
        self.path = str(path)
        self.f = None

    def __enter__(self):
        try:
            import fcntl
            Path(self.path).parent.mkdir(parents=True, exist_ok=True)
            self.f = open(self.path, "a+")
            fcntl.flock(self.f.fileno(), fcntl.LOCK_EX)
        except Exception:
            self.f = None
        return self

    def __exit__(self, *a):
        if self.f is not None:
            try:
                import fcntl
                fcntl.flock(self.f.fileno(), fcntl.LOCK_UN)
                self.f.close()
            except Exception:
                pass
        return False


def _sege_jid_ok(job) -> bool:
    return bool(re.fullmatch(r"se[0-9a-f]{12}", job or ""))


def _sege_p(job, ext):
    return _JOBS_DIR / ("%s.%s" % (job, ext))


def _sege_lease(job) -> str:
    try:
        return _sege_p(job, "lease").read_text(encoding="utf-8").strip()
    except Exception:
        return ""


def _sege_tomar(job) -> str:
    """Toma el job (lease nuevo). Desde acá, un hilo viejo que siga vivo ya no puede reclamar."""
    import uuid as _u
    tok = _u.uuid4().hex
    with _sege_flock(_sege_p(job, "lock")):
        _sege_p(job, "lease").write_text(tok, encoding="utf-8")
    return tok


def _sege_append(job, d) -> None:
    d = dict(d)
    d["ts"] = round(_time.time(), 1)
    with open(str(_sege_p(job, "log")), "a", encoding="utf-8") as f:
        f.write(_json.dumps(d, ensure_ascii=False) + "\n")
        f.flush()
        try:
            _os.fsync(f.fileno())
        except Exception:
            pass


def _sege_reclamar(job, token, canal, num) -> bool:
    """Anota 'P' (lo estoy mandando) ANTES de pegarle a la API. False = perdí el job → parar."""
    with _sege_flock(_sege_p(job, "lock")):
        if _sege_lease(job) != token:
            return False
        _sege_append(job, {"c": canal, "t": "P", "n": str(num)})
    return True


def _sege_anotar(job, canal, num, t, msg="", x=None) -> None:
    with _sege_flock(_sege_p(job, "lock")):
        d = {"c": canal, "t": t, "n": str(num)}
        if msg:
            d["m"] = str(msg)[:300]
        if x:
            d["x"] = x
        _sege_append(job, d)


def _sege_log_leer(job) -> dict:
    """{canal: {num: (ultimo_estado, msg)}} + extras de los OK de WhatsApp (para anotar chats)."""
    est = {"tienda": {}, "wpp": {}}
    extras = {}
    try:
        lineas = _sege_p(job, "log").read_text(encoding="utf-8").splitlines()
    except Exception:
        lineas = []
    for ln in lineas:
        try:
            d = _json.loads(ln)
        except Exception:
            continue                       # una línea cortada por un SIGKILL no rompe nada
        c, t, n = d.get("c"), d.get("t"), str(d.get("n") or "")
        if c not in est or not n:
            continue
        prev = est[c].get(n)
        # un terminal (OK/SALT/U) no lo pisa un P posterior de un hilo viejo
        if prev and prev[0] in ("OK", "SALT") and t == "P":
            continue
        est[c][n] = (t, d.get("m") or "")
        if c == "wpp" and t == "OK" and d.get("x"):
            extras[n] = d["x"]
    return {"est": est, "extras": extras}


def _sege_proc_start(pid) -> str:
    try:
        return open("/proc/%d/stat" % int(pid)).read().rsplit(")", 1)[1].split()[19]
    except Exception:
        return ""


def _sege_pid_vivo(pid, start) -> bool:
    """¿Sigue vivo EL MISMO proceso? (tras un reinicio los pids se repiten: comparo el arranque)."""
    try:
        pid = int(pid)
    except Exception:
        return False
    s = _sege_proc_start(pid)
    if s:
        return (not start) or s == start
    try:
        _os.kill(pid, 0)
        return not start                   # sin /proc no puedo distinguir un pid reciclado
    except PermissionError:
        return not start
    except Exception:
        return False


def _sege_pedido_lite(p) -> dict:
    p = p or {}
    try:
        u = int(float(p.get("unidades") or 0))
    except Exception:
        u = 0
    return {"num": str(p.get("num") or "").replace("#", "").strip(),
            "nombre": (p.get("nombre") or ""), "track": str(p.get("track") or ""),
            "url": (p.get("url") or ""), "carrier": (p.get("carrier") or "andreani"),
            "wa_id": str(p.get("wa_id") or "").strip(), "unidades": u,
            "order_id": p.get("order_id") or "", "fo_id": p.get("fo_id") or "",
            "es_sucursal": bool(p.get("es_sucursal")), "tn": bool(p.get("tn")),
            "wpp": bool(p.get("wpp")), "tienda": (p.get("tienda") or "")}


# ---------------------------- reintentos ante límites de las APIs ----------------------------
def _sege_espera_hdr(r, intento) -> float:
    """Cuánto esperar ante un 429: Retry-After (s) o x-rate-limit-reset de TN (ms); si no, 1,2,4,8 s."""
    try:
        ra = r.headers.get("Retry-After")
        if ra:
            return min(20.0, max(0.5, float(ra)))
        rs = r.headers.get("x-rate-limit-reset")
        if rs:
            return min(20.0, max(0.5, float(rs) / 1000.0))
    except Exception:
        pass
    return min(16.0, 2.0 ** intento)


class _SegeDuda(Exception):
    """El pedido pudo haber llegado a la API (se cortó DESPUÉS de mandarlo): no se reintenta solo."""


def _sege_http(metodo, url, intentos=5, reintentar_5xx=False, **kw):
    """requests con reintento ante 429 y ante errores de conexión que NO llegaron a mandar nada.
    Un ReadTimeout o una conexión cortada a mitad de un POST/PATCH NO se reintentan: el pedido pudo
    haberse procesado del otro lado (sería un WhatsApp o un mail duplicado) → _SegeDuda."""
    ult = None
    for i in range(intentos):
        try:
            r = requests.request(metodo, url, **kw)
        except requests.exceptions.ReadTimeout:
            if metodo.upper() == "GET":
                ult = None
                _time.sleep(min(8.0, 1.0 + i * 2))
                if i < intentos - 1:
                    continue
            raise
        except requests.exceptions.ConnectionError as e:
            txt = str(e)
            pre = isinstance(e, requests.exceptions.ConnectTimeout) or any(
                k in txt for k in ("NewConnectionError", "NameResolution", "Name or service", "Connection refused"))
            if metodo.upper() != "GET" and not pre:
                raise _SegeDuda("%s: %s" % (type(e).__name__, txt[:160]))
            ult = e
            _time.sleep(min(8.0, 1.0 + i * 2))
            continue
        if r.status_code == 429 or (reintentar_5xx and r.status_code >= 500):
            ult = r
            if i < intentos - 1:
                _time.sleep(_sege_espera_hdr(r, i))
                continue
        return r
    if isinstance(ult, Exception):
        raise ult
    return ult


def _sege_gql(gql, H, query, variables=None, intentos=6):
    """POST GraphQL a Shopify con reintento ante 429 y ante THROTTLED (respeta el balde de costo)."""
    body = {"query": query}
    if variables is not None:
        body["variables"] = variables
    j = {}
    for i in range(intentos):
        r = _sege_http("POST", gql, headers=H, data=_json.dumps(body), timeout=20)
        if r.status_code >= 400:
            return None, "Shopify HTTP %s: %s" % (r.status_code, (r.text or "")[:200])
        try:
            j = r.json() if r.content else {}
        except Exception:
            return None, "Shopify devolvió algo que no es JSON: %s" % (r.text or "")[:160]
        errs = j.get("errors") or []
        thr = any(((e or {}).get("extensions") or {}).get("code") == "THROTTLED" for e in errs) \
            if isinstance(errs, list) else False
        if thr and i < intentos - 1:
            espera = 2.0
            try:
                cost = (j.get("extensions") or {}).get("cost") or {}
                ts = cost.get("throttleStatus") or {}
                falta = float(cost.get("requestedQueryCost") or 50) - float(ts.get("currentlyAvailable") or 0)
                espera = max(1.0, min(15.0, falta / max(1.0, float(ts.get("restoreRate") or 50))))
            except Exception:
                pass
            _time.sleep(espera)
            continue
        return j, None
    return j, "Shopify THROTTLED después de %d intentos" % intentos


# ---------------------------------- canal TIENDA: Shopify ----------------------------------
_SEGE_MUT_CREATE = ("mutation($f:FulfillmentInput!){fulfillmentCreate(fulfillment:$f){"
                    "fulfillment{id status trackingInfo{company number url}} userErrors{field message}}}")
_SEGE_MUT_TRACK = ("mutation($fid:ID!,$t:FulfillmentTrackingInput!){fulfillmentTrackingInfoUpdate("
                   "fulfillmentId:$fid,trackingInfoInput:$t,notifyCustomer:true){"
                   "fulfillment{id trackingInfo{number url}} userErrors{field message}}}")


def _sege_shop_ctx(email):
    shop, atok = _seg_shop_conn(email)
    if not shop:
        return None
    base = "https://%s/admin/api/2026-07" % shop
    return {"H": {"X-Shopify-Access-Token": atok, "Content-Type": "application/json"},
            "base": base, "gql": "%s/graphql.json" % base}


_SEGE_MUT_DIGITAL = ("mutation($f:FulfillmentInput!){fulfillmentCreate(fulfillment:$f){"
                     "fulfillment{id status} userErrors{field message}}}")
_SEGE_FO_ABIERTO = ("open", "in_progress", "scheduled")     # FO al que se le puede cargar el tracking físico
_SEGE_FO_DIGITAL_CERRABLE = ("open", "in_progress")         # FO digital (ebook) que se cierra sin aviso


def _sege_fo_lineas_digital(lineas, hay_mas=False):
    """True SOLO si TODAS las líneas del fulfillment order son requiresShipping=false (producto digital:
    la "Guía Digital" de NoxaLab). Sin líneas, con alguna física, con un dato que falta o con más líneas
    sin leer (paginado) → False: ante la duda NO es digital y NUNCA se cierra."""
    if hay_mas or not lineas:
        return False
    return all(x is False for x in lineas)


def _sege_shop_verificar_digitales(ctx, fos_por_verificar) -> None:
    """Lee las líneas (requiresShipping) de los fulfillment orders candidatos a digitales y les pone
    fo["digital"]=True/False. Va APARTE de la consulta de a 25 para no subirle el costo: sólo se
    piden los FO que lo necesitan (el de deliveryMethod NONE, o los pedidos con más de un FO
    abierto), que son pocos. Si la consulta falla, quedan digital=None → no se cierran y al elegir
    el FO para el tracking van al final."""
    fos = [f for f in fos_por_verificar if f.get("id")]
    for i in range(0, len(fos), 25):
        trozo = fos[i:i + 25]
        q = ("query($ids:[ID!]!){nodes(ids:$ids){... on FulfillmentOrder{id "
             "lineItems(first:10){pageInfo{hasNextPage} nodes{requiresShipping}}}}}")
        ids = ["gid://shopify/FulfillmentOrder/%s" % f["id"] for f in trozo]
        try:
            j, err = _sege_gql(ctx["gql"], ctx["H"], q, {"ids": ids})
        except Exception:
            j, err = None, "x"
        if err or not j:
            continue
        por_id = {}
        for nd in ((j.get("data") or {}).get("nodes") or []):
            if isinstance(nd, dict) and nd.get("id"):
                por_id[str(nd["id"]).rsplit("/", 1)[-1]] = nd
        for f in trozo:
            nd = por_id.get(f["id"])
            if not nd or not isinstance(nd.get("lineItems"), dict):
                continue
            li = nd["lineItems"]
            f["digital"] = _sege_fo_lineas_digital(
                [(x or {}).get("requiresShipping") for x in (li.get("nodes") or [])],
                bool((li.get("pageInfo") or {}).get("hasNextPage")))


def _sege_fo_necesita_verificar(fos) -> list:
    """Qué FO de UN pedido hay que verificar línea por línea: los de deliveryMethod NONE (el ebook) y,
    si el pedido tiene más de un FO abierto, todos los abiertos (para no cargarle el tracking físico
    al digital por elegir el primero de la lista)."""
    abiertos = [f for f in fos if f.get("status") in _SEGE_FO_ABIERTO]
    if len(abiertos) > 1:
        return abiertos
    return [f for f in abiertos if f.get("metodo") == "none"]


def _sege_shop_lote(ctx, pedidos) -> dict:
    """fulfillment orders + fulfillments de hasta 25 pedidos en UNA consulta GraphQL (antes la vía 2
    hacía un GET REST por pedido contra el límite de ~2/s y un 429 salía como 'sin fulfillment').
    EBOOK: trae también deliveryMethod del FO y requiresShipping del fulfillment (escalares/objeto
    de 1 punto: la consulta sube ~+5 puntos por pedido). Las líneas de los FO candidatos a digitales
    se leen en una 2ª consulta chica (_sege_shop_verificar_digitales)."""
    mapa = {}
    ids = [str(p.get("order_id")) for p in pedidos if p.get("order_id")]
    for i in range(0, len(ids), 25):
        trozo = ids[i:i + 25]
        q = "query{" + " ".join(
            'o%d: order(id:"gid://shopify/Order/%s"){fulfillmentOrders(first:5){nodes{id status deliveryMethod{methodType}}} '
            'fulfillments(first:5){id status requiresShipping trackingInfo(first:3){number}}}' % (k, oid)
            for k, oid in enumerate(trozo)) + "}"
        try:
            j, err = _sege_gql(ctx["gql"], ctx["H"], q)
        except Exception:
            j, err = None, "x"
        if err or not j:
            continue                       # esos pedidos caen al camino uno por uno (con reintento)
        dat = j.get("data") or {}
        verificar = []
        for k, oid in enumerate(trozo):
            o = dat.get("o%d" % k)
            if not isinstance(o, dict) or o.get("fulfillments") is None or o.get("fulfillmentOrders") is None:
                continue                   # null por error parcial de GraphQL → camino REST, no un falso fallo
            fos = [{"id": str(x.get("id") or "").rsplit("/", 1)[-1],
                    "status": str(x.get("status") or "").lower(),
                    "metodo": str(((x.get("deliveryMethod") or {}).get("methodType")) or "").lower(),
                    "digital": None}
                   for x in ((o.get("fulfillmentOrders") or {}).get("nodes") or [])]
            fus = []
            for f in (o.get("fulfillments") or []):
                trk = [str((t or {}).get("number") or "") for t in (f.get("trackingInfo") or [])]
                rs = f.get("requiresShipping")
                fus.append({"id": str(f.get("id") or "").rsplit("/", 1)[-1],
                            "status": str(f.get("status") or "").lower(),
                            "tracking_number": next((t for t in trk if t), ""),
                            "requires_shipping": rs if isinstance(rs, bool) else None})
            verificar.extend(_sege_fo_necesita_verificar(fos))
            mapa[oid] = {"fos": fos, "fus": fus}
        if verificar:
            _sege_shop_verificar_digitales(ctx, verificar)
    return mapa


def _sege_shop_info_rest(ctx, oid):
    """Camino REST (un pedido) cuando no vino en el lote. Misma forma que _sege_shop_lote."""
    H, base = ctx["H"], ctx["base"]
    rr = _sege_http("GET", "%s/orders/%s/fulfillment_orders.json" % (base, oid), headers=H, timeout=15)
    if rr.status_code != 200:
        return None, "fulfillment_orders HTTP %s: %s" % (rr.status_code, (rr.text or "")[:160])
    fos, lineas_fo = [], {}
    for f in (rr.json().get("fulfillment_orders") or []):
        fid = str(f.get("id"))
        fos.append({"id": fid, "status": str(f.get("status") or "").lower(),
                    "metodo": str(((f.get("delivery_method") or {}).get("method_type")) or "").lower(),
                    "digital": None})
        lineas_fo[fid] = [str((x or {}).get("line_item_id") or "") for x in (f.get("line_items") or [])]
    fr = _sege_http("GET", "%s/orders/%s/fulfillments.json" % (base, oid), headers=H, timeout=15)
    if fr.status_code != 200:
        return None, "fulfillments HTTP %s: %s" % (fr.status_code, (fr.text or "")[:160])
    fus = []
    for f in (fr.json().get("fulfillments") or []):
        lis = [x.get("requires_shipping") for x in (f.get("line_items") or []) if isinstance(x, dict)]
        rs = (any(v is not False for v in lis)) if lis else None
        fus.append({"id": str(f.get("id")), "status": str(f.get("status") or "").lower(),
                    "tracking_number": str(f.get("tracking_number") or ""), "requires_shipping": rs})
    verificar = _sege_fo_necesita_verificar(fos)
    if verificar:
        # el FO de REST no trae requires_shipping por línea → lo saco de las líneas del pedido
        try:
            orr = _sege_http("GET", "%s/orders/%s.json" % (base, oid), headers=H, timeout=15,
                             params={"fields": "id,line_items"})
            if orr.status_code == 200:
                rs_por_li = {str(li.get("id")): li.get("requires_shipping")
                             for li in (((orr.json() or {}).get("order") or {}).get("line_items") or [])}
                for f in verificar:
                    lis = lineas_fo.get(f["id"]) or []
                    f["digital"] = _sege_fo_lineas_digital([rs_por_li.get(x) for x in lis],
                                                           any(x not in rs_por_li for x in lis))
        except Exception:
            pass                           # sin dato → digital=None → no se cierra
    return {"fos": fos, "fus": fus}, None


def _sege_fisico_con_tracking(info, trk="") -> bool:
    """¿El envío físico del pedido ya tiene tracking (el pedido)? Sólo fulfillments físicos y no cancelados."""
    for f in ((info or {}).get("fus") or []):
        if f.get("requires_shipping") is False:
            continue
        if (f.get("status") or "") in ("cancelled", "error", "failure"):
            continue
        t = f.get("tracking_number") or ""
        if t and (not trk or t == trk):
            return True
    return False


def _sege_shop_cerrar_digitales(ctx, info) -> tuple:
    """Cierra (sin avisar al cliente, sin tracking) cada FO ABIERTO cuyas líneas son TODAS
    requiresShipping=false: el ebook de NoxaLab, que se entrega por mail al comprar y si no queda
    el pedido "parcialmente enviado" para siempre. Idempotente: un FO ya cerrado no se toca; un FO
    con alguna línea física (o sin verificar) NUNCA se cierra. → (cerrados, [errores reales])."""
    cerr, errs = 0, []
    for fo in ((info or {}).get("fos") or []):
        if fo.get("digital") is not True or fo.get("status") not in _SEGE_FO_DIGITAL_CERRABLE:
            continue
        v = {"f": {"lineItemsByFulfillmentOrder": [{"fulfillmentOrderId": "gid://shopify/FulfillmentOrder/%s" % fo["id"]}],
                   "notifyCustomer": False}}
        try:
            j, err = _sege_gql(ctx["gql"], ctx["H"], _SEGE_MUT_DIGITAL, v)
            if err:
                errs.append("FO digital %s: %s" % (fo["id"], err))
                continue
            res = ((j.get("data") or {}).get("fulfillmentCreate") or {})
            ue = res.get("userErrors") or []
            if res.get("fulfillment") and not ue:
                cerr += 1
                fo["status"] = "closed"
            else:
                errs.append("FO digital %s: fulfillmentCreate: %s" % (
                    fo["id"], ((ue[0].get("message") or "") if ue else str(j.get("errors") or j))[:200]))
        except Exception as e:
            errs.append("FO digital %s: %s" % (fo["id"], _sege_err(e)))
    return cerr, errs


def _sege_ebook_anotar(al_ebook, p, cerr, errs) -> None:
    if errs:
        try:
            print("[seg-ebook] #%s: no pude cerrar el FO digital: %s" % (p.get("num"), " | ".join(errs)), flush=True)
        except Exception:
            pass
    if al_ebook and (cerr or errs):
        try:
            al_ebook(p, cerr, errs)
        except Exception:
            pass


def _sege_shop_ebook_ya_cargado(ctx, p, info, al_ebook=None) -> None:
    """Pedido cuyo tracking físico YA estaba (el lector lo vio): sólo falta cerrar el FO digital.
    Nunca falla ni toca el estado del seguimiento."""
    try:
        if info is None and p.get("order_id"):
            info, _e = _sege_shop_info_rest(ctx, p["order_id"])
        if not info or not _sege_fisico_con_tracking(info):
            return
        cerr, errs = _sege_shop_cerrar_digitales(ctx, info)
    except Exception as e:
        cerr, errs = 0, [_sege_err(e)]
    _sege_ebook_anotar(al_ebook, p, cerr, errs)


def _sege_shop_ebooks_de(ctx, pedidos, al_ebook=None, seguir=None) -> None:
    """Para los pedidos que se saltaron por tener ya el tracking: lote de 25 + cierre de digitales."""
    from concurrent.futures import ThreadPoolExecutor
    ps = [p for p in pedidos if p.get("order_id")]
    for i in range(0, len(ps), 25):
        if seguir and not seguir():
            return
        trozo = ps[i:i + 25]
        try:
            info = _sege_shop_lote(ctx, trozo)
        except Exception:
            info = {}
        # sólo los que tienen un FO digital abierto necesitan algo más (los demás no gastan nada)
        trozo = [p for p in trozo if p.get("order_id") and (
            str(p["order_id"]) not in info or any(
                f.get("digital") is True and f.get("status") in _SEGE_FO_DIGITAL_CERRABLE
                for f in (info[str(p["order_id"])].get("fos") or [])))]
        if not trozo:
            continue
        try:
            with ThreadPoolExecutor(max_workers=6) as ex:
                list(ex.map(lambda q: _sege_shop_ebook_ya_cargado(ctx, q, info.get(str(q.get("order_id"))), al_ebook), trozo))
        except RuntimeError:
            return                         # el intérprete se apaga: es secundario, no se insiste


def _sege_shop_uno(ctx, p, info, al_ebook=None):
    """UN pedido → ('env'|'salt'|'fail', msg). Doble vía, igual que siempre:
    (1) fulfillment order ABIERTO → fulfillmentCreate con tracking + aviso;
    (2) ya preparado → fulfillmentTrackingInfoUpdate al fulfillment existente (salta si ya tiene ese tracking).
    Es idempotente: si se repite, el (1) ya no encuentra FO abierto y el (2) ve el mismo tracking → 'salt'.
    EBOOK: el FO digital (todas sus líneas requiresShipping=false) NO se usa para el tracking, y con el
    físico ya con tracking ('env'/'salt') se cierra aparte sin aviso. Un fallo al cerrarlo NO cambia el
    resultado del pedido: va a al_ebook(p, cerrados, errores) y al log."""
    oid = p.get("order_id")
    if not oid:
        return ("fail", "no está en Shopify")
    if info is None:                       # no vino en el lote → uno por uno, con reintento ante 429
        try:
            info, e_rest = _sege_shop_info_rest(ctx, oid)
            if e_rest:
                return ("fail", e_rest)
        except Exception as e:
            return ("fail", _sege_err(e))
    r = _sege_shop_tracking(ctx, p, info)
    if r[0] in ("env", "salt"):
        try:
            cerr, errs = _sege_shop_cerrar_digitales(ctx, info)
        except Exception as e:
            cerr, errs = 0, [_sege_err(e)]
        _sege_ebook_anotar(al_ebook, p, cerr, errs)
    return r


def _sege_shop_tracking(ctx, p, info):
    """La carga del tracking FÍSICO (vías 1 y 2). Ignora el FO digital y los fulfillments digitales."""
    H = ctx["H"]
    fos, fus = info.get("fos") or [], info.get("fus") or []
    fus_fis = [f for f in fus if f.get("requires_shipping") is not False]
    trk = str(p.get("track") or "")
    if trk and any((f.get("tracking_number") or "") == trk
                   and (f.get("status") or "") not in ("cancelled", "error", "failure") for f in fus_fis):
        return ("salt", None)
    # FO para el tracking: abierto y NO digital. Los de deliveryMethod NONE sin verificar van al final.
    cands = [f for f in fos if f.get("status") in _SEGE_FO_ABIERTO and f.get("digital") is not True]
    cands.sort(key=lambda f: 1 if f.get("metodo") == "none" else 0)
    fo = cands[0] if cands else None
    try:
        if fo:
            v = {"f": {"lineItemsByFulfillmentOrder": [{"fulfillmentOrderId": "gid://shopify/FulfillmentOrder/%s" % fo["id"]}],
                       "notifyCustomer": True, "trackingInfo": _seg_track_info(p)}}
            j, err = _sege_gql(ctx["gql"], H, _SEGE_MUT_CREATE, v)
            if err:
                return ("fail", err)
            res = ((j.get("data") or {}).get("fulfillmentCreate") or {})
            ue = res.get("userErrors") or []
            if res.get("fulfillment") and not ue:
                fo["status"] = "closed"
                fus.append({"id": str((res["fulfillment"].get("id") or "")).rsplit("/", 1)[-1],
                            "status": "success", "tracking_number": trk, "requires_shipping": True})
                return ("env", None)
            return ("fail", "fulfillmentCreate: " + ((ue[0].get("message") or "") if ue else str(j.get("errors") or j))[:200])
        cand = [f for f in fus_fis if (f.get("status") or "") in ("success", "pending", "open", "")]
        ff = next((f for f in cand if not f.get("tracking_number")), None) or (cand[-1] if cand else None)
        if not ff:
            est = ",".join(str(f.get("status")) + ("(digital)" if f.get("digital") is True else "") for f in fos) or "ninguno"
            return ("fail", "sin fulfillment ni FO abierto (FO: %s)" % est)
        v2 = {"fid": "gid://shopify/Fulfillment/%s" % ff["id"], "t": _seg_track_info(p)}
        j, err = _sege_gql(ctx["gql"], H, _SEGE_MUT_TRACK, v2)
        if err:
            return ("fail", err)
        res = ((j.get("data") or {}).get("fulfillmentTrackingInfoUpdate") or {})
        ue = res.get("userErrors") or []
        if res.get("fulfillment") and not ue:
            ff["tracking_number"] = trk
            return ("env", None)
        return ("fail", "trackingInfoUpdate: " + ((ue[0].get("message") or "") if ue else str(j.get("errors") or j))[:200])
    except (requests.exceptions.ReadTimeout, _SegeDuda) as e:
        # Shopify pudo haberlo procesado. Igual es idempotente: al reanudar se verifica el tracking.
        return ("unc", "Shopify no contestó (%s); se verifica al reanudar" % _sege_err(e))
    except Exception as e:
        return ("fail", _sege_err(e))


# ---------------------------------- canal TIENDA: TiendaNube ----------------------------------
def _sege_tn_ctx(email):
    store, hdr0 = _seg_tn_store(email)
    if not store:
        return None
    return {"H": {**hdr0, "Content-Type": "application/json"}, "base": "%s/%s/orders" % (TN_API, store)}


def _sege_tn_uno(ctx, p):
    num = str(p.get("num"))
    if not (p.get("order_id") and p.get("fo_id")):
        return ("fail", "no está en TiendaNube")
    estado = "READY_FOR_PICKUP" if p.get("es_sucursal") else "DISPATCHED"
    body = {"status": estado, "tracking_info": {"code": p.get("track"), "url": p.get("url"), "notify_customer": True}}
    url = "%s/%s/fulfillment-orders/%s" % (ctx["base"], p["order_id"], p["fo_id"])
    try:
        rr = _sege_http("PATCH", url, headers=ctx["H"], data=_json.dumps(body), timeout=25)
        if rr.status_code in (200, 201, 204):
            return ("env", None)
        return ("fail", "TiendaNube HTTP %s: %s" % (rr.status_code, str(rr.text or "")[:160]))
    except (requests.exceptions.ReadTimeout, _SegeDuda) as e:
        return ("unc", "TiendaNube no contestó (%s): no sé si avisó al cliente, no lo repito" % _sege_err(e))
    except Exception as e:
        return ("fail", "#%s %s" % (num, _sege_err(e)))


# ---------------------------------- canal WHATSAPP ----------------------------------
_SEGE_WA_LIMITE = (4, 80007, 130429)        # límites de Meta → esperar y reintentar


def _sege_wpp_plantilla(c, p):
    num = str(p.get("num"))
    n = ((p.get("nombre") or "cliente").split() or ["cliente"])[0]
    link = p.get("url") or ""
    u = int(p.get("unidades") or 0)
    combo_tpl = (c.get("bot_tpl_combo") or "").strip()
    if (p.get("carrier") or "") in ("envialo", "rpflex"):
        return "seguimiento_flex", [n, num, link]
    if u >= 2 and combo_tpl:
        return combo_tpl, [n, num, link, _seg_presentacion(u)]
    return "seguimiento_despacho", [n, num, link]


def _sege_wpp_uno(c, p):
    """UN WhatsApp → ('env'|'fail'|'unc', msg, extra{wa,nombre,disp,mid,ts})."""
    num = str(p.get("num"))
    wa = (p.get("wa_id") or "").strip()
    if not wa:
        return ("fail", "sin teléfono", None)
    name, params = _sege_wpp_plantilla(c, p)

    def _snd(_name, _params):
        tpl = {"name": _name, "language": {"code": "es_AR"},
               "components": [{"type": "body", "parameters": [{"type": "text", "text": str(x)} for x in _params]}]}
        for i in range(4):
            r = _sege_http("POST", "%s/%s/messages" % (WA_GRAPH, c["phone_id"]), intentos=4,
                           headers={"Authorization": "Bearer " + c["token"]},
                           json={"messaging_product": "whatsapp", "to": wa, "type": "template", "template": tpl},
                           timeout=15)
            try:
                j = r.json() if r.content else {}
            except Exception:
                j = {}
            code = (j.get("error") or {}).get("code")
            if r.status_code >= 400 and code in _SEGE_WA_LIMITE and i < 3:
                _time.sleep(2.0 * (2 ** i))          # límite de Meta: NO se mandó, se puede reintentar
                continue
            return r, j
        return r, j
    try:
        r, j = _snd(name, params)
        if r.status_code >= 400 and (j.get("error") or {}).get("code") == 132001 and name != "seguimiento_despacho":
            name, params = "seguimiento_despacho", params[:3]
            r, j = _snd(name, params)
    except (requests.exceptions.ReadTimeout, _SegeDuda) as e:
        return ("unc", "Meta no contestó (%s): puede haber salido, no lo repito para no duplicar" % _sege_err(e), None)
    except Exception as e:
        return ("fail", _sege_err(e), None)
    if r.status_code >= 400:
        er = j.get("error") or {}
        det = ((er.get("error_data") or {}).get("details") or "")
        return ("fail", "Meta HTTP %s · código %s: %s%s" % (r.status_code, er.get("code"), er.get("message") or "error",
                                                            (" (" + det + ")") if det else ""), None)
    mid = ((j.get("messages") or [{}])[0] or {}).get("id", "")
    disp = _wa_tpl_render(_wa_tpl_body(c, name), params) or ("📦 Seguimiento de tu pedido #%s: %s" % (num, params[2] if len(params) > 2 else ""))
    return ("env", None, {"wa": wa, "nombre": p.get("nombre") or wa, "disp": disp, "mid": mid, "ts": _wa_now()})


# ---------------------------------- wa_chats: escrituras livianas ----------------------------------
def _wa_cuenta_msgs(x) -> int:
    n = 0
    for v in (x or {}).values():
        for cv in (v or {}).values():
            if isinstance(cv, dict):
                n += len(cv.get("messages") or [])
    return n


def _wa_mutar_disco(fn) -> bool:
    """Lee wa_chats UNA vez bajo los dos candados (proceso + archivo), aplica fn(disco) EN EL LUGAR y
    escribe atómico. Para cambios que solo AGREGAN o actualizan campos (estados, plantillas): no
    necesita la fusión completa ni el .bak, y nunca pisa lo que otro escribió. Si no puede leer el
    archivo, NO escribe nada (jamás tratar una lectura fallida como "no hay chats").
    True = quedó en disco (escrito, o ya estaba y no había nada que cambiar); False = no se pudo."""
    with _WA_SAVE_LOCK:
        with _sege_flock(str(WA_CHATS) + ".lock"):
            disco = _wa_leer_principal()
            if disco is None:
                return False
            antes = _wa_cuenta_msgs(disco)
            if not fn(disco):
                return True                  # se leyó bien y ya estaba todo: nada que escribir
            if _wa_cuenta_msgs(disco) < antes:
                return False
            tmp = WA_CHATS.with_suffix(".tmp.%d" % _os.getpid())
            try:
                tmp.write_text(_json.dumps(disco, ensure_ascii=False), encoding="utf-8")
                tmp.replace(WA_CHATS)
            except Exception:
                try:
                    tmp.unlink()
                except Exception:
                    pass
                return False
            return True


# Plantillas mandadas que todavía no están en wa_chats: una por archivo, escritas a disco APENAS Meta
# acepta el mensaje. Se borran recién cuando la plantilla quedó en el chat. Si el worker muere (kill -9,
# OOM), el job se relanza como nuevo, el volcado final falla o el endpoint viejo no pudo anotar, las
# levanta _wa_drenar() desde cualquier worker. Antes vivían solo en memoria (st["anot_pend"]) y con un
# kill -9 el cliente recibía el seguimiento pero el mensaje nunca aparecía en /wa.
_WA_ANOT_DIR = DATA_DIR / "wa_anot_pend"


def _wa_anot_encolar(email, items) -> str:
    items = [{k: v for k, v in it.items() if k != "_f"} for it in (items or []) if isinstance(it, dict) and it.get("wa")]
    if not (email and items):
        return ""
    try:
        import uuid as _u
        _WA_ANOT_DIR.mkdir(parents=True, exist_ok=True)
        f = _WA_ANOT_DIR / ("%d.%d.%s.json" % (_time.time_ns(), _os.getpid(), _u.uuid4().hex[:10]))
        tmp = _WA_ANOT_DIR / (f.name + ".tmp")
        tmp.write_text(_json.dumps({"email": email, "items": items}, ensure_ascii=False), encoding="utf-8")
        tmp.replace(f)
    except Exception:
        return ""
    try:
        _wa_st_asegurar_hilo()
    except Exception:
        pass
    return str(f)


def _wa_anot_borrar(items) -> None:
    for it in items or []:
        f = it.get("_f") if isinstance(it, dict) else None
        if f:
            try:
                _os.unlink(f)
            except Exception:
                pass


_WA_DREN = {"lock": threading.Lock(), "ult_tmp": 0.0}


def _wa_pid_vivo(pid) -> bool:
    try:
        _os.kill(int(pid), 0)
        return True
    except PermissionError:
        return True
    except Exception:
        return False


def _wa_drenar() -> None:
    """Corre en el hilo de estados de CUALQUIER worker (cada 10 s):
    1) fusiona los wa_chats.PENDIENTE.* (guardados que no pudieron releer el disco), en orden;
    2) anota las plantillas pendientes (wa_anot_pend/) con más de 60 s (las recientes son de un
       envío vivo que las vuelca solo; repetir es inofensivo: dedup por id de Meta);
    3) cada 5 min, borra los temporales de procesos muertos (wa_chats.tmp.<pid>, 12 MB c/u)."""
    if not _WA_DREN["lock"].acquire(blocking=False):
        return
    try:
        ahora = _time.time()
        for f in sorted(WA_CHATS.parent.glob(_WA_PEND_GLOB)):
            try:
                d = _json.loads(f.read_text(encoding="utf-8"))
            except Exception:
                break                            # se reintenta en la próxima vuelta
            if not isinstance(d, dict) or not _wa_save_chats(d, _pend=False):
                break
            try:
                f.unlink()
            except Exception:
                pass
        try:
            fs = sorted(_WA_ANOT_DIR.glob("*.json"))[:3000]
        except Exception:
            fs = []
        grupos = {}
        for f in fs:
            try:
                if ahora - f.stat().st_mtime < 60:
                    continue
                j = _json.loads(f.read_text(encoding="utf-8"))
            except Exception:
                continue
            for it in (j.get("items") or []):
                if isinstance(it, dict) and it.get("wa"):
                    it = dict(it)
                    it["_f"] = str(f)
                    grupos.setdefault(j.get("email") or "", []).append(it)
        for em, its in grupos.items():
            if em:
                _wa_anotar_plantillas(em, its)    # si anda, borra los archivos
        if ahora - _WA_DREN["ult_tmp"] > 300:
            _WA_DREN["ult_tmp"] = ahora
            cands = list(WA_CHATS.parent.glob("wa_chats.tmp.*")) + list(WA_CHATS.parent.glob("wa_chats.bak.tmp.*"))
            for f in cands:
                try:
                    pid = f.name.rsplit(".", 1)[1]
                    if ahora - f.stat().st_mtime > 120 and not (pid.isdigit() and _wa_pid_vivo(pid)):
                        f.unlink()
                except Exception:
                    pass
            for f in list(WA_CHATS.parent.glob("wa_chats.PENDIENTE.*.tmp")) + list(_WA_ANOT_DIR.glob("*.tmp")):
                try:
                    if ahora - f.stat().st_mtime > 600:
                        f.unlink()
                except Exception:
                    pass
    finally:
        _WA_DREN["lock"].release()


_WA_ST_RANK = {"": 0, "sent": 1, "delivered": 2, "read": 3, "failed": 4}
_WA_ST_PEND = {}                 # {email: {mid: [status, ts_primera_vez]}}
_WA_ST_LOCK = threading.Lock()
_WA_ST_HILO = {"latido": 0.0, "nuevos": 0, "ult_lectura": 0.0, "vueltas": 0, "aplicados": 0, "error": ""}
_WA_ST_CADA = 10                 # s entre volcados
_WA_ST_VENCE = 900               # un estado cuyo mensaje no aparece en 15 min se descarta


def _wa_st_encolar(email, sid, st) -> None:
    """El webhook ya NO reescribe wa_chats por cada sent/delivered/read: los encola acá."""
    if not (email and sid and st):
        return
    with _WA_ST_LOCK:
        d = _WA_ST_PEND.setdefault(email, {})
        prev = d.get(sid)
        if not prev or _WA_ST_RANK.get(st, 0) >= _WA_ST_RANK.get(prev[0], 0):
            d[sid] = [st, prev[1] if prev else _time.time()]
        _WA_ST_HILO["nuevos"] += 1
    _wa_st_asegurar_hilo()


def _wa_st_asegurar_hilo() -> None:
    """Arranca el volcador desde un REQUEST (nunca al importar: ver realprofit-2-workers-estado).
    El latido se marca ANTES de lanzar, así dos webhooks simultáneos no crean dos hilos."""
    ahora = _time.time()
    if ahora - _WA_ST_HILO["latido"] < 45:
        return
    with _WA_ST_LOCK:
        if ahora - _WA_ST_HILO["latido"] < 45:
            return
        _WA_ST_HILO["latido"] = ahora
    threading.Thread(target=_wa_st_loop, daemon=True, name="wa-estados").start()


def _wa_st_loop() -> None:
    while True:
        _WA_ST_HILO["latido"] = _time.time()
        _time.sleep(_WA_ST_CADA)
        _WA_ST_HILO["latido"] = _time.time()
        try:
            _wa_drenar()
        except Exception:
            pass
        try:
            _wa_st_flush()
            _WA_ST_HILO["error"] = ""
        except Exception as e:
            _WA_ST_HILO["error"] = _sege_err(e)
        _WA_ST_HILO["vueltas"] += 1


def _wa_st_flush(forzar=False) -> None:
    ahora = _time.time()
    with _WA_ST_LOCK:
        if not any(_WA_ST_PEND.values()):
            return
        # si no entró nada nuevo, los que no encontraron su mensaje se reintentan cada 60 s, no cada 10
        if not forzar and not _WA_ST_HILO["nuevos"] and ahora - _WA_ST_HILO["ult_lectura"] < 60:
            return
        snap = {em: {k: list(v) for k, v in d.items()} for em, d in _WA_ST_PEND.items() if d}
        _WA_ST_HILO["nuevos"] = 0
        _WA_ST_HILO["ult_lectura"] = ahora
    hechos = set()

    def _fn(disco):
        ch = False
        for em, d in snap.items():
            for conv in (disco.get(em) or {}).values():
                if not isinstance(conv, dict):
                    continue
                for mm in (conv.get("messages") or []):
                    sid = mm.get("id") if isinstance(mm, dict) else None
                    if sid and sid in d:
                        hechos.add((em, sid))
                        st = d[sid][0]
                        if _WA_ST_RANK.get(st, 0) > _WA_ST_RANK.get(mm.get("status") or "", 0):
                            mm["status"] = st
                            ch = True
        return ch
    _wa_mutar_disco(_fn)
    with _WA_ST_LOCK:
        for em, d in list(_WA_ST_PEND.items()):
            for sid in list(d.keys()):
                v = d[sid]
                if (em, sid) in hechos and v[0] == (snap.get(em, {}).get(sid) or [None])[0]:
                    d.pop(sid, None)
                    _WA_ST_HILO["aplicados"] += 1
                elif ahora - v[1] > _WA_ST_VENCE:
                    d.pop(sid, None)
                    try:
                        _WA_WH_DIAG["status_nomatch"] += 1
                    except Exception:
                        pass
            if not d:
                _WA_ST_PEND.pop(em, None)


def _wa_anotar_plantillas(email, items) -> bool:
    """Agrega al chat los mensajes de plantilla que se mandaron (dedup por id de Meta: repetir es
    inofensivo). Si el estado ya llegó por el webhook y está en la cola, se usa ese."""
    items = [it for it in (items or []) if it and it.get("wa")]
    if not items:
        return False
    with _WA_ST_LOCK:
        cola = dict(_WA_ST_PEND.get(email) or {})

    def _fn(disco):
        convs = disco.setdefault(email, {})
        ch = False
        for it in items:
            conv = convs.get(it["wa"])
            if not isinstance(conv, dict):
                conv = {"name": it.get("nombre") or it["wa"], "messages": []}
                convs[it["wa"]] = conv
            msgs = conv.setdefault("messages", [])
            mid = it.get("mid") or ""
            if mid and any(isinstance(m, dict) and m.get("id") == mid for m in msgs):
                continue
            if not mid and any(isinstance(m, dict) and m.get("type") == "template" and m.get("ts") == it.get("ts")
                               and m.get("text") == (it.get("disp") or "") for m in msgs):
                continue                         # sin id de Meta: misma plantilla, mismo instante
            msgs.append({"dir": "out", "text": it.get("disp") or "", "ts": it.get("ts") or _wa_now(),
                         "type": "template", "id": mid, "status": (cola.get(mid) or ["sent"])[0]})
            conv["updated"] = _wa_now()
            ch = True
        return ch
    ok = _wa_mutar_disco(_fn)
    if ok:
        _wa_anot_borrar(items)
    else:
        sueltos = [it for it in items if not it.get("_f")]
        if sueltos:
            _wa_anot_encolar(email, sueltos)     # que no se pierdan: las reintenta _wa_drenar()
    return ok


def _wa_seg_marcar_varios_seguro(email, nums) -> None:
    """Marca pedidos como avisados por WhatsApp sin perder marcas de otro worker (lock + atómico)."""
    if not nums:
        return
    with _SEG_MARK_LOCK:
        with _sege_flock(str(_WA_SEG_ENV) + ".lock"):
            # _wa_seg_all() devuelve {} si falla la lectura: escribir eso BORRARÍA las marcas de todas
            # las cuentas y el próximo envío le re-mandaría el seguimiento a todos. Ahora se escribe por
            # cada WhatsApp (antes una vez por tanda): si existe y no se puede leer, fallar (el pedido
            # queda OK en el log del job igual, así que el retome tampoco lo repite).
            if _WA_SEG_ENV.exists():
                d = _json.loads(_WA_SEG_ENV.read_text(encoding="utf-8"))
                if not isinstance(d, dict):
                    raise ValueError("wa_seg_enviado.json no es un objeto")
            else:
                d = {}
            m = d.setdefault(email, {})
            ahora = _wa_now()
            for x in nums:
                m[str(x)] = ahora
            tmp = _WA_SEG_ENV.with_suffix(".tmp.%d" % _os.getpid())
            tmp.write_text(_json.dumps(d, ensure_ascii=False), encoding="utf-8")
            tmp.replace(_WA_SEG_ENV)


# ---------------------------------- el job ----------------------------------
def _sege_estado_nuevo(job, email, canal, force, tienda, pedidos) -> dict:
    return {"tipo": "seg-envio", "job": job, "email": email, "canal": canal, "force": bool(force),
            "tienda": tienda, "pedidos": pedidos, "total": len(pedidos), "t0": _time.time(),
            "listo": False, "error": None, "msg": "arrancando…", "intentos": 0, "motivos": [],
            "c": {}, "ok": {"tienda": [], "wpp": []}, "fail": {"tienda": [], "wpp": []},
            "unc": {"tienda": [], "wpp": []}, "errores": [], "anot_pend": []}


def _sege_latir(job, token, stop) -> None:
    """Latido a disco cada 1 s + dispara el volcado de plantillas a wa_chats de a tandas.
    El volcado corre en un HILO APARTE (uno por vez): lee y escribe 12+ MB bajo el candado de
    wa_chats, que comparten el webhook (respuestas de clientes + bot) y el otro worker. Si corría acá
    adentro, una ráfaga de respuestas al seguimiento podía frenar el latido > 60 s → el job parecía
    muerto → se "retomaba" estando vivo y lo que estaba en vuelo quedaba EN DUDA sin motivo."""
    ult_anot = _time.time()
    volc = {"on": False}

    def _volcar(_st):
        try:
            _sege_volcar_anot(job, _st)
        except Exception:
            pass
        finally:
            volc["on"] = False
    while not stop.wait(1.0):
        st = _SEGE_JOBS.get(job)
        if not st or st.get("token") != token:
            return
        # Si OTRO proceso retomó el job (lease nuevo), este latido NO puede seguir pisando el estado en
        # disco: el front vería el progreso saltar entre las dos corridas, o hasta un "listo" falso de
        # la corrida vieja (que pone listo=True al perder el lease) y dejaría de mirar la nueva.
        _lz = _sege_lease(job)
        if _lz and _lz != token:
            return
        try:
            with _SEGE_LOCK:
                st["pid"] = _os.getpid()
                st["ts_lat"] = _time.time()
                n_anot = len(st.get("anot_pend") or [])
                snap = _json.loads(_json.dumps(st, default=str))
            _job_put(job, snap)
            _SEGE_LATIDO_FILE.parent.mkdir(parents=True, exist_ok=True)
            _SEGE_LATIDO_FILE.write_text(str(_time.time()), encoding="utf-8")
            if n_anot and not volc["on"] and (n_anot >= 30 or _time.time() - ult_anot > 15):
                volc["on"] = True
                ult_anot = _time.time()
                try:
                    threading.Thread(target=_volcar, args=(st,), daemon=True, name="seg-anot").start()
                except Exception:
                    volc["on"] = False
        except Exception:
            pass


def _sege_volcar_anot(job, st) -> None:
    with _SEGE_LOCK:
        items = list(st.get("anot_pend") or [])
        st["anot_pend"] = []
    if items and not _wa_anotar_plantillas(st["email"], items):
        with _SEGE_LOCK:                       # no se pudo escribir: vuelven a la cola
            st["anot_pend"] = items + list(st.get("anot_pend") or [])


def _sege_apagando() -> bool:
    """¿El proceso se está apagando? (reciclado por --max-requests, deploy, SIGTERM).
    Al salir, Python primero DRENA los ThreadPoolExecutor (seguiría mandando TODOS los WhatsApp que
    quedaban en la cola mientras el worker ya no atiende) y un pool nuevo tira RuntimeError
    "cannot schedule new futures after interpreter shutdown" (el job terminaba 'listo' con ese error
    y sin mandar el resto). Con esto se suelta el job prolijo y se retoma en el otro worker."""
    try:
        import concurrent.futures.thread as _cft
        if getattr(_cft, "_shutdown", False):
            return True
    except Exception:
        pass
    try:
        import sys as _sy
        return bool(_sy.is_finalizing())
    except Exception:
        return False


def _sege_run(job, token) -> None:
    st = _SEGE_JOBS[job]
    stop = threading.Event()
    threading.Thread(target=_sege_latir, args=(job, token, stop), daemon=True, name="seg-latido").start()
    try:
        email, canal, tienda = st["email"], st["canal"], st["tienda"]
        pedidos = st.get("pedidos") or []
        es_shop = tienda == "shopify"
        log = _sege_log_leer(job)
        canales = (["tienda"] if canal in ("tn", "todos") else []) + (["wpp"] if canal in ("wpp", "todos") else [])
        perdido = {"v": False}
        apagado = {"v": False}               # el proceso se apaga: soltar el job (se retoma en otro worker)
        trabajos = {}
        with _SEGE_LOCK:
            st["ok"] = {"tienda": [], "wpp": []}
            st["fail"] = {"tienda": [], "wpp": []}
            st["unc"] = {"tienda": [], "wpp": []}
            st["errores"] = []
            st["ebook"] = {"cerrados": 0, "errores": []}   # FO digital (ebook): aparte del seguimiento
            st["c"] = {}
            for cn in canales:
                est = log["est"][cn]
                cc = {"total": len(pedidos), "env": 0, "salt": 0, "fail": 0, "unc": 0, "done": 0}
                pend = []
                for p in pedidos:
                    n = p["num"]
                    t, m = est.get(n, (None, ""))
                    if t == "OK":
                        cc["env"] += 1; cc["done"] += 1; st["ok"][cn].append(n)
                    elif t == "SALT":
                        cc["salt"] += 1; cc["done"] += 1; st["ok"][cn].append(n)
                    elif t in ("U", "P") and not (cn == "tienda" and es_shop):
                        # quedó EN VUELO cuando se cortó: pudo haber salido → no se repite solo.
                        # (Shopify sí se reintenta: el chequeo de tracking lo hace idempotente.)
                        cc["unc"] += 1; cc["done"] += 1; st["unc"][cn].append(n)
                        st["errores"].append({"canal": cn, "num": n, "msg": m or "se cortó justo mientras se mandaba: puede haber salido, no lo repito"})
                    else:
                        pend.append(p)       # nunca intentado, falló (F) o Shopify en vuelo → se (re)intenta
                st["c"][cn] = cc
                trabajos[cn] = pend
            # los WhatsApp que ya salieron en corridas anteriores de ESTE job y no llegaron al chat
            st["anot_pend"] = list(log["extras"].values())
            st["msg"] = "mandando…"

        def _res(cn, n, kind, msg, x=None):
            t = {"env": "OK", "salt": "SALT", "fail": "F", "unc": "U"}[kind]
            xa = x
            if x and cn == "wpp" and kind == "env":
                xa = dict(x)
                xa["_f"] = _wa_anot_encolar(email, [x])   # a disco YA: un kill -9 ya no la pierde
            try:
                _sege_anotar(job, cn, n, t, msg or "", x)
            except Exception:
                pass
            if cn == "wpp" and kind == "env":
                try:
                    _wa_seg_marcar_varios_seguro(email, [n])      # YA, pedido por pedido
                except Exception:
                    pass
            with _SEGE_LOCK:
                cc = st["c"][cn]
                cc["done"] += 1
                if kind in ("env", "salt"):
                    cc[kind] += 1; st["ok"][cn].append(n)
                elif kind == "fail":
                    cc["fail"] += 1; st["fail"][cn].append(n)
                    st["errores"].append({"canal": cn, "num": n, "msg": msg or "error"})
                else:
                    cc["unc"] += 1; st["unc"][cn].append(n)
                    st["errores"].append({"canal": cn, "num": n, "msg": msg or "en duda"})
                if xa:
                    st["anot_pend"].append(xa)

        def _al_ebook(p, cerr, errs):
            # el cierre del FO digital NO toca el resultado del pedido ni se re-manda el seguimiento:
            # sólo se cuenta y se anota el error real aparte.
            with _SEGE_LOCK:
                eb = st.setdefault("ebook", {"cerrados": 0, "errores": []})
                eb["cerrados"] = int(eb.get("cerrados") or 0) + int(cerr or 0)
                for m in errs:
                    if len(eb["errores"]) < 200:
                        eb["errores"].append({"num": p.get("num"), "msg": m})

        def _correr(cn, items, fn_uno, hilos):
            from concurrent.futures import ThreadPoolExecutor as _TPE

            def _uno(p):
                if perdido["v"] or job in _SEGE_PARAR:
                    return
                if apagado["v"] or _sege_apagando():
                    apagado["v"] = True          # no reclamo ni uno más: lo retoma el otro worker
                    return
                n = p["num"]
                if not _sege_reclamar(job, token, cn, n):
                    perdido["v"] = True          # otro proceso tomó el job (reanudación)
                    return
                try:
                    r = fn_uno(p)
                except Exception as e:
                    r = ("fail", _sege_err(e), None)
                kind, msg = r[0], r[1]
                _res(cn, n, kind, msg, r[2] if len(r) > 2 else None)
            try:
                with _TPE(max_workers=hilos) as ex:
                    list(ex.map(_uno, items))
            except RuntimeError:
                if _sege_apagando():             # "cannot schedule new futures after interpreter shutdown"
                    apagado["v"] = True
                    return
                raise

        def _canal_tienda():
            items = trabajos.get("tienda") or []
            ya = [p for p in items if p.get("tn")]
            for p in ya:                        # el lector ya vio el tracking cargado
                _res("tienda", p["num"], "salt", None)
            items = [p for p in items if not p.get("tn")]
            if not items and not (es_shop and ya):
                return
            if es_shop:
                ctx = _sege_shop_ctx(email)
                if not ctx:
                    for p in items:
                        _res("tienda", p["num"], "fail", "Shopify no conectado")
                    return
                for i in range(0, len(items), 25):          # de a 25: 1 consulta + 25 envíos en paralelo
                    if perdido["v"] or apagado["v"]:
                        return
                    trozo = items[i:i + 25]
                    info = _sege_shop_lote(ctx, trozo)
                    _correr("tienda", trozo, lambda p: _sege_shop_uno(ctx, p, info.get(str(p.get("order_id"))), _al_ebook), 6)
                if ya:
                    # tracking ya cargado: sólo falta cerrar el FO digital (ebook). Secundario e
                    # idempotente: no reclama ni anota en el log del seguimiento.
                    try:
                        _sege_shop_ebooks_de(ctx, ya, _al_ebook, seguir=lambda: not (
                            perdido["v"] or apagado["v"] or job in _SEGE_PARAR or _sege_apagando()))
                    except Exception as e:
                        _al_ebook({"num": ""}, 0, [_sege_err(e)])
            else:
                ctx = _sege_tn_ctx(email)
                if not ctx:
                    for p in items:
                        _res("tienda", p["num"], "fail", "TiendaNube no conectado")
                    return
                _correr("tienda", items, lambda p: _sege_tn_uno(ctx, p), 3)   # TN: ~2 req/s, con reintento ante 429

        def _canal_wpp():
            items = trabajos.get("wpp") or []
            if not items:
                return
            c = _wa_conf(email) or {}
            if not (c.get("token") and c.get("phone_id")):
                for p in items:
                    _res("wpp", p["num"], "fail", "WhatsApp no conectado")
                return
            ya = {} if st.get("force") else (_wa_seg_all().get(email) or {})
            resto = []
            for p in items:
                if ya.get(p["num"]):
                    _res("wpp", p["num"], "salt", None)
                else:
                    resto.append(p)
            _correr("wpp", resto, lambda p: _sege_wpp_uno(c, p), 8)

        hilos = []
        errs_canal = {}
        for cn, fn in (("tienda", _canal_tienda), ("wpp", _canal_wpp)):
            if cn in canales:
                def _envolver(cn=cn, fn=fn):
                    try:
                        fn()
                    except Exception as e:
                        if _sege_apagando():
                            apagado["v"] = True
                        else:
                            errs_canal[cn] = _sege_err(e)
                h = threading.Thread(target=_envolver, daemon=True, name="seg-" + cn)
                h.start()
                hilos.append(h)
        for h in hilos:                         # tienda y WhatsApp corren A LA VEZ (APIs distintas)
            h.join()
        try:
            _sege_volcar_anot(job, st)          # también al apagarse o perder el job (antes: return sin volcar)
        except Exception:
            pass
        if apagado["v"] and not perdido["v"]:
            # El worker se apaga: NO es "listo". Los pedidos en vuelo ya terminaron (los pools se
            # esperaron arriba) y quedaron anotados OK/F en el log → el retome no deja nada "en duda".
            # Latido VIEJO a propósito: el front lo ve caído YA y lo retoma en el otro worker.
            if st.get("token") == token and _sege_lease(job) == token:
                with _SEGE_LOCK:
                    st["interrumpido"] = ("el worker pid %d se apagó a mitad del envío (reciclado por gunicorn "
                                          "--max-requests, deploy o reinicio). Se retoma desde donde quedó."
                                          % _os.getpid())
                    st["msg"] = "interrumpido"
                    st["token"] = "salida"     # el finally y el latido de este proceso ya no escriben
                    snap = _json.loads(_json.dumps(st, default=str))
                snap["ts_lat"] = _time.time() - _SEGE_MUERTO - 1
                _job_put(job, snap)
            return
        _sege_volcar_anot(job, st)
        if (st["c"].get("tienda") or {}).get("env"):
            try:
                _DESP_CACHE.pop(email, None)
                _desp_cache_save()
            except Exception:
                pass
        with _SEGE_LOCK:
            if perdido["v"]:
                st["msg"] = "otro proceso retomó este envío"
            if errs_canal:
                st["error"] = " · ".join("%s: %s" % kv for kv in errs_canal.items())
            st["listo"] = True
            st["t_fin"] = _time.time()
            if not st["msg"].startswith("otro"):
                st["msg"] = "terminado"
    except Exception as e:
        with _SEGE_LOCK:
            st["error"] = _sege_err(e)
            st["listo"] = True
    finally:
        stop.set()
        try:
            if st.get("token") == token and _sege_lease(job) == token:
                with _SEGE_LOCK:
                    snap = _json.loads(_json.dumps(st, default=str))
                _job_put(job, snap)
        except Exception:
            pass


def _sege_arrancar(job, st) -> None:
    tok = _sege_tomar(job)
    with _SEGE_LOCK:
        st["token"] = tok
        st["pid"] = _os.getpid()
        st["pid_start"] = _sege_proc_start(_os.getpid())
        st["intentos"] = int(st.get("intentos") or 0) + 1
        st["listo"] = False
        st["error"] = None
        st["ts_lat"] = _time.time()          # vivo desde YA (si no, un poll lo vería "caído" 1 s)
        st.pop("interrumpido", None)
    _SEGE_JOBS[job] = st
    _job_put(job, _json.loads(_json.dumps(st, default=str)))
    threading.Thread(target=_sege_run, args=(job, tok), daemon=True, name="seg-envio").start()
    try:
        _wa_st_asegurar_hilo()
    except Exception:
        pass


def _sege_edad(st) -> int:
    try:
        return int(_time.time() - float(st.get("ts_lat") or st.get("ts") or 0))
    except Exception:
        return 10 ** 6


def _sege_motivo_muerte(st, edad) -> str:
    if st.get("interrumpido"):
        return st["interrumpido"]
    pid = st.get("pid")
    donde = st.get("msg") or "?"
    if not _sege_pid_vivo(pid, st.get("pid_start")):
        return ("el proceso que lo mandaba (pid %s) ya no existe: se reinició el server o se recicló el "
                "worker sin avisar (watchdog / SIGKILL / memoria). Último latido hace %ds, iba en «%s»."
                % (pid, edad, donde))
    return ("el proceso (pid %s) sigue vivo pero el envío no late hace %ds: quedó trabado en «%s»."
            % (pid, edad, donde))


def _sege_limpiar_viejos() -> None:
    try:
        lim = _time.time() - 7 * 86400
        for f in _JOBS_DIR.glob("se*.*"):
            try:
                if f.stat().st_mtime < lim:
                    f.unlink()
            except Exception:
                pass
    except Exception:
        pass


_SEGE_CAIDO_RECIENTE = 600     # s: un envío cortado hace menos que esto se RETOMA en vez de lanzar otro


def _sege_activo_de(email, caidos=0):
    """Un envío VIVO de esta cuenta (latiendo), si hay. Evita dos envíos a la vez (doble clic, 2 pestañas).
    caidos>0: también devuelve uno SIN TERMINAR que se cortó hace menos de `caidos` s. Sin esto, mientras
    la pestaña que lo miraba lo retomaba sola, un "Enviar" en otra pestaña largaba un 2º job con los
    mismos pedidos (log propio, vacío) y los dos le mandaban el WhatsApp al mismo cliente; y lo que el
    1º había dejado EN DUDA el 2º lo re-mandaba."""
    ahora = _time.time()
    for job, st in list(_SEGE_JOBS.items()):
        if st.get("email") == email and not st.get("listo") and st.get("token") == _sege_lease(job) \
                and job not in _SEGE_PARAR:
            return job
    lim = max(_SEGE_MUERTO, caidos or 0)
    try:
        for f in _JOBS_DIR.glob("se*.json"):
            try:
                if ahora - f.stat().st_mtime > lim + 5:
                    continue
                d = _json.loads(f.read_text(encoding="utf-8"))
                if d.get("tipo") == "seg-envio" and d.get("email") == email and not d.get("listo") \
                        and _sege_edad(d) <= lim:
                    return f.stem
            except Exception:
                continue
    except Exception:
        pass
    return None


@app.post("/pf-despachos-seg-lanzar")
def pf_despachos_seg_lanzar():
    """Arranca el envío de seguimientos como JOB y vuelve al toque con {job}."""
    if not (email := _user_actual()):
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    try:
        d = request.get_json(silent=True) or {}
        canal = (d.get("canal") or "").strip()
        if canal not in _SEGE_CANALES:
            return jsonify({"ok": False, "msg": "canal inválido: %r" % canal}), 400
        pedidos = [_sege_pedido_lite(p) for p in (d.get("pedidos") or []) if isinstance(p, dict)]
        vistos, lote = set(), []
        for p in pedidos:                        # sin número o repetido en el PDF → afuera
            if p["num"] and p["num"] not in vistos:
                vistos.add(p["num"]); lote.append(p)
        if not lote:
            return jsonify({"ok": False, "msg": "no hay pedidos para enviar"})
        tienda = "shopify" if any(p.get("tienda") == "shopify" for p in lote) else "tn"
        if canal in ("tn", "todos"):
            if tienda == "shopify" and not _seg_shop_conn(email)[0]:
                return jsonify({"ok": False, "msg": "Shopify no está conectado (Integraciones)"})
            if tienda == "tn" and not (_seg_tn_store(email) or (None, None))[0]:
                return jsonify({"ok": False, "msg": "TiendaNube no está conectada (Integraciones)"})
        if canal in ("wpp", "todos"):
            c = _wa_conf(email) or {}
            if not (c.get("token") and c.get("phone_id")):
                return jsonify({"ok": False, "msg": "WhatsApp no está conectado (Config bot)"})
        import hashlib as _hl
        # Candado por cuenta ENTRE el chequeo y el alta: dos pestañas (o los 2 workers) lanzando a la
        # vez creaban DOS jobs que mandaban el mismo WhatsApp. _sege_arrancar deja el job en disco
        # (latiendo) antes de soltar el candado, así el segundo lo ve y se engancha a ese.
        _lk = _JOBS_DIR / ("_lanzar_%s.lock" % _hl.sha1(email.encode("utf-8")).hexdigest()[:16])
        with _SEGE_LANZAR_LOCK:
            with _sege_flock(_lk):
                otro = _sege_activo_de(email, caidos=_SEGE_CAIDO_RECIENTE)
                if otro:
                    _vivo = _sege_activo_de(email) == otro
                    return jsonify({"ok": True, "job": otro, "ya": True,
                                    "msg": ("ya había un envío en curso: te muestro ese (no se manda dos veces)" if _vivo else
                                            "había un envío que se cortó hace poco: lo retomo desde donde quedó (no se "
                                            "repite nada). Cuando termine, volvé a tocar Enviar para lo que falte.")})
                _sege_limpiar_viejos()
                import uuid as _u
                job = "se" + _u.uuid4().hex[:12]
                st = _sege_estado_nuevo(job, email, canal, d.get("force"), tienda, lote)
                _sege_arrancar(job, st)
        return jsonify({"ok": True, "job": job, "total": len(lote)})
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude arrancar el envío (%s)" % _sege_err(e)}), 500


@app.get("/pf-despachos-seg-envio-prog")
def pf_despachos_seg_envio_prog():
    """Progreso del envío. Sirve desde cualquier worker (lee el latido a disco) y si el job murió
    dice POR QUÉ (proceso inexistente / trabado / interrumpido por reciclado)."""
    if not (email := _user_actual()):
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    job = (request.args.get("job") or "").strip()
    if not _sege_jid_ok(job):
        return jsonify({"ok": False, "msg": "job inválido"}), 400
    try:
        st = None
        mem = _SEGE_JOBS.get(job)
        if mem and mem.get("token") and mem.get("token") == _sege_lease(job):
            with _SEGE_LOCK:                 # lo corre ESTE proceso: el dato más fresco
                st = _json.loads(_json.dumps(mem, default=str))
        else:
            st = _job_get(job)
        if not st:
            return jsonify({"ok": False, "msg": "no encuentro el envío %s en el servidor" % job})
        if st.get("email") != email:
            return jsonify({"ok": False, "msg": "ese envío es de otra cuenta"}), 403
        edad = _sege_edad(st)
        muerto = (not st.get("listo")) and edad > _SEGE_MUERTO
        return jsonify({"ok": True, "job": job, "listo": bool(st.get("listo")), "muerto": muerto,
                        "motivo": _sege_motivo_muerte(st, edad) if muerto else "",
                        "error": st.get("error") or "", "msg": st.get("msg") or "",
                        "canal": st.get("canal"), "tienda": st.get("tienda"), "total": st.get("total", 0),
                        "c": st.get("c") or {}, "ok_nums": st.get("ok") or {}, "fail_nums": st.get("fail") or {},
                        "unc_nums": st.get("unc") or {}, "errores": (st.get("errores") or [])[:60],
                        "n_errores": len(st.get("errores") or []), "intentos": st.get("intentos", 1),
                        "motivos": st.get("motivos") or [], "latido": edad,
                        "ebook": st.get("ebook") or {"cerrados": 0, "errores": []},
                        "seg": int((st.get("t_fin") or _time.time()) - float(st.get("t0") or _time.time()))})
    except Exception as e:
        return jsonify({"ok": False, "msg": "error leyendo el progreso (%s)" % _sege_err(e)}), 500


@app.post("/pf-despachos-seg-reanudar")
def pf_despachos_seg_reanudar():
    """Retoma un envío caído desde donde quedó. NO re-manda lo que ya salió (log por pedido) y lo
    que quedó en vuelo lo deja EN DUDA en vez de repetirlo."""
    if not (email := _user_actual()):
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    job = ((request.get_json(silent=True) or {}).get("job") or request.args.get("job") or "").strip()
    if not _sege_jid_ok(job):
        return jsonify({"ok": False, "msg": "job inválido"}), 400
    try:
        # candado: dos pestañas (o los 2 workers) tocando "reanudar" a la vez arrancan UNO solo
        with _sege_flock(_sege_p(job, "rlock")):
            st = _job_get(job)
            if not st or st.get("email") != email:
                return jsonify({"ok": False, "msg": "no encuentro ese envío"})
            if st.get("listo"):
                return jsonify({"ok": True, "job": job, "listo": True})
            edad = _sege_edad(st)
            if edad <= _SEGE_MUERTO:
                return jsonify({"ok": True, "job": job, "vivo": True})
            motivo = _sege_motivo_muerte(st, int(edad))
            st["motivos"] = (list(st.get("motivos") or []) + [motivo])[-5:]
            _SEGE_PARAR.discard(job)
            _sege_arrancar(job, st)
        return jsonify({"ok": True, "job": job, "reanudado": True, "motivo": motivo})
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude reanudar (%s)" % _sege_err(e)}), 500


def _sege_al_salir() -> None:
    """Salida PROLIJA del worker (reciclado por --max-requests, deploy, SIGTERM): deja escrito el
    motivo real en los jobs que corría y vuelca los estados de WhatsApp en cola."""
    try:
        for job, st in list(_SEGE_JOBS.items()):
            if st.get("listo") or _sege_lease(job) != st.get("token"):
                continue
            _SEGE_PARAR.add(job)               # no reclama ni un pedido más
            with _SEGE_LOCK:
                st["interrumpido"] = ("el worker pid %d se apagó a mitad del envío (reciclado por gunicorn "
                                      "--max-requests, deploy o reinicio). Se retoma desde donde quedó."
                                      % _os.getpid())
                st["msg"] = "interrumpido"
                st["token"] = "salida"         # el latido de este proceso deja de escribir
                snap = _json.loads(_json.dumps(st, default=str))
            # latido VIEJO a propósito: que el front lo vea caído YA y lo retome en otro worker
            snap["ts_lat"] = _time.time() - _SEGE_MUERTO - 1
            try:
                _job_put(job, snap)
            except Exception:
                pass
            try:
                _sege_volcar_anot(job, st)     # las plantillas ya mandadas, al chat
            except Exception:
                pass
    except Exception:
        pass
    try:
        _wa_st_flush(forzar=True)
    except Exception:
        pass


import atexit as _atexit_sege
_atexit_sege.register(_sege_al_salir)


_MP_LISTA_CACHE = {}   # {(email,desde,hasta): (ts, out)} — pagos de MP, cache 60s: se pide en varias secciones


def _mp_seg(x) -> float:
    """Segundos desde epoch de un timestamp ISO de MP o de Shopify. 0 si no se puede leer."""
    t = str(x or "").strip()
    if not t:
        return 0.0
    try:
        t = t.replace("Z", "+00:00")
        return _dt.datetime.fromisoformat(t).timestamp()
    except Exception:
        return 0.0


def _mp_tomar_cercano(lst, cuando):
    """De los pagos del MISMO importe, saca el que se aprobo MAS CERCA del pedido.
    Antes se tomaba el primero de la lista: con precios fijos (59.990 / 69.990 / 79.990) hay
    decenas de pagos identicos por dia y cada pedido se quedaba con el de otro. La comision por
    venta salia cualquiera (se vieron 41,5% y 4,5% en pedidos del mismo precio) aunque el total
    del dia cerrara. El pedido y su pago se crean con segundos de diferencia, asi que la hora
    los une bien. Si no hay hora en ninguno de los dos, cae al primero, como antes."""
    if not lst:
        return None
    t0 = _mp_seg(cuando)
    if not t0:
        return lst.pop(0)
    mejor, mejor_d = 0, None
    for i, p in enumerate(lst):
        tp = _mp_seg(p.get("fecha"))
        if not tp:
            continue
        d = abs(tp - t0)
        if mejor_d is None or d < mejor_d:
            mejor, mejor_d = i, d
    if mejor_d is None:
        return lst.pop(0)
    return lst.pop(mejor)


def _mp_es_de_meli(ref) -> bool:
    """True si ese pago de MercadoPago es de una venta de MERCADOLIBRE, no de la tienda.
    MELI cobra con la MISMA cuenta de MP, y su external_reference es el numero de venta:
    16 digitos que arrancan en 2000 (ej "2000018719128266"). Sin este filtro esos pagos caian
    en la bolsa de la tienda y, como el match es por monto y los precios son fijos, se pegaban a
    pedidos de Shopify del mismo importe. Medido el 29-09-2026: 26 de 124, $596.169 de comision
    de MELI contada como comision de MercadoPago de la tienda, ADEMAS de contarse en
    meli_comision. O sea, restada dos veces."""
    r = str(ref or "").strip()
    return len(r) == 16 and r.isdigit() and r.startswith("2000")


def _mp_pagos_lista(email, desde, hasta):
    """Lista de pagos aprobados de MP del usuario: {ref, amount, net, fee}. None si no hay MP.
    Sirve para MATCHEAR cada pago con su pedido de Shopify (comisión exacta por venta, sin inflar)."""
    import time as _t
    ck = (email, desde, hasta)
    c = _MP_LISTA_CACHE.get(ck)
    if c and (_t.time() - c[0] < 60):     # mismo período pedido de nuevo en <60s → sin re-bajar de MP
        return c[1]
    tk = _mp_tokens().get(email)
    token = tk.get("access_token") if tk else None
    fr = _mp_freeze_all().get(email)
    if not token and not fr:
        return None
    # Ventana de MP un poco más ancha que el período: un pago puede aprobarse hasta unos días
    # después de creado el pedido (transferencias, cuotas). Los que no matcheen se ignoran.
    try:
        h2 = (_dt.date.fromisoformat(hasta) + _dt.timedelta(days=4)).isoformat()
    except Exception:
        h2 = hasta
    # Histórico (<= FREEZE_END) del congelado; nuevo (> FREEZE_END) en vivo desde MP.
    if fr:
        _fe = _mp_freeze_end(email) or FREEZE_END
        _live_ini = _dia_post(_fe) if desde <= _fe else desde
        _run_live = hasta > _fe
        _frozen = _mp_freeze_slice(fr, desde, min(h2, _fe))
    else:
        _live_ini = desde; _run_live = True; _frozen = []
    ini = _live_ini + "T00:00:00.000-03:00"
    fin = h2 + "T23:59:59.999-03:00"
    out = []
    for p in _frozen:
        ta = float(p.get("transaction_amount") or 0)
        det = p.get("transaction_details") or {}
        net = float(det.get("net_received_amount") or 0)
        fee = (ta - net) if net else sum(float(f.get("amount") or 0)
                                         for f in (p.get("fee_details") or []))
        fd = p.get("fee_details") or []
        finanz = sum(float(f.get("amount") or 0) for f in fd if f.get("type") == "financing_fee")
        base = sum(float(f.get("amount") or 0) for f in fd if f.get("type") != "financing_fee")
        if not fd:
            base = fee; finanz = 0.0
        # Mismo criterio que los pagos vivos: la retencion de IIBB sale del costo de MP.
        _ret, _cargos = 0.0, {}
        for _c in (p.get("charges_details") or []):
            _nm = str(_c.get("name") or "")
            _am = float(((_c.get("amounts") or {}).get("original")) or _c.get("amount") or 0)
            _cargos[_nm] = round(_cargos.get(_nm, 0.0) + _am, 2)
            if "payer" in _nm:
                continue
            if _c.get("type") == "tax" or _nm.startswith("tax_withholding") or "iibb" in _nm.lower():
                _ret += _am
        fee = fee - _ret
        out.append({"ref": (p.get("external_reference") or "").strip(),
                    "amount": round(ta), "net": round(net, 2), "fee": round(fee, 2),
                    "ret": round(_ret, 2), "cargos": _cargos,
                    "lib": (p.get("money_release_date") or ""),
                    "inst": int(p.get("installments") or 1),
                    "fecha": (p.get("date_approved") or p.get("date_created") or ""),
                    "fee_mp": round(base, 2), "fee_cuotas": round(finanz, 2),
                    "medio": (p.get("payment_method_id") or p.get("payment_type_id") or "")})
    offset = 0
    try:
        while _run_live and token:
            r = requests.get("https://api.mercadopago.com/v1/payments/search",
                             headers={"Authorization": "Bearer " + token},
                             params={"sort": "date_approved", "criteria": "desc",
                                     "range": "date_approved", "begin_date": ini, "end_date": fin,
                                     "status": "approved", "offset": offset, "limit": 100}, timeout=30)
            if r.status_code >= 400:
                if not _frozen and offset == 0:
                    return None
                break
            data = r.json()
            res = data.get("results") or []
            for p in res:
                ta = float(p.get("transaction_amount") or 0)
                det = p.get("transaction_details") or {}
                net = float(det.get("net_received_amount") or 0)
                fee = (ta - net) if net else sum(float(f.get("amount") or 0)
                                                 for f in (p.get("fee_details") or []))
                # desglose para el modal: comisión MP (mercadopago+application) vs cuotas (financing)
                fd = p.get("fee_details") or []
                finanz = sum(float(f.get("amount") or 0) for f in fd if f.get("type") == "financing_fee")
                base = sum(float(f.get("amount") or 0) for f in fd if f.get("type") != "financing_fee")
                if not fd:
                    base = fee; finanz = 0.0
                # RETENCIONES: net_received_amount ya viene con las retenciones de IIBB y
                # Ganancias descontadas, asi que (ta - net) NO es solo la comision de MP. Las
                # retenciones son PAGO A CUENTA de un impuesto, no un costo nuevo: si ademas se
                # carga el IIBB completo por afuera, ese impuesto se cobra dos veces. Se anotan
                # aparte para poder descontarlas del IIBB en vez de tapar el bug con un %.
                _ret, _perc, _cargos = 0.0, 0.0, {}
                for _c in (p.get("charges_details") or []):
                    _nm = str(_c.get("name") or "")
                    _am = float(((_c.get("amounts") or {}).get("original")) or _c.get("amount") or 0)
                    _cargos[_nm] = round(_cargos.get(_nm, 0.0) + _am, 2)
                    # RETENCION de IIBB != PERCEPCION de IVA. Son impuestos distintos y no se
                    # computan igual (confirmado por soporte de MercadoPago, 30-09-2026):
                    #   - retencion de IIBB -> pago a cuenta de IIBB, NO da credito de IVA
                    #   - percepcion de IVA -> SI es credito fiscal de IVA
                    # Hoy esta cuenta no tiene ni una percepcion de IVA: medido sobre 10 dias
                    # (20 al 29-09-2026), 36 tipos de cargo, las 34 fiscales son todas IIBB. Queda
                    # separado igual para que el dia que aparezca una entre sola donde va.
                    # "payer" NO entra: ese es el impuesto al cheque, un cargo real, no pago a cuenta.
                    if "payer" in _nm:
                        continue
                    _low = _nm.lower()
                    if "iva" in _low or "percep" in _low:
                        _perc += _am
                    elif _c.get("type") == "tax" or _nm.startswith("tax_withholding") or "iibb" in _low:
                        _ret += _am
                # La retencion NO es comision de MercadoPago: es IIBB adelantado. Si queda adentro
                # del "fee", el mismo impuesto se cobra dos veces (una acá y otra como IIBB_PCT).
                # La percepcion de IVA tampoco es comision, pero esa SI da credito fiscal.
                fee = fee - _ret - _perc
                out.append({"ref": (p.get("external_reference") or "").strip(),
                            "amount": round(ta), "net": round(net, 2), "fee": round(fee, 2),
                            "inst": int(p.get("installments") or 1),
                    "fecha": (p.get("date_approved") or p.get("date_created") or ""),
                            "fee_mp": round(base, 2), "fee_cuotas": round(finanz, 2),
                            "ret": round(_ret, 2), "perc_iva": round(_perc, 2), "cargos": _cargos,
                    "lib": (p.get("money_release_date") or ""),
                            "medio": (p.get("payment_method_id") or p.get("payment_type_id") or "")})
            offset += 100
            if offset >= (data.get("paging") or {}).get("total", 0) or not res:
                break
    except Exception:
        if not _frozen:
            return None
    _MP_LISTA_CACHE[ck] = (_t.time(), out)
    return out


def _norm_txt(s):
    return "".join(ch for ch in str(s or "").lower() if ch.isalnum())


def _norm_tel(s):
    d = "".join(ch for ch in str(s or "") if ch.isdigit())
    return d[-10:] if len(d) >= 10 else d


def _recompras_periodo(orders, desde, hasta):
    """orders: historico [{'fecha','total','email','tel','nombre'}]. Dos ordenes son del MISMO cliente si
    comparten >=2 de {email, telefono, nombre}. Devuelve (cant, facturacion) de las compras del periodo
    [desde,hasta] que NO son la 1ra del cliente (o sea, recompras)."""
    parent = {}
    def find(x):
        parent.setdefault(x, x)
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != r:
            parent[x], x = r, parent[x]
        return r
    def union(a, b):
        parent[find(a)] = find(b)
    for i, o in enumerate(orders):
        e, ph, n = _norm_txt(o.get("email")), _norm_tel(o.get("tel")), _norm_txt(o.get("nombre"))
        parent.setdefault(("o", i), ("o", i))
        if e and ph:
            union(("o", i), ("k", "ep:%s|%s" % (e, ph)))
        if e and n:
            union(("o", i), ("k", "en:%s|%s" % (e, n)))
        if ph and n:
            union(("o", i), ("k", "pn:%s|%s" % (ph, n)))
    groups = {}
    for i in range(len(orders)):
        groups.setdefault(find(("o", i)), []).append(i)
    cant = 0
    fact = 0.0
    for idxs in groups.values():
        if len(idxs) < 2:
            continue
        idxs.sort(key=lambda i: (orders[i].get("fecha") or ""))
        for j, i in enumerate(idxs):
            if j == 0:
                continue
            f = (orders[i].get("fecha") or "")[:10]
            if desde <= f <= hasta:
                cant += 1
                fact += float(orders[i].get("total") or 0)
    return cant, round(fact, 2)


_TN_HIST_CACHE = {}
_SHOP_HIST_CACHE = {}


def _tn_hist_orders(email, hasta):
    """Ordenes PAGADAS de TN de los ultimos 180 dias hasta `hasta` (cache 10 min) - para recompras."""
    import time as _t
    ck = (email, hasta)
    c = _TN_HIST_CACHE.get(ck)
    if c and (_t.time() - c[0] < 600):
        return c[1]
    try:
        d0 = (_dt.date.fromisoformat(hasta) - _dt.timedelta(days=180)).isoformat()
    except Exception:
        d0 = hasta
    hist = []
    for o in _tn_orders_raw(email, d0, hasta):
        if (o.get("payment_status") or "").lower() != "paid" or o.get("cancelled_at"):
            continue
        cu = o.get("customer") or {}
        sa = _D(o.get("shipping_address"))
        hist.append({"fecha": o.get("created_at") or "", "total": float(o.get("total") or 0),
                     "email": o.get("contact_email") or cu.get("email") or "",
                     "tel": o.get("contact_phone") or o.get("billing_phone") or cu.get("phone") or sa.get("phone") or "",
                     "nombre": cu.get("name") or o.get("contact_name") or sa.get("name") or ""})
    _TN_HIST_CACHE[ck] = (_t.time(), hist)
    return hist


def _shop_hist_orders(email, hasta):
    """Ordenes pagadas de Shopify de los ultimos 180 dias hasta `hasta` (cache 10 min) - para recompras."""
    import time as _t, re as _re
    ck = (email, hasta)
    c = _SHOP_HIST_CACHE.get(ck)
    if c and (_t.time() - c[0] < 600):
        return c[1]
    tk = _shop_tokens().get(email)
    if not tk or not tk.get("access_token") or not tk.get("shop"):
        return []
    shop, token = tk["shop"], tk["access_token"]
    try:
        d0 = (_dt.date.fromisoformat(hasta) - _dt.timedelta(days=180)).isoformat()
    except Exception:
        d0 = hasta
    hist = []
    url = "https://%s/admin/api/2026-07/orders.json" % shop
    params = {"status": "any", "financial_status": "paid", "limit": 250,
              "created_at_min": d0 + "T00:00:00-03:00", "created_at_max": hasta + "T23:59:59-03:00",
              "fields": "created_at,total_price,customer,contact_email,email,billing_address,shipping_address"}
    for _ in range(20):
        try:
            r = requests.get(url, headers={"X-Shopify-Access-Token": token}, params=params, timeout=30)
        except Exception:
            break
        if r.status_code != 200:
            break
        for o in (r.json().get("orders") or []):
            cu = o.get("customer") or {}
            ba = _D(o.get("billing_address"))
            sa = _D(o.get("shipping_address"))
            hist.append({"fecha": o.get("created_at") or "", "total": float(o.get("total_price") or 0),
                         "email": o.get("email") or o.get("contact_email") or cu.get("email") or "",
                         "tel": cu.get("phone") or ba.get("phone") or sa.get("phone") or "",
                         "nombre": ((cu.get("first_name") or "") + " " + (cu.get("last_name") or "")).strip() or ba.get("name") or sa.get("name") or ""})
        nxt = None
        for part in (r.headers.get("Link", "") or "").split(","):
            if 'rel="next"' in part:
                m = _re.search(r"<([^>]+)>", part)
                if m:
                    nxt = m.group(1)
        if not nxt:
            break
        url = nxt
        params = {}
    _SHOP_HIST_CACHE[ck] = (_t.time(), hist)
    return hist


def _shopify_resumen(email, desde, hasta):
    """Arma el 'raw' que espera el dashboard con los pedidos reales de Shopify + costos cargados."""
    tk = _shop_tokens().get(email)
    if not tk or not tk.get("access_token"):
        return None
    shop = tk.get("shop"); token = tk.get("access_token")
    try:
        orders = _shopify_orders(shop, token, desde, hasta)
    except Exception:
        return None
    costos = (_costos().get(email) or {})
    r = resumen_vacio()
    r["fecha"] = desde if desde == hasta else (desde + " a " + hasta)
    r["desde"] = desde; r["hasta"] = hasta
    r["actualizado"] = (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).strftime("%H:%M:%S")
    emap = _envialo_costos(email)   # {nº pedido → costo REAL de envío} (vacío si no conectó Envialo)
    # MP: pagos reales del período para MATCHEAR cada pedido con su pago (comisión exacta).
    pagos = _mp_pagos_lista(email, desde, hasta)
    mp_conectado = pagos is not None
    by_ref, by_amt = {}, {}
    # Los pagos de MERCADOLIBRE quedan FUERA de la bolsa de la tienda: su comision ya se cuenta
    # en meli_comision y, al entrar aca, se pegaba por monto a pedidos de Shopify del mismo
    # importe y se restaba dos veces (medido 29-09-2026: 26 pagos, $596.169 en UN dia).
    for p in (pagos or []):
        if _mp_es_de_meli(p.get("ref")):
            continue
        if p["ref"]:
            by_ref.setdefault(str(p["ref"]), []).append(p)
        by_amt.setdefault(p["amount"], []).append(p)
    mp_costo = 0.0
    mp_match = 0
    iibb_ret = 0.0     # IIBB que MP ya retuvo en los pagos del periodo (pago a cuenta)
    perc_iva = 0.0     # PERCEPCION de IVA: otro impuesto, este SI es credito fiscal
    fact = cobr = costo_prod = reemb_monto = envio_monto = 0.0
    envio_flex = 0            # cuantos se costearon como Flex y no como Andreani
    envio_zona = 0.0   # suma de la tabla Andreani por zona (con descuento)
    unidades = ordenes = reemb_cant = envio_real = 0
    ordenes_cero = 0   # pedidos en $0: no son ventas, pero su producto y envio si cuestan
    prodmap = {}
    ords_list = []
    # Solo cuentan las órdenes YA COBRADAS. Efectivo/transferencia pendiente, autorizado sin capturar o
    # 'pending' NO suman (ni facturación, ni órdenes, ni CPA) hasta que se paguen. Al cobrarse pasan a 'paid'
    # y recién ahí entran. Los reembolsos fueron ventas reales cobradas → siguen contando.
    PAGADAS = ("paid", "partially_paid", "refunded", "partially_refunded")
    for o in orders:
        if o.get("cancelled_at"):
            continue
        if (o.get("financial_status") or "").lower() not in PAGADAS:
            continue
        tot = float(o.get("total_price") or o.get("current_total_price") or 0)
        # Una orden en $0 (reposicion / reenvio sin cargo) NO es una venta: no factura, asi que
        # no genera IVA, ni IIBB, ni comision, ni el 0,6% de tienda, y tampoco lleva el
        # fulfillment de $800. Lo UNICO que cuesta es el producto que se regalo y el envio, y
        # eso se sigue sumando abajo como siempre. Contarla como venta metia un pedido en el
        # divisor sin aportar un peso: el 29-09-2026 el ticket salia $68.374 en vez de $75.269
        # y el Break Even CPA $26.631 en vez de $29.317 (12 de 131 pedidos estaban en $0).
        if tot > 0:
            ordenes += 1
        else:
            ordenes_cero += 1
        fact += tot
        # Envío: costo REAL de Envialo si el pedido ya está ahí; si no, promedio domicilio/sucursal.
        _num = str(o.get("order_number") or o.get("name") or "").replace("#", "").strip()
        if _envio_unificado_paga(_num):
            envio_zona += _envio_costo(o)   # SIEMPRE la tabla Andreani por zona (con descuento)
            # Si el pedido se marco como FLEX, no paga tarifa de correo: cuesta lo que cuesta
            # llevarlo. Si todavia no se cargo ese costo, se deja la tabla de Andreani antes
            # que inventar un numero que le cambie la ganancia a ciegas.
            _metodo = " ".join((x.get("title") or "") for x in (o.get("shipping_lines") or []))
            _fx = _flex_costo_envio(o) if _logi_de(email, _num, _metodo) == "flex" else None
            if _fx is not None:
                envio_monto += _fx; envio_flex += 1
            else:
                _real = emap.get(_num)
                if _real is not None:
                    envio_monto += _real; envio_real += 1
                else:
                    envio_monto += _envio_costo(o)
        # else: viaja dentro del paquete de otro pedido (ver ENVIOS_UNIFICADOS) -> no suma envio
        # MP: matcheo este pedido con su pago real (por referencia; fallback por monto exacto).
        pago = None
        if mp_conectado:
            # El checkout_token PRIMERO: es lo que MP manda de external_reference en esta tienda
            # (ej "r7N7EaGFbPuG1hmd0x0jDF3sP"). Sin el, NINGUN pedido matcheaba por referencia y
            # los 124 del 29-09-2026 caian al match por MONTO, que con precios fijos se cruza.
            for ref in (str(o.get("checkout_token") or ""), str(o.get("checkout_id") or ""),
                        str(o.get("id")), str(o.get("order_number")), _num):
                if not ref:
                    continue
                lst = by_ref.get(ref)
                if lst:
                    pago = lst.pop(0); break
            if pago is None:
                pago = _mp_tomar_cercano(by_amt.get(round(tot)), o.get("created_at"))
            if pago is not None:
                mp_costo += pago["fee"]; mp_match += 1
                # IIBB ya adelantado por MP en ESTE pago. No es costo aparte (el IIBB_PCT del
                # periodo ya lo cobra entero); se guarda para poder auditarlo y ver cuanto del
                # impuesto ya esta pago antes de la DDJJ.
                iibb_ret += float(pago.get("ret") or 0)
                perc_iva += float(pago.get("perc_iva") or 0)
        if (o.get("financial_status") or "") in ("paid", "partially_paid", "authorized"):
            cobr += tot
        for li in (o.get("line_items") or []):
            q = int(li.get("quantity") or 0)
            unidades += q
            pid = str(li.get("product_id") or "")
            c = costos.get(pid)
            if c:
                costo_prod += _costo_qty(c, q)
            nm = li.get("title") or "?"
            prodmap[nm] = prodmap.get(nm, 0) + q
        for rf in (o.get("refunds") or []):
            reemb_cant += 1
            for tx in (rf.get("transactions") or []):
                reemb_monto += float(tx.get("amount") or 0)
        # Fila para la tabla "Últimas ventas" (neto = lo real que entró por MP si matcheó, sino el total).
        ords_list.append({"num": _num, "origen": "Shopify",
                          "estado": _ESTADO_TXT.get((o.get("financial_status") or "").lower(), "—"),
                          "fecha": o.get("created_at") or "",
                          "total": round(tot, 2),
                          "neto": round(pago["net"] if pago else tot, 2)})
    # Costos por venta. MercadoPago: comisión REAL matcheada pedido-por-pedido (mp_costo, ya
    # sumado en el loop). Así NO infla con pagos que no son de la tienda. Si no hay MP conectado,
    # cae al % manual. FIJOS: 1% tienda + 3,5% Ingresos Brutos. Envío: real (Envialo) o promedio.
    iibb_monto = fact * IIBB_PCT / 100.0
    tienda_monto = fact * TIENDA_PCT / 100.0
    if not mp_conectado:
        cu = _comis_user(email)
        mp_costo = fact * (cu["mp_comision"] + cu["mp_cuotas"]) * (1 + cu["iva"] / 100.0) / 100.0
    # RETENCIONES DE MP (IIBB de provincias: SIRTAC, CABA y regimenes locales). Es plata que no
    # entra, asi que resta igual que siempre; lo que cambia es que ahora se ve como linea propia
    # en vez de venir disfrazada de comision de MercadoPago, y que NO suma al IVA a favor.
    comision_monto = mp_costo + iibb_ret + perc_iva + iibb_monto + tienda_monto
    r["mp_costo_real"] = round(mp_costo, 2)
    r["mp_match"] = mp_match            # pedidos que matchearon su pago de MP (comisión exacta)
    r["iibb_monto"] = round(iibb_monto, 2)
    r["tienda_monto"] = round(tienda_monto, 2)
    r["envio_monto"] = round(envio_monto, 2)
    r["ordenes_cero"] = ordenes_cero
    r["envio_zona_monto"] = round(envio_zona, 2)
    r["envio_real"] = envio_real       # cuántos pedidos usaron el costo REAL de Envialo
    # fulfillment $800 por PAQUETE, incluidos los pedidos en $0: la reposicion se arma y se
    # despacha igual, asi que ese trabajo se paga. Lo que NO cuentan es como venta (no van al
    # divisor del ticket ni del CPA). Insumos van aparte, como gasto mensual.
    oper_monto = OPER_ORDEN * (ordenes + ordenes_cero)
    r["oper_monto"] = round(oper_monto, 2)
    ganancia = fact - costo_prod - comision_monto - envio_monto - oper_monto
    # Break-even: contribución ANTES de ads (lo que queda para pagar publicidad).
    _pre_ads = fact - costo_prod - comision_monto - envio_monto - oper_monto
    r["be_roas"] = round(fact / _pre_ads, 2) if _pre_ads > 0 else 0.0
    r["breakeven_roas"] = r["be_roas"]
    r["be_cpa"] = round(_pre_ads / ordenes, 2) if ordenes else 0.0
    r["breakeven_cpa"] = r["be_cpa"]
    r["ordenes"] = ordenes
    r["ventas_periodo"] = ordenes
    r["unidades"] = unidades
    r["facturado"] = round(fact, 2)
    r["cobrado"] = round(cobr, 2)
    r["costo_prod"] = round(costo_prod, 2)
    r["comision"] = round(comision_monto, 2)
    r["ganancia"] = round(ganancia, 2)
    r["margen"] = round(ganancia / fact * 100, 2) if fact else 0.0
    r["ticket"] = round(fact / ordenes, 2) if ordenes else 0.0
    r["gan_por_venta"] = round(ganancia / ordenes, 2) if ordenes else 0.0
    r["reemb_cantidad"] = reemb_cant
    r["reemb_monto"] = round(reemb_monto, 2)
    r["iibb_retenido"] = r["retenciones_mp"] = round(iibb_ret, 2)
    r["percep_iva"] = round(perc_iva, 2)
    # Totales (por ahora solo Shopify, sin MELI)
    r["tot_ordenes"] = ordenes
    r["tot_facturado"] = round(fact, 2)
    r["tot_ganancia"] = round(ganancia, 2)
    r["tot_costo"] = round(costo_prod, 2)
    r["tot_margen"] = round(ganancia / fact * 100, 2) if fact else 0.0
    r["tot_aov"] = round(fact / ordenes, 2) if ordenes else 0.0
    r["tot_gan_por_venta"] = round(ganancia / ordenes, 2) if ordenes else 0.0
    prod = [{"nombre": k, "unidades": v, "facturado": 0.0}
            for k, v in sorted(prodmap.items(), key=lambda x: -x[1])[:10]]
    ords_list.sort(key=lambda x: int(x["num"]) if str(x["num"]).isdigit() else 0, reverse=True)
    return {"raw": r, "prod": prod, "ords": ords_list}


_TN_ORDERS_CACHE = {}   # {(email,desde,hasta): (ts, [orders])} — órdenes crudas de TN, cache 60s


def _tn_orders_raw(email, desde, hasta):
    """Órdenes crudas de TN del período (cache 60s). Las comparten el dashboard y últimas ventas,
    así no se bajan dos veces en la misma carga."""
    import time as _t
    ck = (email, desde, hasta)
    c = _TN_ORDERS_CACHE.get(ck)
    if c and (_t.time() - c[0] < 60):
        return c[1]
    tk = _tn_tokens().get(email)
    if not tk or not tk.get("access_token") or not tk.get("store_id"):
        return []
    store, hdr = tk["store_id"], _tn_headers(tk["access_token"])
    out, vistos, page = [], set(), 1
    while page <= 20:
        try:
            r = requests.get("%s/%s/orders" % (TN_API, store), headers=hdr, params={
                "per_page": 200, "page": page,
                "created_at_min": desde + "T00:00:00-03:00",
                "created_at_max": hasta + "T23:59:59-03:00"}, timeout=40)
            lote = r.json() if r.content else []
        except Exception:
            lote = []
        if not isinstance(lote, list) or not lote:
            break
        for o in lote:
            n = str(o.get("number") or "")
            if n and n not in vistos:
                vistos.add(n); out.append(o)
        if len(lote) < 200:
            break
        page += 1
    _TN_ORDERS_CACHE[ck] = (_t.time(), out)
    return out


_MELI_ULT_ERROR = ""        # ultimo error de la API de MercadoLibre, para mostrarlo tal cual


def _meli_resumen(email, desde, hasta):
    """Mismo 'raw'/prod/ords que Shopify/Tiendanube pero con las ordenes de MercadoLibre.
    COSTOS REALES POR ORDEN (medido el 12/09 sobre una venta real):
      - comision: sale_fee que ML informa en CADA item (ej 12.297,95 sobre 59.990 = 20,5%).
        No se estima con un porcentaje: sale por venta.
      - envio: NO se suma (decision de Cristian).
      - fulfillment: OPER_ORDEN por pedido, igual que los otros canales.
      - IIBB 3,5%. El 1% de tienda NO aplica: ese es de la tienda propia.
      - costo de producto: por SKU (meli:X2-POTE). Si no esta cargado queda en 0 y se cuenta
        en meli_sin_costo, en vez de inventar un numero."""
    global _MELI_ULT_ERROR
    tok, uid = _meli_ctx(email)
    if not tok or not uid:
        _MELI_ULT_ERROR = "no hay token de MercadoLibre conectado"
        return None
    _MELI_ULT_ERROR = ""
    h = {"Authorization": "Bearer " + tok}
    ordenes_ml = []
    # PAGINADO: el tope estaba en 8 paginas = 400 ordenes POR PERIODO. Para un dia sobra, pero al
    # pedir el MES quedaba cortado: septiembre 2026 mostraba 391 ventas de MELI cuando en un solo
    # dia (29-09) hubo 50, o sea ~1.500 en el mes. Faltaban ~$ 70 millones de facturacion.
    # Ahora pagina hasta agotar el total que informa ML, con un tope alto de seguridad y un
    # limite de tiempo para no colgar la pantalla si la cuenta crece mucho.
    import time as _tml
    _fin_ml = _tml.time() + 75          # presupuesto de tiempo, no de paginas
    try:
        off = 0
        _tot_ml = None
        for _ in range(200):                    # tope duro de seguridad (10.000 ordenes)
            if _tml.time() > _fin_ml:
                break
            rr = requests.get("%s/orders/search" % MELI_API, headers=h, timeout=25, params={
                "seller": uid, "sort": "date_desc", "limit": 50, "offset": off,
                "order.date_created.from": desde + "T00:00:00.000-03:00",
                "order.date_created.to": hasta + "T23:59:59.000-03:00"})
            if rr.status_code >= 400:
                # OJO: un error de la API NO es "no vendio nada". Cortando aca el dia quedaba
                # con MELI en CERO y, como la pauta de MELI se lee por otra via (la API de
                # facturacion) y esa SI entra, el canal mostraba una perdida inventada: el
                # 22-10-2026 daba -$189.753 con 0 ventas, y el dia anterior habia vendido 17.
                # Devolver None marca el canal como "no cargo" en vez de mentir un cero.
                _MELI_ULT_ERROR = "HTTP %s %s" % (rr.status_code, (rr.text or "")[:200])
                return None
            jj = rr.json() or {}
            res = jj.get("results") or []
            ordenes_ml += res
            if _tot_ml is None:
                _tot_ml = int((jj.get("paging") or {}).get("total") or 0)
            off += 50
            if not res or off >= (_tot_ml or 0):
                break
    except Exception:
        return None
    costos = (_costos().get(email) or {})
    # PAGOS DE MP DE LAS VENTAS DE MELI. El sale_fee que informa ML es SOLO "cargos de Mercado
    # Libre" (cargo por vender + costo de cuotas). MercadoPago le saca dos cosas mas a la misma
    # venta, y las dos salen de la plata de la venta:
    #   - shp_* : el CARGO POR ENVIO (ej shp_dropoff $ 7.290 en una venta de $ 69.990)
    #   - tax_withholding_* : las RETENCIONES de IIBB de provincias
    # Sin esto la ganancia de MELI salia ~27% mas alta de la real (29-09-2026: $ 408.910 en un
    # dia). Cada venta tiene su numero propio: sale del pago, nunca de un promedio.
    _pg_ml = {}
    for _p in (_mp_pagos_lista(email, desde, hasta) or []):
        if _mp_es_de_meli(_p.get("ref")):
            _pg_ml[str(_p.get("ref"))] = _p
    r = resumen_vacio()
    r["fecha"] = desde if desde == hasta else (desde + " a " + hasta)
    r["desde"] = desde; r["hasta"] = hasta
    r["actualizado"] = (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).strftime("%H:%M:%S")
    fact = costo_prod = comis_ml = 0.0
    envio_ml = ret_ml = 0.0
    envio_real = 0
    unidades = ordenes = sin_costo = 0
    prodmap, ords_list = {}, []
    for o in ordenes_ml:
        if (o.get("status") or "").lower() != "paid":
            continue
        ordenes += 1
        tot = float(o.get("total_amount") or 0)
        fact += tot
        com_orden = 0.0
        for it in (o.get("order_items") or []):
            q = int(it.get("quantity") or 0)
            com_orden += float(it.get("sale_fee") or 0) * q   # sale_fee es POR UNIDAD
            comis_ml += float(it.get("sale_fee") or 0) * q
            itm = it.get("item") or {}
            sku = str(itm.get("seller_sku") or itm.get("seller_custom_field") or "").strip()
            # UNIDADES = POTES, no publicaciones. `quantity` es cuántas veces se compró la
            # publicación: un "Pack x2" comprado una vez trae quantity=1 y son DOS potes, así
            # que contaba casi la mitad (medido 26-09-2026: 14 ventas = 28 potes, decía 14).
            # No se puede usar un factor: la mezcla de X1/X2/X3 cambia todos los días. El costo
            # de acá abajo ya lo hacía bien; las unidades no lo usaban.
            unidades += _meli_units_from_sku(sku) * q if sku else q
            # COSTO POR UNIDAD (meli:POTE), multiplicado por los potes que dice el SKU.
            # Asi un pack nuevo (X3, X6) toma el costo solo, sin cargar nada de nuevo.
            c = costos.get("meli:%s" % sku) if sku else None      # costo propio de ESE sku (si lo cargaron)
            if c:
                costo_prod += _costo_qty(c, q)
            else:
                _base = costos.get("meli:POTE")
                _u = _meli_units_from_sku(sku) if sku else 1
                if _base:
                    costo_prod += _costo_num(_base) * _u * q
                else:
                    sin_costo += q
            nm = itm.get("title") or "?"
            prodmap[nm] = prodmap.get(nm, 0) + q
        # BUG que introduje y corrijo: comis_ml es el ACUMULADOR de todas las comisiones, no la
        # de esta orden. Usarlo aca hacia que el neto de cada orden restara el total acumulado y
        # que la ganancia del dashboard CAMBIARA entre dos lecturas del mismo periodo.
        # ENVIO y RETENCIONES de ESTA venta, del pago real de MercadoPago.
        _env_o = _ret_o = 0.0
        _pm = _pg_ml.get(str(o.get("id") or ""))
        if _pm:
            for _nm, _am in (_pm.get("cargos") or {}).items():
                _n = str(_nm).lower()
                if _n.startswith("shp") or "shipping" in _n:
                    _env_o += float(_am or 0)
            _ret_o = float(_pm.get("ret") or 0)
            if _env_o:
                envio_real += 1
        envio_ml += _env_o
        ret_ml += _ret_o
        ords_list.append({"num": str(o.get("id") or ""), "origen": "MercadoLibre",
                          "estado": "Pagado", "fecha": (o.get("date_created") or ""),
                          "total": round(tot, 2),
                          "neto": round(tot - com_orden - _env_o - _ret_o, 2)})
    iibb_monto = fact * IIBB_PCT / 100.0
    oper_monto = OPER_ORDEN * ordenes
    # Misma bolsa que en la tienda: comision del canal + retenciones + IIBB. Sin 1% de tienda,
    # que ese es de la tienda propia.
    # El CARGO POR ENVIO de ML entra ACA, no en envios: no es un envio que se pague aparte (la
    # etiqueta la da MercadoLibre), es una retencion mas de lo que se queda ML sobre la venta.
    # Decision de Cristian (30-09-2026): "no lo pongas como pago de envios, ponelo como comision
    # o gasto, sin IVA". Por eso NO suma al credito fiscal (meli_comision, que si tiene IVA, sigue
    # siendo solo el sale_fee).
    comision_monto = comis_ml + envio_ml + ret_ml + iibb_monto
    # Adelanto Programado de MercadoPago: 3,75% (IVA incluido) sobre la plata que MP adelanta,
    # que es lo que queda DESPUES de la comision de ML (no sobre el precio de venta).
    # OJO: en MercadoLibre el adelanto para cobrar al instante es 2,5%, NO el 3,75% del
    # Adelanto Programado de MercadoPago de la tienda. Con el 3,75% se le restaba de más a
    # MELI (26-09-2026: $ 30.919 en vez de $ 20.613, o sea $ 10.306 de más en un día).
    # El 2,5% se cobra sobre lo que MP VA A LIBERAR (el "Total a recibir el 28/oct" de la pantalla
    # de MercadoPago), que es la venta menos TODO lo que ya se descuento: cargos de ML, envio y
    # retenciones. Con la base vieja (solo menos la comision de ML) se cobraba de mas: $ 194,94 en
    # una venta de $ 69.990 y $ 10.222,76 en el dia del 29-09-2026.
    adelanto_monto = (fact - comis_ml - envio_ml - ret_ml) * MELI_ADELANTO_PCT / 100.0
    ganancia = fact - costo_prod - comision_monto - oper_monto - adelanto_monto
    r["mp_costo_real"] = 0.0; r["mp_match"] = 0
    r["iibb_monto"] = round(iibb_monto, 2); r["tienda_monto"] = 0.0
    # El envio de MELI NO entra en envio_monto: decision de Cristian (30-09-2026, reafirmada),
    # "no lo pago yo, ya va pagado en el desglose de lo que entra". Se sigue leyendo por venta
    # porque la base del ADELANTO lo necesita (MP adelanta el neto, que ya viene sin el envio) y
    # para poder auditarlo en /pf-debug-meli, pero no resta de la ganancia ni suma credito de IVA.
    # OJO si algun dia se revisa: la facturacion de MELI se cuenta al BRUTO ($ 69.990), no al neto,
    # asi que no descontarlo deja esos $ 7.290 por venta como ganancia ($ 366.500 el 29-09-2026).
    r["envio_monto"] = 0.0          # MELI no tiene envio propio: el cargo va en la comision
    r["meli_envio"] = 0.0
    r["meli_cargo_envio"] = round(envio_ml, 2)    # dentro de comision, SIN credito de IVA
    r["envio_real"] = 0
    r["retenciones_mp"] = r["iibb_retenido"] = r["meli_retenciones"] = round(ret_ml, 2)
    r["oper_monto"] = round(oper_monto, 2)
    _pre = fact - costo_prod - comision_monto - oper_monto - adelanto_monto
    r["be_roas"] = r["breakeven_roas"] = round(fact / _pre, 2) if _pre > 0 else 0.0
    r["be_cpa"] = r["breakeven_cpa"] = round(_pre / ordenes, 2) if ordenes else 0.0
    r["ordenes"] = r["ventas_periodo"] = r["tot_ordenes"] = ordenes
    r["unidades"] = unidades
    r["facturado"] = r["tot_facturado"] = round(fact, 2)
    r["cobrado"] = round(fact - comis_ml, 2)        # lo que entra despues de la comision de ML
    r["costo_prod"] = r["tot_costo"] = round(costo_prod, 2)
    r["comision"] = round(comision_monto, 2)
    r["ganancia"] = r["tot_ganancia"] = round(ganancia, 2)
    r["margen"] = r["tot_margen"] = round(ganancia / fact * 100, 2) if fact else 0.0
    r["ticket"] = r["tot_aov"] = round(fact / ordenes, 2) if ordenes else 0.0
    r["gan_por_venta"] = r["tot_gan_por_venta"] = round(ganancia / ordenes, 2) if ordenes else 0.0
    # campos propios de MELI (ya estaban reservados en resumen_vacio y nunca se llenaban)
    r["meli_ventas"] = ordenes; r["meli_unidades"] = unidades
    r["meli_facturado"] = round(fact, 2); r["meli_cobrado"] = round(fact - comis_ml, 2)
    r["meli_comision"] = round(comis_ml, 2); r["meli_costo"] = round(costo_prod, 2)
    r["meli_ganancia"] = round(ganancia, 2)
    r["meli_aov"] = round(fact / ordenes, 2) if ordenes else 0.0
    r["meli_rent"] = round(ganancia / fact * 100, 2) if fact else 0.0
    r["meli_gan_venta"] = round(ganancia / ordenes, 2) if ordenes else 0.0
    # Lo que de verdad queda en la mano: aca SI se resta el envio, porque MercadoPago te lo
    # descuenta antes de liberar la plata (es el "Total a recibir" de la pantalla de MP).
    r["meli_neto"] = round(fact - comis_ml - envio_ml - ret_ml - adelanto_monto, 2)
    r["meli_sin_costo"] = sin_costo
    r["meli_adelanto"] = round(adelanto_monto, 2)
    prod = [{"nombre": k, "unidades": v, "facturado": 0.0}
            for k, v in sorted(prodmap.items(), key=lambda x: -x[1])[:10]]
    ords_list.sort(key=lambda x: x.get("fecha") or "", reverse=True)
    return {"raw": r, "prod": prod, "ords": ords_list}


def _tn_resumen(email, desde, hasta):
    """Mismo 'raw'/prod/ords que _shopify_resumen pero con los pedidos de Tiendanube."""
    tk = _tn_tokens().get(email)
    if not tk or not tk.get("access_token") or not tk.get("store_id"):
        return None
    orders = [o for o in _tn_orders_raw(email, desde, hasta) if not o.get("cancelled_at")]
    costos = (_costos().get(email) or {})
    pagos = _mp_pagos_lista(email, desde, hasta)
    by_amt = {}
    for p in (pagos or []):
        by_amt.setdefault(p["amount"], []).append(p)
    mp_conectado = pagos is not None
    r = resumen_vacio()
    r["fecha"] = desde if desde == hasta else (desde + " a " + hasta)
    r["desde"] = desde; r["hasta"] = hasta
    r["actualizado"] = (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).strftime("%H:%M:%S")
    fact = cobr = costo_prod = envio_monto = mp_costo = 0.0
    iibb_ret = 0.0     # IIBB que MP ya retuvo (mismo trato que en Shopify)
    perc_iva = 0.0     # PERCEPCION de IVA (mismo trato que en Shopify)
    unidades = ordenes = mp_match = 0
    ordenes_cero = 0   # pedidos en $0: no son ventas (ver la nota en _shopify_resumen)
    prodmap, ords_list = {}, []
    for o in orders:
        if (o.get("payment_status") or "").lower() != "paid":
            continue
        tot = float(o.get("total") or 0)
        # Una orden en $0 (reposicion / reenvio sin cargo) NO es una venta: no factura, asi que
        # no genera IVA, ni IIBB, ni comision, ni el 0,6% de tienda, y tampoco lleva el
        # fulfillment de $800. Lo UNICO que cuesta es el producto que se regalo y el envio, y
        # eso se sigue sumando abajo como siempre. Contarla como venta metia un pedido en el
        # divisor sin aportar un peso: el 29-09-2026 el ticket salia $68.374 en vez de $75.269
        # y el Break Even CPA $26.631 en vez de $29.317 (12 de 131 pedidos estaban en $0).
        if tot > 0:
            ordenes += 1
        else:
            ordenes_cero += 1
        fact += tot; cobr += tot
        _ez = ENVIO_ZONAS.get(_envio_zona(o)) or {"sucursal": ENVIO_SUCURSAL, "domicilio": ENVIO_DOMICILIO}
        _es_suc = _tn_shipping(o).get("type") == "pickup" or _envio_suc(o)
        envio_monto += _ez["sucursal"] if _es_suc else _ez["domicilio"]
        if mp_conectado:
            lst = by_amt.get(round(tot))
            if lst:
                pago = lst.pop(0); mp_costo += pago["fee"]; mp_match += 1
                iibb_ret += float(pago.get("ret") or 0)
                perc_iva += float(pago.get("perc_iva") or 0)
        for p in (o.get("products") or []):
            q = int(p.get("quantity") or 0); unidades += q
            c = costos.get("tn:%s" % p.get("product_id"))
            if c:
                costo_prod += _costo_qty(c, q)
            nm = p.get("name") or "?"
            if isinstance(nm, dict):
                nm = nm.get("es") or next(iter(nm.values()), "?")
            prodmap[nm] = prodmap.get(nm, 0) + q
        ords_list.append({"num": str(o.get("number") or ""), "origen": "Tiendanube",
                          "estado": "Pagado", "fecha": o.get("created_at") or "",
                          "total": round(tot, 2), "neto": round(tot * (1 - TIENDA_PCT / 100.0), 2)})
    iibb_monto = fact * IIBB_PCT / 100.0
    tienda_monto = fact * TIENDA_PCT / 100.0
    if not mp_conectado:
        cu = _comis_user(email)
        mp_costo = fact * (cu["mp_comision"] + cu["mp_cuotas"]) * (1 + cu["iva"] / 100.0) / 100.0
    comision_monto = mp_costo + iibb_ret + perc_iva + iibb_monto + tienda_monto
    oper_monto = OPER_ORDEN * (ordenes + ordenes_cero)   # ver la nota en _shopify_resumen
    ganancia = fact - costo_prod - comision_monto - envio_monto - oper_monto
    r["mp_costo_real"] = round(mp_costo, 2); r["mp_match"] = mp_match
    r["retenciones_mp"] = r["iibb_retenido"] = round(iibb_ret, 2)
    r["percep_iva"] = round(perc_iva, 2)
    r["ordenes_cero"] = ordenes_cero
    r["iibb_monto"] = round(iibb_monto, 2); r["tienda_monto"] = round(tienda_monto, 2)
    r["envio_monto"] = round(envio_monto, 2); r["envio_real"] = 0
    r["oper_monto"] = round(oper_monto, 2)
    _pre = fact - costo_prod - comision_monto - envio_monto - oper_monto
    r["be_roas"] = r["breakeven_roas"] = round(fact / _pre, 2) if _pre > 0 else 0.0
    r["be_cpa"] = r["breakeven_cpa"] = round(_pre / ordenes, 2) if ordenes else 0.0
    r["ordenes"] = r["ventas_periodo"] = r["tot_ordenes"] = ordenes
    r["unidades"] = unidades
    r["facturado"] = r["tot_facturado"] = round(fact, 2)
    r["cobrado"] = round(cobr, 2)
    r["costo_prod"] = r["tot_costo"] = round(costo_prod, 2)
    r["comision"] = round(comision_monto, 2)
    r["ganancia"] = r["tot_ganancia"] = round(ganancia, 2)
    r["margen"] = r["tot_margen"] = round(ganancia / fact * 100, 2) if fact else 0.0
    r["ticket"] = r["tot_aov"] = round(fact / ordenes, 2) if ordenes else 0.0
    r["gan_por_venta"] = r["tot_gan_por_venta"] = round(ganancia / ordenes, 2) if ordenes else 0.0
    r["reemb_cantidad"] = 0; r["reemb_monto"] = 0.0
    prod = [{"nombre": k, "unidades": v, "facturado": 0.0}
            for k, v in sorted(prodmap.items(), key=lambda x: -x[1])[:10]]
    ords_list.sort(key=lambda x: x.get("fecha") or "", reverse=True)
    return {"raw": r, "prod": prod, "ords": ords_list}


def _combinar_resumen(a, b):
    """Suma dos blobs de resumen (Shopify + Tiendanube) y recalcula los ratios."""
    if not a:
        return b
    if not b:
        return a
    ra, rb = a["raw"], b["raw"]
    r = resumen_vacio()
    r["fecha"] = ra.get("fecha"); r["desde"] = ra.get("desde"); r["hasta"] = ra.get("hasta")
    r["actualizado"] = ra.get("actualizado")
    SUM = ["mp_costo_real", "mp_match", "iibb_monto", "tienda_monto", "envio_monto", "envio_real",
           "oper_monto", "ordenes", "ordenes_cero", "ventas_periodo", "unidades", "facturado", "cobrado", "costo_prod",
           "comision", "ganancia", "reemb_cantidad", "reemb_monto", "iibb_retenido", "retenciones_mp", "percep_iva",
           "tot_ordenes", "tot_facturado", "tot_ganancia", "tot_costo",
           "meli_ventas", "meli_unidades", "meli_facturado", "meli_cobrado",
           "meli_comision", "meli_costo", "meli_ganancia", "meli_sin_costo", "meli_adelanto",
                   "meli_envio", "meli_retenciones", "meli_cargo_envio"]
    for k in SUM:
        r[k] = round((ra.get(k) or 0) + (rb.get(k) or 0), 2)
    fact = r["facturado"]; gan = r["ganancia"]; ordn = r["ordenes"]
    r["margen"] = r["tot_margen"] = round(gan / fact * 100, 2) if fact else 0.0
    r["ticket"] = r["tot_aov"] = round(fact / ordn, 2) if ordn else 0.0
    r["gan_por_venta"] = r["tot_gan_por_venta"] = round(gan / ordn, 2) if ordn else 0.0
    _pre = fact - r["costo_prod"] - r["comision"] - r["envio_monto"] - (r.get("oper_monto") or 0)
    r["be_roas"] = r["breakeven_roas"] = round(fact / _pre, 2) if _pre > 0 else 0.0
    r["be_cpa"] = r["breakeven_cpa"] = round(_pre / ordn, 2) if ordn else 0.0
    prod = (a.get("prod") or []) + (b.get("prod") or [])
    prod.sort(key=lambda x: -x.get("unidades", 0))
    ords = (a.get("ords") or []) + (b.get("ords") or [])
    ords.sort(key=lambda x: x.get("fecha") or "", reverse=True)
    return {"raw": r, "prod": prod[:10], "ords": ords}


_ORDS_CACHE = {}
_ESTADO_TXT = {"paid": "Pagado", "partially_paid": "Parcial", "pending": "Pendiente",
               "authorized": "Autorizado", "partially_refunded": "Reemb. parcial",
               "refunded": "Reembolsado", "voided": "Anulado"}


def _shopify_ordenes(email, dias=90):
    """Últimas órdenes REALES de Shopify (últimos `dias` días) para la tabla 'Últimas ventas'.
    Cada una: {num, origen, estado, fecha, total, neto}. neto = lo real que entró por MP (matcheado)
    o el total si no matcheó/no es MP. Cache 2 min por usuario."""
    import time as _t
    tk = _shop_tokens().get(email)
    if not tk or not tk.get("access_token"):
        return []
    c = _ORDS_CACHE.get(email)
    if c and (_t.time() - c[0] < 120):
        return c[1]
    hasta = _hoy()
    desde = (_dt.date.today() - _dt.timedelta(days=dias)).isoformat()
    try:
        orders = _shopify_orders(tk.get("shop"), tk.get("access_token"), desde, hasta)
    except Exception:
        return []
    orders = [o for o in orders if not o.get("cancelled_at")]
    pagos = _mp_pagos_lista(email, desde, hasta)   # para el neto real por pedido
    by_ref, by_amt = {}, {}
    # Los pagos de MERCADOLIBRE quedan FUERA de la bolsa de la tienda: su comision ya se cuenta
    # en meli_comision y, al entrar aca, se pegaba por monto a pedidos de Shopify del mismo
    # importe y se restaba dos veces (medido 29-09-2026: 26 pagos, $596.169 en UN dia).
    for p in (pagos or []):
        if _mp_es_de_meli(p.get("ref")):
            continue
        if p["ref"]:
            by_ref.setdefault(str(p["ref"]), []).append(p)
        by_amt.setdefault(p["amount"], []).append(p)
    out = []
    for o in orders:
        tot = float(o.get("total_price") or o.get("current_total_price") or 0)
        num = str(o.get("order_number") or o.get("name") or "").replace("#", "").strip()
        pago = None
        if pagos is not None:
            for ref in (str(o.get("id")), str(o.get("order_number")), num):
                lst = by_ref.get(ref)
                if lst:
                    pago = lst.pop(0); break
            if pago is None:
                lst = by_amt.get(round(tot))
                if lst:
                    pago = lst.pop(0)
        neto = pago["net"] if pago else tot
        fs = (o.get("financial_status") or "").lower()
        out.append({"num": num, "origen": "Shopify",
                    "estado": _ESTADO_TXT.get(fs, (fs or "—").title()),
                    "fecha": o.get("created_at") or "",
                    "total": round(tot, 2), "neto": round(neto, 2)})
    out.sort(key=lambda x: int(x["num"]) if str(x["num"]).isdigit() else 0, reverse=True)
    out = out[:200]
    _ORDS_CACHE[email] = (_t.time(), out)
    return out


