# ==================== TikTok Ads (conectar con un click) ====================
# Mismo patrón que Meta: OAuth -> token -> cuenta publicitaria elegida -> gasto al Dashboard.
# OJO, la diferencia con Meta: TikTok NO tiene "pegá tu token" tipo Graph Explorer. Sí o sí hay
# que crear una app en business-api.tiktok.com/portal y que TikTok la apruebe. Cuando esté
# aprobada, las 3 variables van en Render y esto anda solo:
#   TIKTOK_APP_ID  /  TIKTOK_APP_SECRET  /  TIKTOK_REDIRECT_URI
# El redirect_uri tiene que ser EXACTAMENTE el mismo que se cargó en la app de TikTok.
TIKTOK_API = "https://business-api.tiktok.com/open_api/v1.3"
TIKTOK_TOKENS = DATA_DIR / "tiktok_tokens.json"   # token + cuenta por usuario (persistente)


def _tiktok_cfg() -> dict:
    return {"app_id": (_os.getenv("TIKTOK_APP_ID") or "").strip(),
            "app_secret": (_os.getenv("TIKTOK_APP_SECRET") or "").strip(),
            "redirect_uri": ((_os.getenv("TIKTOK_REDIRECT_URI") or "").strip()
                             or "https://www.realprofitapp.com/tiktok/callback")}


def _tiktok_tokens() -> dict:
    try:
        return _json.loads(TIKTOK_TOKENS.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _tiktok_save_token(key, data) -> None:
    d = _tiktok_tokens()
    d[str(key)] = data
    TIKTOK_TOKENS.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")


def _tiktok_get(ruta, token, params):
    """GET a la API de TikTok. El token va en el header Access-Token (NO en la query, como Meta).
    TikTok siempre devuelve HTTP 200: el error real viene en el campo 'code' del JSON."""
    r = requests.get(TIKTOK_API + ruta, headers={"Access-Token": token}, params=params, timeout=30)
    j = r.json() if r.content else {}
    if int(j.get("code", -1)) != 0:
        raise RuntimeError(str(j.get("message") or "TikTok devolvió un error")[:160])
    return j.get("data") or {}


@app.get("/conectar-tiktok")
@limiter.limit("30 per hour")
def conectar_tiktok():
    """Manda al usuario a la pantalla oficial de TikTok for Business para autorizar sus Ads."""
    if not _user_actual():
        return redirect("/")
    cfg = _tiktok_cfg()
    if not cfg["app_id"]:
        return ("Falta configurar el App ID de TikTok (variables en Render).", 400)
    state = _secrets.token_urlsafe(16)
    session["tiktok_state"] = state
    qs = _url.urlencode({"app_id": cfg["app_id"], "state": state, "redirect_uri": cfg["redirect_uri"]})
    return redirect("https://business-api.tiktok.com/portal/auth?" + qs, code=302)


@app.get("/tiktok/callback")
@limiter.limit("30 per hour")
def tiktok_callback():
    """TikTok vuelve con 'auth_code'. Lo cambiamos por el access_token (el de Marketing API no
    vence) y guardamos las cuentas publicitarias que autorizó."""
    cfg = _tiktok_cfg()
    code = request.args.get("auth_code") or request.args.get("code")
    state = request.args.get("state")
    if not code:
        return ("RealProfit — punto de conexión con TikTok. Volvé a la app y usá «Conectar».", 200)
    if not state or state != session.get("tiktok_state"):
        return ("La conexión no pasó el control de seguridad. Reintentá desde el botón.", 400)
    try:
        r = requests.post(TIKTOK_API + "/oauth2/access_token/",
                          json={"app_id": cfg["app_id"], "secret": cfg["app_secret"],
                                "auth_code": code, "grant_type": "authorization_code"}, timeout=30)
        j = r.json() if r.content else {}
    except Exception:
        return ("No pudimos conectar con TikTok en este momento. Probá de nuevo.", 502)
    data = j.get("data") or {}
    if int(j.get("code", -1)) != 0 or not data.get("access_token"):
        return ("TikTok no autorizó la conexión: %s" % str(j.get("message") or "")[:140], 400)
    email = _user_actual()
    if not email:
        return redirect("/")
    ids = [str(x) for x in (data.get("advertiser_ids") or [])]
    _tiktok_save_token(email, {"access_token": data["access_token"], "advertisers": ids,
                               "cuenta": ids[0] if len(ids) == 1 else None})
    session.pop("tiktok_state", None)
    return redirect("/?integ=1", code=302)


@app.get("/tiktok/estado")
def tiktok_estado():
    email = _user_actual()
    tk = _tiktok_tokens().get(email) if email else None
    return jsonify({"ok": True, "conectado": bool(tk and tk.get("access_token")),
                    "cuenta": (tk or {}).get("cuenta"),
                    "listo": bool(_tiktok_cfg()["app_id"])})


@app.get("/tiktok/cuentas")
def tiktok_cuentas():
    """Las cuentas publicitarias que el usuario autorizó, con nombre y moneda."""
    email = _user_actual()
    tk = _tiktok_tokens().get(email) if email else None
    if not tk or not tk.get("access_token"):
        return jsonify({"ok": True, "cuentas": [], "elegida": None})
    ids = [str(x) for x in (tk.get("advertisers") or [])]
    cuentas = []
    if ids:
        try:
            d = _tiktok_get("/advertiser/info/", tk["access_token"],
                            {"advertiser_ids": _json.dumps(ids),
                             "fields": _json.dumps(["advertiser_id", "advertiser_name", "currency"])})
            for a in (d.get("list") or []):
                cuentas.append({"id": str(a.get("advertiser_id")),
                                "name": a.get("advertiser_name") or ("Cuenta " + str(a.get("advertiser_id"))),
                                "moneda": a.get("currency")})
        except Exception:
            cuentas = [{"id": i, "name": "Cuenta " + i, "moneda": ""} for i in ids]
    return jsonify({"ok": True, "cuentas": cuentas, "elegida": tk.get("cuenta")})


@app.post("/tiktok/cuenta")
def tiktok_elegir_cuenta():
    """Guarda cuál cuenta publicitaria de TikTok mira este usuario (de ahí sale el gasto)."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "error": "Entrá a RealProfit primero."}), 401
    cid = str((request.get_json(silent=True) or {}).get("cuenta") or "").strip()
    if not cid:
        return jsonify({"ok": False, "error": "Elegí una cuenta."}), 400
    tk = _tiktok_tokens().get(email) or {}
    if not tk.get("access_token"):
        return jsonify({"ok": False, "error": "Conectá TikTok primero."}), 400
    tk["cuenta"] = cid
    tk.pop("moneda", None)                 # cuenta nueva => moneda a recalcular
    _tiktok_save_token(email, tk)
    return jsonify({"ok": True})


@app.get("/desconectar-tiktok")
def desconectar_tiktok():
    email = _user_actual()
    if email:
        d = _tiktok_tokens()
        d.pop(email, None)
        TIKTOK_TOKENS.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    return redirect("/?integ=1")


def _tiktok_spend_crudo(email, desde, hasta):
    """Gasto de TikTok Ads del período EN LA MONEDA DE LA CUENTA.
    Devuelve (monto, moneda, hubo_api). `hubo_api` dice si la API contestó de verdad — NO alcanza
    con mirar la moneda, porque la consulta de moneda puede fallar aunque el gasto haya venido
    bien, y ahí caeríamos al gasto cargado a mano tapando el número real."""
    tk = _tiktok_tokens().get(email) or {}
    token = tk.get("access_token")
    cuenta = str(tk.get("cuenta") or "").strip()
    if not token or not cuenta:
        return 0.0, "", False
    try:
        d = _tiktok_get("/report/integrated/get/", token,
                        {"advertiser_id": cuenta, "report_type": "BASIC",
                         "data_level": "AUCTION_ADVERTISER",
                         "dimensions": _json.dumps(["advertiser_id"]),
                         "metrics": _json.dumps(["spend"]),
                         "start_date": desde, "end_date": hasta, "page_size": 1})
        filas = d.get("list") or []
        monto = float((filas[0].get("metrics") or {}).get("spend") or 0) if filas else 0.0
    except Exception:
        return 0.0, "", False
    moneda = str(tk.get("moneda") or "").upper()
    if not moneda:                          # se pregunta UNA vez y queda guardada
        try:
            info = _tiktok_get("/advertiser/info/", token,
                               {"advertiser_ids": _json.dumps([cuenta]),
                                "fields": _json.dumps(["advertiser_id", "currency"])})
            moneda = str(((info.get("list") or [{}])[0] or {}).get("currency") or "").upper()
            if moneda:
                tk["moneda"] = moneda
                _tiktok_save_token(email, tk)
        except Exception:
            pass
    return monto, moneda, True


# ---- Gasto CARGADO A MANO (mientras TikTok no apruebe la app) ----
# TikTok exige un mail corporativo para registrarte como developer, y la aprobación tarda días.
# Para no quedar ciego mientras tanto, el gasto se puede cargar a mano o subiendo el CSV que baja
# el Ads Manager. Guardado POR DÍA y EN PESOS. Apenas la API esté conectada, MANDA LA API y esto
# queda de respaldo solo: no hay que borrar nada ni apagar nada a mano.
TIKTOK_MANUAL = DATA_DIR / "tiktok_gasto_manual.json"   # {email: {"YYYY-MM-DD": monto_ars}}
_TK_MANUAL_LOCK = threading.Lock()


def _tk_manual_all() -> dict:
    try:
        return _json.loads(TIKTOK_MANUAL.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _tk_manual_set(email, dias: dict) -> int:
    """Guarda {fecha: monto} para ese usuario. Pisa los días que vengan, deja el resto.
    Monto 0 o negativo BORRA el día (así se puede corregir una carga mal hecha)."""
    with _TK_MANUAL_LOCK:
        d = _tk_manual_all()
        mio = d.get(email) or {}
        for f, m in (dias or {}).items():
            if m and float(m) > 0:
                mio[f] = round(float(m), 2)
            else:
                mio.pop(f, None)
        d[email] = mio
        try:
            TIKTOK_MANUAL.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
        except Exception:
            return 0
    return len(dias or {})


def _tk_manual_rango(email, desde, hasta) -> float:
    """Suma lo cargado a mano entre dos fechas (inclusive). Las claves son YYYY-MM-DD, que se
    comparan bien como texto, así que no hace falta parsear nada."""
    mio = _tk_manual_all().get(email) or {}
    d, h = str(desde)[:10], str(hasta)[:10]
    return round(sum(float(v or 0) for f, v in mio.items() if d <= f <= h), 2)


def _tk_num(s) -> float:
    """Pasa a número un importe como lo escribe TikTok: '1.234,56' (es-AR), '1,234.56' (en-US),
    '$ 1234', '1234'. Regla: si están los dos separadores, EL ÚLTIMO es el decimal."""
    t = re.sub(r"[^0-9,.\-]", "", str(s or "")).strip()
    if not t:
        return 0.0
    ult_c, ult_p = t.rfind(","), t.rfind(".")
    if ult_c >= 0 and ult_p >= 0:
        dec = "," if ult_c > ult_p else "."
        mil = "." if dec == "," else ","
        t = t.replace(mil, "").replace(dec, ".")
    elif ult_c >= 0 or ult_p >= 0:
        # Un solo tipo de separador y NO se sabe si es coma decimal o punto de miles. La regla que
        # desempata es cuántos dígitos deja atrás: 1 o 2 => DECIMAL ('12,5' / '1234.56'); 3 => MILES
        # ('1.234' en es-AR es mil doscientos treinta y cuatro, NO uno coma doscientos treinta y
        # cuatro). Sin esto, un gasto de $1.234 entraba al Dashboard como $1,23.
        sep = "," if ult_c >= 0 else "."
        ult = ult_c if ult_c >= 0 else ult_p
        if len(t) - ult - 1 in (1, 2):
            t = t[:ult].replace(sep, "") + "." + t[ult + 1:]
        else:
            t = t.replace(sep, "")
    try:
        return float(t)
    except ValueError:
        return 0.0


def _tk_fecha(s) -> str:
    """Normaliza a YYYY-MM-DD. Acepta '2026-09-22', '22/09/2026' y '2026/09/22'.
    Ojo: TikTok puede traer la fecha con la hora pegada, por eso el corte al principio."""
    t = str(s or "").strip()[:10].replace("/", "-")
    m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})$", t)
    if m:
        return "%s-%02d-%02d" % (m.group(1), int(m.group(2)), int(m.group(3)))
    m = re.match(r"^(\d{1,2})-(\d{1,2})-(\d{4})$", t)     # es-AR: día primero
    if m:
        return "%s-%02d-%02d" % (m.group(3), int(m.group(2)), int(m.group(1)))
    return ""


def _tk_csv_leer(texto):
    """Lee el CSV que baja el Ads Manager de TikTok y devuelve {fecha: gasto}.
    Busca las columnas por NOMBRE (en español o inglés) en vez de por posición, porque el orden
    cambia según qué métricas hayas tildado al armar el reporte."""
    import csv as _csv, io as _io
    texto = (texto or "").lstrip("﻿")                 # los export de TikTok vienen con BOM
    if not texto.strip():
        return {}, "El archivo está vacío."
    primera = texto.split("\n", 1)[0]
    sep = ";" if primera.count(";") > primera.count(",") else ","
    filas = list(_csv.DictReader(_io.StringIO(texto), delimiter=sep))
    if not filas:
        return {}, "No pude leer ninguna fila del archivo."
    cols = [c for c in (filas[0].keys() or []) if c]
    def _buscar(claves):
        for c in cols:
            n = c.strip().lower()
            if any(k in n for k in claves):
                return c
        return None
    c_fecha = _buscar(["fecha", "date", "día", "dia", "day"])
    c_gasto = _buscar(["costo total", "total cost", "costo", "cost", "gasto", "spend", "importe"])
    if not c_fecha or not c_gasto:
        return {}, "No encontré las columnas de fecha y costo. Columnas del archivo: " + ", ".join(cols[:8])
    dias = {}
    for f in filas:
        fe = _tk_fecha(f.get(c_fecha))
        if not fe:
            continue
        dias[fe] = round(dias.get(fe, 0.0) + _tk_num(f.get(c_gasto)), 2)
    if not dias:
        return {}, "Leí el archivo pero ninguna fila tenía una fecha válida."
    return dias, ""


@app.get("/tiktok/gasto")
def tiktok_gasto_ver():
    """Los últimos días cargados a mano, para mostrarlos en la tarjeta."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "dias": []}), 401
    mio = _tk_manual_all().get(email) or {}
    dias = [{"fecha": f, "monto": v} for f, v in sorted(mio.items(), reverse=True)[:30]]
    return jsonify({"ok": True, "dias": dias, "total": round(sum(d["monto"] for d in dias), 2)})


@app.post("/tiktok/gasto")
def tiktok_gasto_cargar():
    """Carga a mano el gasto de UN día (en pesos). Monto 0 borra ese día."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "error": "Entrá a RealProfit primero."}), 401
    j = request.get_json(silent=True) or {}
    fecha = _tk_fecha(j.get("fecha"))
    if not fecha:
        return jsonify({"ok": False, "error": "Fecha inválida."}), 400
    _tk_manual_set(email, {fecha: _tk_num(j.get("monto"))})
    return jsonify({"ok": True, "fecha": fecha})


@app.post("/tiktok/gasto-csv")
def tiktok_gasto_csv():
    """Sube el CSV del Ads Manager de TikTok y carga todos los días de una."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "error": "Entrá a RealProfit primero."}), 401
    f = request.files.get("csv") or (next(iter(request.files.values())) if request.files else None)
    if not f:
        return jsonify({"ok": False, "error": "No llegó ningún archivo."}), 400
    try:
        crudo = f.read()
        try:
            texto = crudo.decode("utf-8-sig")
        except UnicodeDecodeError:
            texto = crudo.decode("latin-1", "replace")     # Excel en Windows guarda así
    except Exception as e:
        return jsonify({"ok": False, "error": "No pude leer el archivo: %s" % str(e)[:120]}), 400
    dias, err = _tk_csv_leer(texto)
    if err:
        return jsonify({"ok": False, "error": err}), 400
    _tk_manual_set(email, dias)
    return jsonify({"ok": True, "dias": len(dias),
                    "total": round(sum(dias.values()), 2),
                    "desde": min(dias), "hasta": max(dias)})


def _tiktok_spend(email, desde, hasta) -> float:
    """Gasto de TikTok del período EN PESOS (mismo criterio que _meta_spend).
    Si la API está conectada MANDA LA API; si no, usa lo cargado a mano."""
    monto, moneda, hubo_api = _tiktok_spend_crudo(email, desde, hasta)
    if hubo_api:
        if monto and moneda == "USD":            # moneda desconocida => se asume local, no se convierte
            monto *= _dolar_ars_vivo()
        # Mismo estabilizador que Meta (solo crece, compartido en disco entre workers), con su
        # propia clave para NO pisar el número de Meta.
        return _meta_spend_estable("tk:" + str(email), desde, hasta, monto)
    # Sin API: lo cargado a mano. NO pasa por el estabilizador, porque acá sí tiene que poder
    # BAJAR (si se corrige una carga mal hecha, el número nuevo manda).
    return _tk_manual_rango(email, desde, hasta)


def _tiktok_ads_usd(email, desde, hasta) -> float:
    """Gasto de TikTok del período EN DÓLARES (para la planilla de finanzas)."""
    monto, moneda, hubo_api = _tiktok_spend_crudo(email, desde, hasta)
    if not hubo_api:                             # sin API: lo cargado a mano, que está en pesos
        monto, moneda = _tk_manual_rango(email, desde, hasta), "ARS"
    elif not moneda:                             # API sí, moneda desconocida => se asume local
        moneda = "ARS"
    if monto and moneda and moneda != "USD":
        tc = _dolar_ars_vivo() or 0
        monto = (monto / tc) if tc else 0.0
    return round(monto, 2)


# ==================== SUBIR CREATIVOS (Meta Ads) ====================
_ADS_API = "https://graph.facebook.com/v23.0"
_ADS_JOBS = {}
_ADS_UPLOADS = {}   # upload_id -> carpeta con los creativos subidos (cache en memoria)
# Las subidas van al DISCO PERSISTENTE (/var/data), NO a /tmp. Antes, un deploy o un reciclado de
# worker borraba /tmp Y vaciaba este dict → "no encontré los videos que subiste" con los archivos
# ya cargados y la config llena. Pasó el 16/09 a las 00:17, justo después de un deploy.
_ADS_UPDIR = DATA_DIR / "ads_uploads"          # carpeta madre de todas las subidas
_ADS_UPIDX = DATA_DIR / "ads_uploads.json"     # {upload_id: {"dir":…, "ts":…, "email":…}}
_ADS_UP_TTL = 24 * 3600                        # una subida vive 24 h; después se purga sola


def _ads_up_idx_load() -> dict:
    try:
        return _json.loads(_ADS_UPIDX.read_text("utf-8"))
    except Exception:
        return {}


def _ads_up_idx_save(d: dict) -> None:
    try:
        _ADS_UPIDX.write_text(_json.dumps(d), "utf-8")
    except Exception:
        pass


def _ads_up_dir(up_id: str):
    """Carpeta de una subida. Mira la memoria y, si no está (worker nuevo o reinicio), el disco."""
    d = _ADS_UPLOADS.get(up_id)
    if d and _os.path.isdir(d):
        return d
    d = (_ads_up_idx_load().get(up_id) or {}).get("dir")
    if d and _os.path.isdir(d):
        _ADS_UPLOADS[up_id] = d
        return d
    return None


def _ads_up_purga(borrar_id: str = "") -> None:
    """Borra la subida indicada y las vencidas. SIN esto el disco (1 GB, compartido con tokens,
    chats y usuarios) se llena solo y se rompe toda la app, no solo los ads."""
    import shutil as _sh, time as _t
    idx = _ads_up_idx_load()
    ahora = _t.time()
    for k in list(idx.keys()):
        it = idx.get(k) or {}
        if k == borrar_id or (ahora - float(it.get("ts") or 0)) > _ADS_UP_TTL:
            try:
                _sh.rmtree(it.get("dir") or "", ignore_errors=True)
            except Exception:
                pass
            idx.pop(k, None)
            _ADS_UPLOADS.pop(k, None)
    _ads_up_idx_save(idx)
# Subida de video a Meta: cuanto se manda por vez. Meta suele pedir el archivo ENTERO de una;
# leerlo entero y ademas armar el cuerpo multipart = 2/3 copias del video en RAM. Con 2 videos
# a la vez eso volteaba el server (medido: 284MB -> 1267MB en 2 min -> SIGKILL).
_ADS_CHUNK = 8 * 1024 * 1024
_ADS_BIGLOCK = threading.Lock()   # si hay que mandar un tramo grande, UNO por vez en todo el server

