@app.get("/pf-ads-identidad")
def pf_ads_identidad():
    """Página / IG / pixel VINCULADOS a la cuenta (para los desplegables)."""
    if not _user_actual():
        return jsonify({"ok": False})
    cfg = _ADS_CUENTAS.get(request.args.get("cuenta") or "cp1") or _ADS_CUENTAS["cp1"]
    acct = cfg["ad_account"]

    def lst(path, fields):
        try:
            return _ads_call("GET", "act_%s/%s" % (acct, path), params={"fields": fields, "limit": 50}).get("data", [])
        except Exception:
            return []

    def lst_raw(path, fields):
        try:
            return _ads_call("GET", path, params={"fields": fields, "limit": 100}).get("data", [])
        except Exception:
            return []
    pixels = [{"id": p["id"], "name": p.get("name", "")} for p in lst("adspixels", "id,name")]
    igs = [{"id": i["id"], "name": "@" + (i.get("username") or "")} for i in lst("instagram_accounts", "id,username")]
    # Páginas: las que conectaste (me/accounts) + las promocionables de la cuenta. Sin nombres hardcodeados.
    pages, seen = [], set()
    for p in (lst_raw("me/accounts", "id,name") + lst("promote_pages", "id,name")):
        pid = p.get("id")
        if pid and pid not in seen:
            seen.add(pid); pages.append({"id": pid, "name": p.get("name", "") or "Página"})
    if cfg.get("page") and cfg["page"] not in seen:                # la del config, con su NOMBRE REAL
        nm = ""
        try:
            nm = (_ads_call("GET", str(cfg["page"]), params={"fields": "name"}) or {}).get("name", "")
        except Exception:
            pass
        pages.insert(0, {"id": cfg["page"], "name": nm or "Página conectada"})
    # MISMO respaldo para el IG que para la página: una cuenta publicitaria NUEVA todavía no tiene
    # el Instagram asociado, así que act_<cuenta>/instagram_accounts vuelve vacío y el desplegable
    # caía en "Sin IG (page-backed)" aunque el IG esté configurado. Lo agrego con su nombre real.
    if cfg.get("ig") and not any(str(i.get("id")) == str(cfg["ig"]) for i in igs):
        nmig = ""
        try:
            nmig = (_ads_call("GET", str(cfg["ig"]), params={"fields": "username"}) or {}).get("username", "")
        except Exception:
            pass
        igs.insert(0, {"id": cfg["ig"], "name": ("@" + nmig) if nmig else "Instagram conectado"})
    # MISMO respaldo para el PIXEL. act_<cuenta>/adspixels devuelve solo los pixels ASIGNADOS a
    # esa cuenta publicitaria: en una cuenta nueva vuelve vacio y el desplegable quedaba en
    # blanco (paso el 21-10-2026 con CP PESOS). Se agrega el del config con su nombre real, pero
    # marcado: si Meta no lo lista es porque todavia no esta asignado a la cuenta y va a
    # rechazar el anuncio. Mejor verlo aca que descubrirlo cuando falla la subida.
    pixel_ok = any(str(x.get("id")) == str(cfg.get("pixel")) for x in pixels)
    if cfg.get("pixel") and not pixel_ok:
        nmpx = ""
        try:
            nmpx = (_ads_call("GET", str(cfg["pixel"]), params={"fields": "name"}) or {}).get("name", "")
        except Exception:
            pass
        pixels.insert(0, {"id": cfg["pixel"],
                          "name": (nmpx or "Pixel del config") + "  \u26a0 no asignado a esta cuenta"})
    # MONEDA de la cuenta: el presupuesto se manda en centavos de ESTA moneda, así que poner "35"
    # en una cuenta en pesos son $35 ARS (Meta lo rechaza), no US$35. Se muestra al lado del campo.
    # MINIMO DIARIO: Meta lo devuelve en la unidad chica (centavos). Sin esto, en una cuenta en
    # pesos el usuario ponia 35 pensando en dolares y Meta contestaba "presupuesto demasiado bajo".
    moneda = ""; min_diario = 0
    try:
        _cta = _ads_call("GET", "act_%s" % acct,
                         params={"fields": "currency,min_daily_budget"}) or {}
        moneda = _cta.get("currency", "") or ""
        min_diario = int(float(_cta.get("min_daily_budget") or 0)) / 100.0
    except Exception:
        pass
    return jsonify({"ok": True, "pixels": pixels, "igs": igs, "pages": pages, "moneda": moneda,
                    "min_diario": min_diario, "pixel_asignado": bool(pixel_ok),
                    "def": {"page": cfg["page"], "pixel": cfg["pixel"], "ig": cfg.get("ig", "")},
                    "ultimo": _ads_lastcfg_get(_user_actual(), request.args.get("cuenta") or "cp1")})


@app.get("/pf-ads-posts")
def pf_ads_posts():
    """{nombre del anuncio -> post id} de una cuenta. Lo usa la extension ROAS real.

    El Administrador no muestra el post id en ninguna columna, y el HTML de la fila
    tampoco trae el id del anuncio (Meta lo ofusca en js_xxx). Por eso el cruce va por
    NOMBRE: los duplicados del mismo creativo comparten el object_story_id, que es
    justo el que se usa para escalar una publicacion que ya corre."""
    if not _user_actual():
        return jsonify({"ok": False, "posts": {}}), 401
    acct = (request.args.get("act") or "").replace("act_", "").strip()
    if not acct.isdigit():
        return jsonify({"ok": False, "msg": "falta act", "posts": {}}), 400
    # El gasto del MISMO rango que esta mirando en el Administrador. Sirve de huella
    # para saber que fila es cual sin pedirle que agregue la columna del id: el id de
    # anuncio no esta en el HTML (Meta lo ofusca) y los nombres son "8", "7", "3".
    desde = (request.args.get("desde") or "").strip()
    hasta = (request.args.get("hasta") or "").strip()
    posts, por_id, por_gasto, gastos = {}, {}, {}, []
    campos = "id,name,creative{effective_object_story_id,object_story_id}"
    def _fecha_ok(x):
        return len(x) == 10 and x[4] == "-" and x[7] == "-" and x.replace("-", "").isdigit()
    if _fecha_ok(desde) and _fecha_ok(hasta):
        campos += ",insights.time_range({'since':'%s','until':'%s'}){spend}" % (desde, hasta)
    params = {"fields": campos, "limit": 200}
    try:
        for _ in range(25):                      # tope de seguridad: 5.000 anuncios
            r = _ads_call("GET", "act_%s/ads" % acct, params=params)
            datos = r.get("data") or []
            for a in datos:
                cr = a.get("creative") or {}
                sid = cr.get("effective_object_story_id") or cr.get("object_story_id") or ""
                if not sid:
                    continue
                nom = (a.get("name") or "").strip()
                if nom:
                    posts[nom] = sid
                por_id[str(a.get("id"))] = sid
                # Clave por gasto, con 2 decimales como lo muestra el Administrador.
                # Si dos anuncios gastaron EXACTO lo mismo la huella no sirve: se marca
                # en None para no mostrar un post id equivocado.
                try:
                    _ins = ((a.get("insights") or {}).get("data") or [])
                    if _ins:
                        _g = float(_ins[0].get("spend") or 0)
                        if _g > 0:
                            _k = "%.2f" % _g
                            por_gasto[_k] = None if _k in por_gasto else sid
                            gastos.append([round(_g, 2), sid])
                except Exception:
                    pass
            sig = ((r.get("paging") or {}).get("cursors") or {}).get("after")
            if not sig or not datos:
                break
            params = dict(params)
            params["after"] = sig
        return jsonify({"ok": True, "act": acct, "posts": posts, "por_id": por_id,
                        "por_gasto": {k: v for k, v in por_gasto.items() if v},
                        # La lista completa, porque el gasto se mueve en VIVO: cuando la
                        # extension compara, el Administrador ya muestra unos centavos mas.
                        # Con la lista puede buscar el mas cercano en vez de exacto.
                        "gastos": gastos,
                        "desde": desde, "hasta": hasta, "total": len(por_id)})
    except Exception as e:
        # El error real, no un generico: si el token no ve la cuenta hay que saberlo.
        return jsonify({"ok": False, "msg": ("%s: %s" % (type(e).__name__, e))[:200],
                        "posts": {}})


@app.get("/pf-ads-campanas")
def pf_ads_campanas():
    if not _user_actual():
        return jsonify({"ok": False, "campanas": []})
    cfg = _ADS_CUENTAS.get(request.args.get("cuenta") or "cp1") or _ADS_CUENTAS["cp1"]
    try:
        r = _ads_call("GET", "act_%s/campaigns" % cfg["ad_account"],
                      params={"fields": "name,effective_status,daily_budget", "limit": 100,
                              "effective_status": _json.dumps(["ACTIVE"])})   # solo campañas ACTIVAS
        out = [{"id": c["id"], "name": c.get("name", ""), "cbo": bool(c.get("daily_budget")),
                "presupuesto": int((c.get("daily_budget") or 0)) // 100, "activa": True}
               for c in r.get("data", []) if c.get("effective_status") == "ACTIVE"]
        out.sort(key=lambda x: int(x["id"]) if str(x["id"]).isdigit() else 0, reverse=True)
        return jsonify({"ok": True, "campanas": out})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e), "campanas": []})


@app.get("/pf-ads-conjuntos-config")
def pf_ads_conjuntos_config():
    """La configuracion REAL de los conjuntos de una cuenta, para comparar si son todos iguales.
    Solo lectura: no crea ni modifica nada."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 400
    cfg = _ADS_CUENTAS.get(request.args.get("cuenta") or "cp1") or _ADS_CUENTAS["cp1"]
    acct = cfg["ad_account"]
    if not acct:
        return jsonify({"ok": False, "msg": "cuenta no configurada"})
    try:
        lim = max(1, min(60, int(request.args.get("n") or 25)))
    except Exception:
        lim = 25
    F = ("name,status,effective_status,billing_event,optimization_goal,bid_strategy,daily_budget,"
         "attribution_spec,promoted_object,destination_type,pacing_type,optimization_sub_event,"
         "targeting,created_time,campaign{name}")
    try:
        j = _ads_call("GET", "act_%s/adsets" % acct,
                      params={"fields": F, "limit": lim,
                              "date_preset": "last_30d"}) or {}
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:110])})
    out = []
    for s_ in (j.get("data") or []):
        t = s_.get("targeting") or {}
        geo = (t.get("geo_locations") or {}).get("countries") or []
        aut = (t.get("targeting_automation") or {})
        out.append({
            "id": s_.get("id"), "nombre": (s_.get("name") or "")[:46],
            "campana": ((s_.get("campaign") or {}).get("name") or "")[:34],
            "estado": s_.get("effective_status") or s_.get("status"),
            "creado": (s_.get("created_time") or "")[:10],
            "billing": s_.get("billing_event"), "meta": s_.get("optimization_goal"),
            "puja": s_.get("bid_strategy"),
            "presupuesto": int((s_.get("daily_budget") or 0)) // 100,
            "evento": (s_.get("promoted_object") or {}).get("custom_event_type"),
            "pixel": (s_.get("promoted_object") or {}).get("pixel_id"),
            "atribucion": ["%s/%sd" % (a.get("event_type", ""), a.get("window_days"))
                           for a in (s_.get("attribution_spec") or [])],
            "paises": geo, "advantage": aut.get("advantage_audience"),
            "edad": "%s-%s" % (t.get("age_min", ""), t.get("age_max", "")),
            "sexos": t.get("genders") or "todos",
            "intereses": len(((t.get("flexible_spec") or [{}])[0] or {}).get("interests") or []),
            "destino": s_.get("destination_type"), "pacing": s_.get("pacing_type"),
        })
    return jsonify({"ok": True, "n": len(out), "conjuntos": out})


_ADS_CONJ_CACHE = {}        # campaign_id -> (cuando, conjuntos). Ver abajo por que.


# ══════════════════════ Llamada de la mañana ══════════════════════
# Twilio llama al celular y lee el resumen del dia anterior. La gracia no es el despertador
# (eso lo hace el iPhone) sino escuchar los numeros antes de levantarse.
#
# Hace falta en Render:  TWILIO_SID · TWILIO_TOKEN · TWILIO_FROM (el numero comprado)
#                        LLAMADA_A (a quien llamar)  ·  LLAMADA_CLAVE (para el cron)
TWILIO_SID = (_os.getenv("TWILIO_SID", "") or "").strip()
TWILIO_TOKEN = (_os.getenv("TWILIO_TOKEN", "") or "").strip()
TWILIO_FROM = (_os.getenv("TWILIO_FROM", "") or "").strip()
LLAMADA_A = (_os.getenv("LLAMADA_A", "") or "").strip()
LLAMADA_CLAVE = (_os.getenv("LLAMADA_CLAVE", "") or "").strip()


def _voz_plata(n) -> str:
    """Los numeros como se DICEN, no como se escriben. '1.240.500' leido por el sintetizador
    sale 'uno punto doscientos cuarenta' — en millones y miles se entiende."""
    n = int(round(float(n or 0)))
    if n >= 1000000:
        m = round(n / 1000000.0, 1)
        ent = int(m)
        if m == ent:
            return "%d %s de pesos" % (ent, "millón" if ent == 1 else "millones")
        return "%s %s de pesos" % (("%.1f" % m).replace(".", " coma "),
                                   "millón" if ent == 0 else "millones")
    if n >= 1000:
        resto = n % 1000
        return "%d mil%s pesos" % (n // 1000, (" %d" % resto) if resto else "")
    return "%d pesos" % n


def _voz_resumen(email) -> str:
    """El texto que se lee por telefono. Son los MISMOS numeros del dashboard: se llama a
    _pf_periodo_blob, no se recalcula nada aparte (si no, dirian cosas distintas)."""
    import datetime as _d
    ayer = (_d.date.today() - _d.timedelta(days=1)).isoformat()
    partes = ["Buen día Cristian."]
    try:
        r = (_pf_periodo_blob(email, ayer, ayer) or {}).get("raw") or {}
    except Exception:
        r = {}
    ordenes = int(r.get("tot_ordenes") or r.get("ordenes") or 0)
    if ordenes:
        partes.append("Ayer vendiste %s en %d pedidos." %
                      (_voz_plata(r.get("tot_facturado") or r.get("facturado")), ordenes))
        if float(r.get("ganancia") or 0):
            partes.append("La ganancia fue %s." % _voz_plata(r.get("tot_ganancia") or r.get("ganancia")))
        if float(r.get("roas") or 0):
            partes.append("El ROAS, %s." % ("%.2f" % float(r["roas"])).replace(".", " coma "))
    else:
        partes.append("Ayer no hubo ventas registradas.")
    try:
        pend = [x for x in (_despachos_orders(email) or []) if not x.get("estado")]
        if pend:
            partes.append("Tenés %d pedidos para despachar." % len(pend))
    except Exception:
        pass
    try:
        _fx = [v for v in (_flex_de(email) or {}).values() if v.get("estado") == "registrado"]
        if _fx:
            partes.append("%d son de Flex, todavía sin salir." % len(_fx))
    except Exception:
        pass
    partes.append("Que tengas buen día.")
    return " ".join(partes)


_VOZ_CHARLA = {}        # sid de la llamada -> [(quien, texto)]. Se limpia solo al colgar.
_VOZ_VOZ = "Polly.Mia-Neural"
_VOZ_IDIOMA = "es-MX"


def _voz_say(txt, escuchar=True, pausa=0):
    """Un TwiML. Si `escuchar`, despues de hablar abre el microfono y espera la respuesta."""
    from xml.sax.saxutils import escape as _esc
    x = ['<?xml version="1.0" encoding="UTF-8"?><Response>']
    if pausa:
        x.append('<Pause length="%d"/>' % pausa)
    if escuchar:
        # El <Say> va DENTRO del Gather: asi el microfono ya esta abierto mientras habla y
        # puede interrumpirlo, como con el OK Google. Afuera, hay que esperar a que termine.
        x.append('<Gather input="speech" language="es-AR" speechTimeout="auto" '
                 'action="/voz-charla" method="POST" actionOnEmptyResult="true">')
        x.append('<Say voice="%s" language="%s">%s</Say>' % (_VOZ_VOZ, _VOZ_IDIOMA, _esc(txt)))
        x.append('</Gather>')
    else:
        x.append('<Say voice="%s" language="%s">%s</Say><Hangup/>' % (_VOZ_VOZ, _VOZ_IDIOMA, _esc(txt)))
    x.append('</Response>')
    return Response("".join(x), mimetype="text/xml")


_VOZ_CHAU = ("chau", "listo gracias", "nada mas", "cortá", "corta", "adios", "adiós",
             "gracias nada mas", "ya esta", "ya está", "no nada mas", "cortar")


def _voz_contexto(email) -> str:
    """Los datos del negocio que el asistente tiene A MANO para contestar por telefono.
    Es el mismo resumen que lee al atender, mas lo que puede llegar a preguntar."""
    import datetime as _d
    hoy = _d.date.today().isoformat()
    ayer = (_d.date.today() - _d.timedelta(days=1)).isoformat()
    L = []
    for et, f in (("AYER", ayer), ("HOY", hoy)):
        try:
            r = (_pf_periodo_blob(email, f, f) or {}).get("raw") or {}
        except Exception:
            continue
        L.append("%s (%s): %d pedidos, facturado %s, ganancia %s, ROAS %s, pauta %s" % (
            et, f, int(r.get("tot_ordenes") or 0), int(r.get("tot_facturado") or 0),
            int(r.get("tot_ganancia") or 0), round(float(r.get("roas") or 0), 2),
            int(r.get("publi_ars") or 0)))
    try:
        pend = [x for x in (_despachos_orders(email) or []) if not x.get("estado")]
        L.append("Pedidos sin despachar: %d" % len(pend))
    except Exception:
        pass
    try:
        fx = [v for v in (_flex_de(email) or {}).values() if v.get("estado") == "registrado"]
        L.append("Envios Flex sin salir: %d" % len(fx))
    except Exception:
        pass
    return "\n".join(L) or "(no pude leer los numeros ahora)"


def _voz_pensar(email, sid, dijo) -> str:
    """Que contesta. Usa el mismo Claude que el bot de WhatsApp (ANTHROPIC_API_KEY ya esta
    en Render). Respuestas CORTAS: por telefono un parrafo largo no se sigue."""
    hist = _VOZ_CHARLA.setdefault(sid, [])
    hist.append(("cliente", dijo))
    sis = ("Sos el asistente de Cristian, dueño de NoxaLab, y le estas hablando POR TELEFONO "
           "a la mañana temprano. Contesta en argentino, en UNA o DOS frases cortas, sin "
           "listas ni simbolos: todo lo que escribas se va a leer en voz alta. Si te pregunta "
           "por numeros del negocio, usa SOLO los datos de abajo y no inventes. Si no los "
           "tenes, decilo. Si te pregunta otra cosa cualquiera, contesta igual, corto.\n\n"
           "DATOS DE HOY:\n" + _voz_contexto(email))
    msgs = [{"role": ("user" if q == "cliente" else "assistant"), "content": t}
            for q, t in hist[-12:]]
    try:
        r = requests.post("https://api.anthropic.com/v1/messages", timeout=25,
                          headers={"x-api-key": _os.getenv("ANTHROPIC_API_KEY", ""),
                                   "anthropic-version": "2023-06-01",
                                   "content-type": "application/json"},
                          json={"model": "claude-opus-4-8", "max_tokens": 200,
                                "system": sis, "messages": msgs})
        j = r.json()
        txt = "".join(b.get("text", "") for b in (j.get("content") or [])).strip()
    except Exception:
        txt = ""
    if not txt:
        txt = "Perdón, no te escuché bien. ¿Me lo repetís?"
    hist.append(("bot", txt))
    return txt


@app.post("/voz-charla")
def voz_charla():
    """Cada vuelta de la conversacion: Twilio manda lo que dijo Cristian, contestamos."""
    sid = (request.form.get("CallSid") or "").strip()
    dijo = (request.form.get("SpeechResult") or "").strip()
    email = _os.getenv("MCP_EMAIL", "") or _os.getenv("META_OWNER_EMAIL", "")
    if not dijo:
        if _VOZ_CHARLA.get(sid, []) and len(_VOZ_CHARLA[sid]) > 2:
            _VOZ_CHARLA.pop(sid, None)
            return _voz_say("Bueno, te dejo. Buen día.", escuchar=False)
        return _voz_say("¿Estás ahí? Preguntame lo que quieras.")
    if _res_norm(dijo) in [_res_norm(x) for x in _VOZ_CHAU]:
        _VOZ_CHARLA.pop(sid, None)
        return _voz_say("Dale, buen día Cristian.", escuchar=False)
    return _voz_say(_voz_pensar(email, sid, dijo))


@app.get("/voz-resumen")
def voz_resumen():
    """Lo que Twilio pide cuando el cliente atiende: TwiML con el texto a leer.

    Va SIN sesion a proposito — lo llama Twilio, no un navegador — pero lleva la clave en la
    URL. Si no coincide, se corta sin decir nada: no se filtran los numeros del negocio."""
    if LLAMADA_CLAVE and (request.args.get("clave") or "") != LLAMADA_CLAVE:
        return Response('<?xml version="1.0" encoding="UTF-8"?><Response><Hangup/></Response>',
                        mimetype="text/xml")
    import datetime as _dv
    _h = _dv.datetime.now().hour
    txt = ("Buen día Cristian, arriba. Son las %d y algo. Dale, despertate." % _h) if _h < 12 \
        else "Hola Cristian, soy tu asistente. ¿Qué necesitás?"
    txt += " Si querés te paso los números del negocio, o preguntame lo que sea."
    # DESPERTADOR, no informe. La gracia es que suene el telefono y que haya alguien del
    # otro lado: a una alarma la apagas dormido, a una llamada la tenes que atender y
    # contestar. Por eso arranca despertandolo y recien da los numeros SI los pide.
    return _voz_say(txt, escuchar=True, pausa=1)


def _llamar(a=None) -> dict:
    """Dispara la llamada. Devuelve {ok, msg/sid}."""
    if not (TWILIO_SID and TWILIO_TOKEN and TWILIO_FROM):
        return {"ok": False, "msg": "faltan TWILIO_SID / TWILIO_TOKEN / TWILIO_FROM en Render"}
    destino = (a or LLAMADA_A or "").strip()
    if not destino:
        return {"ok": False, "msg": "falta LLAMADA_A (a qué número llamar)"}
    url = "%s/voz-resumen" % RP_BASE.rstrip("/")
    if LLAMADA_CLAVE:
        url += "?clave=" + _url.quote(LLAMADA_CLAVE)
    try:
        r = requests.post("https://api.twilio.com/2010-04-01/Accounts/%s/Calls.json" % TWILIO_SID,
                          auth=(TWILIO_SID, TWILIO_TOKEN), timeout=30,
                          data={"To": destino, "From": TWILIO_FROM, "Url": url, "Method": "GET"})
        j = r.json() if r.content else {}
    except Exception as e:
        return {"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:140])}
    if r.status_code >= 400:
        return {"ok": False, "msg": j.get("message") or ("HTTP %d" % r.status_code),
                "codigo": j.get("code")}
    return {"ok": True, "sid": j.get("sid"), "a": destino}


