@app.post("/pf-ads-subir")
def pf_ads_subir():
    if not _user_actual():
        return jsonify({"ok": False}), 401
    import tempfile, uuid, zipfile, shutil as _sh
    files = request.files.getlist("videos")
    if not files:
        return jsonify({"ok": False, "msg": "elegí al menos un video"}), 400
    # SE SUBE DE A UN ARCHIVO. Flask corta el pedido entero a los 35 MB (tope puesto para que un
    # archivo gigante no se cargue en RAM y mate al worker), asi que mandar 10 fotos juntas
    # reventaba con "El archivo es muy grande" aunque ninguna lo fuera. Ahora el front manda uno
    # por vez y reusa la misma tanda con upload_id: el tope pasa a ser POR ARCHIVO, no por tanda.
    up_id = (request.form.get("upload_id") or "").strip()
    d = ""
    if up_id:
        _idx0 = _ads_up_idx_load().get(up_id) or {}
        if _idx0.get("dir") and _idx0.get("email") == (_user_actual() or ""):
            d = _idx0["dir"]
        else:
            up_id = ""                                # no es tuya o ya vencio: arranca una nueva
    if not up_id:
        up_id = uuid.uuid4().hex[:12]
        _ads_up_purga()                               # limpia las subidas vencidas antes de crear otra
        d = str(_ADS_UPDIR / up_id)                   # DISCO persistente: sobrevive deploys y reinicios
    _os.makedirs(d, exist_ok=True)
    EXT = (".mp4", ".mov", ".m4v", ".jpg", ".jpeg", ".png", ".webp")

    def _destino_unico(base):
        dest = _os.path.join(d, base); k = 1
        while _os.path.exists(dest):
            dest = _os.path.join(d, "%d_%s" % (k, base)); k += 1
        return dest

    for f in files:
        fn = (f.filename or "")
        if fn.lower().endswith(".zip"):
            # ZIP (ej: la carpeta entera bajada de Drive) → descomprimir SOLO los videos/fotos,
            # aplanando subcarpetas internas. Streaming directo, sin pasos de más = rápido.
            zp = _os.path.join(d, "_paquete.zip")
            f.save(zp)
            try:
                with zipfile.ZipFile(zp) as z:
                    for zi in z.infolist():
                        if zi.is_dir():
                            continue
                        base = _os.path.basename(zi.filename)
                        if not base or base.startswith(".") or "__MACOSX" in zi.filename:
                            continue
                        if not base.lower().endswith(EXT):
                            continue
                        with z.open(zi) as src, open(_destino_unico(base), "wb") as out:
                            _sh.copyfileobj(src, out, 1024 * 1024 * 4)
            except zipfile.BadZipFile:
                return jsonify({"ok": False, "msg": "ese .zip está dañado o no lo pude abrir"}), 400
            finally:
                try:
                    _os.remove(zp)
                except Exception:
                    pass
        else:
            name = _os.path.basename(fn or "video.mp4")
            if not name.lower().endswith(EXT):
                continue
            f.save(_destino_unico(name))

    # juntar TODO lo que quedó en la carpeta (sueltos + los que salieron del zip), en orden
    vids = []
    for name in sorted(_os.listdir(d)):
        p = _os.path.join(d, name)
        if _os.path.isfile(p) and name.lower().endswith(EXT):
            vids.append({"name": name, "mb": round(_os.path.getsize(p) / 1048576)})
    if not vids:
        return jsonify({"ok": False, "msg": "no encontré videos ni fotos (.mp4/.mov/.jpg/.png), ni sueltos ni dentro del zip"}), 400
    vids.sort(key=lambda v: v["name"])
    _ADS_UPLOADS[up_id] = d
    _idx = _ads_up_idx_load()                         # y al disco, para que lo vea cualquier worker
    _idx[up_id] = {"dir": d, "ts": __import__("time").time(), "email": _user_actual() or ""}
    _ads_up_idx_save(_idx)
    return jsonify({"ok": True, "upload_id": up_id, "videos": vids})


@app.post("/pf-ads-lanzar")
def pf_ads_lanzar():
    if not _user_actual():
        return jsonify({"ok": False}), 401
    if not _ads_token():
        return jsonify({"ok": False, "msg": "falta META_TOKEN en el servidor (Render → Environment)"}), 400
    data = request.get_json(silent=True) or {}
    _escala = (data.get("modo") or "renovacion") == "escala"
    if _escala:
        if not [p for p in (data.get("posts") or []) if _ads_post_id(p, "1")]:
            return jsonify({"ok": False, "msg": "pegá al menos una publicación (post ID) para escalar"}), 400
    elif not (data.get("drive") or "").strip() and not (data.get("upload_id") or "").strip():
        return jsonify({"ok": False, "msg": "pegá el link de Drive o subí tus videos"}), 400
    # Limite de costo / de puja SIN puja: Meta lo rechaza recien a mitad del job, con los videos
    # ya subidos y la campaña creada a medias. Mejor frenarlo acá y decir que falta.
    _es = (data.get("estrategia") or "minimo").strip()
    if _es in ("costcap", "bidcap") and not [v for v in (data.get("pujas") or []) if _ads_num(v) > 0]:
        return jsonify({"ok": False,
                        "msg": "elegiste %s pero no agregaste ninguna puja" % (
                            "objetivo de costo por resultado" if _es == "costcap"
                            else "límite de puja")}), 400
    import uuid
    # MULTI-CUENTA: si vienen varias, se lanza UN job por cuenta. Cada uno con SU token y SU
    # presupuesto (las cuentas pueden estar en monedas distintas: un solo numero no sirve para las dos).
    ctas = [str(x) for x in (data.get("cuentas") or []) if str(x).strip()]
    if not ctas:
        ctas = [data.get("cuenta") or "cp1"]
    vistas = []
    for c in ctas:                       # sin repetidos, respetando el orden
        if c not in vistas and c in _ADS_CUENTAS:
            vistas.append(c)
    if not vistas:
        return jsonify({"ok": False, "msg": "no reconocí la cuenta elegida"}), 400
    presups = data.get("presupuestos") or {}
    jobs = []
    for c in vistas:
        d = dict(data)
        d["cuenta"] = c
        d.pop("cuentas", None); d.pop("presupuestos", None)
        if presups.get(c):
            d["presupuesto"] = presups[c]
        d["_token"] = _ads_token_para_cuenta(c)   # token que REALMENTE puede usar esa cuenta (no cruza cuentas)
        job = uuid.uuid4().hex[:12]
        _ads_lastcfg_set(_user_actual(), c, d)    # recordar la config para la próxima subida
        _ADS_JOBS[job] = {"done": 0, "total": 0, "msg": "Arrancando…", "listo": False, "error": None, "stats": {}}
        _job_put(job, _ADS_JOBS[job])   # a DISCO: si el worker se recicla, el progreso no se pierde
        threading.Thread(target=_ads_run, args=(job, d), daemon=True).start()
        jobs.append({"job": job, "cuenta": c,
                     "nombre": (_ADS_CUENTAS.get(c) or {}).get("nombre", c)})
    return jsonify({"ok": True, "job": jobs[0]["job"], "jobs": jobs})


@app.get("/pf-ads-progreso")
def pf_ads_progreso():
    if not _user_actual():
        return jsonify({"ok": False}), 401
    _jid = (request.args.get("job") or "").strip()
    # memoria primero, disco después: sin el respaldo en disco, un reciclado del worker de gunicorn
    # devolvía 404 y la pantalla se quedaba clavada en el último mensaje ("Creando conjunto 1 de 1…")
    # aunque el servidor hubiera seguido y creado todo bien en Meta.
    st = _ADS_JOBS.get(_jid) or _job_get(_jid)
    if not st:
        return jsonify({"ok": False}), 404
    # Si hace mas de 3 minutos que no late, el proceso murio. Dos causas vistas: el worker de
    # gunicorn se reciclo por --max-requests (medido 14-sep: mato el job 19s despues de lanzarlo,
    # sin una sola linea de OOM) o el sistema lo mato por memoria. NO afirmar cual de las dos:
    # decir que se corto. Antes la pantalla quedaba clavada en "Subiendo videos 5/6" para siempre.
    if not st.get("listo") and not st.get("error"):
        import time as _tp
        _ts = float(st.get("ts") or 0)
        if _ts and (_tp.time() - _ts) > 180:
            st["error"] = ("Se corto en \"%s\": el servidor reinicio el proceso y no siguio. "
                           "ANTES de relanzar mira en Meta que quedo creado: puede haber quedado "
                           "una campana a medias." % (st.get("msg") or "")[:60])
            st["listo"] = True
            _job_put(_jid, st)
    return jsonify({"ok": True, **{k: st.get(k) for k in ("done", "total", "msg", "listo", "error", "stats")}})


# ---------------- Dashboard ----------------
@app.get("/")
def home():
    email = _user_actual()
    if not email:                       # sin login → pantalla de ingreso
        return Response(_LOGIN_PAGE, mimetype="text/html")
    # SEGURIDAD (16/09/2026): un empleado NO ve la plata. Los numeros del dashboard se calculan
    # ACA, en el server, y viajan PINTADOS adentro del HTML (window.__MFY__). Por eso tener los
    # /pf-* en SOLO_ADMIN no alcanzaba: el empleado nunca los pedia y los veia igual. Peor: su
    # sesion corre con el email del DUENO (ver /login), asi que el calculo le devolvia la
    # facturacion real de la cuenta. Se corta por ROL, nunca por email.
    _admin = (_mi_rol() == "admin")
    if not _admin:
        # Si TODO lo que tiene habilitado vive en una pagina propia, ni pisa el armazon del
        # dashboard: entra y va derecho a lo suyo (atencion al cliente -> /wa).
        _secs = [s for s in (session.get("secciones") or []) if s in SECCIONES]
        _propias = {"whatsapp": "/wa", "meli": "/meli"}
        _dest = [_propias[s] for s in _secs if s in _propias]
        if _secs and len(_dest) == len(_secs):
            return redirect(_dest[0])
    try:
        html = (RAIZ / "pf.html").read_text(encoding="utf-8")
    except Exception as e:
        return Response(f"<p style='color:#fff;font-family:sans-serif;padding:20px'>"
                        f"No se pudo cargar pf.html: {e}</p>", mimetype="text/html")
    import json as _json
    # LOS NUMEROS REALES VIAJAN EN EL HTML. Antes se inyectaba el ULTIMO snapshot guardado y los
    # numeros de verdad recien aparecian cuando el React pedia /pf-periodo (~28s). Ahora los calcula
    # el server aca mismo (cache de 60s: 0,4s tibio, ~2s frio) y salen pintados desde el primer frame.
    # Si falla o no hay datos, se cae al snapshot viejo y, si tampoco hay, a vacio con guiones.
    _real = None
    try:
        if _admin:                      # al empleado NO se le calcula la plata (ver arriba)
            _real = _pf_periodo_blob(email, _hoy(), _hoy(), solo_fresco=True)
    except Exception:
        _real = None
    # RECOMPRAS: consulta pesada (180 dias de historia) que va aparte y tarda 5-12s en frio. Si la
    # historia YA esta cacheada el calculo es instantaneo -> viaja en el HTML y las 2 tarjetas salen
    # llenas de una. Si esta fria NO frenamos la pagina: se calienta en un hilo y el navegador la pide.
    try:
        _hy = _hoy()
        if _real and (((email, _hy) in _SHOP_HIST_CACHE) or ((email, _hy) in _TN_HIST_CACHE)):
            _rc = 0; _rf = 0.0
            for _fn in (_tn_hist_orders, _shop_hist_orders):
                try:
                    _c, _f = _recompras_periodo(_fn(email, _hy), _hy, _hy)
                    _rc += _c; _rf += _f
                except Exception:
                    pass
            _real["raw"]["recompras"] = _rc
            _real["raw"]["fact_recompra"] = round(_rf, 2)
        elif _real:
            import threading as _th
            def _calentar():
                for _f2 in (_tn_hist_orders, _shop_hist_orders):
                    try: _f2(email, _hy)
                    except Exception: pass
            _th.Thread(target=_calentar, daemon=True).start()
    except Exception:
        pass
    _frescos = bool(_real and (_real.get("raw") or {}).get("be_cpa") is not None)
    try:
        # OJO: _load_last_blob(email) es el ULTIMO dashboard del DUENO guardado en disco. Si se
        # dejaba como fallback para todos, el empleado seguia viendo los numeros reales aunque no
        # se los calcularamos. Para quien no es admin: vacio y punto.
        blob = _json.dumps((_real or _load_last_blob(email) or _blob_vacio()) if _admin
                           else _blob_vacio(), ensure_ascii=False)
    except Exception:
        blob = _json.dumps(_blob_vacio(), ensure_ascii=False); _frescos = False
    # Inyectamos datos VACÍOS (sin esto el dashboard haría fetch y mostraría error).
    # CORTINA: un div propio, a pantalla completa, inyectado en el <head> -> existe antes de que el
    # React de ProfitFlow pinte su primer pixel. Asi NUNCA se ven sus numeros demo (81 ventas,
    # $3.200.000) ni ceros. Se saca cuando los valores reales ya estan pintados. Trae su propio
    # autodestruct a los 8s: si el JS grande fallara, la pagina NO queda tapada.
    _CORTINA = (
        "<style>#rp-cortina{position:fixed;inset:0;z-index:2147483000;background:#0b1120;display:flex;"
        "align-items:center;justify-content:center;transition:opacity .22s ease}"
        "@keyframes rpsp{to{transform:rotate(360deg)}}</style>"
        "<script>(function(){try{"
        "var d=document.createElement('div');d.id='rp-cortina';"
        "d.innerHTML='<div style=\"display:flex;align-items:center;gap:10px;color:#93a3ba;"
        "font:600 13px/1 system-ui,-apple-system,sans-serif\">"
        "<span style=\"width:14px;height:14px;border:2px solid #93a3ba;border-top-color:transparent;"
        "border-radius:50%;display:inline-block;animation:rpsp .7s linear infinite\"></span>"
        "Cargando tus datos</div>';"
        "(document.body||document.documentElement).appendChild(d);"
        "setTimeout(function(){var x=document.getElementById('rp-cortina');if(x)x.remove();},8000);"
        "}catch(e){}})();</script>"
    )
    if "</head>" in html:
        html = html.replace("</head>", "<script>window.__MFY__=" + blob + ";window.__RPSRV__="
                            + (blob if _frescos else "null") + ";</script>" + _CORTINA + "</head>", 1)
    # Caja de usuario abajo a la izquierda (email + cerrar sesión).
    inicial = (email[0] if email else "?").upper()
    userbox = ('<a class="rp-pill" href="/logout" title="Cerrar sesión" style="bottom:16px" '
               'onclick="window.location.assign(\'/logout\');return false;">'
               '<span class="rp-ic" style="background:#137fec;color:#fff;font-weight:700;font-size:14px">'
               + inicial + '</span>'
               '<span class="rp-lbl"><span class="em">' + email + '</span>'
               '<span style="color:#94a3b8;font-size:11px">Cerrar sesión &#8594;</span></span></a>')
    # Link "WhatsApp" en la barra (pill fija, mismo estilo que la caja de usuario; abre /wa).
    wa_pill = ('<a class="rp-pill" href="/wa" title="WhatsApp" style="bottom:70px">'
               '<span class="rp-ic" style="background:#25D366;color:#fff">'
               '<svg viewBox="0 0 24 24" width="18" height="18" fill="#fff"><path d="M.057 24l1.687-6.163a11.867 11.867 0 01-1.587-5.945C.16 5.335 5.495 0 12.05 0a11.817 11.817 0 018.413 3.488 11.824 11.824 0 013.48 8.414c-.003 6.557-5.338 11.892-11.893 11.892a11.9 11.9 0 01-5.688-1.448L.057 24zm6.597-3.807c1.676.995 3.276 1.591 5.392 1.592 5.448 0 9.886-4.434 9.889-9.885.002-5.462-4.415-9.89-9.881-9.892-5.452 0-9.887 4.434-9.889 9.884a9.86 9.86 0 001.51 5.26l-.999 3.648 3.743-.977zm11.387-5.464c-.074-.124-.272-.198-.57-.347-.297-.149-1.758-.868-2.031-.967-.272-.099-.47-.148-.669.149-.198.297-.767.967-.94 1.165-.173.198-.347.223-.644.074-.297-.149-1.255-.462-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.297-.347.446-.521.151-.172.2-.296.3-.495.099-.198.05-.372-.025-.521-.075-.148-.669-1.611-.916-2.206-.242-.579-.487-.501-.669-.51l-.57-.01c-.198 0-.52.074-.792.372s-1.04 1.016-1.04 2.479 1.065 2.876 1.213 3.074c.149.198 2.096 3.2 5.077 4.487.709.306 1.263.489 1.694.626.712.226 1.36.194 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413z"/></svg>'
               '</span><span class="rp-lbl"><span class="em">WhatsApp</span></span></a>')
    # Dejar solo Dashboard + Integraciones, sacar el logo, botón MP y caja de usuario.
    # (El link de WhatsApp ahora es un ítem del menú, se agrega en el JS de _SOLO_DASH.)
    extra = _SOLO_DASH + userbox + _BOTIFY_WIDGET + _RP_GLASS   # rp-glass
    if "</body>" in html:
        html = html.replace("</body>", extra + "</body>", 1)
    else:
        html = html + extra
    resp = Response(html, mimetype="text/html")
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    return resp


# ---------------- Endpoints en blanco (para que no rompa nada) ----------------
_PF_CACHE = {}   # (email, desde, hasta) -> (momento, blob) — evita pegarle a Shopify en cada refresco


def _pf_cerrado(hasta) -> bool:
    """True si el período YA TERMINÓ (no incluye hoy). Un período cerrado no puede cambiar:
    sus ventas, su gasto y sus comisiones son historia. Con el TTL de 60s se recalculaba igual
    cada minuto, y un mes tarda ~40 s (medido 26-09-2026: 39.992 ms). Por eso cambiar a "ayer"
    o a un mes pasado parecía colgado: no estaba roto, estaba recalculando lo mismo de nuevo."""
    try:
        hoy = _dt.datetime.now(_dt.timezone(_dt.timedelta(hours=-3))).date()
        return _dt.datetime.strptime(str(hasta)[:10], "%Y-%m-%d").date() < hoy
    except Exception:
        return False


def _pf_ttl(hasta) -> int:
    """Segundos que vale el cache: 12 h si el período está cerrado, 60 s si incluye hoy."""
    return 43200 if _pf_cerrado(hasta) else 60

_LAST_BLOB = DATA_DIR / "last_blob.json"   # ULTIMO dashboard de HOY por usuario -> home() lo inyecta = carga instantanea (estilo Escalafy)
def _save_last_blob(email, blob):
    try:
        d = {}
        if _LAST_BLOB.exists():
            d = _json.loads(_LAST_BLOB.read_text(encoding="utf-8"))
        d[str(email)] = blob
        _LAST_BLOB.write_text(_json.dumps(d, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass
def _load_last_blob(email):
    try:
        return _json.loads(_LAST_BLOB.read_text(encoding="utf-8")).get(str(email))
    except Exception:
        return None


_PF_DISCO = {"email": None, "ts": 0.0, "blob": None}   # memo 5s del snapshot que dejo el OTRO worker


def _pf_blob_ts(b):
    try:
        return int(((b or {}).get("raw") or {}).get("calc_ts") or 0)
    except Exception:
        return 0


def _pf_mejor(email, blob, desde, hasta, key=None, now=None):
    """Devuelve el blob MAS NUEVO entre el que tiene ESTE worker y el que dejo el otro en disco.
    gunicorn corre 2 workers y _PF_CACHE es memoria de cada uno: cuando uno se queda con un
    snapshot viejo, la pagina alterna entre los dos y el KPI de Ventas titila (ese lo pinta el
    React directo, no pasa por el filtro calc_ts del front). Solo puede ir para ADELANTE:
    nunca devuelve algo con sello mas viejo que el que ya tenia."""
    try:
        if not (desde == hasta == _hoy()):
            return blob                     # el snapshot de disco es SOLO el del dia de hoy
        import time as _tm
        if _PF_DISCO["email"] != email or (_time.time() - _PF_DISCO["ts"]) > 5:
            _PF_DISCO["blob"] = _load_last_blob(email)
            _PF_DISCO["email"] = email
            _PF_DISCO["ts"] = _time.time()
        otro = _PF_DISCO["blob"]
        if otro and _pf_blob_ts(otro) > _pf_blob_ts(blob):
            if key is not None and now is not None:
                _PF_CACHE[key] = (now, otro)    # me pongo al dia: dejo de servir el viejo
            return otro
    except Exception:
        pass
    return blob


def _pf_periodo_blob(email, desde, hasta, espera=8, solo_fresco=False):
    """Los KPI reales del período (lo que devuelve /pf-periodo). Se saco de la ruta para poder
    llamarlo TAMBIEN desde home(): asi la pagina sale con los numeros de verdad ya adentro del
    HTML, en vez de mostrar el snapshot viejo mientras espera un fetch."""
    # ESTAMPIDA (medido en los logs de Render, 8-sep-2026): el dashboard pide /pf-periodo CADA 2
    # SEGUNDOS. Con cache de 60s, al vencer la cache TODAS las que estaban en vuelo fallan juntas y
    # cada una se manda a recalcular contra Shopify + Meta + MercadoPago al mismo tiempo. Seis
    # calculos pesados arrancando en el mismo segundo tapaban los hilos del server 20-30 segundos
    # (por eso /diag, que no hace nada, timeouteaba). Ahora calcula UNO SOLO: el resto recibe el
    # valor anterior al toque, y si no hay ninguno espera al que esta calculando.
    key = (email, desde, hasta)
    now = _dt.datetime.utcnow()
    c = _PF_CACHE.get(key)
    if c and (now - c[0]).total_seconds() < _pf_ttl(hasta):
        return _pf_mejor(email, c[1], desde, hasta, key, now)
    # home() entra con solo_fresco=True: si no hay un valor FRESCO en memoria devuelve None y la
    # pagina sale al instante (el front pide /pf-periodo por su cuenta y la cortina tapa hasta que
    # llegan los numeros REALES). Antes home() esperaba hasta 45s al calculo y la app no abria.
    if solo_fresco:
        return None
    with _PF_LOCKS_G:
        lk = _PF_LOCKS.get(key)
        if lk is None:
            lk = _PF_LOCKS[key] = threading.Lock()
    if c:
        if not lk.acquire(False):
            # otro ya lo esta calculando y tengo valor previo -> lo sirvo YA (pero si el OTRO
            # worker ya dejo uno mas nuevo en disco, va ese: si no, los KPI titilan entre ambos)
            return _pf_mejor(email, c[1], desde, hasta, key, now)
    # 8s (era 45). Con 45 cada request esperaba con un HILO tomado: el dashboard pide /pf-periodo
    # cada 2s, asi que en medio minuto habia 22 esperando y se comian los 16 hilos de gunicorn ->
    # la app entera dejaba de contestar (y con la cache fria, despues de cada deploy, siempre).
    elif not lk.acquire(True, espera):
        # El que calcula tarda demasiado y no tengo nada en memoria. Devolver _blob_vacio() serviria
        # CEROS, que es un dato falso en pantalla. Prefiero el ultimo snapshot guardado en disco: es
        # de hace un rato pero es real, y el proximo poll (a los 2s) ya trae el valor fresco.
        try:
            return _pf_mejor(email, _load_last_blob(email) or _blob_vacio(), desde, hasta, key, now)
        except Exception:
            return _blob_vacio()
    try:
        c2 = _PF_CACHE.get(key)      # pudo terminar el otro mientras yo esperaba el candado
        if c2 and (_dt.datetime.utcnow() - c2[0]).total_seconds() < _pf_ttl(hasta):
            return _pf_mejor(email, c2[1], desde, hasta, key, now)
        return _pf_periodo_calcular(email, desde, hasta, key, now)
    finally:
        lk.release()


_PF_LOCKS = {}                     # (email,desde,hasta) -> Lock: UNO SOLO calcula por periodo
_PF_LOCKS_G = threading.Lock()     # candado del diccionario de candados


PF_DIAS = DATA_DIR / "pf_dias.json"   # un dia CERRADO ya calculado: no cambia nunca mas

# ---------------- Generador de creativos: biblioteca de moldes ----------------
# Los moldes son estaticos REALES de la competencia bajados de la Meta Ad Library, filtrados
# (sin videos, sin duplicados por hash, sin "ugly ads" sin texto) y rankeados por impresiones,
# duplicados y antiguedad. Se suben desde la Mac en miniatura; el original se queda alla porque
# el replicador corre ahi.
GEN_DIR = DATA_DIR / "moldes"
GEN_META = DATA_DIR / "moldes_meta.json"


def _gen_meta() -> dict:
    try:
        return _json.loads(GEN_META.read_text(encoding="utf-8"))
    except Exception:
        return {"moldes": [], "actualizado": ""}


@app.post("/gen-subir")
def gen_subir():
    """Recibe un zip con las miniaturas + el json de metadatos. Solo para el dueno."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"}), 401
    import zipfile, io as _io
    f = request.files.get("zip")
    meta = request.form.get("meta") or ""
    if not f:
        return jsonify({"ok": False, "msg": "falta el zip"}), 400
    GEN_DIR.mkdir(parents=True, exist_ok=True)
    n = 0
    try:
        with zipfile.ZipFile(_io.BytesIO(f.read())) as z:
            for nom in z.namelist():
                if not nom.lower().endswith((".jpg", ".jpeg", ".png", ".webp")):
                    continue
                base = _os.path.basename(nom)
                if not base or "/" in base or "\\" in base:
                    continue
                (GEN_DIR / base).write_bytes(z.read(nom))
                n += 1
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:160])}), 400
    if meta:
        GEN_META.write_text(meta, encoding="utf-8")
    return jsonify({"ok": True, "imagenes": n, "moldes": len(_gen_meta().get("moldes") or [])})


@app.post("/gen-subir-parte")
def gen_subir_parte():
    """Sube el zip de moldes EN TRAMOS. Un paquete de 14 MB no entra en una sola llamada de
    JavaScript, asi que llega partido en base64 y se arma en disco."""
    if not _user_actual():
        return jsonify({"ok": False}), 401
    import base64 as _b64, zipfile, io as _io
    j = request.get_json(silent=True) or {}
    try:
        i = int(j.get("i", 0)); tot = int(j.get("n", 1))
    except Exception:
        return jsonify({"ok": False, "msg": "i/n invalidos"}), 400
    tmp = DATA_DIR / "_gen_tmp.zip"
    datos = _b64.b64decode(j.get("b64") or "")
    with open(str(tmp), "wb" if i == 0 else "ab") as fh:
        fh.write(datos)
    if i < tot - 1:
        return jsonify({"ok": True, "parte": i + 1, "de": tot,
                        "bytes": _os.path.getsize(str(tmp))})
    GEN_DIR.mkdir(parents=True, exist_ok=True)
    n_img = 0
    try:
        with zipfile.ZipFile(str(tmp)) as z:
            for nom in z.namelist():
                if not nom.lower().endswith((".jpg", ".jpeg", ".png", ".webp")):
                    continue
                base = _os.path.basename(nom)
                if not base:
                    continue
                (GEN_DIR / base).write_bytes(z.read(nom))
                n_img += 1
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:160])}), 400
    meta = j.get("meta")
    if meta:
        GEN_META.write_text(_json.dumps(meta, ensure_ascii=False), encoding="utf-8")
    try:
        _os.remove(str(tmp))
    except Exception:
        pass
    return jsonify({"ok": True, "listo": True, "imagenes": n_img,
                    "moldes": len((_gen_meta().get("moldes") or []))})


@app.get("/gen-datos")
def gen_datos():
    if not _user_actual():
        return jsonify({"ok": False}), 401
    return jsonify({"ok": True, **_gen_meta()})


@app.get("/gen-img/<path:arch>")
def gen_img(arch):
    if not _user_actual():
        return "", 401
    base = _os.path.basename(arch)
    f = GEN_DIR / base
    if not f.exists():
        return "", 404
    return send_file(str(f), mimetype="image/jpeg", max_age=86400)


@app.get("/generador")
def generador():
    if not _user_actual():
        return redirect("/login")
    return Response(_GEN_PAGE, mimetype="text/html")


