@app.get("/meli/ventas")
def meli_ventas():
    """Últimas ventas/órdenes de la cuenta de ML conectada (por email)."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "ventas": []})
    tok = _meli_token(email)
    d = _meli_tokens().get(email) or {}
    uid = d.get("user_id")
    if not tok or not uid:
        return jsonify({"ok": False, "msg": "Mercado Libre no conectado", "ventas": []})
    try:
        r = requests.get("%s/orders/search" % MELI_API,
                         headers={"Authorization": "Bearer " + tok},
                         params={"seller": uid, "sort": "date_desc", "limit": 30}, timeout=25)
        j = r.json() if r.content else {}
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:100], "ventas": []})
    out = []
    for o in j.get("results", []):
        items = o.get("order_items") or []
        tit = (items[0].get("item") or {}).get("title", "") if items else ""
        un = sum(int(it.get("quantity") or 0) for it in items)
        sku = ""
        for it in items:
            _s = str((it.get("item") or {}).get("seller_sku")
                     or (it.get("item") or {}).get("seller_custom_field") or "").strip()
            if _s and _s not in sku:
                sku = (sku + " + " + _s) if sku else _s
        potes = 0
        for it in items:
            _s = str((it.get("item") or {}).get("seller_sku")
                     or (it.get("item") or {}).get("seller_custom_field") or "").strip()
            potes += _meli_units_sku(_s)[0] * int(it.get("quantity") or 1)
        out.append({"id": o.get("id"), "fecha": (o.get("date_created") or "")[:10],
                    "estado": o.get("status", ""), "comprador": (o.get("buyer") or {}).get("nickname", ""),
                    "titulo": tit, "unidades": un, "total": o.get("total_amount", 0),
                    "sku": sku, "potes": potes,
                    "sid": str((o.get("shipping") or {}).get("id") or "")})
    return jsonify({"ok": True, "ventas": out, "total": (j.get("paging") or {}).get("total")})


def _meli_ctx(email):
    """(token, user_id) del ML conectado, o (None, None)."""
    tok = _meli_token(email)
    d = _meli_tokens().get(email) or {}
    return tok, d.get("user_id")


@app.get("/meli/prep-ver")
def meli_prep_ver():
    """LEE el tiempo de preparacion de cada publicacion. NO cambia nada.

    Existe porque no hay doc publica clara de como guarda ML el "listo para enviar": hay que
    mirar como viene en las publicaciones REALES antes de escribir el cambio. Lo mismo que se
    hizo con la estrategia de puja de Meta: leer la cuenta, no adivinar."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    tok, uid = _meli_ctx(email)
    if not tok or not uid:
        return jsonify({"ok": False, "msg": "conectá MercadoLibre primero"}), 400
    h = {"Authorization": "Bearer " + tok}
    ids, offset = [], 0
    while len(ids) < 500:
        try:
            r = requests.get("%s/users/%s/items/search" % (MELI_API, uid), headers=h,
                             params={"limit": 100, "offset": offset, "status": "active"}, timeout=30)
            j = r.json() if r.content else {}
        except Exception as e:
            return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:120])}), 500
        lote = j.get("results") or []
        ids.extend(lote)
        offset += 100
        if len(lote) < 100 or offset >= int((j.get("paging") or {}).get("total", 0)):
            break
    out, resumen = [], {}
    for i in range(0, len(ids), 20):
        try:
            r = requests.get("%s/items" % MELI_API, headers=h,
                             params={"ids": ",".join(ids[i:i + 20])}, timeout=30)
            for w in (r.json() if r.content else []):
                b = (w or {}).get("body") or {}
                if not b.get("id"):
                    continue
                mt = next((t for t in (b.get("sale_terms") or [])
                           if t.get("id") == "MANUFACTURING_TIME"), None)
                val = (mt or {}).get("value_name") or "(no tiene)"
                resumen[val] = resumen.get(val, 0) + 1
                out.append({"id": b["id"], "titulo": (b.get("title") or "")[:60],
                            "estado": b.get("status"), "prep": val,
                            "value_id": (mt or {}).get("value_id"),
                            "struct": (mt or {}).get("value_struct")})
        except Exception:
            pass
    return jsonify({"ok": True, "total": len(out), "resumen": resumen, "items": out[:300]})


def _meli_items_full(tok, uid, con_desc=True):
    """TODAS las publicaciones del vendedor con el cuerpo completo (incluye sold_quantity).
    /users/{uid}/items/search pagina de a 100; sin filtro de status trae activas, pausadas y cerradas."""
    h = {"Authorization": "Bearer " + tok}
    ids, offset = [], 0
    while True:
        try:
            r = requests.get("%s/users/%s/items/search" % (MELI_API, uid), headers=h,
                             params={"limit": 100, "offset": offset}, timeout=30)
            j = r.json() if r.content else {}
        except Exception:
            break
        lote = j.get("results") or []
        ids.extend(lote)
        total = (j.get("paging") or {}).get("total", len(ids))
        offset += 100
        if len(lote) < 100 or offset >= total or offset >= 2000:
            break
    items = []
    for i in range(0, len(ids), 20):
        try:
            rr = requests.get("%s/items" % MELI_API, headers=h,
                              params={"ids": ",".join(ids[i:i + 20])}, timeout=30)
            arr = rr.json() if rr.content else []
        except Exception:
            arr = []
        for wrap in arr:
            b = wrap.get("body") or {}
            if b.get("id"):
                items.append(b)
    if con_desc:
        for b in items:
            try:
                rd = requests.get("%s/items/%s/description" % (MELI_API, b["id"]), headers=h, timeout=20)
                b["_descripcion"] = ((rd.json() if rd.content else {}) or {}).get("plain_text", "") or ""
            except Exception:
                b["_descripcion"] = ""
    return items


def _meli_fila(b):
    """Aplana una publicacion a lo que hace falta para volver a publicarla en otra cuenta."""
    sku = b.get("seller_custom_field") or ""
    attrs = []
    for a in (b.get("attributes") or []):
        if a.get("id") == "SELLER_SKU" and not sku:
            sku = a.get("value_name") or ""
        v = a.get("value_name") or a.get("value_id") or ""
        if v and a.get("id"):
            attrs.append("%s=%s" % (a["id"], v))
    fotos = [p.get("secure_url") or p.get("url") or "" for p in (b.get("pictures") or [])]
    env = b.get("shipping") or {}
    return {
        "id": b.get("id", ""), "estado": b.get("status", ""), "titulo": b.get("title", ""),
        "vendidas": b.get("sold_quantity") or 0,
        "stock": b.get("available_quantity") or 0,
        "precio": b.get("price"), "moneda": b.get("currency_id", ""),
        "categoria": b.get("category_id", ""), "tipo": b.get("listing_type_id", ""),
        "condicion": b.get("condition", ""), "modo": b.get("buying_mode", ""),
        "sku": sku, "link": b.get("permalink", ""),
        "envio_modo": env.get("mode", ""), "envio_gratis": bool(env.get("free_shipping")),
        "garantia": next((a.get("value_name", "") for a in (b.get("sale_terms") or [])
                          if a.get("id") == "WARRANTY_TIME"), ""),
        "fotos": fotos, "atributos": attrs, "descripcion": b.get("_descripcion", ""),
    }


