def _meli_clon_payload(b, stock=None):
    """Arma el cuerpo de POST /items a partir de una publicacion existente.
    Se dejan afuera los atributos de solo lectura y el logistic_type: son de la cuenta vieja."""
    attrs, sku = [], (b.get("seller_custom_field") or "")
    for a in (b.get("attributes") or []):
        tg = a.get("tags") or {}
        if a.get("id") == "SELLER_SKU":
            sku = sku or (a.get("value_name") or "")
            continue
        # ML rechaza los que no son modificables al crear: "Attribute [X] ignored because
        # it is not modifiable". Son banderas de la cuenta vendedora, no del producto.
        if a.get("id") in ("IS_TOM_BRAND", "IS_HIGHLIGHT_BRAND"):
            continue
        if tg.get("read_only"):
            continue
        _at = {"id": a["id"]}
        if a.get("value_id"):
            _at["value_id"] = a["value_id"]
        if a.get("value_name"):
            _at["value_name"] = str(a["value_name"])[:255]
        if len(_at) > 1:
            attrs.append(_at)
    if sku:
        attrs.append({"id": "SELLER_SKU", "value_name": str(sku)[:60]})
    # al aplanar una con variantes, el atributo que variaba (el Sabor) queda dentro de la
    # variante: sin subirlo aca, ML rechaza con "El campo Sabor es obligatorio".
    _ya = set(a["id"] for a in attrs)
    for v in (b.get("variations") or []):
        for c in (v.get("attribute_combinations") or []):
            if c.get("id") and c["id"] not in _ya and (c.get("value_name") or c.get("value_id")):
                _c = {"id": c["id"]}
                if c.get("value_id"):
                    _c["value_id"] = c["value_id"]
                if c.get("value_name"):
                    _c["value_name"] = str(c["value_name"])[:255]
                attrs.append(_c)
                _ya.add(c["id"])
        break
    fotos = [{"source": (p.get("secure_url") or p.get("url"))} for p in (b.get("pictures") or [])
             if (p.get("secure_url") or p.get("url"))]
    env = b.get("shipping") or {}
    _q0 = b.get("available_quantity")
    if not _q0 and b.get("variations"):      # con variantes el stock vive en cada variante
        _q0 = sum(int(v.get("available_quantity") or 0) for v in b["variations"])
    try:
        qty = int(stock) if stock not in (None, "") else int(_q0 or 1)
    except Exception:
        qty = int(_q0 or 1)
    p = {"category_id": b.get("category_id", ""),
         "price": b.get("price"), "currency_id": b.get("currency_id") or "ARS",
         "available_quantity": max(1, qty),
         "buying_mode": b.get("buying_mode") or "buy_it_now",
         "listing_type_id": b.get("listing_type_id") or "gold_special",
         "condition": b.get("condition") or "new",
         "pictures": fotos, "attributes": attrs,
         "shipping": {"mode": env.get("mode") or "me2",
                      "local_pick_up": False,
                      "free_shipping": bool(env.get("free_shipping"))}}
    # TODAS las condiciones de venta, no solo la garantia: el pedido es un clon literal.
    st = []
    for t in (b.get("sale_terms") or []):
        # INSTALLMENTS_CAMPAIGN no se puede setear al crear ("Not allowed to modify sale term"):
        # las cuotas las define la campana en la que esta inscripta LA CUENTA, no la publicacion.
        if t.get("id") == "INSTALLMENTS_CAMPAIGN":
            continue
        if (t.get("tags") or {}).get("read_only"):
            continue
        if t.get("value_id"):
            st.append({"id": t["id"], "value_id": t["value_id"]})
        elif t.get("value_name"):
            st.append({"id": t["id"], "value_name": t["value_name"]})
    if st:
        p["sale_terms"] = st
    if b.get("seller_custom_field"):
        p["seller_custom_field"] = b["seller_custom_field"]
    if b.get("video_id"):
        p["video_id"] = b["video_id"]
    if b.get("warranty"):
        p["warranty"] = str(b["warranty"])[:255]
    # family_name: Mercado Libre lo exige al crear ("The body does not contains [family_name]").
    # Se le pone uno UNICO por publicacion —el titulo mas el MLA de origen— para que cada una
    # nazca como publicacion aparte y NO como variante de otra. Es un nombre interno del
    # catalogo del vendedor, no el titulo que ve el comprador.
    # Con family_name, Mercado Libre NO acepta "title": arma el titulo el solo a partir de la
    # familia y los atributos ("The fields [title] are invalid for requested call"). Asi que el
    # family_name es el titulo de la publicacion nueva.
    p["family_name"] = (b.get("title") or "")[:250]
    # Las variantes NO se copian a proposito: el pedido es que sean publicaciones distintas,
    # y ademas Mercado Libre las rechaza junto con family_name.
    if b.get("catalog_listing") and b.get("catalog_product_id"):
        p["catalog_listing"] = True
        p["catalog_product_id"] = b["catalog_product_id"]
    return p


@app.get("/meli/lupa-destino")
def meli_lupa_destino():
    """Lee (solo GET) cualquier recurso de la API con el token de la cuenta DESTINO.
    Sirve para ver como esta configurada esa cuenta sin andar adivinando."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 400
    tok, uid = _meli_ctx(email + "#destino")
    if not tok or not uid:
        return jsonify({"ok": False, "msg": "cuenta destino no conectada"})
    ruta = (request.args.get("ruta") or "/users/me").strip()
    if not ruta.startswith("/"):
        return jsonify({"ok": False, "msg": "la ruta arranca con /"})
    ruta = ruta.replace("{uid}", str(uid))
    try:
        r = requests.get(MELI_API + ruta, headers={"Authorization": "Bearer " + tok}, timeout=25)
        cuerpo = r.json() if (r.content and r.status_code < 400) else (r.text or "")[:1500]
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:120])})
    return jsonify({"ok": True, "ruta": ruta, "status": r.status_code, "cuerpo": cuerpo})


@app.post("/meli/destino-sku")
def meli_destino_sku():
    """Carga el SKU en una publicacion de la cuenta DESTINO. Solo toca ese campo."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 400
    tok, uid = _meli_ctx(email + "#destino")
    if not tok or not uid:
        return jsonify({"ok": False, "msg": "cuenta destino no conectada"})
    d = request.get_json(silent=True) or {}
    pares = d.get("pares") or []
    if not pares:
        return jsonify({"ok": False, "msg": "falta 'pares': [{id, sku}]"})
    h = {"Authorization": "Bearer " + tok, "Content-Type": "application/json"}
    out = []
    for p in pares[:60]:
        iid = str(p.get("id") or "").strip().upper()
        sku = str(p.get("sku") or "").strip()
        if not iid or not sku:
            out.append({"id": iid, "ok": False, "error": "falta id o sku"}); continue
        cuerpo = {"seller_custom_field": sku,
                  "attributes": [{"id": "SELLER_SKU", "value_name": sku}]}
        try:
            r = requests.put("%s/items/%s" % (MELI_API, iid), headers=h,
                             data=_json.dumps(cuerpo), timeout=30)
            j = r.json() if r.content else {}
            if r.status_code < 400:
                out.append({"id": iid, "ok": True, "sku": j.get("seller_custom_field") or sku})
            else:
                out.append({"id": iid, "ok": False, "error": _meli_error(r)})
        except Exception as e:
            out.append({"id": iid, "ok": False, "error": "%s: %s" % (type(e).__name__, str(e)[:90])})
    return jsonify({"ok": True, "filas": out, "bien": sum(1 for x in out if x["ok"])})


@app.post("/meli/clonar")
def meli_clonar():
    """Copia publicaciones de la cuenta conectada a la cuenta DESTINO.
    Sin 'aplicar' NO crea nada: pasa cada una por /items/validate y devuelve que diria ML."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 400
    tok_o, uid_o = _meli_ctx(email)
    tok_d, uid_d = _meli_ctx(email + "#destino")
    if not tok_o or not uid_o:
        return jsonify({"ok": False, "msg": "La cuenta de origen no esta conectada."})
    if not tok_d or not uid_d:
        return jsonify({"ok": False, "msg": "Falta conectar la cuenta destino."})
    if str(uid_o) == str(uid_d):
        return jsonify({"ok": False, "msg": "La cuenta destino es la MISMA que la de origen. "
                                            "Desconectala y conecta la otra (usa una ventana privada)."})
    d = request.get_json(silent=True) or {}
    ids = [str(x).strip().upper() for x in (d.get("ids") or []) if str(x).strip()]
    if not ids:
        return jsonify({"ok": False, "msg": "No marcaste ninguna publicacion."})
    if len(ids) > 60:
        return jsonify({"ok": False, "msg": "Son %d publicaciones. Freno por las dudas: de a 60." % len(ids)})
    aplicar = bool(d.get("aplicar"))
    pausar = d.get("pausar", True)
    stock = d.get("stock")
    envio = (d.get("envio") or "copiar")   # copiar | auto (auto = no mandar shipping, que lo ponga ML)
    ho = {"Authorization": "Bearer " + tok_o}
    hd = {"Authorization": "Bearer " + tok_d, "Content-Type": "application/json"}
    filas, creadas = [], 0
    for iid in ids:
        f = {"id": iid, "titulo": "", "ok": False, "nuevo": "", "error": ""}
        try:
            rb = requests.get("%s/items/%s" % (MELI_API, iid), headers=ho, timeout=25)
            b = rb.json() if rb.content else {}
        except Exception as e:
            f["error"] = "no pude leer la publicacion: %s" % str(e)[:80]
            filas.append(f); continue
        if not b.get("id"):
            f["error"] = "no existe en la cuenta de origen"
            filas.append(f); continue
        f["titulo"] = b.get("title", "")
        cuerpo = _meli_clon_payload(b, stock)
        if envio == "auto":
            cuerpo.pop("shipping", None)
        f["copia"] = {"fotos": len(cuerpo.get("pictures") or []),
                      "atributos": len(cuerpo.get("attributes") or []),
                      "condiciones": len(cuerpo.get("sale_terms") or []),
                      "tipo": cuerpo.get("listing_type_id", ""),
                      "precio": cuerpo.get("price"),
                      "stock": cuerpo.get("available_quantity"),
                      "envio_gratis": bool((cuerpo.get("shipping") or {}).get("free_shipping")),
                      "variantes": len(b.get("variations") or []),
                      "familia": cuerpo.get("family_name", "")}
        try:
            if not aplicar:
                rv = requests.post("%s/items/validate" % MELI_API, headers=hd,
                                   data=_json.dumps(cuerpo), timeout=40)
                if rv.status_code in (200, 201, 204):
                    f["ok"] = True
                else:
                    f["error"] = _meli_error(rv)
            else:
                rc = requests.post("%s/items" % MELI_API, headers=hd,
                                   data=_json.dumps(cuerpo), timeout=60)
                j = rc.json() if rc.content else {}
                if rc.status_code in (200, 201) and j.get("id"):
                    f["ok"] = True; f["nuevo"] = j["id"]; creadas += 1
                    txt = ""
                    try:
                        rd = requests.get("%s/items/%s/description" % (MELI_API, iid), headers=ho, timeout=20)
                        jd = (rd.json() if rd.content else {}) or {}
                        txt = jd.get("plain_text") or jd.get("text") or ""
                    except Exception:
                        pass
                    if txt:
                        try:
                            requests.post("%s/items/%s/description" % (MELI_API, j["id"]), headers=hd,
                                          data=_json.dumps({"plain_text": txt}), timeout=30)
                        except Exception:
                            pass
                    if pausar:
                        try:
                            requests.put("%s/items/%s" % (MELI_API, j["id"]), headers=hd,
                                         data=_json.dumps({"status": "paused"}), timeout=25)
                        except Exception:
                            pass
                else:
                    f["error"] = _meli_error(rc)
        except Exception as e:
            f["error"] = "%s: %s" % (type(e).__name__, str(e)[:90])
        filas.append(f)
    return jsonify({"ok": True, "aplicado": aplicar, "creadas": creadas,
                    "bien": sum(1 for x in filas if x["ok"]),
                    "mal": sum(1 for x in filas if not x["ok"]), "filas": filas})


def _meli_error(r):
    """El mensaje REAL que devolvio Mercado Libre, no un generico."""
    try:
        j = r.json()
    except Exception:
        return "HTTP %s %s" % (r.status_code, (r.text or "")[:120])
    partes = []
    for c in (j.get("cause") or []):
        m = c.get("message") or c.get("code") or ""
        det = c.get("cause") or c.get("references") or c.get("department")
        if m:
            partes.append(str(m) + ((" %s" % det) if det else ""))
    if not partes and j.get("message"):
        partes.append(str(j["message"]))
    crudo = ""
    # si ML contesta un generico tipo "body.invalid_fields", el detalle esta en el cuerpo
    if not partes or len(" ".join(partes)) < 60:
        try:
            crudo = " | crudo: " + _json.dumps(j, ensure_ascii=False)[:900]
        except Exception:
            crudo = " | crudo: " + (r.text or "")[:900]
    return ("HTTP %s \u00b7 " % r.status_code) + (" | ".join(partes)[:400]) + crudo


@app.get("/meli/publicaciones-ventas")
def meli_publicaciones_ventas():
    """Todas las publicaciones con cuantas unidades vendio cada una."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 400
    tok, uid = _meli_ctx(email)
    if not tok or not uid:
        return jsonify({"ok": False, "msg": "Mercado Libre no conectado"})
    filas = [_meli_fila(b) for b in _meli_items_full(tok, uid, con_desc=False)]
    filas.sort(key=lambda x: -(x["vendidas"] or 0))
