# ---------------- Tiendanube (OAuth un-clic, igual que Shopify) ----------------
TIENDANUBE_SECRETS = RAIZ / "tiendanube_secrets.json"     # App ID + Client Secret (dueño de la app)
TIENDANUBE_TOKENS = DATA_DIR / "tiendanube_tokens.json"   # {email: {access_token, store_id}}
TN_API = "https://api.tiendanube.com/v1"
TN_UA = "RealProfit (soporte@realprofitapp.com)"


def _tn_cfg() -> dict:
    import os
    try:
        c = _json.loads(TIENDANUBE_SECRETS.read_text(encoding="utf-8"))
    except Exception:
        c = {}
    return {"app_id": os.getenv("TIENDANUBE_APP_ID") or c.get("app_id", ""),
            "client_secret": os.getenv("TIENDANUBE_CLIENT_SECRET") or c.get("client_secret", "")}


def _tn_tokens() -> dict:
    try:
        return _json.loads(TIENDANUBE_TOKENS.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _tn_save_token(email, data) -> None:
    d = _tn_tokens()
    d[str(email)] = data
    TIENDANUBE_TOKENS.parent.mkdir(parents=True, exist_ok=True)
    TIENDANUBE_TOKENS.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")


def _tn_headers(token) -> dict:
    return {"Authentication": "bearer " + str(token), "User-Agent": TN_UA}


def _resolver_suc_completo(suc_raw, lat, lng, pid, cp, sucs):
    """Corre la MISMA cadena del generador de Excel y devuelve (sucursal_oficial, via).
    exacto → coordenadas del punto → vivo → None (revisar). SOLO devuelve sucursales del desplegable
    de Andreani (la carga masiva las exige); un punto que no está (ej San Martín 1927) → None → REVISAR
    (ese se despacha por Envialo, no por el Excel)."""
    of = _and_suc_exacto(suc_raw)
    if of:
        return of, "exacto"
    try:
        of = _and_suc_coord(lat, lng, "HOP" in str(suc_raw).upper(), pid, sucs)
    except Exception:
        of = None
    if of:
        return of, "coordenadas"
    try:
        lv = _and_suc_live(suc_raw, cp or "")
    except Exception:
        lv = None
    if lv:
        return lv, "vivo"
    return None, None


# ---------- Envialo como autoridad de sucursales (subir su Excel → 1=1) ----------
ENVIALO_SUC = DATA_DIR / "envialo_sucursales.json"   # {email: {num: sucursal_oficial}}


def _envialo_suc(email):
    try:
        return _json.loads(ENVIALO_SUC.read_text(encoding="utf-8")).get(str(email), {})
    except Exception:
        return {}


def _envialo_suc_save(email, mapping):
    try:
        d = _json.loads(ENVIALO_SUC.read_text(encoding="utf-8"))
    except Exception:
        d = {}
    cur = d.get(str(email), {})
    cur.update({str(k): str(v) for k, v in (mapping or {}).items() if k and v})
    d[str(email)] = cur
    ENVIALO_SUC.parent.mkdir(parents=True, exist_ok=True)
    ENVIALO_SUC.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    return cur


ENVIALO_EXCL = DATA_DIR / "envialo_excluir.json"   # {email: [nums]} pedidos que NO coinciden con Envialo → se despachan por Envialo, NUNCA van en el Excel de Andreani (evita doble despacho)


def _envialo_excl(email):
    try:
        return set(_json.loads(ENVIALO_EXCL.read_text(encoding="utf-8")).get(str(email), []))
    except Exception:
        return set()


def _envialo_excl_save(email, nums):
    try:
        d = _json.loads(ENVIALO_EXCL.read_text(encoding="utf-8"))
    except Exception:
        d = {}
    d[str(email)] = sorted({str(n) for n in (nums or []) if n})
    ENVIALO_EXCL.parent.mkdir(parents=True, exist_ok=True)
    ENVIALO_EXCL.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    return d[str(email)]


def _parse_envialo_xlsx(data):
    """Lee el export de Envialo → {num_interno: sucursal}. SOLO la sucursal (ignora DNI, nombres, todo lo demás).
    Robusto: usa la hoja de sucursales y ubica la columna de sucursal aunque cambie de lugar; nunca rompe."""
    import io
    import openpyxl as _oxl
    wb = _oxl.load_workbook(io.BytesIO(data), read_only=True, data_only=True)
    out = {}
    hojas = [h for h in wb.sheetnames if "sucursal" in h.lower()] or list(wb.sheetnames)
    for hoja in hojas:
        try:
            for r in wb[hoja].iter_rows(min_row=2, values_only=True):
                if not r or len(r) < 7:
                    continue
                num = str(r[6]).strip() if r[6] is not None else ""
                if not num.isdigit():
                    continue
                suc = str(r[13]).strip() if len(r) > 13 and r[13] else ""
                if not suc:   # si no está en la col esperada, busco la celda que parezca sucursal Andreani
                    for cell in r:
                        s = str(cell or "").strip()
                        if s and ("ANDREANI" in s.upper() or " HOP " in (" " + s.upper() + " ")):
                            suc = s
                            break
                if num and suc:
                    out[num] = suc
        except Exception:
            continue
    return out


@app.post("/pf-despachos-envialo")
def pf_despachos_envialo():
    """Sube el Excel de Envialo y lo usa como AUTORIDAD de sucursales (1=1): compara pedido por pedido
    contra lo que resuelve RealProfit; si alguna no coincide, GANA la de Envialo. Guarda esos valores
    para que el Excel de Andreani salga con las sucursales de Envialo."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "logueate"}), 401
    f = request.files.get("xlsx") or request.files.get("file")
    if not f:
        return jsonify({"ok": False, "msg": "subí el Excel de Envialo"}), 400
    try:
        env = _parse_envialo_xlsx(f.read())
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude leer el Excel: " + str(e)[:120]}), 400
    if not env:
        return jsonify({"ok": False, "msg": "el Excel no tiene sucursales en la hoja 'A sucursal'"}), 400
    try:
        import openpyxl as _oxl
        _tpl = ANDREANI_TPL if ANDREANI_TPL.exists() else Path(_os.path.expanduser("~/Downloads/EnvioMasivoExcelPaquetes.xlsx"))
        _cpidx, sucs = _and_cfg(_oxl.load_workbook(_tpl, read_only=True, data_only=True))
    except Exception:
        sucs = []
    rows = {str(r["num"]): r for r in (_despachos_orders(email) or [])}

    def _n(s):
        return _re_and.sub(r"\s+", " ", _ud_and.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode().upper()).strip()
    distintas, coinciden, solo_envialo = [], 0, 0
    for num, suc_env in env.items():
        try:
            r = rows.get(num)
            if not r:
                solo_envialo += 1
                continue
            mia, _via = _resolver_suc_completo(r.get("suc_nombre") or "", r.get("suc_lat"), r.get("suc_lng"),
                                               r.get("suc_pid"), r.get("cp"), sucs)
            if _n(mia) == _n(suc_env):
                coinciden += 1
            else:
                distintas.append({"num": num, "realprofit": mia or "REVISAR", "envialo": suc_env})
        except Exception:
            distintas.append({"num": num, "realprofit": "REVISAR", "envialo": suc_env})
    guardadas = _envialo_suc_save(email, env)   # Envialo manda: guardo TODAS
    # Las que NO coinciden se despachan por Envialo → las excluyo del Excel de Andreani (no doble despacho)
    excluidas = _envialo_excl_save(email, [d["num"] for d in distintas])
    return jsonify({"ok": True, "total": len(env), "coinciden": coinciden,
                    "distintas": distintas, "solo_en_envialo": solo_envialo,
                    "excluidas": len(excluidas), "guardadas": len(guardadas)})


@app.get("/pf-suc-preview")
def pf_suc_preview():
    """Preview (logueado) de a qué SUCURSAL oficial de Andreani resuelve un pedido, con el punto
    que eligió el cliente. Sirve para confirmar ANTES de despachar. Busca en TiendaNube y Shopify.
    Con ?debug=1 (logueado) muestra además los pasos del resolvedor (exacto/coord)."""
    if not _user_actual():
        return jsonify({"ok": False, "msg": "logueate"}), 401
    dbg = (request.args.get("debug") or "") == "1"
    nums = [n.strip() for n in (request.args.get("nums") or request.args.get("num") or "").split(",") if n.strip()]
    if not nums:
        return jsonify({"ok": False, "msg": "falta num"}), 400
    try:
        import openpyxl as _oxl
        _tpl = ANDREANI_TPL if ANDREANI_TPL.exists() else Path(_os.path.expanduser("~/Downloads/EnvioMasivoExcelPaquetes.xlsx"))
        _cpidx, sucs = _and_cfg(_oxl.load_workbook(_tpl, read_only=True, data_only=True))
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude cargar plantilla: " + str(e)[:100]}), 500
    found = []
    numset = set(nums)
    # --- TiendaNube ---
    for email, tk in _tn_tokens().items():
        if not (isinstance(tk, dict) and tk.get("access_token") and tk.get("store_id")):
            continue
        for num in nums:
            try:
                r = requests.get("%s/%s/orders" % (TN_API, tk["store_id"]), headers=_tn_headers(tk["access_token"]),
                                 params={"q": num, "per_page": 10}, timeout=30)
                arr = r.json() if r.content else []
            except Exception:
                arr = []
            for o in (arr if isinstance(arr, list) else []):
                if str(o.get("number")) != num:
                    continue
                pk = _tn_pickup(o); pkad = _D(pk.get("address"))
                suc_raw = _tn_pickup_nombre(o)
                lat = pkad.get("latitude") or pkad.get("lat") or ""
                lng = pkad.get("longitude") or pkad.get("lng") or ""
                pid = str(o.get("shipping_option_reference") or "")
                cp = str(pkad.get("zipcode") or (_D(o.get("shipping_address"))).get("zipcode") or "")
                of, via = _resolver_suc_completo(suc_raw, lat, lng, pid, cp, sucs)
                item = {"tienda": "TiendaNube", "cuenta": email, "num": num,
                        "punto_elegido": pk.get("name") or suc_raw, "punto_extraido": suc_raw,
                        "lat": lat, "lng": lng, "punto_id": pid,
                        "SUCURSAL_RESUELTA": of or "⚠️ REVISAR (no la mando a cualquier lado)", "via": via}
                if dbg:
                    try:
                        _ex = _and_suc_exacto(suc_raw)
                    except Exception as e:
                        _ex = "err:" + str(e)[:40]
                    try:
                        _co = _and_suc_coord(lat, lng, "HOP" in str(suc_raw).upper(), pid, sucs)
                    except Exception as e:
                        _co = "err:" + str(e)[:40]
                    item["_debug"] = {"pickup_raw": pk, "shipping_option": o.get("shipping_option"),
                                      "shipping_option_reference": o.get("shipping_option_reference"),
                                      "paso_exacto": _ex, "paso_coord": _co}
                found.append(item)
    # --- Shopify ---
    for email, tk in _shop_tokens().items():
        if not (isinstance(tk, dict) and tk.get("access_token") and tk.get("shop")):
            continue
        for num in nums:
            try:
                r = requests.get("https://%s/admin/api/2024-10/orders.json" % tk["shop"],
                                 headers={"X-Shopify-Access-Token": tk["access_token"]},
                                 params={"status": "any", "name": num, "limit": 5,
                                         "fields": "order_number,name,shipping_lines,shipping_address"}, timeout=30)
                arr = (r.json() or {}).get("orders") or []
            except Exception:
                arr = []
            for o in arr:
                if str(o.get("order_number")) != num:
                    continue
                suc_raw = " ".join((s.get("title") or "") for s in (o.get("shipping_lines") or [])).strip()
                cp = str((_D(o.get("shipping_address"))).get("zip") or "")
                of, via = _resolver_suc_completo(suc_raw, "", "", "", cp, sucs)
                item = {"tienda": "Shopify", "cuenta": email, "num": num,
                        "punto_elegido": suc_raw, "punto_extraido": suc_raw,
                        "SUCURSAL_RESUELTA": of or "⚠️ REVISAR (no la mando a cualquier lado)", "via": via}
                if dbg:
                    item["_debug"] = {"shipping_lines": o.get("shipping_lines"),
                                      "paso_exacto": _and_suc_exacto(suc_raw)}
                found.append(item)
    if not found:
        return jsonify({"ok": False, "msg": "no encontré los pedidos %s en ninguna tienda conectada" % nums})
    return jsonify({"ok": True, "resultado": found})


