# ================= WhatsApp (Cloud API) — módulo AISLADO =================
# No toca el dashboard. Storage propio en el disco persistente (/var/data). La vinculación es
# por NÚMERO de API (phone_id + token + waba_id). El webhook lo sirve RealProfit (HTTPS de Render,
# siempre arriba) y REENVÍA lo entrante al bot de METAFY (forward_url) para no cortar el auto-respondedor.
WA_TOKENS = DATA_DIR / "wa_tokens.json"   # {email: {phone_id, token, waba_id, verify_token, forward_url, numero}}
WA_CHATS = DATA_DIR / "wa_chats.json"     # {email: {wa_id: {name, updated, messages:[...]}}}
WA_GRAPH = "https://graph.facebook.com/v21.0"
WA_URL_PUBLICA = _os.environ.get("WA_URL_PUBLICA", "https://www.realprofitapp.com")
# Servicio WhatsApp Web (Baileys), corre aparte en Render. RealProfit le habla por HTTP.
WA_WEB_URL = _os.environ.get("WA_WEB_URL", "").rstrip("/")     # ej https://realprofit-wa-web.onrender.com
WA_WEB_SECRET = _os.environ.get("WA_WEB_SECRET", "")           # mismo secret que el servicio Node
_WA_WEB_NAMES = {}   # email -> nombre del número conectado por Web (ej "NoxaLab Argentina") para la marca del bot


def _wa_marca_auto(email, cfg):
    """Marca del bot: la cargada por el dueño, o si no, el nombre del número de WhatsApp conectado
    (así el bot responde como el negocio de la cuenta, nunca hardcodeado)."""
    m = (cfg.get("bot_marca") or "").strip() if isinstance(cfg, dict) else ""
    return m or (_WA_WEB_NAMES.get(email) or "").strip()


# Estado del vigilante, para poder mirarlo desde afuera (/wa-salud).
_WA_SALUD = {"ts": 0, "sesiones": [], "acciones": [], "arranco": 0, "vueltas": 0, "error": None}
_WA_ULT_ARREGLO = {}


def _wa_anotar(msg):
    import time as _t
    _WA_SALUD["acciones"] = (_WA_SALUD.get("acciones") or [])[-19:] + [
        {"ts": _t.time(), "hora": _dt.datetime.now().strftime("%d/%m %H:%M:%S"), "msg": msg}]


def _wa_vigilar_sordera():
    """El WhatsApp Web puede quedar 'connected', con el socket vivo y el sondeo OK, y NO RECIBIR
    NADA. Paso el 11/09: diez horas mudo sin que nada lo detectara, porque el watchdog miraba
    'hace cuanto no llega ALGO' y ese reloj lo refrescan los acuses y el propio ping.

    Este vigilante mira lo unico que importa: hace cuanto no entra UN MENSAJE. Si pasa el umbral
    repara solo, en dos escalones, y NUNCA pide QR (no toca creds.json):
      1) SORDA_1 min  -> limpieza de las sesiones de signal + reconexion
      2) SORDA_2 min  -> limpieza PROFUNDA (tambien las app-state-sync de la bandeja)
    El puente tiene su propio watchdog a los 40 min; este es la red de seguridad por si aquel
    quedo trabado. Por eso los umbrales van despues, y se espera entre arreglos para no estar
    reconectando sesiones sanas de madrugada."""
    import time as _t
    if not (WA_WEB_URL and WA_WEB_SECRET):
        return
    SORDA_1 = int(_os.getenv("WA_VIG_MIN", "60"))        # min sin un solo mensaje -> limpieza normal
    SORDA_2 = int(_os.getenv("WA_VIG_MIN2", "120"))      # min -> limpieza profunda
    ESPERA = int(_os.getenv("WA_VIG_ESPERA", "30"))      # min minimos entre dos arreglos de la misma cuenta
    h = {"x-wa-secret": WA_WEB_SECRET}
    d = requests.get(WA_WEB_URL + "/diag", headers=h, timeout=(10, 20)).json()
    ahora = _t.time()
    _WA_SALUD["ts"] = ahora
    _WA_SALUD["sesiones"] = [{"acc": x.get("acc"), "status": x.get("status"),
                              "seg_sin_mensajes": x.get("seg_sin_mensajes"),
                              "ws_muerto": x.get("ws_muerto")} for x in (d.get("sesiones") or [])]
    for ses in (d.get("sesiones") or []):
        acc = ses.get("acc") or ""
        if ses.get("status") != "connected":
            continue                                     # no conectada: el puente ya la reconecta
        mudos = (ses.get("seg_sin_mensajes") or 0) / 60.0
        if mudos < SORDA_1:
            continue
        if (ahora - _WA_ULT_ARREGLO.get(acc, 0)) < ESPERA * 60:
            continue                                     # recien arreglada: darle tiempo
        profundo = mudos >= SORDA_2
        try:
            r = requests.post(WA_WEB_URL + "/limpiar-sesiones", headers=h, timeout=120,
                              json={"acc": acc, "profundo": profundo})
            _WA_ULT_ARREGLO[acc] = ahora
            _wa_anotar("%s sorda %d min -> limpieza %s: %s"
                       % (acc, int(mudos), "PROFUNDA" if profundo else "normal", str(r.text)[:90]))
        except Exception as e:
            _wa_anotar("%s sorda %d min -> fallo el arreglo: %s" % (acc, int(mudos), str(e)[:80]))


def _wa_con_limite(fn, seg, nombre):
    """Corre fn en un hilo aparte y no espera mas de `seg` segundos. Si se cuelga se abandona
    (es daemon) y el vigilante sigue girando. Un vigilante bloqueado no vigila nada."""
    caja = {}
    def _correr():
        try:
            caja["r"] = fn()
        except Exception as e:
            caja["e"] = e
    h = threading.Thread(target=_correr, daemon=True, name=nombre)
    h.start()
    h.join(seg)
    if h.is_alive():
        _WA_SALUD["colgados"] = (_WA_SALUD.get("colgados") or 0) + 1
        _WA_SALUD["ult_colgado"] = nombre
        return False
    if "e" in caja:
        raise caja["e"]
    return True


def _wa_web_keepalive():
    """Ping al servicio de WhatsApp Web cada 3 min (para que Render no lo duerma) + vigilante
    de sordera: si deja de RECIBIR mensajes, lo repara solo.
    Deja constancia de que ARRANCO y de cada vuelta: sin eso, si el hilo no corre o se muere,
    el endpoint queda en cero y no hay forma de distinguir 'no arranco' de 'arranco y fallo'."""
    import time as _t
    _WA_SALUD["arranco"] = _t.time()
    while True:
        _WA_SALUD["vueltas"] = (_WA_SALUD.get("vueltas") or 0) + 1
        _WA_SALUD["latido"] = _t.time()      # se mueve en CADA vuelta: distingue vivo de colgado
        _WA_SALUD["paso"] = "health"
        try:
            if WA_WEB_URL:
                _wa_con_limite(lambda: requests.get(WA_WEB_URL + "/health", timeout=(10, 15)),
                               25, "wa-ping")
        except Exception:
            pass
        _WA_SALUD["paso"] = "sordera"
        try:
            # 150s: la limpieza de sesiones puede tardar hasta 120s cuando repara de verdad
            _wa_con_limite(_wa_vigilar_sordera, 150, "wa-sordera")
            _WA_SALUD["error"] = None
        except Exception as e:
            _WA_SALUD["error"] = "%s: %s" % (type(e).__name__, str(e)[:160])
            try: _wa_anotar("vigilante fallo: %s: %s" % (type(e).__name__, str(e)[:80]))
            except Exception: pass
        _WA_SALUD["paso"] = "durmiendo"
        _t.sleep(90)


def _wa_vig_vivo():
    """Levanta el hilo si se murio. Un vigilante que corre una sola vez no protege nada:
    el 11/09 quedo en la vuelta 1 durante 15 min. Esto lo resucita desde cualquier request."""
    import time as _t
    lat = _WA_SALUD.get("latido") or 0
    if lat and (_t.time() - lat) < 200:
        return False                          # late: esta vivo
    try:
        _WA_SALUD["latido"] = _t.time()   # marcar YA: si entran 2 requests juntas no nacen 2 hilos
        threading.Thread(target=_wa_web_keepalive, daemon=True).start()
        _WA_SALUD["resucitado"] = (_WA_SALUD.get("resucitado") or 0) + 1
        return True
    except Exception:
        return False


@app.before_request
def _wa_vig_auto():
    """Que el resucitador NO dependa de que alguien mire /wa-salud: un domingo no la mira nadie.
    Enganchado aca lo revisa cualquier request de la app. Es leer un dict y restar: no cuesta nada.
    Ademas gunicorn corre 2 workers = 2 vigilantes independientes, y asi se cubren los dos."""
    try:
        _wa_vig_vivo()
    except Exception:
        pass


@app.get("/wa-salud")
def wa_salud():
    """Estado del WhatsApp Web y lo que hizo el vigilante. Para mirar si estuvo sordo."""
    if not _user_actual():
        return jsonify({"ok": False}), 401
    import time as _t
    _a = _WA_SALUD.get("arranco") or 0
    _lat = _WA_SALUD.get("latido") or 0
    _revivio = _wa_vig_vivo()
    return jsonify({"ok": True,
                    "pid": _os.getpid(),
                    "paso": _WA_SALUD.get("paso"),
                    "colgados": _WA_SALUD.get("colgados") or 0,
                    "ult_colgado": _WA_SALUD.get("ult_colgado"),
                    "latido_hace_seg": round(_t.time() - _lat, 1) if _lat else None,
                    "resucitado": _WA_SALUD.get("resucitado") or 0,
                    "revivio_ahora": _revivio,
                    "hilo_arranco": bool(_a),
                    "hilo_hace_seg": round(_t.time() - _a, 1) if _a else None,
                    "vueltas": _WA_SALUD.get("vueltas") or 0,
                    "error": _WA_SALUD.get("error"),
                    "hace_seg": round(_t.time() - (_WA_SALUD.get("ts") or 0), 1) if _WA_SALUD.get("ts") else None,
                    "sesiones": _WA_SALUD.get("sesiones") or [],
                    "acciones": list(reversed(_WA_SALUD.get("acciones") or []))})


# El vigilante NO se arranca aca a proposito (ver _wa_vig_vivo): un hilo lanzado durante el
# import queda trabado en el start() y no vuelve a girar. Lo levanta el primer request, que es
# el camino probado. Por eso ver "resucitado: 1" despues de un deploy es lo NORMAL.

try:    # bot de finanzas: completa la planilla del día vencido ~1:15am (hora AR)
    threading.Thread(target=_fin_bot_loop, daemon=True, name="fin-bot").start()
except Exception:
    pass


def _wa_web_send(email, wid, text):
    """Manda un texto por el WhatsApp Web (servicio Baileys). Devuelve (ok, id, err)."""
    if not (WA_WEB_URL and WA_WEB_SECRET):
        return False, "", "servicio Web no configurado"
    try:
        r = requests.post(WA_WEB_URL + "/send",
                          headers={"x-wa-secret": WA_WEB_SECRET},
                          json={"acc": email, "to": wid, "text": text}, timeout=20)
        j = r.json() if r.content else {}
        if r.status_code >= 400 or not j.get("ok"):
            return False, "", j.get("msg", "error %s" % r.status_code)
        return True, "", ""
    except Exception as e:
        return False, "", str(e)[:120]


def _wa_tokens():
    try:
        return _json.loads(WA_TOKENS.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _wa_save_tokens(d):
    WA_TOKENS.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")


def _wa_leer_principal(intentos=3):
    """Lee wa_chats.json (el PRINCIPAL). Reintenta con espera: con la RAM al tope una lectura puede
    fallar por MemoryError y la siguiente andar. Devuelve el dict, o None si NO se pudo leer.
    Archivo inexistente cuenta como vacío SOLO si tampoco hay .bak (instalación nueva): si hay .bak
    y falta el principal algo anda mal y NO se trata como "no hay chats"."""
    for i in range(max(1, intentos)):
        try:
            d = _json.loads(WA_CHATS.read_text(encoding="utf-8"))
            return d if isinstance(d, dict) else None
        except FileNotFoundError:
            if not WA_CHATS.with_suffix(".bak").exists():
                return {}
        except Exception:
            pass
        if i < intentos - 1:
            _time.sleep(0.3 * (i + 1))
    return None


def _wa_foto_marcar(d):
    """Anota en cada chat de la foto ("_o") cómo estaban sus campos al LEERLOS. Al guardar, la fusión
    compara contra eso y aplica SOLO lo que este que guarda cambió de verdad; el resto de los campos
    los toma del disco. Sin esto, el que guardaba con una foto vieja (bot pensando 3 s, webhook)
    pisaba los campos de TODOS los chats de su foto: un chat con un mensaje nuevo quedaba unread=0 y
    updated viejo (leído y hundido en la lista) y un pend_pedido ya sacado revivía. "_o" no se
    escribe nunca al disco (la fusión lo saca)."""
    try:
        for convs in (d or {}).values():
            if not isinstance(convs, dict):
                continue
            for conv in convs.values():
                if isinstance(conv, dict):
                    f = {k: v for k, v in conv.items() if k not in ("messages", "_o")}
                    conv["_o"] = _json.dumps(f, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        pass
    return d


def _wa_chats_all():
    d = _wa_leer_principal()
    if d is not None:
        return _wa_foto_marcar(d)
    # NUNCA devolver {} a la ligera. Igual, desde el 31-10-2026 ningún guardado escribe sin poder
    # releer el PRINCIPAL (ver _guardar_fusionado): una foto vieja o vacía ya no puede borrar nada.
    try:
        return _wa_foto_marcar(_json.loads(WA_CHATS.with_suffix(".bak").read_text(encoding="utf-8")))
    except Exception:
        return {}


_WA_SAVE_LOCK = threading.Lock()   # un guardado por vez DENTRO del proceso


def _wa_msg_clave(m):
    """Identidad de un mensaje para poder unirlos sin perder ni duplicar. Verificado contra los
    datos vivos el 16/09/2026: los 236 mensajes traian 'id' y NINGUNO estaba repetido. El
    respaldo por ts+dir+texto es solo por si algun dia entra uno sin id."""
    return (m.get("id") or "").strip() or "%s|%s|%s" % (
        m.get("ts", ""), m.get("dir", ""), (m.get("text") or "")[:80])


def _wa_cuenta_unicos(x) -> int:
    """Mensajes DISTINTOS (por _wa_msg_clave) de todos los chats. La guarda de "no bajar la cuenta"
    compara esto y no el conteo bruto: si en disco quedaban 2 mensajes con la misma clave, la fusión
    (que los une) bajaba el bruto y se rechazaba en silencio cualquier guardado sin mensajes nuevos."""
    n = 0
    for v in (x or {}).values():
        if not isinstance(v, dict):
            continue
        for c in v.values():
            if isinstance(c, dict):
                n += len({_wa_msg_clave(m) for m in (c.get("messages") or []) if isinstance(m, dict)})
    return n


def _wa_fusion_campos(vieja, conv):
    """Campos del chat (todo menos messages). Si el que guarda trae "_o" (cómo estaban al leer),
    se aplica SOLO lo que cambió respecto de eso (incluido sacar un campo: pop de pend_pedido) y el
    resto queda como está en disco. Sin "_o" (chat armado a mano) manda el que guarda, como antes."""
    cur = {k: v for k, v in conv.items() if k not in ("messages", "_o")}
    o = conv.get("_o")
    if not isinstance(o, str):
        return dict(cur)
    try:
        orig = _json.loads(o)
    except Exception:
        return dict(cur)
    fus = {k: v for k, v in vieja.items() if k not in ("messages", "_o")}

    def _cj(v):
        return _json.dumps(v, ensure_ascii=False, sort_keys=True, default=str)
    if _cj(cur) == o:
        return fus                            # no tocó ningún campo de este chat
    for k in set(cur) | set(orig):
        if k in cur:
            if k not in orig or _cj(cur[k]) != _cj(orig[k]):
                fus[k] = cur[k]               # lo cambió el que guarda
        elif k in orig:
            fus.pop(k, None)                  # lo sacó el que guarda (a propósito)
    return fus


def _wa_fusion_chats(disco, nuevo):
    """Une lo que YA hay en disco con lo que se quiere guardar, SIN PERDER NADA.
    Dos reglas, y de ahi sale la garantia:
      1) un chat que existe en disco NUNCA desaparece (aunque el que guarda no lo tenga);
      2) la lista de mensajes de un chat NUNCA se achica: se unen por _wa_msg_clave().
    Los demas campos del chat (unread, bot_nota, pend_pedido...): se aplica lo que EL QUE GUARDA
    cambió respecto de cómo los leyó ("_o", ver _wa_foto_marcar); lo que no tocó queda como está en
    disco. Asi un pop() a proposito -borrar pend_pedido al crear el pedido- se respeta, y una foto
    vieja ya no revierte lo que otro escribio en otro chat. pedido_shopify: si esta en disco se
    conserva si o si (perderlo permitiria cargar dos veces el mismo pedido). El estado de cada
    mensaje (sent/delivered/read/failed) nunca baja de nivel."""
    out = dict(disco or {})
    for email, convs in (nuevo or {}).items():
        base = dict(out.get(email) or {})
        for wid, conv in (convs or {}).items():
            vieja = base.get(wid)
            if not isinstance(conv, dict):
                continue
            if not isinstance(vieja, dict):
                nc = {k: v for k, v in conv.items() if k != "_o"}
                base[wid] = nc
                continue
            fus = _wa_fusion_campos(vieja, conv)
            if vieja.get("pedido_shopify") and not fus.get("pedido_shopify"):
                fus["pedido_shopify"] = vieja["pedido_shopify"]
            vistos, orden = {}, []
            for m in list(vieja.get("messages") or []) + list(conv.get("messages") or []):
                if not isinstance(m, dict):
                    continue
                k = _wa_msg_clave(m)
                if k in vistos:                   # el mismo mensaje por los dos lados: completa
                    ya = vistos[k]
                    st_ya = ya.get("status") or ""
                    for kk, vv in m.items():
                        if vv not in (None, ""):
                            ya[kk] = vv
                    if _WA_ST_RANK.get(st_ya, 0) > _WA_ST_RANK.get(ya.get("status") or "", 0):
                        ya["status"] = st_ya      # una foto vieja no baja read→sent
                    continue
                vistos[k] = dict(m)
                orden.append(k)
            msgs = [vistos[k] for k in orden]
            msgs.sort(key=lambda x: x.get("ts") or "")
            fus["messages"] = msgs
            base[wid] = fus
        out[email] = base
    return out


_WA_PEND_GLOB = "wa_chats.PENDIENTE.*.json"


def _wa_pend_guardar(d) -> bool:
    """No se pudo releer el principal: lo que se quería guardar va a un archivo aparte
    (wa_chats.PENDIENTE.<ts>.<pid>.json, atómico) y lo fusiona después _wa_drenar(). Nada se pierde
    y nada se escribe a ciegas."""
    try:
        f = WA_CHATS.parent / ("wa_chats.PENDIENTE.%d.%d.json" % (_time.time_ns(), _os.getpid()))
        tmp = WA_CHATS.parent / (f.name + ".tmp")
        try:
            tmp.write_text(_json.dumps(d or {}, ensure_ascii=False), encoding="utf-8")
            tmp.replace(f)
        finally:
            try:
                if tmp.exists():
                    tmp.unlink()
            except Exception:
                pass
        try:
            _wa_st_asegurar_hilo()            # el que lo drena
        except Exception:
            pass
        return True
    except Exception:
        return False


def _wa_save_chats(d, _pend=True):
    """Guarda los chats FUSIONANDO, nunca reemplazando. Devuelve True si quedó guardado (o en
    PENDIENTE para fusionarlo apenas se pueda leer el disco); False solo si no se pudo ninguna.

    POR QUE: antes esto reescribia el archivo entero con la foto que traia el que llamaba. Como
    hay 20 lugares que hacen leer-modificar-escribir y el server corre con 2 workers, dos pedidos
    a la vez se pisaban (A lee, B lee, A escribe, B escribe -> se pierde lo de A). Asi se
    perdieron 1.751 chats el 16/09/2026 con el envio masivo de seguimientos.

    AHORA: al escribir se RELEE el disco y se une (ver _wa_fusion_chats), con un candado por proceso
    y otro entre procesos. Si el PRINCIPAL no se puede releer (3 intentos), NO se escribe: va a
    PENDIENTE (nunca se usa el .bak, que va una escritura atrás, como base de una escritura).
    Se rechaza el guardado si aun asi bajaria la cuenta de mensajes distintos (no puede pasar),
    copia en wa_chats.bak (atómica, después del principal), y escritura atomica (tmp + replace)."""
    r = False
    try:
        with _WA_SAVE_LOCK:                       # un guardado por vez DENTRO del proceso
            # ...y uno por vez ENTRE procesos: el server corre con 2 workers, y el candado de arriba
            # no los sincroniza. Sin esto quedaba una ventana de milisegundos entre releer el disco y
            # reemplazar el archivo donde el otro worker podia escribir y su version quedaba pisada.
            # El lock se toma sobre un archivo aparte (wa_chats.lock) y se libera SIEMPRE (finally).
            _lk = None
            try:
                import fcntl
                _lk = open(str(WA_CHATS) + ".lock", "a+")
                fcntl.flock(_lk.fileno(), fcntl.LOCK_EX)
            except Exception:
                _lk = None                        # si no se puede (SO sin flock), se sigue igual
            try:
                r = _guardar_fusionado(d, _wa_cuenta_unicos)
            finally:
                if _lk is not None:
                    try:
                        import fcntl as _fc
                        _fc.flock(_lk.fileno(), _fc.LOCK_UN)
                        _lk.close()
                    except Exception:
                        pass
    except Exception:
        r = False
    if r:
        # lo que esta foto traía ya está en disco: desde acá, un nuevo guardado de la MISMA foto (el bot
        # guarda varias veces mientras piensa) aplica solo lo que cambie de ahora en más.
        _wa_foto_marcar(d)
    elif _pend:
        r = _wa_pend_guardar(d)
    return bool(r)


def _guardar_fusionado(d, _cuenta):
    """Relee el disco, FUSIONA y escribe. Se llama con los dos candados tomados (proceso + archivo).
    True = escrito (o rechazado y guardado aparte para mirarlo); False = no se escribió NADA."""
    tmp = btmp = None
    try:
        # NO tratar una lectura fallida como "no hay nada" (eso borró todo el 16-09), y tampoco
        # fusionar contra el .bak: va una escritura atrás y se perdía lo que entró en la última.
        disco = _wa_leer_principal()
        if disco is None:
            return False
        final = _wa_fusion_chats(disco, d or {})
        if _cuenta(final) < _cuenta(disco):
            try:                    # no deberia pasar nunca; si pasa, queda para mirarlo
                (WA_CHATS.parent / ("wa_chats.RECHAZADO.%d.json" % _time.time_ns())).write_text(
                    _json.dumps({"nuevo": _cuenta(final), "viejo": _cuenta(disco),
                                 "datos": d}, ensure_ascii=False, default=str), encoding="utf-8")
                return True
            except Exception:
                return False
        # temporal POR PROCESO: si dos escribieran a la vez el mismo .tmp, uno se llevaba los
        # bytes del otro y el archivo final quedaba mezclado.
        tmp = WA_CHATS.with_suffix(".tmp.%d" % _os.getpid())
        tmp.write_text(_json.dumps(final, ensure_ascii=False), encoding="utf-8")
        tmp.replace(WA_CHATS)
        tmp = None
        if disco:
            # copia de la versión anterior, DESPUÉS del principal y atómica: antes iba con write_text
            # directo y un kill -9 a mitad la dejaba cortada (6 de 28 kills en la prueba).
            try:
                btmp = WA_CHATS.with_suffix(".bak.tmp.%d" % _os.getpid())
                btmp.write_text(_json.dumps(disco, ensure_ascii=False), encoding="utf-8")
                btmp.replace(WA_CHATS.with_suffix(".bak"))
                btmp = None
            except Exception:
                pass
        return True
    except Exception:
        return False                          # el principal no se reemplazó: no se escribió nada
    finally:
        for t in (tmp, btmp):
            if t is not None:
                try:
                    t.unlink()
                except Exception:
                    pass


def _wa_conf(email):
    return _wa_tokens().get(email)


def _wa_email_by_phone_id(pid):
    for em, c in _wa_tokens().items():
        if str(c.get("phone_id")) == str(pid):
            return em
    return None


def _wa_now():
    return (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).strftime("%Y-%m-%d %H:%M:%S")


# ───────────────────────── BOT / auto-respondedor (cerebro Claude) ─────────────────────────
# El cerebro vive en agente_ia.py. Se activa SOLO por cuenta (conf["bot"]=True) — así queda
# gateado a VisionPure y apagado para el resto. Arranca DESACTIVADO por defecto.

def _pdf_a_imagen(datos):
    """Convierte la 1er pagina de un PDF en PNG para que el cerebro la PUEDA VER.
    Varios bancos mandan el comprobante de transferencia en PDF y WhatsApp lo entrega como
    'document', no como foto: el 12/09 Sergio mando comprobante_177651199855.pdf y el bot
    tuvo que pedirle una captura porque no lo abria."""
    try:
        import pymupdf
        doc = pymupdf.open(stream=datos, filetype="pdf")
        if not doc.page_count:
            return None, ""
        pix = doc.load_page(0).get_pixmap(dpi=140)
        return pix.tobytes("png"), "image/png"
    except Exception:
        return None, ""


def _wa_web_media_bytes(email, media_id, intentos=12):
    """Baja del puente el archivo de un medio del canal WEB -> (bytes, mime) o (None, "").
    Reintenta: el puente avisa del mensaje y guarda el archivo en paralelo, asi que el primer
    intento puede llegar antes de que termine de escribirlo."""
    import time as _t          # faltaba: el _t.sleep del reintento tiraba NameError (bug preexistente)
    if not (media_id and WA_WEB_URL and WA_WEB_SECRET):
        return None, ""
    for i in range(intentos):
        try:
            r = requests.get(WA_WEB_URL + "/media", headers={"x-wa-secret": WA_WEB_SECRET},
                             params={"acc": email, "id": media_id}, timeout=30)
            if r.status_code == 200 and r.content:
                return r.content, (r.headers.get("Content-Type") or "application/octet-stream")
        except Exception:
            pass
        _t.sleep(1.5)
    return None, ""


def _wa_bot_media(conf, media_id):
    """Descarga un media de WhatsApp (imagen/comprobante) → (bytes, mime) o (None, '')."""
    try:
        r = requests.get("%s/%s" % (WA_GRAPH, media_id), params={"access_token": conf["token"]}, timeout=20)
        if r.status_code >= 400:
            return None, ""
        j = r.json(); url = j.get("url"); mime = j.get("mime_type", "") or ""
        rr = requests.get(url, headers={"Authorization": "Bearer " + conf["token"]}, timeout=40)
        if rr.status_code >= 400:
            return None, ""
        return rr.content, (rr.headers.get("Content-Type") or mime or "image/jpeg")
    except Exception:
        return None, ""


def _wa_bot_send(conf, wid, text):
    """Manda un texto por la Graph API. Devuelve (ok, msg_id, err)."""
    try:
        r = requests.post("%s/%s/messages" % (WA_GRAPH, conf["phone_id"]),
                          headers={"Authorization": "Bearer " + conf["token"]},
                          json={"messaging_product": "whatsapp", "to": wid, "type": "text", "text": {"body": text}},
                          timeout=20)
        j = r.json()
        if r.status_code >= 400:
            return False, "", (j.get("error") or {}).get("message", "error %s" % r.status_code)
        return True, (j.get("messages") or [{}])[0].get("id", ""), ""
    except Exception as e:
        return False, "", str(e)[:120]


def _bot_activo_ahora(c):
    """¿El bot debe responder AHORA según su horario? 24h = siempre; franja = dentro del rango
    (hora Argentina, UTC-3). Si la franja cruza medianoche (ej 20:00→09:00) lo contempla."""
    if (c.get("bot_sched") or "24h") == "24h":
        return True
    try:
        import datetime
        now = datetime.datetime.utcnow() - datetime.timedelta(hours=3)  # AR = UTC-3
        cur = now.hour * 60 + now.minute
        def _mins(s):
            p = (s or "0:0").split(":"); return int(p[0]) * 60 + int(p[1])
        d = _mins(c.get("bot_desde") or "20:00")
        h = _mins(c.get("bot_hasta") or "09:00")
    except Exception:
        return True
    if d == h:
        return True
    if d < h:
        return d <= cur < h
    return cur >= d or cur < h  # cruza medianoche


def _bot_canal_ok(c, canal):
    """¿El bot está habilitado para ESTE canal ('api' o 'web')? Default: api (retrocompatible)."""
    sel = c.get("bot_canal") or "api"
    return sel == "ambos" or sel == canal


# ══════════ CAMPAÑA DE RESEÑAS EN VIDEO ══════════
# Al mandar la plantilla `resena_video_35`, el cliente contesta y para el bot eso es una
# conversacion nueva: le arranca a VENDER encima de la campaña. Pasa porque el bot solo se
# calla cuando contesto una PERSONA, y las plantillas estan excluidas de ese chequeo a
# proposito (si no, el seguimiento de despacho lo dejaria mudo para siempre).
#
# Mientras el chat este en campaña, el bot sigue este guion y no el cerebro de ventas. NO se
# queda ciego: si el cliente pregunta otra cosa, cae de nuevo en el cerebro normal, que sigue
# sabiendo que compro y que pidio.
CUPON_RESENA = "RES35"
_RES_DIAS = 10                       # cuanto queda abierta la campaña en un chat
# Los TEXTOS de los botones de la plantilla. Se siguen usando SOLO para el gate
# `_res_activa`, que a proposito confia unicamente en botones de verdad (type="button"):
# un cliente cualquiera escribe "no gracias" todo el tiempo y con texto suelto lo
# metiamos en la campaña.
_RES_SI = ("quiero el 35", "quiero el descuento", "dale quiero el 35")
_RES_NO = ("ahora no", "no gracias", "no me interesa")

# Para CONTESTAR, en cambio, hay que entender como escribe la gente. Con el match exacto
# de antes el bot se quedaba MUDO justo con el que decia que si ("si", "dale", "me
# interesa", "como hago" no matcheaban ninguna de las tres frases de arriba), y los 95 de
# la tanda #1001-#1100 los hubiera tenido que contestar Cristian a mano.
_RES_NO_FRASE = ("ahora no", "no gracias", "no me interesa", "no quiero", "no puedo",
                 "no tengo tiempo", "mas adelante", "otro dia", "no por ahora",
                 "no hace falta", "dejalo", "no me sirve", "prefiero no")
_RES_NO_PAL = {"no", "nop", "nope", "negativo", "paso"}
_RES_SI_FRASE = ("quiero el 35", "quiero el descuento", "quiero descuento", "me interesa",
                 "si quiero", "dale quiero", "quiero hacerlo", "me sumo", "de una",
                 "como hago", "como es", "como seria", "como lo hago", "como lo mando",
                 "donde lo mando", "que tengo que hacer", "que hay que hacer", "contame",
                 "decime como", "si me interesa", "obvio que quiero")
_RES_SI_PAL = {"si", "sii", "siii", "sisi", "sip", "dale", "obvio", "claro", "ok", "oka",
               "okey", "listo", "acepto", "quiero", "perfecto", "genial", "buenisimo",
               "barbaro", "va", "vale", "bueno", "joya", "copado", "interesa"}

# "Lo hago mas tarde": no es un no. Se le agradece y se le dejan los pasos igual.
_RES_LUEGO_FRASE = ("luego", "despues", "mas tarde", "manana", "en un rato", "cuando pueda",
                    "cuando tenga tiempo", "ahora no puedo", "en breve", "ya lo hago",
                    "lo hago", "mas adelante lo hago", "mas rato", "a la noche")

# Preguntas de logistica: NO se las contesta el guion de la campaña, pero TAMPOCO van al
# cerebro de ventas mientras la tarjeta este puesta. Quedan marcadas para que las vea una
# persona. Si se dejaran pasar al cerebro, volveria a mandar precio y links.
_RES_OTRO_TEMA = ("pedido", "envio", "llego", "llega", "demora", "correo", "andreani",
                  "seguimiento", "factura", "devolucion", "reclamo", "no me llego")


def _res_norm(t) -> str:
    """Texto comparable: sin tildes, sin signos, en minuscula y con un solo espacio.
    Hace falta porque la plantilla se carga a mano en Meta y basta un '35 %' con espacio o
    un 'proxima' sin tilde para que un match exacto deje de reconocerla — y ahi el bot le
    arranca a VENDER al cliente en medio de la campaña."""
    import unicodedata as _u
    t = "".join(c for c in _u.normalize("NFD", str(t or "")) if _u.category(c) != "Mn").lower()
    return " ".join("".join(c if c.isalnum() else " " for c in t).split())


def _res_es_plantilla(txt) -> bool:
    """¿Este texto es la plantilla de la campaña? Se mira por SEÑAS, no por la frase exacta:
    tiene que hablar de 35 y de video o reseña. Las otras plantillas que manda Cristian
    (seguimiento de despacho, Flex, reclamo) no hablan de nada de eso."""
    n = _res_norm(txt)
    return "35" in n and ("video" in n or "resena" in n)


def _res_otro_tema(n) -> bool:
    """¿Esta preguntando por otra cosa (su pedido, el envio, la plata)?"""
    return any(f in n for f in _RES_OTRO_TEMA)


def _res_no_quiere(n) -> bool:
    if any(f in n for f in _RES_NO_FRASE):
        return True
    pal = n.split()
    return len(pal) <= 3 and bool(pal) and pal[0] in _RES_NO_PAL


def _res_luego(n) -> bool:
    """¿Lo deja para mas tarde? No es un no: se le dejan los pasos igual."""
    return any(f in n for f in _RES_LUEGO_FRASE)


def _res_quiere(n) -> bool:
    """¿Dijo que si? Se evalua DESPUES del no, porque 'no quiero' contiene 'quiero'."""
    if _res_no_quiere(n):
        return False
    if any(f in n for f in _RES_SI_FRASE):
        return True
    # Una afirmacion corta y sola ("si", "dale", "ok") se toma como un si SOLO porque el
    # mensaje anterior fue la plantilla preguntandole si quiere el 35%: sin ese contexto
    # "dale" no significa nada. Por eso esto se llama unicamente desde `_res_guion`, que
    # corre nada mas cuando `_res_activa` dio True.
    pal = n.split()
    return len(pal) <= 4 and any(x in _RES_SI_PAL for x in pal)


_RES_INSTR = ("Dale 🙌\n\nGrabá 15 segundos con el celular, que se te vea la cara, contando:\n\n"
              "• cómo te llegó el pedido\n• si lo venís usando seguido\n• qué efectos notaste hasta ahora\n\n"
              "Mandámelo por acá y te paso el código.")
_RES_CHAU = "Listo, sin problema 🙌 Gracias igual."
_RES_AYUDA = ("Es más fácil de lo que parece 🙌\n\n"
              "1. Tocá el clip 📎 acá abajo\n"
              "2. Elegí Cámara y pasá a video\n"
              "3. Grabá 15 segundos contando cómo te llegó, si lo usás seguido y qué notaste\n"
              "4. Mandámelo por acá\n\n"
              "No hace falta que sea perfecto, al contrario.")
_RES_FORMATO = ("Gracias por mandarlo 🙌 Para el 35% tiene que ser un video y que se te vea la "
                "cara — es lo que le da valor al testimonio.\n\n" + _RES_AYUDA)
_RES_LUEGO = ("Dale, cuando puedas 🙌 Te dejo los pasos así los tenés a mano:\n\n")
_RES_RECIBIDO = ("¡Buenísimo, me llegó! 🙌 Lo revisa una persona del equipo y te pasa el código "
                 "por acá. Gracias por tomarte el tiempo 💚")


def _res_fresca(ts) -> bool:
    """¿La plantilla se mando hace menos de _RES_DIAS dias?

    `_RES_DIAS` estaba declarado desde el principio y NO SE USABA: la campaña no se cerraba
    nunca. Un chat que recibio la plantilla quedaba "en campaña" mientras esa plantilla
    siguiera entre los ultimos 40 mensajes, asi que meses despues el cliente escribia
    "no quiero" por cualquier otra cosa y el bot le contestaba "Listo, sin problema" y le
    pegaba la tarjeta de reseñas. Con el reconocimiento de texto libre eso se agravaba.
    """
    try:
        t = _dt.datetime.strptime(str(ts or "")[:19], "%Y-%m-%d %H:%M:%S")
    except Exception:
        try:
            t = _dt.datetime.strptime(str(ts or "")[:16], "%Y-%m-%d %H:%M")
        except Exception:
            return False          # sin fecha no se asume que esta viva
    ahora = _dt.datetime.utcnow() - _dt.timedelta(hours=3)
    return (ahora - t).days < _RES_DIAS


def _res_activa(conv) -> bool:
    """¿Este chat esta en la campaña?

    Gana EL EVENTO MAS NUEVO, no el historial. Antes esto miraba `res_cerrada`, que se
    prende cuando el cliente toca "Ahora no" y NO SE APAGA NUNCA: le volvias a mandar la
    plantilla y el bot ya no la reconocia, o el que se arrepentia ("al final si quiero")
    caia al cerebro de ventas. Pasó de verdad el 11-10 probando con el chat de Cristian.
    """
    msgs = (conv.get("messages") or [])[-40:]
    ultimo_in = next((m for m in reversed(msgs) if m.get("dir") == "in"), None)
    for m in reversed(msgs):
        if m.get("dir") == "out" and m.get("type") == "template" and _res_es_plantilla(m.get("text")):
            # Plantilla vieja = campaña cerrada. Se corta aca y NO se sigue buscando mas
            # atras: si esta es vieja, cualquier otra es todavia mas vieja.
            return _res_fresca(m.get("ts"))
        # OJO: solo vale el BOTON de verdad (el webhook lo marca type="button"), nunca texto
        # suelto. Un cliente cualquiera escribe "no gracias" o "ahora no" todo el tiempo y
        # con eso lo metiamos en la campaña: el bot le contestaba "Listo, sin problema" y le
        # cerraba el chat en vez de atenderlo.
        if m.get("dir") == "in" and m.get("type") == "button":
            n = _res_norm(m.get("text"))
            if n in _RES_SI:
                return _res_fresca(m.get("ts"))
            if n in _RES_NO:
                # Dijo que no: sigue "en campaña" solo para poder despedirse esta vez. Si
                # despues escribe cualquier otra cosa, lo atiende el cerebro normal.
                return (m is ultimo_in) and _res_fresca(m.get("ts"))
    return False


# OJO con las palabras sueltas: "cambio" matcheaba "no he sentido ningun CAMBIO" y el bot le
# mandaba las instrucciones de la reseña a alguien que decia que el producto no le hizo nada
# (Jose Antonio Amoros, 12-10 18:55). Van solo frases que no se cruzan con otra cosa.
_RES_COMPRA = ("comprar", "comprarme", "quiero otro", "quiero dos", "quiero mas",
               "me mandas otro", "otro pote", "dos potes", "tres potes", "mas potes",
               "cuanto sale", "cuanto esta", "que precio", "el precio")

# QUEJAS Y DUDAS DE SALUD. Van ANTES que todo: a alguien que dice que no le hizo efecto no se
# le pide un video de reseña. El bot no contesta y lo ve una persona.
_RES_QUEJA = ("no he sentido", "no senti", "no sentí", "no noto", "no note", "ningun cambio",
              "ninguna mejora", "no me hizo", "no hizo nada", "no funciona", "no me funciono",
              "no funciono", "no sirve", "no me sirvio", "sin resultados", "no veo resultados",
              "no veo cambios", "no pasa nada", "no me anda", "no mejore", "sigo igual",
              "no cambio nada", "me cayo mal", "me hizo mal", "efecto adverso", "alergia",
              "me siento mal", "peor", "estafa", "no me llego nada", "devolucion", "reembolso")


def _res_queja(n) -> bool:
    """¿Se esta quejando o dice que no le hizo efecto? No es alguien a quien pedirle reseña."""
    return any(f in n for f in _RES_QUEJA)


def _res_compra(n) -> bool:
    """¿Esta hablando de comprar mas? Con la tarjeta puesta esto NO lo cierra el bot."""
    return any(f in n for f in _RES_COMPRA)


def _res_guion(conv, last_in):
    """Que contesta el bot mientras el chat tiene la TARJETA DE RESEÑAS.

    REGLA DURA: con la tarjeta puesta el bot NUNCA pasa por el cerebro de ventas. Le pasa
    LOS PASOS del descuento y nada mas — ni precio, ni alias, ni links.

    Paso de verdad el 12-10-2026 con Nilton Carlos: a los 2 minutos de recibir la plantilla
    contesto "Hola. Bueno. Luego lo hago. Estoy por comprar dos postes mas." y el bot le
    mando precio, alias de transferencia, link de descuento y el de Mercado Libre encima de
    la campaña. El guion devolvia None y ese None caia derecho al cerebro de ventas.

    Devuelve:
      texto -> se lo manda
      ""    -> NO contesta y lo deja marcado para que lo mire una persona
      None  -> solo si el chat ya no esta en campaña (no deberia pasar aca)
    """
    t = _res_norm(last_in.get("text"))
    tipo = last_in.get("type") or "text"

    def _no_repetir(msg):
        """Nunca mandar dos veces seguidas el mismo texto. Es la ultima red: aunque una rama
        nueva se equivoque, el cliente no ve el mismo mensaje repetido."""
        if not msg:
            return msg
        for m in reversed((conv.get("messages") or [])[-12:]):
            if m.get("dir") == "out" and m.get("by") == "bot":
                if (m.get("text") or "").strip() == msg.strip():
                    conv["res_ojo"] = conv.get("res_ojo") or "insiste y ya le contestamos lo mismo"
                    return ""
                break
        return msg

    if tipo == "video":
        # El video NO lo valida el bot: acusa recibo y lo deja pendiente para una persona,
        # que es la que decide y manda el cupon.
        conv["res_video"] = _wa_now()
        conv.pop("res_video_ok", None)
        return _RES_RECIBIDO

    if tipo in ("image", "audio", "document"):
        conv["res_instr"] = True
        return _no_repetir(_RES_FORMATO)

    # ── de aca para abajo es texto ──
    # PRIMERO la queja: si dice que no le hizo efecto, el bot NO le pide el video ni le
    # contesta nada. Lo ve una persona. Paso el 12-10 con Jose Antonio Amoros: escribio
    # "hace casi 2 meses que lo tomo y no he sentido ningun cambio" y el bot le contesto
    # "Dale, grabá 15 segundos".
    if _res_queja(t):
        conv["res_ojo"] = "dice que no le hizo efecto / se queja"
        return ""

    if _res_no_quiere(t):
        conv["res_cerrada"] = True
        return _no_repetir(_RES_CHAU)

    if _res_luego(t):
        # "Luego lo hago": se le agradece y se le dejan los pasos, asi los tiene cuando se
        # ponga. Si ademas menciono que quiere comprar mas, se marca para que Cristian lo
        # cierre a mano: esa venta la hace una persona, no un link automatico.
        conv["res_luego"] = _wa_now()
        conv["res_instr"] = True
        if _res_compra(t):
            conv["res_ojo"] = "quiere comprar mas"
        return _no_repetir(_RES_LUEGO + _RES_AYUDA)

    if _res_compra(t):
        # Contesto A LA PLANTILLA diciendo que quiere llevar mas potes. Eso sigue siendo
        # la campaña: se le pasan LAS INSTRUCCIONES, igual que si hubiera tocado el boton.
        # NO se le tira el link ni el precio — eso fue lo que paso con Nilton Carlos.
        # Ademas queda marcado para que Cristian le cierre la venta a mano.
        conv["res_ojo"] = "quiere comprar mas"
        ya = bool(conv.get("res_instr"))
        conv["res_pedido"] = _wa_now()
        conv["res_instr"] = True
        return _no_repetir(_RES_AYUDA if ya else _RES_INSTR)

    if _res_quiere(t):
        ya = bool(conv.get("res_instr"))
        conv["res_pedido"] = _wa_now()
        conv["res_instr"] = True
        return _no_repetir(_RES_AYUDA if ya else _RES_INSTR)


    if _res_otro_tema(t):
        # Pregunta por su pedido o su envio: no es de la campaña, pero tampoco va al
        # cerebro de ventas con la tarjeta puesta. Lo ve una persona.
        conv["res_ojo"] = "pregunta por su pedido"
        return ""

    # Cualquier otra cosa: los pasos del descuento UNA sola vez. Si ya se los explicamos y
    # sigue escribiendo otra cosa, el bot se calla y lo ve una persona.
    #
    # Sin este corte el bot repetia los mismos pasos a cada mensaje: a Sergio (12-10 18:44) le
    # mando el mismo texto DOS VECES seguidas, la segunda contestando "si me queres llamar
    # dentro de 1 mes te cuento". Parece un robot roto y quema el chat.
    if conv.get("res_instr"):
        conv["res_ojo"] = "ya le explicamos y contestó otra cosa"
        return ""
    conv["res_instr"] = True
    return _no_repetir(_RES_AYUDA)


def _wa_bot_run(email, conf, wid, chats, canal="api"):
    """Corre el cerebro sobre la conversación wid y (si corresponde) responde solo.
    Anti-doble-respuesta por id del último entrante. Nunca lanza."""
    try:
        import agente_ia
    except Exception:
        return
    conv = (chats.get(email) or {}).get(wid)
    if not conf.get("bot"):
        return
    if not _bot_canal_ok(conf, canal):          # ¿este canal (web/api) tiene el bot prendido?
        if conv is not None:
            conv["bot_nota"] = ("⚠️ El bot está configurado para el canal '%s' y este mensaje entró por '%s'. "
                                "Cambialo en Config bot → ¿En qué WhatsApp responde?") % (conf.get("bot_canal") or "api", canal)
            _wa_save_chats(chats)
        return
    if not _bot_activo_ahora(conf):             # ¿estamos dentro del horario configurado?
        if conv is not None:
            conv["bot_nota"] = "⏰ Fuera del horario del bot (%s a %s hora Argentina). No responde ahora." % (
                conf.get("bot_desde") or "20:00", conf.get("bot_hasta") or "09:00")
            _wa_save_chats(chats)
        return
    if not conv:
        return
    msgs = conv.get("messages", [])
    # último mensaje ENTRANTE
    last_in = None
    for m in reversed(msgs):
        if m.get("dir") == "in":
            last_in = m; break
    if not last_in:
        return
    # ATENCIÓN HUMANA MANDA: si en ESTA conversación ya contestó una persona, el bot no se mete
    # más acá — lo resuelve ella. Es SOLO por chat: sigue respondiendo todos los demás.
    # No cuentan como "persona" ni los mensajes del propio bot ni las plantillas automáticas
    # (seguimiento de despacho, carritos), que salen solas y no son atención real.
    _mudo = False                       # hay humano atendiendo: el bot MIRA pero no habla
    _last_out = None
    for m in reversed(msgs):
        if m.get("dir") == "out":
            _last_out = m
            break
    if _last_out and _last_out.get("by") != "bot" and _last_out.get("type") != "template":
        conv["bot_humano"] = True
        conv.pop("bot_nota", None)      # lo tomó una persona → se apaga la marca de urgente
        _wa_save_chats(chats)
        # ANTES acá había un `return` seco: el bot se iba del chat para siempre. El problema es que
        # tampoco MIRABA, y si el cliente mandaba el comprobante en un chat que venía atendiendo una
        # persona, nadie lo evaluaba y la transferencia no se marcaba nunca (16/09, chat
        # "Corrientes": PDF a las 16:34, datos a las 16:38, y quedó sin marca).
        # Ahora sigue de largo SOLO si el último entrante trae un adjunto que puede ser comprobante:
        # lo evalúa, marca la transferencia y NO responde nada. Si no hay adjunto se va como antes
        # (no tiene sentido gastar una llamada al cerebro para no contestar).
        #
        # 19/09: faltaba un caso. La ETIQUETA existe para ORIENTAR AL QUE ATIENDE, o sea que en los
        # chats que toca una persona es donde MÁS falta hace — y eran justo los únicos que quedaban
        # sin etiquetar nunca, porque la etiqueta sólo se asigna cuando corre el cerebro (chat "Cano
        # Carlos": devolución del envío, $8.000 de reenvío y el cliente diciendo "abuso... estafa",
        # sin ninguna marca). Ahora, si el texto trae SEÑALES de problema, el cerebro corre igual en
        # mudo: sólo para clasificar. El filtro es local y gratis, así que se paga una llamada nada
        # más cuando puede haber algo que marcar, no en cada mensaje de cada chat atendido.
        if last_in.get("type") not in ("image", "document"):
            if not _wa_texto_con_senal(last_in.get("text") or ""):
                return
        _mudo = True

    lin_id = last_in.get("id") or ""
    if lin_id and conv.get("bot_last_in") == lin_id:
        return  # ya lo procesamos (re-entrega de Meta o segundo webhook)
    conv["bot_last_in"] = lin_id  # marco YA y guardo, para que un reintento de Meta lo vea y no duplique
    _wa_save_chats(chats)

    # Audio/voz: Claude no escucha, así que lo TRANSCRIBIMOS con Whisper (la misma función que
    # usa el bot de gastos) y seguimos como si fuera texto. Antes se cortaba acá: el cliente
    # mandaba un audio y el bot no contestaba NADA.
    if last_in.get("type") in ("audio", "voice"):
        _dat, _mim = (None, "")
        if last_in.get("canal") == "web" and last_in.get("media_id"):
            _dat, _mim = _wa_web_media_bytes(email, last_in["media_id"])
        elif last_in.get("media_id"):
            _dat, _mim = _wa_bot_media(conf, last_in["media_id"])
        _txt = _gastos_transcribir(_dat, _mim or last_in.get("mime") or "audio/ogg") if _dat else ""
        if _txt:
            last_in["text"] = _txt
            last_in["transcripto"] = True
            conv["bot_nota"] = "🎤 Audio transcripto: " + _txt[:120]
            _wa_save_chats(chats)
        else:
            # Antes esto hacia `return` y el cliente quedaba SIN NINGUNA respuesta (paso el
            # 11/09 con el audio de las 21:49). Ahora sigue igual, con un texto que le dice
            # al cerebro que hubo un audio que no se pudo escuchar: contesta y pide que lo
            # escriba, en vez de dejarlo mudo.
            conv["bot_nota"] = "🎤 Llegó un audio y no lo pude transcribir — escuchalo vos"
            last_in["text"] = ("[el cliente mando un audio que no se pudo escuchar: pedile "
                               "amablemente que lo escriba o lo mande de nuevo]")
            _wa_save_chats(chats)

    # Historial legible (últimos 40) para el cerebro.
    hist = []
    for m in msgs[-40:]:
        t = (m.get("text") or "").strip()
        if not t and m.get("type") in ("image", "video", "document", "sticker", "audio", "voice"):
            t = "[%s]" % m.get("type")
        hist.append({"dir": m.get("dir"), "texto": t})

    # Imagen del último entrante (comprobante/foto) → visión.
    # Por el canal WEB el archivo lo tiene el puente (Baileys), no la Graph API de Meta.
    # Un comprobante NO siempre llega como foto: los bancos lo mandan en PDF y WhatsApp lo
    # entrega como "document". Tambien cuenta la foto enviada "como archivo" (document con
    # mime image/*). Antes solo entraba type=="image" y todo lo demas quedaba sin mirar.
    imagenes = []
    if last_in.get("type") == "video" and last_in.get("media_id"):
        # VIDEO: se le saca un cuadro y va como imagen (si no, el bot decía "no logro verlo").
        if last_in.get("canal") == "web":
            _vd, _vm = _wa_web_media_bytes(email, last_in["media_id"])
        else:
            _vd, _vm = _wa_bot_media(conf, last_in["media_id"])
        _fd, _fm = _wa_video_a_imagen(_vd) if _vd else (None, "")
        if _fd:
            imagenes.append((_fd, _fm))
    if last_in.get("type") in ("image", "document") and last_in.get("media_id"):
        if last_in.get("canal") == "web":
            data, mime = _wa_web_media_bytes(email, last_in["media_id"])
        else:
            data, mime = _wa_bot_media(conf, last_in["media_id"])
        mime = (mime or last_in.get("mime") or "").lower()
        if data and "pdf" in mime:
            data, mime = _pdf_a_imagen(data)
        if data and (mime.startswith("image/") or last_in.get("type") == "image"):
            imagenes.append((data, mime if mime.startswith("image/") else "image/jpeg"))

    # CAMPAÑA DE RESEÑAS: si el chat esta en campaña, manda el guion y el cerebro de ventas
    # no corre. Si el guion devuelve None (llego el video, o el cliente escribio otra cosa),
    # sigue de largo al cerebro normal, que sabe lo que compro.
    if (not _mudo) and _res_activa(conv):
        _rmsg = _res_guion(conv, last_in)
        _es_video = last_in.get("type") == "video"
        # "" = el guion decide NO contestar: con la tarjeta de reseñas puesta el bot no pasa
        # al cerebro de ventas ni para preguntas de pedido ni para "quiero comprar mas". Eso
        # lo cierra una persona. (Sin tarjeta, `_res_activa` da False y ni entra acá: ahí el
        # cerebro contesta como siempre.)
        if _rmsg == "":
            conv["bot_nota"] = "⭐ Campaña reseñas — %s. Contestale vos: el bot no le manda links." % (
                conv.get("res_ojo") or "contestó algo que el guion no cubre")
            conv["etiqueta"] = conv.get("etiqueta") or "resena"
            _wa_save_chats(chats)
            return
        if _es_video:
            # El video NO lo valida el bot: acusa recibo (antes se quedaba mudo y la persona
            # grababa, mandaba y no le contestaba nadie) y lo deja marcado como PENDIENTE
            # para que lo analice Cristian, que es el que manda el cupón.
            conv["bot_nota"] = "🎥 Video de reseña — revisalo y mandale el cupón %s" % CUPON_RESENA
            conv["etiqueta"] = "resena"        # para que salga en el filtro Reseñas
        if _rmsg:
            if canal == "web":
                _ok, _mid, _err = _wa_web_send(email, conv.get("web_jid") or wid, _rmsg)
            else:
                _ok, _mid, _err = _wa_bot_send(conf, wid, _rmsg)
            if _ok:
                conv["messages"].append({"dir": "out", "text": _rmsg, "ts": _wa_now(),
                                         "type": "text", "id": _mid, "status": "sent", "by": "bot"})
                conv["updated"] = _wa_now()
                if not _es_video and not conv.get("res_ojo"):
                    conv.pop("bot_nota", None)   # con video o con marca, la nota TIENE que quedar
                elif conv.get("res_ojo"):
                    conv["bot_nota"] = "⭐ Campaña reseñas — %s. Fijate si lo cerrás vos." % conv["res_ojo"]
            else:
                conv["bot_nota"] = "⚠️ Campaña reseñas: falló el envío: " + (_err or "?")
            _wa_save_chats(chats)
            return
        if _es_video:
            _wa_save_chats(chats)
            return

    d = agente_ia.decidir(hist, imagenes=imagenes, nombre=conv.get("name", ""),
                          extra_instr=_bot_extra_instr(conf),
                          marca=_wa_marca_auto(email, conf),
                          pago={"titular": conf.get("bot_pago_titular", ""),
                                "alias": conf.get("bot_pago_alias", ""),
                                "cuit": conf.get("bot_pago_cuit", "")})
    conv["bot_motivo"] = d.get("motivo", ""); conv["bot_cat"] = d.get("categoria", "")
    # ETIQUETA automática: la elige el cerebro con los criterios de Cristian (transferencia /
    # problema envío / problema producto / reclamo MP). Reemplaza al cartel URGENTE.
    _et = (d.get("etiqueta") or "").strip().lower()
    if _et in _WA_ETIQ:
        conv["etiqueta"] = _et
    # TRANSFERENCIA CERRADA -> queda PENDIENTE DE CREAR EL PEDIDO.
    # El cerebro ya venía validando el comprobante (es_comprobante + titular_ok, que es true SOLO si
    # el destinatario del comprobante somos nosotros) pero esa señal se tiraba: nadie la leía. Acá
    # se marca el chat, y esa marca es LA que hace aparecer el botón "Cargar pedido" en /wa.
    # Se borra sola cuando el pedido se crea, así el botón desaparece de ese chat.
    _comp = d.get("comprobante") or {}
    # EXIGENCIA POSITIVA: se marca SOLO si el cerebro dijo, con todas las letras, que el papel es una
    # TRANSFERENCIA. Antes alcanzaba con "no parece checkout", y la duda marcaba: el 17/09/2026 entró
    # un "Comprobante de pago" de Mercado Pago que decia "Titulo: Compra en NoxaLab / Forma de Pago:
    # Dinero disponible en Mercado Pago" por $59.990 (Walter Rodriguez) y quedo como transferencia a
    # cargar -> el pedido ya existia por el checkout e iba a salir duplicado. Y por monto no habia
    # forma de agarrarlo: $59.990 es exactamente el precio de lista. Ahora, si el cerebro no dice
    # "transferencia", NO se marca.
    _medio = (_comp.get("medio") or "").strip().lower()
    # CANDADO de compra web: si el papel dice compra/tarjeta/débito/dinero en cuenta, NO se marca y
    # NO se piden datos: el mensaje del modelo se reemplaza por una confirmación fija.
    # REGLA DE CRISTIAN (17/09/2026): es TRANSFERENCIA solo si (1) antes le pasamos ALIAS y MONTO en el
    # chat y (2) el papel DICE transferencia. Si no se cumplen las dos, NO se piden datos y NO se marca.
    _es_comp = bool(d.get("es_comprobante"))
    _compra_web = _es_comp and _wa_comp_es_compra_web(_comp)
    _dice_transf = _es_comp and not _compra_web and _wa_comp_dice_transferencia(_comp)
    _paso_alias = _wa_chat_paso_alias(conv, conf)
    _papel = str(_comp.get("texto_literal") or "")[:120]
    _nota_post = None
    # ¿Este comprobante es de un pedido que YA EXISTE? (el cliente pregunta por su pedido y manda el
    # comprobante para que lo busquen). Si aparece en Shopify: se contesta el ESTADO, se anota el
    # pedido en el chat y NO se marca nada para cargar.
    _ped_existe = _wa_buscar_pedido_comprobante(email, _comp, conv, wid, _compra_web) if _es_comp else None
    _msg_estado = _wa_msg_estado_pedido(_ped_existe) if _ped_existe else None
    if _ped_existe:
        conv["pedido_shopify"] = str(_ped_existe.get("order_number") or _ped_existe.get("name") or "").replace("#", "")
        if conv.get("etiqueta") == "transferencia": conv.pop("etiqueta", None)   # ya cargado: se saca la etiqueta
        conv.pop("pend_pedido", None)
        conv["bot_motivo"] = ("Comprobante de un pedido que YA existe: #%s (%s). Papel: %s"
                              % (conv["pedido_shopify"], _ped_existe.get("fulfillment_status") or "sin despachar", _papel))
        if _msg_estado:
            d["responder"] = True
            d["escalar"] = False
            d["mensaje"] = _msg_estado
        else:
            d["responder"] = True
            d["escalar"] = False
            d["mensaje"] = "Recibí el comprobante 🙌 Lo está mirando un compañero del equipo y te confirmamos por acá."
            _nota_post = "⚠️ El bot lo derivó a vos: el pedido #%s figura CANCELADO" % conv["pedido_shopify"]
    elif _compra_web and _wa_comp_es_nuestro(_comp, email, conf):
        d["responder"] = True
        d["escalar"] = False
        d["mensaje"] = _wa_msg_compra_web(conv.get("name"), wid)
        conv["bot_motivo"] = ("Compra por la WEB (no transferencia): no se piden datos ni se carga pedido. "
                              "Papel: " + _papel)
    elif _es_comp and not (_dice_transf and _paso_alias):
        # Comprobante que NO cumple la regla: o el papel no dice transferencia, o nunca le pasamos el
        # alias y el monto. No se le piden datos ni se confirma nada: lo mira una persona.
        _por = ("el papel no dice transferencia" if not _dice_transf
                else "en el chat nunca le pasamos el alias y el monto")
        d["responder"] = True
        d["escalar"] = False
        d["mensaje"] = "Recibí el comprobante 🙌 Lo está chequeando un compañero del equipo y te confirmamos por acá."
        _pago = "pagó $%s el %s (op. %s)" % (_comp.get("monto") or "?", _comp.get("fecha") or "?",
                                              _comp.get("operacion") or "?")
        conv["bot_motivo"] = ("Comprobante sin confirmar: " + _por + ". No encontré un pedido en Shopify para "
                              "ese pago: " + _pago + ". Papel: " + _papel)
        _nota_post = ("⚠️ El bot lo derivó a vos: " + _pago + " y NO aparece pedido en Shopify ("
                      + _por + ")")
    if _es_comp and not conv.get("pend_pedido") and not conv.get("pedido_shopify"):
        # POR QUÉ no se marcó este comprobante. Queda guardado aparte porque bot_motivo lo pisa el
        # mensaje siguiente, y sin esto no hay forma de saber por qué una transferencia no se marcó
        # (Cristian, 18/09/2026: "algunas transferencias no las marca").
        conv["comp_nomarca"] = {
            "ts": _wa_now(), "monto": str(_comp.get("monto") or ""),
            "medio": _medio, "papel": _papel[:80],
            "titular_ok": bool(_comp.get("titular_ok")),
            "dice_transferencia": bool(_dice_transf),
            "le_pasamos_alias": bool(_paso_alias),
            "parece_compra_web": bool(_compra_web),
            "pedido_ya_existe": str((_ped_existe or {}).get("order_number") or ""),
        }
    if (_es_comp and _comp.get("titular_ok") and _dice_transf and _paso_alias
            and not _compra_web and _medio != "tarjeta"
            and not conv.get("pedido_shopify")
            and not _wa_es_checkout(_comp.get("monto"), _comp.get("medio"))):
        conv["etiqueta"] = "transferencia"      # hay que cargarla -> queda etiquetada sola
        conv["pend_pedido"] = {"monto": str(_comp.get("monto") or ""),
                               "fecha": str(_comp.get("fecha") or ""),
                               "operacion": str(_comp.get("operacion") or ""),
                               # CON QUE pago: 'transferencia' | 'tarjeta' | 'otro'. Se guarda para
                               # que la lista de chats pueda revalidarlo despues (ver /wa-chats).
                               "medio": str(_comp.get("medio") or ""),
                               "ts": _wa_now()}

    # ANTI-DOBLE RESPUESTA: si el cliente manda 2 cosas seguidas (foto + texto), entran 2 webhooks
    # y cada uno llama al cerebro por separado -> contestaba DOS VECES casi lo mismo (18/09/2026,
    # chat "Lic. Hector Carola": imagen y texto a las 19:45 -> dos mensajes con los mismos precios).
    # Antes de mandar se relee el chat del disco: si YA hay respuesta del bot posterior a este
    # entrante, o si entró un mensaje MÁS NUEVO (lo contesta esa otra llamada, con más contexto),
    # este envío se cancela.
    _dup = False
    try:
        _ts_in = last_in.get("ts") or ""
        _m2 = ((_wa_chats_all().get(email) or {}).get(wid) or {}).get("messages") or []
        for _x in reversed(_m2):
            _t = _x.get("ts") or ""
            if _t <= _ts_in:
                break
            if _x.get("dir") == "out" and _x.get("by") == "bot":
                _dup = True; break          # otra llamada ya contestó
            if _x.get("dir") == "in":
                _dup = True; break          # llegó algo más nuevo: contesta la otra llamada
    except Exception:
        _dup = False
    if _dup:
        _wa_save_chats(chats)
        return
    if (not _mudo) and d.get("responder") and (d.get("mensaje") or "").strip():
        msg = d["mensaje"].strip()
        if conf.get("bot_mode", "auto") == "draft":
            conv["bot_draft"] = msg  # deja el borrador listo para que el humano lo mande
            conv["bot_nota"] = "📝 Borrador del bot listo"
        else:
            if canal == "web":
                # responder al MISMO jid que entró (ej "...@lid") → 1 solo chat por persona (sin duplicar)
                ok, mid, err = _wa_web_send(email, conv.get("web_jid") or wid, msg)
            else:
                ok, mid, err = _wa_bot_send(conf, wid, msg)
            if ok:
                conv["messages"].append({"dir": "out", "text": msg, "ts": _wa_now(),
                                         "type": "text", "id": mid, "status": "sent", "by": "bot"})
                conv["updated"] = _wa_now(); conv.pop("bot_nota", None)
            else:
                conv["bot_nota"] = "⚠️ El bot quiso responder pero falló el envío: " + (err or "?")
    elif (not _mudo) and d.get("escalar"):
        conv["bot_nota"] = "⚠️ El bot lo derivó a vos" + (": " + d["motivo"] if d.get("motivo") else "")
    # Contestó Y derivó (ej: un RECLAMO, que ahora pide nombre y número de pedido): el envío OK borra
    # bot_nota, y sin esto el chat dejaba de salir en rojo para la persona que tiene que resolverlo.
    if (not _nota_post and not _mudo and d.get("escalar") and d.get("responder")
            and (d.get("mensaje") or "").strip()):
        _nota_post = "⚠️ El bot lo derivó a vos" + (": " + d["motivo"] if d.get("motivo") else "")
    if _nota_post:                      # va DESPUÉS del envío: el envío OK borra bot_nota
        conv["bot_nota"] = _nota_post
    _wa_save_chats(chats)


_WA_ETIQ = {                      # etiquetas de color por chat (las pone el bot o atención)
    "transferencia":    {"txt": "TRANSFERENCIA",    "col": "#0b5d43"},
    "problema_envio":   {"txt": "PROBLEMA ENVÍO",   "col": "#b06000"},
    "problema_producto": {"txt": "PROBLEMA PRODUCTO", "col": "#6b3fa0"},
    "reclamo_mp":       {"txt": "RECLAMO MP",       "col": "#b3261e"},
    "resena":           {"txt": "RESEÑA",           "col": "#1f6feb"},
}


@app.post("/wa-etiqueta")
def wa_etiqueta():
    """Asigna (o saca) la etiqueta de color de un chat. La usa atención desde el botón
    'Etiqueta' y también el bot cuando detecta el caso. Sirve para filtrar la lista."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    wid = (request.form.get("wa_id") or "").strip()
    et = (request.form.get("etiqueta") or "").strip().lower()
    if not wid:
        return jsonify({"ok": False, "msg": "falta el chat"})
    if et and et not in _WA_ETIQ:
        return jsonify({"ok": False, "msg": "etiqueta desconocida"})
    chats = _wa_chats_all()
    conv = (chats.get(email) or {}).get(wid)
    if conv is None:
        return jsonify({"ok": False, "msg": "no encontré ese chat"})
    if et:
        conv["etiqueta"] = et
    else:
        conv.pop("etiqueta", None)          # sin etiqueta = se saca
    _wa_save_chats(chats)
    return jsonify({"ok": True, "etiqueta": et})


@app.post("/wa-resolver")
def wa_resolver():
    """Saca el URGENTE / DERIVADO A ATENCION de un chat: lo aprieta el que lo resolvio.
    Antes el rojo solo se apagaba si atencion CONTESTABA algo; si el tema se resolvia por
    telefono, o no hacia falta responder, el chat quedaba marcado para siempre."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    wid = (request.form.get("wa_id") or "").strip()
    if not wid:
        return jsonify({"ok": False, "msg": "falta el chat"})
    chats = _wa_chats_all()
    conv = (chats.get(email) or {}).get(wid)
    if conv is None:
        return jsonify({"ok": False, "msg": "no encontré ese chat"})
    # OPCIONAL: 'pedido' = numero de un pedido que YA EXISTE en Shopify. Sirve para apagar un
    # "TRANSFERENCIA A CARGAR" que quedo mal puesto, SIN crear nada: se anota el pedido real y se
    # borra la marca pendiente, asi ese chat no se puede cargar dos veces nunca mas.
    # Por que hace falta: /wa-pedido-crear era el UNICO que limpiaba pend_pedido, y crea una orden
    # nueva -> para un chat que ya tiene su pedido hecho por el checkout, usarlo DUPLICA la venta.
    # Caso real 17/09/2026: Walter Rodriguez pago por la web ($59.990, pedido #4884 de las 07:57) y
    # su chat quedo marcado como transferencia a cargar; por monto no habia forma de detectarlo
    # (es el precio de lista exacto) y la marca vieja no tiene el campo 'medio'.
    _ped = (request.form.get("pedido") or "").strip().lstrip("#")
    if _ped:
        conv["pedido_shopify"] = _ped
        if conv.get("etiqueta") == "transferencia": conv.pop("etiqueta", None)
        conv.pop("pend_pedido", None)
        _wa_save_chats(chats)
        return jsonify({"ok": True, "pedido": _ped})
    # Mismo camino que cuando contesta una persona (ver _wa_bot_run): queda tomado por humano y
    # se limpia lo que dispara el rojo en el calculo de _urg de /wa-chats.
    conv["bot_humano"] = True
    conv.pop("bot_nota", None)
    conv.pop("bot_motivo", None)
    conv.pop("bot_cat", None)
    _wa_save_chats(chats)
    return jsonify({"ok": True})


# ---------------- Transferencia cerrada por WhatsApp -> pedido REAL en Shopify ----------------
# Antes, cuando se cerraba una venta por transferencia, el pedido NO existia en ningun lado: el bot
# juntaba nombre/DNI/direccion, decia "queda en despacho" y todo moria en el chat. Estos dos
# endpoints lo convierten en una orden de Shopify con la MISMA forma que lee Despachos
# (ver el armado de _despachos_shopify), porque si un solo campo va en otro lugar el pedido
# aparece incompleto o mal clasificado:
#   - DNI            -> note_attributes (asi lo busca _dni_de)
#   - sucursal/domic -> title de shipping_lines (asi lo clasifica _txt_es_sucursal: palabra entera)
#   - pagado         -> transactions kind=sale; si no queda "paid", Despachos lo IGNORA
# Nada se crea solo: el bot no toca esto. El de atencion revisa los datos y aprieta el boton.
_WA_PROD_NAD = 9490859393212          # NoxaLab(R) Complejo de NAD+ 7 en 1 en Polvo (el que usan las ventas reales)
_WA_PROD_CAPS = 9526897541308         # NoxaLab(R) Oxido Nitrico — el que se regala con los packs grandes
_WA_PRECIO_PACK = {1: 49990.0, 2: 59990.0, 3: 74990.0}   # verificado contra los pedidos del dia


def _wa_monto_num(monto):
    """'$ 56.990,50' / '56990.5' / '56.990' -> 56990.0 (pesos enteros). None si no se entiende.
    Ojo con los centavos: vienen con coma o con punto segun quien escriba el comprobante."""
    d = "".join(ch for ch in str(monto or "") if ch.isdigit() or ch in ".,")
    if not d:
        return None
    m = _re_and.search(r"[.,](\d{1,2})$", d)      # eso de atras son centavos, no miles
    if m:
        d = d[:m.start()]
    ent = "".join(ch for ch in d if ch.isdigit())
    try:
        return float(ent) if ent else None
    except Exception:
        return None


_WA_TXT_COMPRA = (r"compra\s+en\b|comprobante\s+de\s+pago|compra\s+con\s+tarjeta|"
                  r"tarjeta\s+de\s+(debito|credito)|tarj\.?\s*nro|dinero\s+disponible|"
                  r"dinero\s+en\s+cuenta|merpago|pago\s+con\s+saldo|saldo\s+en\s+mercado\s+pago")


def _wa_sin_tildes(s):
    import unicodedata
    return unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode().lower()


# Señales de que un mensaje PUEDE merecer etiqueta (problema envío / producto / reclamo MP).
# Es un filtro LOCAL y gratis: decide si vale la pena gastar una llamada al cerebro en un chat que
# ya está atendiendo una persona. No etiqueta nada por sí solo — eso lo sigue decidiendo el cerebro
# con los criterios de Cristian. Va ancho a propósito: perder una etiqueta cuesta más que una
# llamada de más, y el que atiende se queda sin la marca que necesita para ubicarse.
_WA_SENAL = re.compile(
    r"estaf|abuso|fraude|choreo|robo|verguenza|denunci|"
    r"reclam|reembols|devoluc|devuelv|devolv|plata de vuelta|mi dinero|"
    r"no me lleg|nunca lleg|no lleg|todavia no|sigue sin lleg|no recib|"
    r"demora|tarda|atras|perdid|extravi|"
    r"roto|rota|abiert|danad|golpead|vencid|faltab|falta un|falta el|me falta|menos de lo|"
    r"no es lo que|no era lo que|equivocad|otra direccion|mal la direccion|"
    r"reenvi|re-envi|volvio a|devolvieron|lo devolv|no lo retir|no fui a retir|"
    r"mercado pago|mercadopago|contracargo|"
    r"cancel|anul|no quiero mas|quiero que me devuelvan")


def _wa_texto_con_senal(txt) -> bool:
    """¿El texto tiene alguna señal de problema que justifique clasificarlo?"""
    return bool(_WA_SENAL.search(_wa_sin_tildes(txt)))


def _wa_comp_es_compra_web(comp) -> bool:
    """¿Este comprobante es de una COMPRA POR LA WEB (tarjeta, débito de Mercado Pago, dinero en
    cuenta) y NO de una transferencia? Decide el CÓDIGO mirando el texto que el modelo copió
    TEXTUAL del papel, no la clasificación del modelo (que es lo que falló: Carrizo 16/09 con
    "COMPRA CON TARJETA DE DEBITO", Walter 17/09 con "Compra en NoxaLab / Dinero disponible en
    Mercado Pago" — a los dos les pidió los datos y los marcó para cargar un pedido que ya existía).
    Orden: tarjeta manda; si dice transferencia es transferencia; si dice compra/pago con saldo es
    compra; si el papel no dice nada claro, recién ahí se usa lo que clasificó el modelo."""
    c = comp or {}
    txt = _wa_sin_tildes(" ".join(str(c.get(k) or "") for k in ("texto_literal", "destinatario")))
    medio = (c.get("medio") or "").strip().lower()
    if _re_and.search(r"compra\s+con\s+tarjeta|tarj\.?\s*nro|tarjeta\s+de\s+(debito|credito)", txt):
        return True
    if "transfer" in txt:
        return False
    if _re_and.search(_WA_TXT_COMPRA, txt):
        return True
    return medio == "tarjeta"


def _wa_video_a_imagen(datos):
    """Saca un CUADRO del video para que el cerebro lo PUEDA VER. WhatsApp entrega videos y el bot
    contestaba 'me llegó el video pero no logro verlo' (19/09/2026, Carlos: mostraba un frasco de
    OTRA marca y el bot lo tomó como reclamo nuestro). Usa el ffmpeg que ya viene con el paquete."""
    import subprocess, tempfile, os as _o
    exe = _ads_ffmpeg()
    if not exe or not datos:
        return None, ""
    tin = tout = None
    try:
        with tempfile.NamedTemporaryFile(suffix=".mp4", delete=False) as f:
            f.write(datos); tin = f.name
        tout = tin + ".jpg"
        subprocess.run([exe, "-y", "-loglevel", "error", "-ss", "1", "-i", tin,
                        "-frames:v", "1", "-vf", "scale=720:-1", tout],
                       timeout=25, capture_output=True)
        if _o.path.exists(tout) and _o.path.getsize(tout) > 500:
            with open(tout, "rb") as f:
                return f.read(), "image/jpeg"
    except Exception:
        pass
    finally:
        for p in (tin, tout):
            try:
                if p:
                    _o.remove(p)
            except Exception:
                pass
    return None, ""


def _wa_comp_dice_transferencia(comp) -> bool:
    """¿El PAPEL dice transferencia? Regla de Cristian (17/09/2026): el comprobante tiene que decir
    TRANSFERENCIA, no pago ni compra. Cuenta 'transferencia/transferiste' y 'enviaste dinero / envío
    de dinero' (así titulan las transferencias Mercado Pago y Ualá). Si hay señales de tarjeta, NO."""
    c = comp or {}
    txt = _wa_sin_tildes(" ".join(str(c.get(k) or "") for k in ("texto_literal", "destinatario")))
    if _re_and.search(r"compra\s+con\s+tarjeta|tarj\.?\s*nro|tarjeta\s+de\s+(debito|credito)", txt):
        return False
    return bool(_re_and.search(r"transfer|enviaste\s+dinero|envio\s+de\s+dinero", txt))


def _wa_chat_paso_alias(conv, conf) -> bool:
    """¿ANTES del comprobante le pasamos el ALIAS y el MONTO en el chat? Regla de Cristian: la
    transferencia se toma una vez que le pasamos alias y monto. Mira los mensajes salientes
    (bot o persona) anteriores al último entrante. El alias tiene que aparecer como palabra suelta
    (así 'noxalaboficial.com' del link de la web NO cuenta como haber pasado el alias)."""
    ali = _wa_sin_tildes(conf.get("bot_pago_alias")).strip()
    tit = _wa_sin_tildes(conf.get("bot_pago_titular")).strip()
    msgs = conv.get("messages") or []
    ult_in = max([i for i, m in enumerate(msgs) if m.get("dir") == "in"] or [len(msgs)])
    vio_alias = vio_monto = False
    for m in msgs[:ult_in]:
        if m.get("dir") != "out":
            continue
        t = _wa_sin_tildes(m.get("text"))
        # "alias" tiene que estar pegado: la MARCA se llama igual que el alias ("pago a NOXALAB"),
        # y sin esto cualquier mención de la tienda contaba como haber pasado el alias.
        if ali and len(ali) >= 3 and _re_and.search(
                r"alias.{0,20}?(?<![a-z0-9])" + _re_and.escape(ali) + r"(?![a-z0-9])", t):
            vio_alias = True
        elif tit and len(tit) >= 6 and tit in t:
            vio_alias = True
        if _re_and.search(r"\$\s?\d", t):
            vio_monto = True
    return vio_alias and vio_monto


_WA_MESES = {"enero": 1, "febrero": 2, "marzo": 3, "abril": 4, "mayo": 5, "junio": 6, "julio": 7,
             "agosto": 8, "septiembre": 9, "setiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12}


def _wa_comp_fecha(comp):
    """Fecha y hora del comprobante (hora Argentina) -> datetime UTC naive, o None. Entiende
    '17/09/2026 07:57', '16/09/26 - 20:12 hs', 'Jueves, 17 de septiembre 2026, 07:57:12'."""
    import datetime as _dtm
    c = comp or {}
    t = _wa_sin_tildes(" ".join(str(c.get(k) or "") for k in ("fecha", "texto_literal")))
    d = mo = y = None
    m = _re_and.search(r"(\d{1,2})\s*[/.-]\s*(\d{1,2})\s*[/.-]\s*(\d{2,4})", t)
    if m:
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
    else:
        m = _re_and.search(r"(\d{1,2})\s*(?:de\s+|/)?\s*(" + "|".join(_WA_MESES) + r")\s*(?:de\s+|/)?\s*(\d{4})?", t)
        if m:
            d, mo = int(m.group(1)), _WA_MESES[m.group(2)]
            y = int(m.group(3)) if m.group(3) else (_dtm.datetime.utcnow() - _dtm.timedelta(hours=3)).year
    if not d:
        return None
    if y < 100:
        y += 2000
    hh = mm = 12
    h = _re_and.search(r"(\d{1,2}):(\d{2})", t)
    if h:
        hh, mm = int(h.group(1)), int(h.group(2))
    try:
        return _dtm.datetime(y, mo, d, hh, mm) + _dtm.timedelta(hours=3)      # AR -> UTC
    except Exception:
        return None


def _wa_buscar_pedido_comprobante(email, comp, conv, wid, compra_web=False):
    """Busca en Shopify el pedido al que corresponde un comprobante, para contestar el ESTADO en vez
    de tratarlo como una venta nueva. Pedido de Cristian (17/09/2026): el cliente pregunta por su
    pedido, le piden el comprobante, lo manda... y quedaba marcado 'TRANSFERENCIA A CARGAR'.
    Para no contestarle el pedido de OTRO con el mismo monto, exige monto Y (teléfono o nombre dicho
    en el chat). Una compra web también vale con monto + creada a <=15 min del pago.
    Devuelve el pedido (dict de Shopify) o None. Nunca lanza."""
    import datetime as _dtm
    try:
        tk = _shop_tokens().get(email) or {}
        if not tk.get("access_token") or not tk.get("shop"):
            return None
        monto = _wa_monto_num((comp or {}).get("monto"))
        if not monto:
            return None
        T = _wa_comp_fecha(comp)
        ahora = _dtm.datetime.utcnow()
        desde = (T - _dtm.timedelta(hours=2)) if T else (ahora - _dtm.timedelta(days=4))
        hasta = (T + _dtm.timedelta(days=2)) if T else ahora
        r = requests.get("https://%s/admin/api/2026-07/orders.json" % tk["shop"],
                         headers={"X-Shopify-Access-Token": tk["access_token"]},
                         params={"status": "any", "limit": 250,
                                 "created_at_min": desde.strftime("%Y-%m-%dT%H:%M:%SZ"),
                                 "created_at_max": hasta.strftime("%Y-%m-%dT%H:%M:%SZ"),
                                 "fields": "id,name,order_number,created_at,total_price,financial_status,"
                                           "fulfillment_status,cancelled_at,customer,shipping_address,"
                                           "billing_address,phone,fulfillments,note_attributes"},
                         timeout=15)
        ords = (r.json() or {}).get("orders") or []
    except Exception:
        return None
    tel = _solo_dig(wid)[-10:]
    chat_in = _wa_sin_tildes(" ".join([str(conv.get("name") or "")] + [
        str(m.get("text") or "") for m in (conv.get("messages") or []) if m.get("dir") == "in"]))
    mejor, mejor_k = None, None
    for o in ords:
        try:
            tot = float(o.get("total_price") or 0)
        except Exception:
            continue
        if abs(tot - monto) > 2:
            continue
        tels = [(o.get("phone") or "")] + [((o.get(k) or {}).get("phone") or "") for k in
                                           ("shipping_address", "billing_address", "customer")]
        tels += [str(a.get("value") or "") for a in (o.get("note_attributes") or [])]
        tel_ok = bool(tel) and len(tel) >= 8 and any(_solo_dig(x).endswith(tel[-8:]) for x in tels if x)
        cu = o.get("customer") or {}
        sa = o.get("shipping_address") or {}
        nom = _wa_sin_tildes(" ".join([str(cu.get("first_name") or ""), str(cu.get("last_name") or ""),
                                       str(sa.get("name") or "")]))
        toks = {w for w in _re_and.findall(r"[a-z]{3,}", nom)}
        nom_ok = len([w for w in toks if _re_and.search(r"\b" + w + r"\b", chat_in)]) >= 2
        cerca = False
        if T:
            try:
                oc = _dtm.datetime.strptime(str(o.get("created_at"))[:19], "%Y-%m-%dT%H:%M:%S")
                off = str(o.get("created_at"))[19:25]
                if off and off[0] in "+-":
                    sg = 1 if off[0] == "+" else -1
                    oc -= sg * _dtm.timedelta(hours=int(off[1:3]), minutes=int(off[4:6]))
                cerca = abs((oc - T).total_seconds()) <= 15 * 60
            except Exception:
                cerca = False
        if not (tel_ok or nom_ok or (compra_web and cerca)):
            continue
        k = (tel_ok, nom_ok, cerca)
        if mejor is None or k > mejor_k:
            mejor, mejor_k = o, k
    return mejor


def _wa_msg_estado_pedido(o):
    """Respuesta con el ESTADO real del pedido encontrado."""
    num = str(o.get("order_number") or o.get("name") or "").replace("#", "")
    trk = next((f.get("tracking_number") for f in (o.get("fulfillments") or []) if f.get("tracking_number")), "")
    if o.get("cancelled_at"):
        return None
    if trk:
        return ("Ya lo ubiqué 🙌 Es tu pedido #%s y ya salió por Andreani. Lo seguís acá: "
                "https://www.andreani.com/envio/%s" % (num, trk))
    return ("Ya lo ubiqué 🙌 Es tu pedido #%s: está pago y en preparación para el despacho. Apenas "
            "salga te llega el seguimiento de Andreani por mail." % num)


def _wa_comp_es_nuestro(comp, email, conf) -> bool:
    """¿La compra es en NUESTRA tienda? (marca, alias o titular aparecen en el papel)."""
    c = comp or {}
    txt = _wa_sin_tildes(" ".join(str(c.get(k) or "") for k in ("texto_literal", "destinatario")))
    claves = []
    for v in (_wa_marca_auto(email, conf), conf.get("bot_pago_alias"), conf.get("bot_pago_titular")):
        v = _wa_sin_tildes(v).strip()
        if len(v) >= 4:
            claves.append(v)
    return any(k in txt or k.replace(" ", "") in txt.replace(" ", "") for k in claves)


def _wa_msg_compra_web(nombre, wid):
    """Respuesta FIJA cuando mandan el comprobante de una compra web: NO se piden datos (ya los
    cargó al pagar en la página) y no se le dice que 'el monto no coincide'."""
    n = (str(nombre or "").strip().split() or [""])[0]
    n = (", " + n.capitalize()) if n.isalpha() and len(n) >= 2 else ""
    ops = [
        "¡Listo%s! 🙌 Ese es el comprobante de tu compra por la web, así que el pedido ya quedó cargado "
        "con los datos que pusiste al pagar. No hace falta que me pases nada más: apenas se despache "
        "te llega el seguimiento por mail.",
        "Perfecto%s 👌 Vi el comprobante: es de la compra en la página, así que ya está todo tomado con "
        "los datos que cargaste ahí. No necesito nada más; el seguimiento de Andreani te llega por "
        "correo cuando sale.",
    ]
    return ops[sum(map(ord, str(wid or ""))) % len(ops)] % n


def _wa_es_checkout(monto, medio="") -> bool:
    """¿El comprobante es una COMPRA POR LA WEB y no una transferencia cerrada por WhatsApp?
    Importa mucho: esa compra YA tiene su pedido creado por Shopify, así que marcarla como
    "pendiente de cargar" termina en un pedido DUPLICADO y pagado en la tienda.

    Se mira en DOS pasos, y el primero manda:

    1) EL MEDIO DE PAGO (lo lee el cerebro de la imagen). Si el ticket dice "COMPRA CON TARJETA
       DE DEBITO/CREDITO", "tarj nro." o el comercio "Merpago*", es checkout SEGURO. Esta es la
       señal confiable: por monto NO alcanza, porque una compra web a sucursal (envío gratis y
       sin descuento) sale EXACTAMENTE lo mismo que una transferencia.

    2) EL MONTO, como segunda linea de defensa, solo en las combinaciones INEQUIVOCAS:
         - con BOT5 (5% OFF), a sucursal:   p*0.95
         - con BOT5 y envio a domicilio:    p*0.95 + 1990
         - a precio de lista + domicilio:   p + 1990   (la transferencia NUNCA paga envio)
       El precio de lista SOLO (p) queda AFUERA a proposito: eso es justo lo que paga una
       transferencia, y meterlo mataria todas las ventas cerradas por WhatsApp.

    (17/09/2026 — se escapo Carrizo: pago $58.980,50 = $56.990,50 + $1.990 de envio y el chat
    quedo marcado "TRANSFERENCIA A CARGAR" teniendo ya el pedido #4835 hecho por el checkout;
    su ticket decia "COMPRA CON TARJETA DE DEBITO / Merpago*noxalab". Antes aca solo se miraba
    p*0.95 sin envio.)"""
    if (medio or "").strip().lower() == "tarjeta":
        return True
    v = _wa_monto_num(monto)
    if not v:
        return False
    _ENV = 1990                                   # envio a domicilio por la web
    cand = []
    for p in _WA_PRECIO_PACK.values():
        _d5 = round(p * 0.95)
        cand += [_d5, _d5 + _ENV, p + _ENV]
    return any(abs(v - c) <= 2 for c in cand)

_WA_PED_SIS = (
    "Leés una conversación de WhatsApp donde YA se cerró una venta por transferencia y extraés los "
    "datos del pedido. Respondés UNICAMENTE un JSON válido, sin texto alrededor y sin markdown.\n"
    "Campos exactos:\n"
    '{"nombre":"","dni":"","tel":"","email":"","calle":"","numero":"","extra":"","localidad":"",'
    '"provincia":"","cp":"","tipo":"domicilio","sucursal":"","potes":0,"total":null,"faltan":[]}\n'
    "Reglas:\n"
    "- potes: cantidad de potes acordada (normalmente 1, 2 o 3).\n"
    "- tipo: 'sucursal' si acordaron retirar por sucursal o punto Andreani; 'domicilio' si va a la "
    "casa o al trabajo.\n"
    "- sucursal: solo si tipo es sucursal, el nombre del punto tal cual lo dijeron.\n"
    "- total: el monto que transfirió, si figura en el chat; si no, null.\n"
    "- dni y tel: solo dígitos (el teléfono sin +54 ni el 9).\n"
    "- nombre: SIEMPRE el del CLIENTE. NUNCA el destinatario ni el titular que figura en el "
    "comprobante: ese somos nosotros (pasó: puso 'Leonel Baran', que es nuestro titular).\n"
    "- Si un dato no lo dio el cliente sino que lo dedujimos o completamos nosotros en el chat "
    "(típico: el código postal), igual ponelo, pero nombralo en 'faltan' para que se revise.\n"
    "- Si el comprobante dice 'Compra en' / es un pago hecho por la WEB y no una transferencia, "
    "poné 'compra_web' en faltan: ese pedido ya existe y no hay que cargarlo de nuevo.\n"
    "- faltan: lista de los campos que NO se dijeron en el chat.\n"
    "NO inventes ningún dato: lo que no esté en la conversación va vacío y se nombra en 'faltan'."
)


@app.post("/wa-pedido-extraer")
def wa_pedido_extraer():
    """Lee el chat y devuelve los datos del pedido para que el humano los revise. No crea nada."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    wid = (request.form.get("wa_id") or "").strip()
    if not wid:
        return jsonify({"ok": False, "msg": "falta el chat"})
    conv = ((_wa_chats_all().get(email) or {}).get(wid) or {})
    msgs = conv.get("messages") or []
    if not msgs:
        return jsonify({"ok": False, "msg": "el chat está vacío"})
    hist = []
    for m in msgs[-60:]:
        t = (m.get("text") or "").strip() or ("[%s]" % (m.get("type") or "adjunto"))
        hist.append(("Cliente: " if m.get("dir") == "in" else "Nosotros: ") + t)
    try:
        import agente_ia
        raw = agente_ia.chat([{"role": "user", "content": "\n".join(hist)}], _WA_PED_SIS, max_tokens=900)
    except Exception as e:
        return jsonify({"ok": False, "msg": "no se pudo leer la conversación: " + str(e)[:90]})
    txt = (raw or "").strip()
    i, j = txt.find("{"), txt.rfind("}")
    if i < 0 or j <= i:
        return jsonify({"ok": False, "msg": "no pude sacar los datos del chat, cargalo a mano"})
    try:
        d = _json.loads(txt[i:j + 1])
    except Exception:
        return jsonify({"ok": False, "msg": "la lectura del chat no vino en formato válido"})
    try:
        d["potes"] = int(d.get("potes") or 0)
    except Exception:
        d["potes"] = 0
    # El monto REAL que el bot leyó del comprobante manda sobre la tabla de precios: si transfirió
    # con descuento o de más, el pedido tiene que salir por lo que pagó de verdad.
    _pp = conv.get("pend_pedido") or {}
    if not d.get("total") and _pp.get("monto"):
        _s = "".join(ch for ch in str(_pp["monto"]).split(",")[0] if ch.isdigit())
        if _s:
            d["total"] = float(_s)
    if not d.get("total"):
        d["total"] = _WA_PRECIO_PACK.get(d["potes"]) or 0
    d["comp_fecha"] = _pp.get("fecha", "")
    d["comp_oper"] = _pp.get("operacion", "")
    d["nombre"] = (d.get("nombre") or conv.get("name") or "").strip()
    d["dni"] = _solo_dig(d.get("dni"))
    d["tel"] = _solo_dig(d.get("tel")) or _solo_dig(wid)
    d["caps"] = 0          # el Oxido Nitrico de regalo NO se adivina del chat: lo pone el que carga
    d["ya_cargado"] = conv.get("pedido_shopify", "")
    return jsonify({"ok": True, "datos": d})


@app.post("/wa-pedido-crear")
def wa_pedido_crear():
    """Crea la orden en Shopify, ya pagada por transferencia y con el envío sin cargo."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    tk = _shop_tokens().get(email)
    if not tk or not tk.get("access_token") or not tk.get("shop"):
        return jsonify({"ok": False, "msg": "Shopify no está conectado en Integraciones"})
    f = request.form
    nombre = (f.get("nombre") or "").strip()
    if not nombre:
        return jsonify({"ok": False, "msg": "falta el nombre del cliente"})
    try:
        potes = int(float(f.get("potes") or 0))
    except Exception:
        potes = 0
    if potes < 1:
        return jsonify({"ok": False, "msg": "falta la cantidad de potes"})
    try:
        total = float(str(f.get("total") or "0").replace(".", "").replace(",", ".")) if "," in str(f.get("total") or "") \
            else float(f.get("total") or 0)
    except Exception:
        total = 0.0
    if total <= 0:
        total = _WA_PRECIO_PACK.get(potes) or 0.0
    if total <= 0:
        return jsonify({"ok": False, "msg": "falta el total del pedido"})
    tipo = "sucursal" if (f.get("tipo") or "") == "sucursal" else "domicilio"
    shop, token = tk["shop"], tk["access_token"]
    H = {"X-Shopify-Access-Token": token, "Content-Type": "application/json"}
    # La variante se resuelve EN VIVO: el id cambia si tocan el producto, y hardcodearlo se rompe solo.
    try:
        r = requests.get("https://%s/admin/api/2026-07/products/%s.json" % (shop, _WA_PROD_NAD),
                         headers=H, params={"fields": "id,title,variants"}, timeout=25)
        vid = (((r.json().get("product") or {}).get("variants") or [{}])[0]).get("id")
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude leer el producto en Shopify: " + str(e)[:90]})
    if not vid:
        return jsonify({"ok": False, "msg": "no encontré la variante del producto en Shopify"})
    # OXIDO NITRICO de regalo. Si es 0 (lo normal) no cambia NADA respecto de antes.
    try:
        caps = int(float(f.get("caps") or 0))
    except Exception:
        caps = 0
    vid_caps = None
    if caps > 0:
        # Se resuelve ANTES de crear la orden: si falla, no queremos media orden cargada.
        try:
            rc = requests.get("https://%s/admin/api/2026-07/products/%s.json" % (shop, _WA_PROD_CAPS),
                              headers=H, params={"fields": "id,title,variants"}, timeout=25)
            vid_caps = (((rc.json().get("product") or {}).get("variants") or [{}])[0]).get("id")
        except Exception as e:
            return jsonify({"ok": False, "msg": "no pude leer el Oxido Nitrico en Shopify: " + str(e)[:90]})
        if not vid_caps:
            return jsonify({"ok": False, "msg": "no encontré la variante del Oxido Nitrico en Shopify"})
    # OJO: este título es lo que después decide sucursal vs domicilio (_txt_es_sucursal busca la
    # PALABRA ENTERA). Si dice "domicilio" nunca se clasifica como sucursal, y viceversa.
    if tipo == "sucursal":
        suc = (f.get("sucursal") or "").strip()
        env_tit = "Envío a sucursal Andreani" + ((" — " + suc) if suc else "")
    else:
        env_tit = "Envío a domicilio (transferencia, sin cargo)"
    calle = " ".join(p for p in [(f.get("calle") or "").strip(), (f.get("numero") or "").strip()] if p)
    # OJO: en esta tienda el DNI viaja en el campo "Empresa" (company) del checkout, igual que en
    # los pedidos de la web. Va ahi Y en note_attributes: _dni_de mira los dos, y el export de
    # Andreani necesita encontrarlo si o si (sin DNI no se retira en sucursal).
    addr = {"name": nombre, "address1": calle, "address2": (f.get("extra") or "").strip(),
            "company": _solo_dig(f.get("dni")),
            "city": (f.get("localidad") or "").strip(), "province": (f.get("provincia") or "").strip(),
            "zip": (f.get("cp") or "").strip(), "country": "Argentina",
            "phone": _solo_dig(f.get("tel"))}
    payload = {"order": {
        "email": (f.get("email") or "").strip(),
        "currency": "ARS",
        "line_items": ([{"variant_id": vid, "quantity": potes, "price": "%.2f" % round(total / potes, 2)}]
                       + ([{"variant_id": vid_caps, "quantity": caps, "price": "0.00"}] if vid_caps else [])),
        "shipping_address": addr, "billing_address": addr,
        "shipping_lines": [{"title": env_tit, "price": "0.00"}],
        "note": "Venta cerrada por WhatsApp, pagada por transferencia.",
        "note_attributes": [{"name": "DNI", "value": _solo_dig(f.get("dni"))},
                            {"name": "Origen", "value": "WhatsApp — transferencia"},
                            {"name": "WhatsApp", "value": (f.get("wa_id") or "").strip()}],
        "tags": "whatsapp, transferencia",
        "transactions": [{"kind": "sale", "status": "success", "amount": "%.2f" % total,
                          "gateway": "Transferencia bancaria"}],
        "send_receipt": False, "send_fulfillment_receipt": False,
        "inventory_behaviour": "decrement_obeying_policy",
    }}
    try:
        r = requests.post("https://%s/admin/api/2026-07/orders.json" % shop, headers=H,
                          json=payload, timeout=30)
        j = r.json()
    except Exception as e:
        return jsonify({"ok": False, "msg": "no se pudo crear: " + str(e)[:110]})
    if r.status_code >= 400:
        return jsonify({"ok": False, "msg": "Shopify lo rechazó: " + str(j.get("errors") or j)[:200]})
    o = j.get("order") or {}
    num = str(o.get("order_number") or o.get("name") or "").replace("#", "")
    wid = (f.get("wa_id") or "").strip()
    chats = _wa_chats_all()
    conv = (chats.get(email) or {}).get(wid)
    if conv is not None:
        conv["pedido_shopify"] = num          # queda anotado -> no se carga dos veces
        if conv.get("etiqueta") == "transferencia": conv.pop("etiqueta", None)   # cargado -> chau etiqueta
        conv.pop("pend_pedido", None)         # ya no está pendiente -> el botón desaparece del chat
        _wa_save_chats(chats)
    try:
        _DESP_CACHE.pop(email, None)          # que Despachos lo vea ya, sin esperar el cache
    except Exception:
        pass
    return jsonify({"ok": True, "num": num})


