@app.get("/wa-diag-meta")
def wa_diag_meta():
    """Le pregunta A META como esta configurado el numero: si la app esta suscripta al WABA (sin eso
    Meta NO manda los mensajes entrantes), en que estado esta el numero y que webhook tiene puesto.
    Sirve para dejar de adivinar en el panel."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 401
    c = _wa_conf(email) or {}
    if not (c.get("token") and c.get("phone_id")):
        return jsonify({"ok": False, "msg": "esta cuenta no tiene la API conectada"})
    out = {"ok": True, "phone_id": c.get("phone_id"), "waba_id": c.get("waba_id", "")}
    tok = c["token"]

    def _get(url, params=None):
        try:
            r = requests.get(url, params=dict(params or {}, access_token=tok), timeout=25)
            return r.status_code, (r.json() if r.content else {})
        except Exception as e:
            return 0, {"error": "%s: %s" % (type(e).__name__, str(e)[:120])}

    # 1) el numero: nombre, estado y calidad
    cod, j = _get("%s/%s" % (WA_GRAPH, c["phone_id"]),
                  {"fields": "display_phone_number,verified_name,quality_rating,status,"
                             "code_verification_status,platform_type"})
    out["numero"] = {"http": cod, **(j if isinstance(j, dict) else {})}

    # 2) apps suscriptas al WABA: SIN esto no llegan los mensajes entrantes
    if c.get("waba_id"):
        cod, j = _get("%s/%s/subscribed_apps" % (WA_GRAPH, c["waba_id"]))
        out["apps_suscriptas"] = {"http": cod, **(j if isinstance(j, dict) else {})}

    # 3) A QUE negocio/cuenta de facturacion pertenece la WABA. El billing hub muestra un
    #    "Identificador" que puede NO ser el id de la WABA, asi que a ojo no se puede saber
    #    si la cuenta que tiene tarjeta es la que realmente manda los mensajes.
    if c.get("waba_id"):
        cod, j = _get("%s/%s" % (WA_GRAPH, c["waba_id"]),
                      {"fields": "id,name,currency,account_review_status,"
                                 "owner_business_info,on_behalf_of_business_info"})
        out["waba_info"] = {"http": cod, **(j if isinstance(j, dict) else {})}

    # 4) numeros que ya cuelgan de esa WABA: para saber si entra uno nuevo sin crear otra cuenta
    if c.get("waba_id"):
        cod, j = _get("%s/%s/phone_numbers" % (WA_GRAPH, c["waba_id"]),
                      {"fields": "id,display_phone_number,verified_name,quality_rating,"
                                 "code_verification_status,platform_type,status"})
        out["numeros_de_la_waba"] = {"http": cod, **(j if isinstance(j, dict) else {})}

    # 5) puede mandar YA? messaging_limit_tier + throughput dicen si esta habilitado de verdad
    cod, j = _get("%s/%s" % (WA_GRAPH, c["phone_id"]),
                  {"fields": "messaging_limit_tier,throughput,name_status,"
                             "new_name_status,account_mode,is_official_business_account"})
    out["habilitacion"] = {"http": cod, **(j if isinstance(j, dict) else {})}

    return jsonify(out)


@app.get("/wa-diag-meta2")
def wa_diag_meta2():
    """SOLO LECTURA. Pide la METADATA del nodo del numero y de la WABA: Meta devuelve la lista de
    campos y conexiones. Sirve para saber si webhook_configuration del NUMERO se puede ESCRIBIR
    (y por donde), sin intentar escribir nada en produccion."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 401
    c = _wa_conf(email) or {}
    tok, pid, waba = c.get("token"), c.get("phone_id"), c.get("waba_id")
    if not (tok and pid):
        return jsonify({"ok": False, "msg": "esta cuenta no tiene WhatsApp API conectado"})
    out = {"ok": True, "phone_id": pid, "waba_id": waba, "pruebas": {}}

    def _g(etq, url, params):
        try:
            r = requests.get(url, params=params, timeout=25)
            out["pruebas"][etq] = {"http": r.status_code, "resp": (r.json() if r.content else {})}
        except Exception as e:
            out["pruebas"][etq] = {"error": "%s: %s" % (type(e).__name__, str(e)[:120])}

    _g("metadata_del_numero", "%s/%s" % (WA_GRAPH, pid),
       {"metadata": "1", "access_token": tok})
    _g("metadata_de_la_waba", "%s/%s" % (WA_GRAPH, waba or ""),
       {"metadata": "1", "access_token": tok})
    _g("numeros_con_su_webhook", "%s/%s/phone_numbers" % (WA_GRAPH, waba or ""),
       {"fields": "display_phone_number,verified_name,webhook_configuration", "access_token": tok})
    return jsonify(out)


@app.get("/wa-diag-num")
def wa_diag_num():
    """SOLO LECTURA. Averigua si Meta admite un webhook POR NUMERO (y no solo por WABA).
    Si existiera, se podria desviar SOLO el numero nuevo a RealProfit dejando el viejo en
    redchat. Pide campos a proposito para que Meta conteste que campos son validos.
    NO escribe nada."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 401
    c = _wa_conf(email) or {}
    tok, pid = c.get("token"), c.get("phone_id")
    if not (tok and pid):
        return jsonify({"ok": False, "msg": "esta cuenta no tiene WhatsApp API conectado"})
    out = {"ok": True, "phone_id": pid, "waba_id": c.get("waba_id"), "pruebas": {}}

    def _g(etiqueta, url, params):
        try:
            r = requests.get(url, params=params, timeout=25)
            j = (r.json() if r.content else {})
            out["pruebas"][etiqueta] = {"http": r.status_code, "resp": j}
        except Exception as e:
            out["pruebas"][etiqueta] = {"error": "%s: %s" % (type(e).__name__, str(e)[:120])}

    # 1) el numero con el campo que buscamos (si no existe, Meta lista los validos en el error)
    _g("numero_webhook_configuration", "%s/%s" % (WA_GRAPH, pid),
       {"fields": "display_phone_number,webhook_configuration", "access_token": tok})
    # 2) el mismo campo como subrecurso
    _g("subrecurso_webhook_configuration", "%s/%s/webhook_configuration" % (WA_GRAPH, pid),
       {"access_token": tok})
    # 3) campo invalido a proposito -> Meta responde con la lista de campos validos del nodo
    _g("campos_validos_del_numero", "%s/%s" % (WA_GRAPH, pid),
       {"fields": "zzz_campo_inexistente", "access_token": tok})
    return jsonify(out)


@app.get("/wa-diag-app")
def wa_diag_app():
    """SOLO LECTURA. De que app de Meta es el token guardado, y que apps estan suscriptas al WABA.
    Sirve para saber si RealProfit puede suscribir SU PROPIA app al mismo WABA y recibir los
    mensajes EN PARALELO, sin tocar el override_callback_uri que hoy manda todo a redchat.
    NO escribe nada en Meta."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 401
    c = _wa_conf(email) or {}
    tok = c.get("token")
    if not tok:
        return jsonify({"ok": False, "msg": "esta cuenta no tiene WhatsApp API conectado"})
    out = {"ok": True, "waba_id": c.get("waba_id"), "phone_id": c.get("phone_id"),
           "app_de_realprofit": _os.getenv("META_APP_ID", "")}
    try:
        r = requests.get("%s/debug_token" % WA_GRAPH, timeout=25,
                         params={"input_token": tok, "access_token": tok})
        j = ((r.json() if r.content else {}) or {}).get("data") or {}
        out["token_app_id"] = str(j.get("app_id") or "")
        out["token_app_nombre"] = j.get("application")
        out["token_tipo"] = j.get("type")
        out["token_vence"] = j.get("expires_at")
        out["token_valido"] = j.get("is_valid")
        out["scopes"] = j.get("scopes")
    except Exception as e:
        out["debug_token_error"] = "%s: %s" % (type(e).__name__, str(e)[:140])
    try:
        r2 = requests.get("%s/%s/subscribed_apps" % (WA_GRAPH, c.get("waba_id") or ""),
                          params={"access_token": tok}, timeout=25)
        out["apps_suscriptas"] = (r2.json() if r2.content else {})
    except Exception as e:
        out["subscribed_error"] = "%s: %s" % (type(e).__name__, str(e)[:140])
    out["misma_app"] = (out.get("token_app_id") or "x") == (out.get("app_de_realprofit") or "y")
    return jsonify(out)


@app.post("/wa-suscribir")
def wa_suscribir():
    """Suscribe la app al WABA (equivale al boton 'Subscribe' de WhatsApp Manager). Sin esto Meta
    recibe los mensajes pero NO nos los reenvia al webhook."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 401
    c = _wa_conf(email) or {}
    if not (c.get("token") and c.get("waba_id")):
        return jsonify({"ok": False, "msg": "faltan token o WABA ID"})
    try:
        r = requests.post("%s/%s/subscribed_apps" % (WA_GRAPH, c["waba_id"]),
                          params={"access_token": c["token"]}, timeout=25)
        return jsonify({"ok": r.status_code < 400, "http": r.status_code,
                        "det": (r.json() if r.content else {})})
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:150])})


@app.route("/wa-webhook", methods=["GET", "POST"])
def wa_webhook():
    if request.method == "GET":
        mode = request.args.get("hub.mode")
        tok = request.args.get("hub.verify_token")
        chal = request.args.get("hub.challenge")
        if mode == "subscribe" and tok:
            for c in _wa_tokens().values():
                if tok == c.get("verify_token"):
                    return Response(chal or "", mimetype="text/plain")
        return Response("forbidden", status=403)
    raw = request.get_data()
    data = request.get_json(force=True, silent=True) or {}
    try:
        _WA_WH_DIAG["posts"] += 1; _WA_WH_DIAG["last_ts"] = _wa_now()
    except Exception:
        pass
    try:
        # 1) ESTADOS (sent/delivered/read/failed) → a una COLA en memoria que se vuelca cada 10 s en UNA
        #    escritura (_wa_st_flush). Antes CADA estado leía wa_chats.json entero (12+ MB), recorría todos
        #    los mensajes y lo reescribía dos veces con candado entre workers: ~0,8 s de CPU por estado. Un
        #    envío de seguimientos dispara 2-3 estados por plantilla → CPU 100%, el server sin contestar y
        #    el watchdog reiniciándolo (logs 24, 25, 26 y 29-10-2026).
        hay_msgs = False
        for entry in (data.get("entry") or []):
            for ch in (entry.get("changes") or []):
                val = ch.get("value") or {}
                if val.get("messages"):
                    hay_msgs = True
                _sts = val.get("statuses") or []
                if not _sts:
                    continue
                em = _wa_email_by_phone_id(str((val.get("metadata") or {}).get("phone_number_id") or ""))
                try:
                    _WA_WH_DIAG["statuses"] += len(_sts)
                    _WA_WH_DIAG["last_status"] = "%s:%s" % (_sts[-1].get("status"), (_sts[-1].get("id") or "")[-8:])
                except Exception:
                    pass
                if not em:
                    continue
                for s in _sts:
                    _wa_st_encolar(em, s.get("id"), s.get("status"))
        # 2) MENSAJES ENTRANTES: igual que siempre. wa_chats se lee SOLO si llegó un mensaje.
        chats = _wa_chats_all() if hay_msgs else {}
        changed = False; fwd = set(); bot_jobs = {}
        for entry in data.get("entry", []):
            for ch in entry.get("changes", []):
                val = ch.get("value") or {}
                pid = str((val.get("metadata") or {}).get("phone_number_id") or "")
                em = _wa_email_by_phone_id(pid)
                if not em:
                    continue
                cf = _wa_conf(em) or {}
                if cf.get("forward_url"):
                    fwd.add(cf["forward_url"])
                cont = {p.get("wa_id"): (p.get("profile") or {}).get("name", "")
                        for p in (val.get("contacts") or [])}
                emap = chats.setdefault(em, {})
                for m in (val.get("messages") or []):
                    wid = m.get("from")
                    conv = emap.setdefault(wid, {"name": cont.get(wid, wid), "messages": []})
                    if cont.get(wid):
                        conv["name"] = cont[wid]
                    t = m.get("type"); txt = ""; media = None
                    if t == "text":
                        txt = (m.get("text") or {}).get("body", "")
                    elif t == "button":
                        txt = (m.get("button") or {}).get("text", "[botón]")
                    elif t in ("image", "audio", "video", "document", "sticker", "voice"):
                        mo = m.get(t) or {}
                        media = {"id": mo.get("id"), "mime": mo.get("mime_type", ""),
                                 "filename": mo.get("filename", "")}
                        txt = mo.get("caption", "")
                    elif t == "location":
                        lo = m.get("location") or {}
                        txt = "📍 " + (lo.get("name") or "Ubicación")
                    else:
                        txt = "[%s]" % (t or "?")
                    msg = {"dir": "in", "text": txt, "ts": _wa_now(), "type": t, "id": m.get("id")}
                    if media:
                        msg["media_id"] = media["id"]; msg["mime"] = media["mime"]; msg["filename"] = media["filename"]
                    conv["messages"].append(msg)
                    conv["unread"] = conv.get("unread", 0) + 1   # contador de no leídos (badge 1/2/3)
                    conv["updated"] = _wa_now(); changed = True
                    if cf.get("bot"):                            # cuenta con auto-respondedor prendido
                        bot_jobs[(em, wid)] = cf
        if changed and not _wa_save_chats(chats):
            return jsonify({"ok": False}), 500
        for u in fwd:
            try:
                requests.post(u, data=raw, headers={"Content-Type": "application/json"}, timeout=4)
            except Exception:
                pass
        # Auto-respondedor: corre el cerebro para las cuentas con el bot prendido (VisionPure).
        for (em, wid), cf in bot_jobs.items():
            try:
                _wa_bot_run(em, cf, wid, chats)
            except Exception:
                pass
    except Exception:
        pass
    return jsonify({"ok": True})


@app.get("/wa-chats")
def wa_chats():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    try:
        _wa_st_asegurar_hilo()
    except Exception:
        pass
    # ETag por versión del archivo: la pantalla /wa pide esto cada 4 s y cada respuesta pesaba 12,7 MB
    # aunque no hubiera cambiado nada. Si el archivo no cambió → 304 sin leerlo ni armar nada
    # (el navegador reusa la respuesta que ya tiene).
    def _wa_chats_etag():
        try:
            _stt = WA_CHATS.stat()
            import hashlib as _hl
            return '"%s"' % _hl.sha1(("%s|%d|%d|v1" % (email, _stt.st_mtime_ns, _stt.st_size)).encode()).hexdigest()[:20]
        except Exception:
            return ""
    _etag = _wa_chats_etag()
    if _etag and _etag in (request.headers.get("If-None-Match") or ""):
        _r304 = Response(status=304)
        _r304.headers["ETag"] = _etag
        _r304.headers["Cache-Control"] = "private, no-cache"
        return _r304
    emap = _wa_chats_all().get(email, {})
    # ETIQUETA DE CAMPAÑA: el chat entra al filtro "Reseña" apenas la plantilla esta en el
    # chat, sin esperar a que el cliente conteste. Asi se ve a quien se le mando y quien
    # todavia no respondio. Solo se pone si el chat NO tiene otra etiqueta, y una sola vez:
    # si Cristian se la saca a mano, no vuelve.
    _etq_nueva = False
    for _c in emap.values():
        if _c.get("res_etq") or _c.get("etiqueta"):
            continue
        if _res_activa(_c):
            _c["etiqueta"] = "resena"
            _c["res_etq"] = True
            _etq_nueva = True
    if _etq_nueva:
        _todo = _wa_chats_all()
        _todo[email] = emap
        _wa_save_chats(_todo)
    out = []
    for wid, conv in emap.items():
        msgs = conv.get("messages", [])
        # Excluir las conversaciones que son SOLO del canal WEB (Baileys las reenvía a este mismo store
        # para que las procese el bot, pero NO deben mostrarse en la pestaña API → esas van en la Web).
        ins = [m for m in msgs if m.get("dir") == "in"]
        if ins and all(m.get("canal") == "web" for m in ins):
            continue
        apimsgs = [m for m in msgs if m.get("canal") != "web"]   # en la pestaña API, solo lo del API
        if not apimsgs:
            continue
        last = apimsgs[-1]
        # Marca de DERIVACIÓN: el bot avisa que lo pasa a una persona (bot_nota) y con qué
        # categoría (reclamo, precio…). Sin esto la pantalla no tenía cómo saberlo.
        # La nota se BORRA cuando el bot logra responder, así que en los derivados suele venir
        # vacía: el texto útil está en bot_motivo (lo que escribió el cerebro al derivar).
        _nota = (conv.get("bot_nota", "") or "").strip()
        _mot = (conv.get("bot_motivo", "") or "").strip()
        # ¿Lo tomó una persona? Se calcula ACÁ, mirando el último saliente, y NO sólo con la marca
        # que deja el bot: esa sólo se escribe cuando entra un mensaje nuevo del cliente, así que
        # si atención contestaba y el cliente no volvía a escribir, el URGENTE quedaba pegado.
        _lastout = None
        for _m in reversed(apimsgs):
            if _m.get("dir") == "out":
                _lastout = _m
                break
        _hum = bool(conv.get("bot_humano")) or bool(
            _lastout and _lastout.get("by") != "bot" and _lastout.get("type") != "template")
        _urg = (("deriv" in _nota.lower()) or (conv.get("bot_cat") or "") == "reclamo") and not _hum
        if _urg and not _nota:
            _nota = _mot or "El bot lo derivó a atención"
        # ¿Hay una transferencia cerrada esperando que se cargue el pedido? La marca la pone el BOT
        # cuando valida el comprobante (ver _wa_bot_run), no se adivina acá: antes yo la deducía por
        # palabras sueltas del chat y el botón terminaba saliendo donde no había ninguna venta.
        # Una vez creado el pedido la marca se borra -> el botón desaparece de ese chat.
        # Se revalida ACÁ además de al marcar: así una marca vieja o mal puesta (típico: una compra
        # de checkout, que ya tiene su pedido hecho por Shopify) deja de mostrar el botón sola, sin
        # tener que salir a corregir wa_chats.json a mano.
        # AVISOS: si lo último que pasó en el chat es una PLANTILLA nuestra (seguimiento, carrito),
        # el chat va a la pestaña Avisos y NO ensucia la lista real. Vuelve a Chats apenas la
        # persona conteste algo después de esa plantilla. Motivo: un envío masivo de 140 seguimientos
        # empujaba 122 chats nuevos arriba de todo y tapaba las conversaciones de verdad (18/09/2026).
        _avi = False
        for _m in reversed(apimsgs):
            if _m.get("dir") == "in":
                break                      # contestó después de la plantilla -> es un chat normal
            if _m.get("type") == "template":
                _avi = True
                break
        _vta = (bool(conv.get("pend_pedido")) and not conv.get("pedido_shopify")
                and not _wa_es_checkout((conv.get("pend_pedido") or {}).get("monto"),
                                        (conv.get("pend_pedido") or {}).get("medio")))
        out.append({"wa_id": wid, "name": conv.get("name", wid),
                    "last": last.get("text", ""), "ts": conv.get("updated", ""),
                    "unread": conv.get("unread", 0),
                    "nota": _nota, "cat": conv.get("bot_cat", "") or "",
                    "motivo": conv.get("bot_motivo", "") or "",
                    "humano": _hum, "urgente": bool(_urg),
                    "pedido": conv.get("pedido_shopify", "") or "",
                    "venta": bool(_vta),

                    "nomarca": conv.get("comp_nomarca") or {},


                    "aviso": bool(_avi),
                    # VIDEO DE RESEÑA PENDIENTE: lo manda el cliente, lo analiza una persona.
                    # Sin esto la marca `res_video` se escribia y no se mostraba en ningun
                    # lado: el video llegaba y nadie se enteraba.
                    "resvideo": bool(conv.get("res_video")) and not conv.get("res_video_ok"),



                    "etiqueta": ("" if (conv.get("etiqueta") == "transferencia" and conv.get("pedido_shopify")) else (conv.get("etiqueta") or "")),
                    "messages": apimsgs[-300:]})
    # Orden NORMAL por fecha: el chat con actividad más reciente arriba. Los derivados NO se
    # fijan arriba — si no llega nada nuevo bajan solos; el chip rojo alcanza para ubicarlos.
    out.sort(key=lambda x: x.get("ts", ""), reverse=True)
    _resp = jsonify({"ok": True, "chats": out})
    _etag = _wa_chats_etag()                 # después del posible guardado de etiquetas
    if _etag:
        _resp.headers["ETag"] = _etag
        _resp.headers["Cache-Control"] = "private, no-cache"
    return _resp


@app.post("/wa-leido")
def wa_leido():
    """Marca un chat como leído (pone unread=0). Lo llama la UI al abrir la conversación."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    wid = (request.form.get("wa_id") or "").strip()
    chats = _wa_chats_all()
    conv = (chats.get(email) or {}).get(wid)
    if conv and conv.get("unread"):
        conv["unread"] = 0
        _wa_save_chats(chats)
    return jsonify({"ok": True})


@app.get("/wa-bot-config")
def wa_bot_config_get():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    c = _wa_conf(email) or {}
    try:
        import agente_ia
        key_ok = agente_ia.disponible()
    except Exception:
        key_ok = False
    return jsonify({"ok": True, "bot": bool(c.get("bot")), "mode": c.get("bot_mode", "auto"),
                    "instr": c.get("bot_instr", ""), "key_ok": key_ok,
                    "canal": c.get("bot_canal", "api"),
                    "sched": c.get("bot_sched", "24h"),
                    "desde": c.get("bot_desde", "20:00"), "hasta": c.get("bot_hasta", "09:00"),
                    "marca": c.get("bot_marca", ""),
                    "nombre": c.get("bot_nombre", ""),
                    "estilo": c.get("bot_estilo", "resolutivo"),
                    "humanizar": bool(c.get("bot_humanizar", True)),
                    "handoff_msg": c.get("bot_handoff_msg", ""),
                    "handoff_rules": c.get("bot_handoff_rules", []),
                    "reglas_si": c.get("bot_reglas_si", []),
                    "reglas_no": c.get("bot_reglas_no", []),
                    "instr_int": c.get("bot_instr_int", ""),
                    "temp": c.get("bot_temp", 0.6),
                    "demora": c.get("bot_demora", "instant"),
                    "ignora_grupos": bool(c.get("bot_ignora_grupos", False)),
                    "excluidos": c.get("bot_excluidos", []),
                    "pago_titular": c.get("bot_pago_titular", ""),
                    "pago_alias": c.get("bot_pago_alias", ""),
                    "pago_cuit": c.get("bot_pago_cuit", ""),
                    "ejemplos_n": int(c.get("bot_ejemplos_n", 0)),
                    "ejemplos_len": len(c.get("bot_ejemplos", "") or ""),
                    "activo_ahora": _bot_activo_ahora(c),
                    "conectado": bool(c.get("token") and c.get("phone_id"))})


@app.post("/wa-bot-config")
def wa_bot_config_set():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    toks = _wa_tokens()
    c = toks.get(email)
    if not c:
        return jsonify({"ok": False, "msg": "WhatsApp no conectado"})
    if "bot" in request.form:
        c["bot"] = request.form.get("bot") in ("1", "true", "on", "True")
    if "mode" in request.form:
        c["bot_mode"] = "draft" if request.form.get("mode") == "draft" else "auto"
    if "instr" in request.form:
        # 12000 y no 6000: el cerebro ya estaba en 5829 y no entraban las reglas nuevas.
        # Con el tope viejo, guardar cortaba el final del texto SIN AVISAR.
        c["bot_instr"] = (request.form.get("instr") or "")[:12000]
    if "marca" in request.form:
        c["bot_marca"] = (request.form.get("marca") or "")[:80]
    if "pago_titular" in request.form:
        c["bot_pago_titular"] = (request.form.get("pago_titular") or "")[:120]
    if "pago_alias" in request.form:
        c["bot_pago_alias"] = (request.form.get("pago_alias") or "")[:120]
    if "pago_cuit" in request.form:
        c["bot_pago_cuit"] = (request.form.get("pago_cuit") or "")[:20]
    if "canal" in request.form:
        v = request.form.get("canal")
        c["bot_canal"] = v if v in ("api", "web", "ambos") else "api"
    if "sched" in request.form:
        c["bot_sched"] = "franja" if request.form.get("sched") == "franja" else "24h"
    def _hhmm(s, dflt):
        import re as _re
        s = (s or "").strip()
        return s if _re.match(r"^\d{1,2}:\d{2}$", s) else dflt
    if "desde" in request.form:
        c["bot_desde"] = _hhmm(request.form.get("desde"), "20:00")
    if "hasta" in request.form:
        c["bot_hasta"] = _hhmm(request.form.get("hasta"), "09:00")
    # ── Campos de la pantalla nueva (estilo Capitan) ──
    if "nombre" in request.form:
        c["bot_nombre"] = (request.form.get("nombre") or "")[:60]
    if "estilo" in request.form:
        v = request.form.get("estilo")
        c["bot_estilo"] = v if v in ("resolutivo", "directo", "conversacional") else "resolutivo"
    if "humanizar" in request.form:
        c["bot_humanizar"] = request.form.get("humanizar") in ("1", "true", "on", "True")
    if "handoff_msg" in request.form:
        c["bot_handoff_msg"] = (request.form.get("handoff_msg") or "")[:500]
    if "handoff_rules" in request.form:
        _rs = [l.strip() for l in (request.form.get("handoff_rules") or "").split("\n") if l.strip()]
        c["bot_handoff_rules"] = _rs[:20]
    if "reglas_si" in request.form:
        _rs = [l.strip() for l in (request.form.get("reglas_si") or "").split("\n") if l.strip()]
        c["bot_reglas_si"] = _rs[:20]
    if "reglas_no" in request.form:
        _rs = [l.strip() for l in (request.form.get("reglas_no") or "").split("\n") if l.strip()]
        c["bot_reglas_no"] = _rs[:20]
    if "instr_int" in request.form:
        c["bot_instr_int"] = (request.form.get("instr_int") or "")[:2000]
    if "temp" in request.form:
        try:
            c["bot_temp"] = max(0.0, min(1.0, float(request.form.get("temp") or 0.6)))
        except Exception:
            c["bot_temp"] = 0.6
    if "demora" in request.form:
        v = request.form.get("demora")
        c["bot_demora"] = v if v in ("instant", "fija", "aleatoria") else "instant"
    if "ignora_grupos" in request.form:
        c["bot_ignora_grupos"] = request.form.get("ignora_grupos") in ("1", "true", "on", "True")
    if "excluidos" in request.form:
        _ex = [l.strip() for l in (request.form.get("excluidos") or "").replace(",", "\n").split("\n") if l.strip()]
        c["bot_excluidos"] = _ex[:100]
    _wa_save_tokens(toks)
    return jsonify({"ok": True, "bot": bool(c.get("bot")), "mode": c.get("bot_mode", "auto"),
                    "canal": c.get("bot_canal", "api"), "activo_ahora": _bot_activo_ahora(c)})


@app.post("/wa-bot-probar")
def wa_bot_probar():
    """Probador: le tirás un mensaje de cliente y devuelve qué DECIDIRÍA el bot, sin enviar nada."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    c = _wa_conf(email) or {}
    txt = (request.form.get("text") or "").strip()
    nombre = (request.form.get("nombre") or "").strip()
    if not txt:
        return jsonify({"ok": False, "msg": "escribí un mensaje de prueba"})
    try:
        import agente_ia
    except Exception as e:
        return jsonify({"ok": False, "msg": "cerebro no disponible: " + str(e)[:80]})
    if not agente_ia.disponible():
        return jsonify({"ok": False, "msg": "Falta ANTHROPIC_API_KEY en el servidor (Render → Environment)"})
    hist = [{"dir": "in", "texto": txt}]
    d = agente_ia.decidir(hist, nombre=nombre, extra_instr=_bot_extra_instr(c),
                          marca=_wa_marca_auto(email, c),
                          pago={"titular": c.get("bot_pago_titular", ""),
                                "alias": c.get("bot_pago_alias", ""),
                                "cuit": c.get("bot_pago_cuit", "")})
    return jsonify({"ok": True, "d": d})


def _backlog_page_html(desde):
    return ("""<!doctype html><meta charset=utf-8><title>Reproceso backlog bot</title>
<body style="font-family:system-ui;background:#0b1220;color:#e5edf7;padding:24px;max-width:760px;margin:auto">
<h2>&#129302; Responder backlog del bot</h2>
<p>Corte: desde <b>__D__</b> de hoy hasta ahora (hora Argentina). Solo agarra chats cuyo <b>&uacute;ltimo mensaje es entrante y sigue sin contestar</b>. Cada chat se intenta una sola vez.</p>
<button id=go style="background:#2563eb;color:#fff;border:0;padding:11px 20px;border-radius:9px;font-size:15px;font-weight:700;cursor:pointer">&#9654;&#65039; Empezar</button>
<div id=stat style="margin-top:16px;font-size:15px"></div>
<pre id=log style="margin-top:12px;background:#111c2b;padding:12px;border-radius:8px;max-height:52vh;overflow:auto;font-size:12px;white-space:pre-wrap"></pre>
<script>
var T={p:0,r:0,e:0,f:0,n:0};
var desde="__D__";
function line(s){var l=document.getElementById('log');l.textContent+=s+"\\n";l.scrollTop=l.scrollHeight;}
function stat(x){document.getElementById('stat').innerHTML="Procesados <b>"+T.p+"</b> &middot; &#9989; respondidos <b>"+T.r+"</b> &middot; derivados "+T.e+" &middot; sin respuesta "+T.n+" &middot; fall&oacute; env&iacute;o "+T.f+(x?(" &middot; "+x):"");}
function batch(){
  fetch('/wa-bot-backlog?run=1&n=5&desde='+encodeURIComponent(desde)).then(function(r){return r.json();}).then(function(j){
    if(!j.ok){line("ERROR: "+(j.msg||'?'));document.getElementById('go').disabled=false;return;}
    T.p+=j.procesados_ahora;T.r+=j.respondidos;T.e+=j.escalados;T.f+=j.fallo_envio;T.n+=j.sin_responder;
    (j.detalle||[]).forEach(function(d){line((d.estado||'')+"  "+d.wid+(d.nota?("  \\u2014 "+d.nota):""));});
    stat("quedan "+j.restantes);
    if(j.procesados_ahora>0 && j.restantes>0){ setTimeout(batch,400); }
    else { stat("LISTO \\u2713"); line("\\u2500\\u2500 FIN \\u2500\\u2500"); document.getElementById('go').disabled=false; }
  }).catch(function(e){line("ERROR red: "+e);document.getElementById('go').disabled=false;});
}
document.getElementById('go').onclick=function(){this.disabled=true;T={p:0,r:0,e:0,f:0,n:0};document.getElementById('log').textContent='';stat('arrancando\\u2026');batch();};
</script></body>""").replace("__D__", desde)


@app.route("/wa-bot-backlog", methods=["GET", "POST"])
def wa_bot_backlog():
    """TEMP: reprocesa el backlog de chats sin contestar desde una hora de corte (default 19:00 hoy).
    Destraba el anti-duplicado y corre el cerebro para que responda. Login-gated. Batches de a n."""
    email = _user_actual()
    desde = (request.values.get("desde") or "19:00").strip()
    if not request.values.get("run"):
        if not email:
            return _backlog_page_html(desde).replace("Empezar", "Logueate en RealProfit primero")
        return _backlog_page_html(desde)
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    conf = _wa_conf(email) or {}
    if not conf.get("bot"):
        return jsonify({"ok": False, "msg": "el bot está apagado para esta cuenta"})
    try:
        hh, mm = [int(x) for x in desde.split(":")[:2]]
    except Exception:
        hh, mm = 19, 0
    hoy = (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).strftime("%Y-%m-%d")
    cutoff = "%s %02d:%02d:00" % (hoy, hh, mm)
    try:
        n = max(1, min(int(request.values.get("n") or 5), 12))
    except Exception:
        n = 5
    # Canal con el que se corre el cerebro. ANTES estaba clavado en "web": en una cuenta
    # configurada en "api" (NoxaLab) el bot rechazaba TODO por canal equivocado y encima
    # dejaba el chat marcado como intentado, o sea que se quemaba el backlog entero sin
    # contestar a nadie. Por defecto se usa el canal configurado de la cuenta.
    _canal = (request.values.get("canal") or conf.get("bot_canal") or "api").strip().lower()
    if _canal not in ("api", "web"):
        _canal = "api"
    chats = _wa_chats_all()
    convs = (chats.get(email) or {})

    def _cands():
        out = []
        for wid, conv in convs.items():
            msgs = conv.get("messages") or []
            if not msgs:
                continue
            last = msgs[-1]
            if last.get("dir") != "in":
                continue
            if (last.get("ts") or "") < cutoff:
                continue
            if conv.get("bot_backlog_seen") == (last.get("id") or ""):
                continue
            out.append((last.get("ts") or "", wid, last.get("id") or ""))
        out.sort()
        return out

    cands = _cands()
    total_pend = len(cands)
    done = resp = esc = fail = noresp = 0
    detalle = []
    import time as _t
    for ts, wid, mid in cands[:n]:
        conv = convs.get(wid)
        if not conv:
            continue
        conv["bot_backlog_seen"] = mid          # ya lo intenté (evita loop infinito)
        conv.pop("bot_last_in", None)           # destraba el anti-duplicado del bot
        conv.pop("bot_nota", None)              # nota vieja: si no, no se sabe si es de esta corrida
        antes = len(conv.get("messages") or [])
        try:
            _wa_bot_run(email, conf, wid, chats, canal=_canal)
        except Exception as e:
            fail += 1
            detalle.append({"wid": wid, "estado": "error", "nota": str(e)[:80]})
            continue
        done += 1
        m2 = (convs.get(wid) or {}).get("messages") or []
        if len(m2) > antes and m2[-1].get("by") == "bot":
            resp += 1
            detalle.append({"wid": wid, "estado": "respondido"})
        else:
            nota = (convs.get(wid) or {}).get("bot_nota", "") or ""
            # Si NO contestó por un problema de CONFIGURACIÓN (canal o horario), el chat no se
            # "gasta": se desmarca para poder reintentarlo una vez arreglada la config. Si se
            # dejara marcado, arreglar el canal después no serviría de nada.
            if ("canal" in nota) or ("horario" in nota):
                (convs.get(wid) or {}).pop("bot_backlog_seen", None)
            if "deriv" in nota:
                esc += 1
            elif "envío" in nota or "envio" in nota:
                fail += 1
            else:
                noresp += 1
            detalle.append({"wid": wid, "estado": "sin respuesta", "nota": nota[:90]})
        _t.sleep(0.15)
    _wa_save_chats(chats)
    restantes = max(0, total_pend - done)
    return jsonify({"ok": True, "cutoff": cutoff, "procesados_ahora": done, "respondidos": resp,
                    "escalados": esc, "fallo_envio": fail, "sin_responder": noresp,
                    "restantes": restantes, "detalle": detalle})


def _bot_extra_instr(c):
    """Instrucciones del dueño + los EJEMPLOS aprendidos de chats reales (si cargó alguno). Es lo que
    ve el cerebro además del rol base. Se lo pasamos como extra_instr en cada decisión."""
    instr = (c or {}).get("bot_instr", "") or ""
    ej = (c or {}).get("bot_ejemplos", "") or ""
    if ej.strip():
        instr = (instr + "\n\n# CÓMO RESPONDE EL DUEÑO EN LA REALIDAD (aprendido de chats humanos: tono, "
                 "respuestas típicas y sobre todo QUÉ NO responde solo → escala). Imitá este estilo:\n" + ej.strip())
    return instr


def _wa_aprender_pares(text):
    """Parsea un export de WhatsApp (formato 'CHAT n/N' + '[fecha hora] Quien: msg') y saca los pares
    (mensaje del cliente → respuesta del dueño 'Yo'). Descarta multimedia/notificaciones/base64 y las
    respuestas de PEDIDO PUNTUAL (seguimiento/tracking/reclamo) porque esas las maneja un humano."""
    import re as _re
    SKIP = ("[notificacion", "[imagen]", "[audio", "[documento", "[sticker]", "[llamada]", "[album]",
            "[mensaje eliminado]", "[evento", "[protocol]", "[mensaje interactivo]")
    hdr = _re.compile(r"^\[(\d{2}/\d{2}/\d{4}) (\d{1,2}:\d{2})\]\s+(.+?):\s?(.*)$")
    chatsep = _re.compile(r"^CHAT \d+/\d+:")

    def _malo(t):
        tl = (t or "").lower()
        if any(s in tl for s in SKIP):
            return True
        # base64 / blobs (corridas largas sin espacios) o vacío
        if not t or len(t) < 2:
            return True
        for tok in t.split():
            if len(tok) > 45:
                return True
        return False

    def _es_pedido(t):
        tl = (t or "").lower()
        return ("andreani.com" in tl or "seguimiento" in tl or "reclamo" in tl
                or bool(_re.search(r"\d{10,}", t)))

    chats, cur, speaker, buf = [], [], None, []

    def _flush():
        nonlocal speaker, buf
        if speaker is not None:
            cur.append((speaker, "\n".join(buf).strip()))
        speaker, buf = None, []

    def _flushchat():
        nonlocal cur
        _flush()
        if cur:
            chats.append(cur)
        cur = []

    for ln in (text or "").splitlines():
        s = ln.strip()
        if chatsep.match(s):
            _flushchat(); continue
        if s.startswith("=========="):
            continue
        m = hdr.match(ln)
        if m:
            _flush()
            speaker = "yo" if m.group(3).strip().lower() == "yo" else "cli"
            buf = [m.group(4)]
        elif speaker is not None:
            buf.append(ln)
    _flushchat()

    pares, vistos = [], set()
    for chat in chats:
        i, n = 0, len(chat)
        while i < n:
            if chat[i][0] == "cli":
                q = [chat[i][1]]; j = i + 1
                while j < n and chat[j][0] == "cli":
                    q.append(chat[j][1]); j += 1
                a = []
                while j < n and chat[j][0] == "yo":
                    a.append(chat[j][1]); j += 1
                if a:
                    qt = " ".join(x for x in q if x).strip()
                    at = "\n".join(x for x in a if x).strip()
                    if qt and at and not _malo(qt) and not _malo(at) and not _es_pedido(at):
                        key = _re.sub(r"\s+", " ", at.lower())[:80]
                        if key not in vistos:
                            vistos.add(key)
                            pares.append((qt[:300], at[:700]))
                i = j
            else:
                i += 1
    return pares


@app.post("/wa-bot-aprender")
def wa_bot_aprender():
    """Sube un export de chats de WhatsApp (.txt) → el bot APRENDE tu tono, tus respuestas típicas y qué
    escalás. Destila los pares reales con el mismo cerebro (Claude) y lo guarda por cuenta."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    toks = _wa_tokens()
    c = toks.get(email)
    if not c:
        return jsonify({"ok": False, "msg": "WhatsApp no conectado"})
    f = request.files.get("file") or (next(iter(request.files.values())) if request.files else None)
    if not f:
        return jsonify({"ok": False, "msg": "subí el .txt de chats"})
    try:
        raw = f.read()
        text = raw.decode("utf-8", "ignore") if isinstance(raw, (bytes, bytearray)) else str(raw)
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude leer el archivo (%s)" % str(e)[:80]})
    pares = _wa_aprender_pares(text)
    if not pares:
        return jsonify({"ok": False, "msg": "no encontré charlas con respuestas tuyas en ese archivo"})
    try:
        import agente_ia
    except Exception as e:
        return jsonify({"ok": False, "msg": "cerebro no disponible: " + str(e)[:80]})
    if not agente_ia.disponible():
        return jsonify({"ok": False, "msg": "Falta ANTHROPIC_API_KEY en el servidor"})
    # armo una muestra (deduplicada, acotada) para no reventar el contexto
    muestra = pares[:180]
    cuerpo = "\n\n".join("CLIENTE: %s\nDUEÑO: %s" % (q, a) for q, a in muestra)
    sistema = (
        "Sos un analista de atención al cliente. Abajo hay pares REALES de WhatsApp: lo que preguntó un "
        "cliente y cómo respondió el DUEÑO de la tienda. Resumí, EN ARGENTINO y SOLO con lo que aparece "
        "(no inventes precios, links ni datos), en máximo ~3500 caracteres y con este formato exacto:\n"
        "## PREGUNTAS FRECUENTES\n- <pregunta>: <mejor respuesta corta, en el tono del dueño>\n"
        "## EJEMPLOS DE TONO (8, textuales)\nCLIENTE: ...\nDUEÑO: ...\n"
        "## NO RESPONDER SOLO (escalar a humano)\n- <situaciones donde el dueño deriva: pedidos puntuales, "
        "'no me llegó', seguimiento, reclamos, comprobantes, cancelaciones, direcciones>\n"
        "Sé fiel al estilo real del dueño (saludos, muletillas, cómo maneja objeciones)."
    )
    resumen = agente_ia.chat([{"role": "user", "content": cuerpo}], sistema, max_tokens=2200)
    resumen = (resumen or "").strip()[:6000]
    if not resumen or len(resumen) < 40:
        return jsonify({"ok": False, "msg": "no pude destilar los chats, probá de nuevo"})
    c["bot_ejemplos"] = resumen
    c["bot_ejemplos_n"] = len(pares)
    _wa_save_tokens(toks)
    return jsonify({"ok": True, "pares": len(pares), "usados": len(muestra), "resumen": resumen})


@app.post("/wa-web-hook")
def wa_web_hook():
    """Lo llama el servicio de WhatsApp Web (Baileys) por cada mensaje ENTRANTE.
    Guarda el mensaje y, si el bot está en canal web + horario, responde solo. Aislado por cuenta."""
    if not WA_WEB_SECRET or request.headers.get("x-wa-secret") != WA_WEB_SECRET:
        return jsonify({"ok": False}), 403
    d = request.get_json(silent=True) or {}
    email = (d.get("acc") or "").strip()
    # GRUPO DE GASTOS: tiene su propio cerebro y NO pasa por el bot de ventas.
    # Va antes de validar el texto porque en el grupo puede venir solo un audio/foto/PDF.
    if d.get("grupo") and email:
        try:
            if _gastos_hook(email, d):
                return jsonify({"ok": True, "gastos": True})
        except Exception as e:
            return jsonify({"ok": False, "msg": "gastos %s: %s" % (type(e).__name__, str(e)[:120])})
        return jsonify({"ok": True})
    tel = re.sub(r"\D", "", d.get("tel") or d.get("from") or "")
    text = (d.get("text") or "").strip()
    # Una FOTO o un AUDIO sin leyenda no traen texto. Antes se descartaban aca y el bot ni se
    # enteraba (los comprobantes sin leyenda eran invisibles). Ahora entran con su tipo y su
    # archivo, y el cerebro los mira (imagen) o los escucha (audio, via Whisper).
    medio = (d.get("medio") or "").strip().lower()
    media_id = (d.get("media_id") or "").strip()
    if not email or not tel or not (text or medio):
        return jsonify({"ok": False, "msg": "faltan datos"})
    cf = _wa_conf(email)
    if not cf:
        return jsonify({"ok": False, "msg": "cuenta sin WhatsApp"})
    chats = _wa_chats_all()
    conv = chats.setdefault(email, {}).setdefault(tel, {"name": d.get("name") or tel, "messages": []})
    if d.get("name"):
        conv["name"] = d["name"]
    # Guardo el jid EXACTO con el que entró (ej "...@lid"). El bot DEBE responder a este mismo jid,
    # si no WhatsApp lo manda al jid de teléfono (@s.whatsapp.net) y queda un chat DUPLICADO por persona.
    _raw_from = (d.get("from") or "").strip()
    if "@" in _raw_from:
        conv["web_jid"] = _raw_from
    import hashlib as _hl
    # id ÚNICO por mensaje: si el puente manda un id real lo usamos; si no, tel+ts+hash del texto
    # (así el dedup del bot NO bloquea todos los mensajes de un mismo número cuando no viene ts).
    _mid = (d.get("id") or d.get("msgId") or d.get("wamid") or "").strip()
    _inid = _mid or ("web:%s:%s:%s" % (tel, d.get("ts") or "", _hl.sha1(text.encode("utf-8")).hexdigest()[:8]))
    _tipo = medio if medio in ("image", "audio", "video", "document", "sticker", "gif") else "text"
    _msg = {"dir": "in", "text": text, "ts": _wa_now(), "type": _tipo, "id": _inid, "canal": "web"}
    if media_id:
        _msg["media_id"] = media_id
        _msg["mime"] = (d.get("mime") or "")
    conv["messages"].append(_msg)
    conv["unread"] = conv.get("unread", 0) + 1
    conv["updated"] = _wa_now()
    _wa_save_chats(chats)
    try:
        _wa_bot_run(email, cf, tel, chats, canal="web")
    except Exception:
        pass
    return jsonify({"ok": True})


# ── Puente con el servicio de WhatsApp Web (Baileys) — todo aislado por email ──
def _wa_web_call(method, path, email, extra=None, timeout=25):
    """Habla con el servicio Node pasando siempre acc=email (aislación). (resp, json|None)."""
    if not (WA_WEB_URL and WA_WEB_SECRET):
        return None, {"ok": False, "msg": "El servicio de WhatsApp Web no está configurado (faltan WA_WEB_URL / WA_WEB_SECRET)."}
    try:
        h = {"x-wa-secret": WA_WEB_SECRET}
        body = dict(extra or {}); body["acc"] = email
        if method == "GET":
            r = requests.get(WA_WEB_URL + path, headers=h, params=body, timeout=timeout)
        else:
            r = requests.post(WA_WEB_URL + path, headers=h, json=body, timeout=timeout)
        return r, (r.json() if r.content else {})
    except Exception as e:
        return None, {"ok": False, "msg": "No se pudo hablar con el servicio Web: " + str(e)[:100]}


@app.post("/wa-web-connect")
def wa_web_connect():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    # aseguro un lugar para la config del bot aunque use SOLO WhatsApp Web (sin Cloud API)
    toks = _wa_tokens()
    if email not in toks:
        toks[email] = {"web": True}
        _wa_save_tokens(toks)
    _r, j = _wa_web_call("POST", "/connect", email)
    if isinstance(j, dict) and (j.get("me") or {}).get("name"):
        _WA_WEB_NAMES[email] = j["me"]["name"]
    return jsonify(j if isinstance(j, dict) else {"ok": False})


