def _mcp_tool_negocio(email, a):
    d, h = _mcp_fechas(a)
    b = _pf_periodo_blob(email, d, h)
    r = b.get("raw") or {}
    L = ["NEGOCIO  %s%s" % (d, "" if d == h else "  al  " + h), ""]
    L.append("Ventas           %s   (tienda %s · MercadoLibre %s)" % (
        r.get("ordenes", 0), r.get("ordenes_web", 0), r.get("meli_ventas", 0)))
    L.append("Facturacion      %s" % _mcp_pesos(r.get("facturado")))
    L.append("Ganancia         %s   (margen %s%%)" % (_mcp_pesos(r.get("ganancia")), r.get("margen", 0)))
    L.append("Ticket promedio  %s" % _mcp_pesos(r.get("aov")))
    L.append("")
    L.append("PUBLICIDAD")
    L.append("  Inversion      %s" % _mcp_pesos(r.get("publi_ars")))
    L.append("  CPA            %s      (tope para no perder: %s)" % (
        _mcp_pesos(r.get("cpa")), _mcp_pesos(r.get("be_cpa"))))
    L.append("  ROAS           %sx     (minimo para no perder: %sx)" % (r.get("roas", 0), r.get("be_roas", 0)))
    if r.get("comision_agencia"):
        L.append("  Comision CP3   %s   (10%% de la pauta de CP3, se resta de la ganancia)"
                 % _mcp_pesos(r.get("comision_agencia")))
    L.append("")
    L.append("POR CANAL")
    L.append("  Tienda         %s facturado · ganancia %s · margen %s%%" % (
        _mcp_pesos(r.get("facturado_web")), _mcp_pesos(r.get("web_ganancia")), r.get("web_margen", 0)))
    if r.get("meli_ok") is False:
        # Sin esto se leia "0 facturado" y una perdida, que es lo que pasa cuando la pauta de
        # MELI entra pero las ventas no: parece un dia malo y en realidad es un dato que falta.
        L.append("  MercadoLibre   NO SE PUDO LEER%s" % (
            ("  (" + str(r.get("meli_error"))[:120] + ")") if r.get("meli_error") else ""))
        L.append("                 la pauta de MELI (%s) si se leyo, asi que la ganancia la"
                 % _mcp_pesos(r.get("publi_meli")))
        L.append("                 descuenta sin las ventas que la justifican")
    else:
        L.append("  MercadoLibre   %s facturado · ganancia %s · margen %s%%" % (
            _mcp_pesos(r.get("meli_facturado")), _mcp_pesos(r.get("ml_ganancia")), r.get("ml_margen", 0)))
    if r.get("ri"):
        L.append("")
        L.append("IVA  (ventas %s%% · compras %s%%)" % (IVA_VENTAS_PCT, IVA_COMPRAS_PCT))
        L.append("  Debito %s · credito %s · a pagar %s" % (
            _mcp_pesos(r.get("iva_total")), _mcp_pesos(r.get("iva_favor")), _mcp_pesos(r.get("iva_pagar"))))
    L.append("")
    L.append("Nota: la pauta NO trae las ventas de MercadoLibre, por eso el CPA y el break even "
             "se calculan SOLO con la tienda.")
    return "\n".join(L)


def _mcp_ads_insights(email, d, h, nivel="account", campos=None, limite=500):
    """Insights de Meta de TODAS las cuentas, ya pasados a pesos."""
    import urllib.parse as _up
    tk = _meta_tokens().get(email) or {}
    token = tk.get("access_token") or _os.getenv("META_OWNER_TOKEN", "")
    if not token:
        return None, "No hay token de Meta conectado."
    cuentas = [(k.upper(), v["ad_account"]) for k, v in _ADS_CUENTAS.items()]
    vistas, out = set(), []
    # DOS cotizaciones distintas, a proposito:
    #  - el GASTO se pasa al costo REAL del dolar de pauta (cotizacion / 0,9177521), que es lo
    #    que sale del bolsillo por cada dolar.
    #  - la FACTURACION que informa Meta son pesos reales que Meta expreso en dolares, asi que
    #    vuelve a pesos con la cotizacion de mercado.
    # Usar la misma para los dos dejaba el ROAS igual al de Meta y escondia que el dolar
    # encarecio la pauta un 10%. Esta tabla mostraba el gasto mas barato que el dashboard.
    dolar = _dolar_ars_vivo() or 1.0
    dolar_gasto = _dolar_ads(d) or dolar
    f = campos or "spend,account_currency"
    for nom, acc in cuentas:
        if acc in vistas:
            continue
        vistas.add(acc)
        q = _up.urlencode({"fields": f, "level": nivel, "limit": str(limite),
                           "time_range": _json.dumps({"since": d, "until": h}),
                           "access_token": token})
        try:
            rr = requests.get("https://graph.facebook.com/%s/act_%s/insights?%s" % (META_API, acc, q), timeout=45)
            dd = rr.json() if rr.content else {}
        except Exception as e:
            out.append({"cuenta": nom, "error": str(e)[:80]}); continue
        if dd.get("error"):
            out.append({"cuenta": nom, "error": dd["error"].get("message", "")[:80]}); continue
        for row in (dd.get("data") or []):
            gasto = float(row.get("spend") or 0)
            mon = (row.get("account_currency") or "ARS").upper()
            ars = gasto * dolar_gasto if mon == "USD" else gasto
            # La cuenta de AGENCIA no se paga directo a Meta: la agencia factura el gasto + su
            # comision. Sin esto CP3 aparecia mas barata de lo que cuesta y su ROAS mas alto:
            # un 5,00 en pantalla es 4,55 real.
            if _FIN_ACT_AGENCIA and str(acc) == str(_FIN_ACT_AGENCIA):
                ars *= (1.0 + _FIN_AGENCIA_PCT / 100.0)
            comp = val = 0.0
            for ac in (row.get("actions") or []):
                if ac.get("action_type") in ("purchase", "omni_purchase", "offsite_conversion.fb_pixel_purchase"):
                    comp = max(comp, float(ac.get("value") or 0))
            for ac in (row.get("action_values") or []):
                if ac.get("action_type") in ("purchase", "omni_purchase", "offsite_conversion.fb_pixel_purchase"):
                    val = max(val, float(ac.get("value") or 0))
            out.append({"cuenta": nom, "acc": acc, "gasto": ars, "moneda": mon, "gasto_orig": gasto,
                        "compras": comp, "valor": val * dolar if mon == "USD" else val,
                        "nombre": row.get("ad_name") or row.get("campaign_name") or "",
                        "campania": row.get("campaign_name") or "",
                        "ctr": float(row.get("ctr") or 0), "frec": float(row.get("frequency") or 0)})
    return out, None


def _mcp_tool_ads_cuentas(email, a):
    d, h = _mcp_fechas(a)
    filas, err = _mcp_ads_insights(email, d, h, "account",
                                   "spend,account_currency,actions,action_values")
    if err:
        return err
    L = ["META ADS POR CUENTA  %s%s" % (d, "" if d == h else "  al  " + h), ""]
    L.append("%-5s %14s %9s %14s %8s" % ("cta", "gasto", "compras", "costo/compra", "ROAS"))
    tg = tc = tv = 0.0
    sinacceso = [f["cuenta"] for f in filas if f.get("error")]
    for f in sorted([x for x in filas if not x.get("error")], key=lambda x: -x.get("gasto", 0)):
        if f["gasto"] <= 0:
            continue
        tg += f["gasto"]; tc += f["compras"]; tv += f["valor"]
        L.append("%-5s %14s %9d %14s %7.2fx%s" % (
            f["cuenta"], _mcp_pesos(f["gasto"]), f["compras"],
            _mcp_pesos(f["gasto"] / f["compras"]) if f["compras"] else "—",
            (f["valor"] / f["gasto"]) if f["gasto"] else 0,
            "   (factura en USD)" if f["moneda"] == "USD" else ""))
    L.append("-" * 56)
    L.append("%-5s %14s %9d %14s %7.2fx" % ("TOTAL", _mcp_pesos(tg), tc,
             _mcp_pesos(tg / tc) if tc else "—", (tv / tg) if tg else 0))
    if sinacceso:
        L.append("")
        L.append("Sin acceso con este token: %s" % ", ".join(sinacceso))
    L.append("")
    L.append("Las compras son las que Meta se ATRIBUYE. Para las ventas reales usa la "
             "herramienta 'negocio'. CP3 ademas lleva 10% de comision de agencia.")
    return "\n".join(L)


def _mcp_tool_ads_anuncios(email, a):
    d, h = _mcp_fechas(a)
    top = int(a.get("top") or 10)
    filas, err = _mcp_ads_insights(
        email, d, h, "ad",
        "ad_name,campaign_name,spend,account_currency,actions,action_values,ctr,frequency", 400)
    if err:
        return err
    filas = [f for f in filas if not f.get("error") and f.get("gasto", 0) > 0]
    if not filas:
        return "No hubo gasto en anuncios entre %s y %s." % (d, h)
    tg = sum(f["gasto"] for f in filas); tc = sum(f["compras"] for f in filas)
    tv = sum(f["valor"] for f in filas)
    con = sorted([f for f in filas if f["compras"] > 0], key=lambda f: f["gasto"] / f["compras"])
    sin = sorted([f for f in filas if f["compras"] == 0], key=lambda f: -f["gasto"])
    L = ["META ADS ANUNCIO POR ANUNCIO  %s%s" % (d, "" if d == h else "  al  " + h), ""]
    L.append("%d anuncios con gasto · %s · %d compras · costo/compra %s · ROAS %.2fx" % (
        len(filas), _mcp_pesos(tg), tc, _mcp_pesos(tg / tc) if tc else "—", (tv / tg) if tg else 0))
    L.append("")
    L.append("LOS QUE MEJOR VENDEN")
    L.append("%-5s %-34s %12s %5s %12s %7s" % ("cta", "anuncio", "gasto", "comp", "costo/comp", "ROAS"))
    for f in con[:top]:
        L.append("%-5s %-34s %12s %5d %12s %6.1fx" % (
            f["cuenta"], f["nombre"][:34], _mcp_pesos(f["gasto"]), f["compras"],
            _mcp_pesos(f["gasto"] / f["compras"]), f["valor"] / f["gasto"] if f["gasto"] else 0))
    L.append("")
    L.append("LOS QUE QUEMAN PLATA SIN VENDER NADA")
    L.append("%-5s %-34s %12s %8s %7s" % ("cta", "anuncio", "gasto", "CTR", "frec"))
    for f in sin[:top]:
        L.append("%-5s %-34s %12s %7.2f%% %6.2f" % (
            f["cuenta"], f["nombre"][:34], _mcp_pesos(f["gasto"]), f["ctr"], f["frec"]))
    gq = sum(f["gasto"] for f in sin)
    L.append("")
    L.append("En anuncios SIN una sola compra: %s  (%.0f%% del gasto)" % (
        _mcp_pesos(gq), 100 * gq / tg if tg else 0))
    return "\n".join(L)


def _mcp_tool_despachos(email, a):
    try:
        rows = _despachos_orders(email) or []
    except Exception as e:
        return "No pude traer los pedidos: %s: %s" % (type(e).__name__, str(e)[:120])
    pend = [r for r in rows if r.get("estado") != "enviada"]
    if not pend:
        return "No hay pedidos pagados sin despachar."
    L = ["PEDIDOS A DESPACHAR: %d" % len(pend), ""]
    L.append("%-8s %-26s %-22s %-7s %4s %12s" % ("pedido", "cliente", "destino", "CP", "u.", "total"))
    for r in pend[:60]:
        L.append("%-8s %-26s %-22s %-7s %4s %12s" % (
            "#" + str(r.get("num", "")), (r.get("nombre") or "")[:26], (r.get("localidad") or "")[:22],
            r.get("cp", ""), r.get("unidades", 0), _mcp_pesos(r.get("total"))))
    if len(pend) > 60:
        L.append("... y %d mas" % (len(pend) - 60))
    L.append("")
    L.append("Total a despachar: %s" % _mcp_pesos(sum(float(r.get("total") or 0) for r in pend)))
    return "\n".join(L)


_MCP_FN = {"negocio": _mcp_tool_negocio, "ads_cuentas": _mcp_tool_ads_cuentas,
           "ads_anuncios": _mcp_tool_ads_anuncios, "despachos": _mcp_tool_despachos}


# ───────────────────────────── el transporte ─────────────────────────────
@app.route("/mcp/<clave>", methods=["GET", "POST", "OPTIONS", "DELETE"])
def mcp_servidor(clave):
    if request.method == "OPTIONS":
        return _mcp_cors(Response(status=200))
    if not MCP_CLAVE or clave != MCP_CLAVE:
        return _mcp_cors(Response("no existe", status=404, mimetype="text/plain"))
    if request.method == "DELETE":                 # el cliente cierra la sesion
        return _mcp_cors(Response(status=204))
    if request.method == "GET":
        # No abrimos canal del servidor al cliente: no hace falta, todo es pregunta-respuesta.
        return _mcp_cors(Response("sin stream", status=405, mimetype="text/plain"))

    msg = request.get_json(silent=True)
    if msg is None:
        return _mcp_err(None, -32700, "JSON invalido")
    if isinstance(msg, list):                      # lote: proceso el primero con id
        msg = next((m for m in msg if isinstance(m, dict) and m.get("id") is not None), msg[0])
    idd = msg.get("id")
    metodo = msg.get("method") or ""

    if metodo == "initialize":
        pv = ((msg.get("params") or {}).get("protocolVersion")) or MCP_PROTO
        import uuid as _uuid
        return _mcp_rta({"jsonrpc": "2.0", "id": idd, "result": {
            "protocolVersion": pv,
            "capabilities": {"tools": {"listChanged": False}},
            "serverInfo": {"name": "RealProfit", "version": "1.0.0"},
            "instructions": (
                "Datos reales del negocio de NoxaLab: ventas, ganancia, publicidad de Meta y "
                "pedidos a despachar. Todo es SOLO LECTURA.\n"
                "Dos fuentes que NO son lo mismo: 'negocio' sale de los pedidos y pagos reales "
                "(Shopify + MercadoLibre) y es la verdad; 'ads_cuentas' y 'ads_anuncios' salen de "
                "Meta, que se atribuye MENOS ventas de las que hubo. Para comparar creativos entre "
                "si, Meta sirve; para saber cuanto se gano, usa 'negocio'.\n"
                "La pauta no trae las ventas de MercadoLibre: por eso el CPA y el break even se "
                "calculan solo con la tienda. Los montos van en pesos."),
        }}, sid=_uuid.uuid4().hex)

    if metodo in ("notifications/initialized", "notifications/cancelled"):
        return _mcp_cors(Response(status=202))
    if metodo == "ping":
        return _mcp_rta({"jsonrpc": "2.0", "id": idd, "result": {}})
    if metodo == "tools/list":
        return _mcp_rta({"jsonrpc": "2.0", "id": idd, "result": {"tools": _MCP_TOOLS}})
    if metodo in ("resources/list", "prompts/list"):
        k = "resources" if metodo.startswith("resources") else "prompts"
        return _mcp_rta({"jsonrpc": "2.0", "id": idd, "result": {k: []}})

    if metodo == "tools/call":
        p = msg.get("params") or {}
        fn = _MCP_FN.get(p.get("name") or "")
        if not fn:
            return _mcp_err(idd, -32602, "No existe la herramienta '%s'" % p.get("name"))
        email = _mcp_email()
        if not email:
            return _mcp_texto(idd, "El conector no tiene cuenta configurada (falta MCP_EMAIL).")
        try:
            return _mcp_texto(idd, fn(email, p.get("arguments") or {}))
        except Exception as e:
            import traceback as _tb
            t = _tb.extract_tb(e.__traceback__)
            ln = (" @ %s:%d" % (t[-1].name, t[-1].lineno)) if t else ""
            return _mcp_rta({"jsonrpc": "2.0", "id": idd, "result": {
                "content": [{"type": "text", "text": "Fallo la consulta — %s: %s%s"
                             % (type(e).__name__, str(e)[:200], ln)}], "isError": True}})

    if idd is None:
        return _mcp_cors(Response(status=202))
    return _mcp_err(idd, -32601, "Metodo desconocido: %s" % metodo)


# ───────────────── LOGISTICA POR PEDIDO (Andreani / Flex) ─────────────────
# Cada pedido se costeaba SIEMPRE con la tabla de Andreani por zona. Los que lleva Cristian
# por Flex no cuestan eso, asi que el envio promedio (y con el la ganancia y el break even)
# salian mal. Aca se marca cual va por cual y el costo sigue a la marca.
#
# Por defecto TODO es Andreani: solo se guardan los que se marcan como Flex.

DESP_LOGI = DATA_DIR / "desp_logistica.json"      # {email: {num: "flex"}}

# Lo que te cuesta a VOS un envio por Flex (nafta + lo que le pagas al que reparte).
# Vacio = todavia no configurado -> se sigue costeando como Andreani, para no cambiarte
# la ganancia a ciegas con un numero inventado.
_FLEX_COSTO_UNICO = (_os.getenv("FLEX_COSTO", "") or "").strip()
_FLEX_COSTO_ZONA = {                               # pisa al unico si estan cargados
    "caba": (_os.getenv("FLEX_COSTO_CABA", "") or "").strip(),
    "norte": (_os.getenv("FLEX_COSTO_NORTE", "") or "").strip(),
    "oeste": (_os.getenv("FLEX_COSTO_OESTE", "") or "").strip(),
    "sur": (_os.getenv("FLEX_COSTO_SUR", "") or "").strip(),
}


def _logi_all() -> dict:
    try:
        return _json.loads(DESP_LOGI.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _logi(email) -> dict:
    return (_logi_all().get(email) or {})


def _logi_auto(metodo) -> str:
    """La logistica sale SOLA del metodo de envio que eligio el cliente en el checkout.
    Los de Envialo Flex son los del rayito; tambien se aceptan las variantes escritas."""
    t = (metodo or "").lower()
    if "\u26a1" in t or "flex" in t or "envialo" in t or "redchat" in t:
        return "flex"
    return "andreani"


def _logi_de(email, num, metodo=None) -> str:
    """Primero lo que marco Cristian a mano (gana siempre), si no lo que dice el metodo de
    envio. Andreani es el default."""
    m = _logi(email).get(str(num))
    if m in ("flex", "andreani"):
        return m
    return _logi_auto(metodo)


def _logi_set(email, nums, cual) -> int:
    todo = _logi_all()
    d = todo.setdefault(email, {})
    n = 0
    for x in nums:
        k = str(x).strip()
        if not k:
            continue
        # Se guardan los DOS: ahora que la deteccion es automatica, marcar "Andreani" a mano
        # tiene que poder CONTRADECIR al metodo de envio, no solo borrar la marca.
        if cual == "auto":
            d.pop(k, None)                         # vuelve a decidir el metodo de envio
        else:
            d[k] = "flex" if cual == "flex" else "andreani"
        n += 1
    tmp = DESP_LOGI.with_suffix(".tmp")
    tmp.write_text(_json.dumps(todo, ensure_ascii=False), encoding="utf-8")
    tmp.replace(DESP_LOGI)
    return n


# TARIFAS DE FLEX CON FECHA.
# Hasta el 12-10 el Flex era propio y costaba $4.000 planos. Desde el 14-10-2026 a las 00:00
# lo lleva Envialo y cobra por zona, asi que un pedido del 10 NO puede costearse con la tarifa
# del 14: cada envio se cobra con la tarifa que regia EL DIA que se hizo.
# Formato de la env FLEX_TARIFAS (JSON):
#   [{"desde":"2026-10-14","caba":0,"norte":0,"oeste":0,"sur":0,"unico":0}, ...]
# Lo de antes de la primera fecha cae en FLEX_COSTO / FLEX_COSTO_<ZONA>, como siempre.
try:
    _FLEX_TARIFAS = sorted(_json.loads(_os.getenv("FLEX_TARIFAS", "") or "[]"),
                           key=lambda t: t.get("desde") or "")
except Exception:
    _FLEX_TARIFAS = []


# COSTOS REALES DE ENVIALO, PEDIDO POR PEDIDO.
# Envialo no cobra por las 4 zonas nuestras sino por anillo de distancia: San Isidro $6.200 y
# San Fernando $6.300 son los dos "norte"; Lanus $6.200 y Glew $6.300 son los dos "sur".
# Cualquier tabla por zona le erra. Pero RedChat muestra el costo de CADA envio con el numero
# de venta de Shopify al lado, que es la misma clave que usa RealProfit: se pega esa tabla y
# cada pedido queda con lo que Envialo cobro DE VERDAD. Sin promedios.
FLEX_COSTOS_F = DATA_DIR / "flex_costos.json"      # {num_pedido: costo}


def _flex_costos_all() -> dict:
    try:
        return _json.loads(FLEX_COSTOS_F.read_text(encoding="utf-8"))
    except Exception:
        return {}


_RE_FLEX_FILA = _re_and.compile(
    r"(?:^|\s)(\d{3,6})\b.{0,200}?\$\s*([\d.]+(?:,\d{2})?)", _re_and.S)


def _flex_costos_parsear(txt: str) -> dict:
    """Lee lo que se pego de RedChat. Cada fila trae el numero de venta y mas adelante el
    costo con signo $. Se toma el ULTIMO monto de la fila: el primero es el total de la venta
    ($70.890) y el que interesa es el costo de envio ($6.600)."""
    out = {}
    for linea in (txt or "").splitlines():
        l = linea.strip()
        if not l:
            continue
        m = _re_and.match(r"^#?(\d{3,6})\b", l)
        if not m:
            continue
        montos = _re_and.findall(r"\$\s*([\d.]+(?:,\d{2})?)", l)
        if not montos:
            continue
        v = montos[-1].replace(".", "").replace(",", ".")
        try:
            c = float(v)
        except Exception:
            continue
        if c > 0:
            out[m.group(1)] = round(c, 2)
    return out


@app.post("/pf-flex-costos")
def pf_flex_costos():
    """Pegar la tabla de RedChat (Ordenes filtradas por Envialo Flex)."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    d = request.get_json(silent=True) or {}
    if d.get("ver"):
        a = _flex_costos_all()
        return jsonify({"ok": True, "cuantos": len(a),
                        "ultimos": sorted(a.items(), key=lambda x: -int(x[0]))[:12]})
    nuevos = _flex_costos_parsear(d.get("texto") or "")
    if not nuevos:
        return jsonify({"ok": False, "msg": "No reconoci ninguna fila. Pega las filas con el "
                                            "numero de venta y el costo de envio."}), 400
    todo = _flex_costos_all()
    todo.update({str(k): v for k, v in nuevos.items()})
    try:
        tmp = FLEX_COSTOS_F.with_suffix(".tmp")
        tmp.write_text(_json.dumps(todo, ensure_ascii=False), encoding="utf-8")
        tmp.replace(FLEX_COSTOS_F)
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, str(e)[:120])}), 500
    return jsonify({"ok": True, "cargados": len(nuevos), "total": len(todo),
                    "detalle": sorted(nuevos.items(), key=lambda x: -int(x[0]))[:15]})


def _flex_fecha_de(o) -> str:
    for k in ("created_at", "processed_at", "fecha", "date_created"):
        v = (o or {}).get(k)
        if v:
            return str(v)[:10]
    return _dt.date.today().isoformat()


def _flex_costo_envio(o) -> float:
    """Lo que cuesta de verdad llevarlo por Flex, con la tarifa vigente el dia del pedido.
    Si no hay nada configurado devuelve None y el pedido se sigue costeando con la tabla de
    Andreani (mejor eso que inventar un numero)."""
    _num = str((o or {}).get("order_number") or (o or {}).get("name") or "").lstrip("#")
    _real = _flex_costos_all().get(_num)
    if _real:
        return float(_real)                      # lo que Envialo cobro de verdad, gana siempre
    dia = _flex_fecha_de(o)
    if dia >= FLEX_RC2_DESDE:
        # Tarifa de Envialo por RedChat medida el 24-10: 4 anillos por CP (ver FLEX_RC2_CP).
        return _flex_rc2(o)
    z = _flex_zona(_prov_cp(o)[1], _prov_cp(o)[0]) or ""
    v = ""
    for t in _FLEX_TARIFAS:                      # ordenadas: gana la ultima que ya empezo
        if (t.get("desde") or "") <= dia:
            v = t.get(z) or t.get("unico") or ""
    if not v:
        v = _FLEX_COSTO_ZONA.get(z) or _FLEX_COSTO_UNICO
    try:
        return float(str(v).replace(".", "").replace(",", ".")) if v else None
    except Exception:
        return None


@app.post("/pf-desp-logistica")
def pf_desp_logistica():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    d = request.get_json(silent=True) or {}
    cual = d.get("logistica") or "andreani"
    if cual not in ("flex", "andreani", "auto"):
        cual = "andreani"
    if d.get("todos") and cual == "auto":
        # Reset: se borran TODAS las marcas a mano y vuelve a decidir el metodo de envio.
        todo = _logi_all()
        n = len(todo.get(email) or {})
        todo[email] = {}
        tmp = DESP_LOGI.with_suffix(".tmp")
        tmp.write_text(_json.dumps(todo, ensure_ascii=False), encoding="utf-8")
        tmp.replace(DESP_LOGI)
    else:
        n = _logi_set(email, d.get("nums") or [], cual)
    try:                                           # los numeros del dashboard cambian: tiro el cache
        _DESP_CACHE.pop(email, None); _desp_cache_save()
    except Exception:
        pass
    return jsonify({"ok": True, "marcados": n, "logistica": cual,
                    "costo_configurado": bool(_FLEX_COSTO_UNICO or any(_FLEX_COSTO_ZONA.values()))})


